export type EntryType = 'itinerary' | 'expense' | 'memory';

export interface BaseEntry {
  id: string;
  timestamp: Date;
  type: EntryType;
}

export interface ItineraryEntry extends BaseEntry {
  type: 'itinerary';
  time: string;
  location: string;
  notes?: string;
}

export interface ExpenseEntry extends BaseEntry {
  type: 'expense';
  amount: number;
  category: string;
  currency: string;
  description: string;
}

export interface MemoryEntry extends BaseEntry {
  type: 'memory';
  content: string;
  imageUrl?: string;
  mood?: string;
}

export type JournalEntry = ItineraryEntry | ExpenseEntry | MemoryEntry;

export interface DayTimeline {
  id: string;
  date: Date;
  dayNumber: number;
  entries: JournalEntry[];
}

export interface Trip {
  id: string;
  title: string;
  startDate: Date;
  endDate: Date;
  coverImage?: string;
  days: DayTimeline[];
}

export type AppTab = 'itinerary' | 'journal' | 'expenses' | 'trips';

