import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const polishMemory = async (rawNote: string): Promise<string> => {
  if (!process.env.API_KEY) return rawNote;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Transform the following travel note into a beautiful, reflective journal entry inspired by Japanese travel essays. Keep it concise (max 3 sentences) and evocative.

      Note: "${rawNote}"`,
      config: {
        temperature: 0.7,
        maxOutputTokens: 150,
      }
    });

    return response.text?.trim() || rawNote;
  } catch (error) {
    console.error("Gemini Error:", error);
    return rawNote;
  }
};

import React from 'react';
import { 
  Map, 
  BookOpen, 
  CreditCard, 
  Compass, 
  Plus, 
  Calendar, 
  Clock, 
  MapPin, 
  Camera,
  ArrowRight,
  MoreHorizontal
} from 'lucide-react';

interface IconProps {
  name: 'itinerary' | 'journal' | 'expenses' | 'trips' | 'plus' | 'calendar' | 'clock' | 'mapPin' | 'camera' | 'arrow' | 'more';
  size?: number;
  className?: string;
  onClick?: () => void;
}

const Icon: React.FC<IconProps> = ({ name, size = 20, className, onClick }) => {
  const icons = {
    itinerary: Map,
    journal: BookOpen,
    expenses: CreditCard,
    trips: Compass,
    plus: Plus,
    calendar: Calendar,
    clock: Clock,
    mapPin: MapPin,
    camera: Camera,
    arrow: ArrowRight,
    more: MoreHorizontal
  };

  const LucideIcon = icons[name];
  return <LucideIcon size={size} className={className} onClick={onClick} strokeWidth={1.5} />;
};

export default Icon;

import React from 'react';
import { JournalEntry, ItineraryEntry, ExpenseEntry, MemoryEntry } from '../types';
import Icon from './Icon';
import { COLORS } from '../constants';

interface EntryItemProps {
  entry: JournalEntry;
}

const EntryItem: React.FC<EntryItemProps> = ({ entry }) => {
  if (entry.type === 'itinerary') {
    const item = entry as ItineraryEntry;
    return (
      <div className="flex gap-4 mb-6">
        <div className="text-xs text-[#A0A098] w-10 pt-1 font-medium">{item.time}</div>
        <div className="flex-1">
          <div className="flex items-center gap-2 mb-1">
            <Icon name="mapPin" size={14} className="text-[#8DA399]" />
            <span className="font-medium text-sm">{item.location}</span>
          </div>
          {item.notes && <p className="text-xs text-[#70706B] leading-relaxed italic">{item.notes}</p>}
        </div>
      </div>
    );
  }

  if (entry.type === 'expense') {
    const item = entry as ExpenseEntry;
    return (
      <div className="flex items-center justify-between py-3 border-b border-[#F0EFEB] last:border-0">
        <div className="flex flex-col">
          <span className="text-sm font-medium">{item.description}</span>
          <span className="text-[10px] text-[#A0A098] uppercase tracking-wider">{item.category}</span>
        </div>
        <div className="text-sm font-medium">
          {item.currency} {item.amount.toLocaleString()}
        </div>
      </div>
    );
  }

  if (entry.type === 'memory') {
    const item = entry as MemoryEntry;
    return (
      <div className="my-6">
        {item.imageUrl && (
          <div className="mb-4 rounded-2xl overflow-hidden shadow-sm">
            <img src={item.imageUrl} alt="Memory" className="w-full h-48 object-cover" />
          </div>
        )}
        <p className="text-sm leading-relaxed text-[#555550] serif italic">
