import React from 'react';
import { DayTimeline } from '../types';
import EntryItem from './EntryItem';
import Icon from './Icon';

interface DayCardProps {
  day: DayTimeline;
}

const DayCard: React.FC<DayCardProps> = ({ day }) => {
  const formattedDate = day.date.toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
    weekday: 'long'
  });

  const totalExpense = day.entries
    .filter(e => e.type === 'expense')
    .reduce((acc, curr: any) => acc + curr.amount, 0);

  return (
    <div className="mb-8 bg-white rounded-[32px] p-8 shadow-[0_4px_24px_rgba(0,0,0,0.03)] border border-[#F0EFEB] transition-all duration-500 ease-out hover:shadow-[0_8px_32px_rgba(0,0,0,0.06)]">
      <div className="flex justify-between items-baseline mb-8">
        <div>
          <h3 className="text-xs font-semibold tracking-[0.2em] uppercase text-[#8DA399] mb-1">
            Day {day.dayNumber}
          </h3>
          <h2 className="text-xl font-medium text-[#4A4A4A]">
            {formattedDate}
          </h2>
        </div>
        {totalExpense > 0 && (
          <div className="text-right">
            <span className="text-[10px] text-[#A0A098] uppercase tracking-wider block mb-0.5">Spent today</span>
            <span className="text-xs font-semibold">JPY {totalExpense.toLocaleString()}</span>
          </div>
        )}
      </div>

      <div className="space-y-2">
        {day.entries.length === 0 ? (
          <div className="py-12 flex flex-col items-center justify-center text-[#A0A098] border-2 border-dashed border-[#F0EFEB] rounded-2xl">
            <Icon name="plus" size={24} className="mb-2 opacity-40" />
            <span className="text-xs tracking-wider">Plan your day</span>
          </div>
        ) : (
          day.entries.map((entry) => (
            <EntryItem key={entry.id} entry={entry} />
          ))
        )}
      </div>
    </div>
  );
};

export default DayCard;

import React from 'react';
import { AppTab } from '../types';
import Icon from './Icon';

interface NavigationProps {
  activeTab: AppTab;
  onTabChange: (tab: AppTab) => void;
}

const Navigation: React.FC<NavigationProps> = ({ activeTab, onTabChange }) => {
  const tabs: { id: AppTab; label: string; icon: any }[] = [
    { id: 'itinerary', label: 'Plan', icon: 'itinerary' },
    { id: 'journal', label: 'Journal', icon: 'journal' },
    { id: 'expenses', label: 'Spent', icon: 'expenses' },
    { id: 'trips', label: 'Trips', icon: 'trips' },
  ];

  return (
    <nav className="fixed bottom-0 left-0 right-0 bg-white/80 backdrop-blur-xl border-t border-[#F0EFEB] px-6 pb-8 pt-4 flex justify-between items-center z-50">
      {tabs.map((tab) => {
        const isActive = activeTab === tab.id;
        return (
          <button
            key={tab.id}
            onClick={() => onTabChange(tab.id)}
            className="flex flex-col items-center gap-1.5 transition-all duration-300"
          >
            <Icon 
              name={tab.icon} 
              className={`transition-colors duration-300 ${isActive ? 'text-[#8DA399]' : 'text-[#A0A098]'}`} 
              size={22} 
            />
            <span className={`text-[10px] font-medium tracking-widest uppercase transition-colors duration-300 ${isActive ? 'text-[#8DA399]' : 'text-[#A0A098]'}`}>
              {tab.label}
            </span>
          </button>
        );
      })}
    </nav>
  );
};

export default Navigation;

import React, { useState, useEffect } from 'react';
import { AppTab, Trip, JournalEntry, EntryType } from './types';
import { MOCK_TRIP, COLORS } from './constants';
import DayCard from './components/DayCard';
import Navigation from './components/Navigation';
import Icon from './components/Icon';
import { polishMemory } from './services/geminiService';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<AppTab>('itinerary');
  const [trip, setTrip] = useState<Trip>(MOCK_TRIP);
  const [isScrolled, setIsScrolled] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [loadingAI, setLoadingAI] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const handleAddEntry = async (type: EntryType) => {
    // Basic interaction for demo
    if (type === 'memory') {
      const note = prompt("What's on your mind?");
      if (note) {
        setLoadingAI(true);
        const polished = await polishMemory(note);
        setLoadingAI(false);

        const newEntry: JournalEntry = {
          id: Date.now().toString(),
          type: 'memory',
          timestamp: new Date(),
          content: polished,
          mood: 'Reflective'
        };

        const updatedDays = [...trip.days];
        updatedDays[0].entries.unshift(newEntry);
        setTrip({ ...trip, days: updatedDays });
      }
    } else {
      alert("Feature coming soon in this minimalist demo!");
    }
    setShowAddModal(false);
  };

  return (
    <div className="min-h-screen pb-32 max-w-lg mx-auto bg-[#F9F8F6]">
      {/* Dynamic Header */}
      <header className={`sticky top-0 z-40 transition-all duration-500 px-8 pt-12 pb-6 ${isScrolled ? 'bg-white/80 backdrop-blur-lg shadow-sm pt-6 pb-4' : 'bg-transparent'}`}>
        <div className="flex justify-between items-center">
          <div>
            <h1 className="text-3xl font-medium tracking-tight text-[#4A4A4A]">
              {trip.title}
            </h1>
            {!isScrolled && (
              <p className="text-sm text-[#A0A098] mt-2 serif italic">
                Tokyo & Kyoto, Spring 2024
              </p>
            )}
          </div>
          <button className="w-10 h-10 rounded-full bg-white border border-[#F0EFEB] flex items-center justify-center shadow-sm text-[#A0A098] hover:text-[#8DA399] transition-colors">
            <Icon name="more" size={20} />
          </button>
        </div>
      </header>

      {/* Main Content Area */}
      <main className="px-6 animate-in fade-in slide-in-from-bottom-4 duration-1000">
        {activeTab === 'itinerary' && (
          <div className="mt-8">
            {trip.days.map((day) => (
              <DayCard key={day.id} day={day} />
            ))}
          </div>
        )}

        {activeTab === 'journal' && (
          <div className="mt-8 space-y-8">
            <div className="bg-white rounded-[32px] p-8 border border-[#F0EFEB]">
              <h2 className="text-2xl font-medium mb-6">Memories</h2>
              {trip.days.flatMap(d => d.entries).filter(e => e.type === 'memory').map((entry: any) => (
                <div key={entry.id} className="mb-10 last:mb-0 border-b border-[#F9F8F6] pb-8 last:border-0 last:pb-0">
                  <div className="flex items-center gap-3 mb-4">
                     <span className="text-[10px] font-bold uppercase tracking-widest text-[#8DA399]">Collected</span>
                  </div>
                  <p className="serif text-lg leading-relaxed text-[#555550] italic">"{entry.content}"</p>
                  {entry.imageUrl && (
                    <img src={entry.imageUrl} className="w-full h-48 object-cover rounded-2xl mt-4 opacity-90 grayscale-[0.2]" />
                  )}
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'expenses' && (
          <div className="mt-8">
             <div className="bg-white rounded-[32px] p-8 border border-[#F0EFEB]">
              <h2 className="text-2xl font-medium mb-6">Financials</h2>
              <div className="space-y-4">
                {trip.days.map(day => {
                  const dayExpense = day.entries.filter(e => e.type === 'expense');
                  if (dayExpense.length === 0) return null;
                  return (
                    <div key={day.id} className="mb-6">
                      <div className="flex justify-between items-center mb-2">
                        <span className="text-xs font-bold text-[#A0A098] tracking-widest uppercase">Day {day.dayNumber}</span>
                      </div>
                      {dayExpense.map((e: any) => (
                        <div key={e.id} className="flex justify-between py-2 text-sm">
                          <span className="text-[#60605B]">{e.description}</span>
                          <span className="font-medium">{e.amount.toLocaleString()} JPY</span>
                        </div>
                      ))}
                    </div>
                  );
                })}
              </div>
             </div>
          </div>
        )}

        {activeTab === 'trips' && (
           <div className="mt-8">
             <div className="bg-white rounded-[32px] p-8 border border-[#F0EFEB] text-center py-24">
                <Icon name="trips" size={40} className="mx-auto mb-4 text-[#E5E4E2]" />
                <p className="text-[#A0A098] serif italic">No other journeys yet.</p>
             </div>
           </div>
        )}
      </main>

      {/* AI Loading State */}
      {loadingAI && (
        <div className="fixed inset-0 bg-white/60 backdrop-blur-sm z-50 flex flex-col items-center justify-center animate-in fade-in duration-300">
          <div className="w-12 h-12 rounded-full border-2 border-[#8DA399] border-t-transparent animate-spin mb-4" />
          <p className="serif italic text-[#8DA399]">Polishing your memory...</p>
        </div>
      )}

      {/* Floating Action Menu */}
      <div className="fixed bottom-32 right-8 z-50">
        <button 
          onClick={() => setShowAddModal(!showAddModal)}
          className={`w-14 h-14 rounded-full bg-[#8DA399] text-white flex items-center justify-center shadow-lg transition-transform duration-500 hover:scale-110 active:scale-95 ${showAddModal ? 'rotate-45' : ''}`}
        >
          <Icon name="plus" size={28} />
        </button>

        {showAddModal && (
          <div className="absolute bottom-16 right-0 space-y-3 flex flex-col items-end animate-in fade-in slide-in-from-bottom-2 duration-300">
            <button 
              onClick={() => handleAddEntry('memory')}
              className="px-4 py-2 bg-white rounded-full shadow-md border border-[#F0EFEB] text-xs font-medium tracking-wider flex items-center gap-2"
            >
              Write Reflection <Icon name="journal" size={14} className="text-[#8DA399]" />
            </button>
            <button 
              onClick={() => handleAddEntry('itinerary')}
              className="px-4 py-2 bg-white rounded-full shadow-md border border-[#F0EFEB] text-xs font-medium tracking-wider flex items-center gap-2"
            >
              Add Stop <Icon name="itinerary" size={14} className="text-[#8DA399]" />
            </button>
            <button 
              onClick={() => handleAddEntry('expense')}
              className="px-4 py-2 bg-white rounded-full shadow-md border border-[#F0EFEB] text-xs font-medium tracking-wider flex items-center gap-2"
            >
              Record Expense <Icon name="expenses" size={14} className="text-[#8DA399]" />
            </button>
          </div>
        )}
      </div>

      <Navigation activeTab={activeTab} onTabChange={setActiveTab} />
    </div>
  );
};

export default App;

