import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const polishMemory = async (rawNote: string): Promise<string> => {
  if (!process.env.API_KEY) return rawNote;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `將以下旅遊筆記轉換為優美、具反思性的札記，風格參考日式旅遊散文。
      保持簡短（最多 3 句）且富有感染力。請務必使用繁體中文（Traditional Chinese）。

      筆記內容： "${rawNote}"`,
      config: {
        temperature: 0.7,
        maxOutputTokens: 150,
      }
    });

    return response.text?.trim() || rawNote;
  } catch (error) {
    console.error("Gemini Error:", error);
    return rawNote;
  }
};

