      onDelete(entry.id);
    }
  };

  if (entry.type === 'itinerary') {
    const item = entry as ItineraryEntry;
    return (
      <div className="flex gap-6 mb-8 group relative">
        <div className="w-16 pt-1">
          <span className="text-[10px] font-medium text-[#8A8A85] tracking-widest block uppercase">{item.time}</span>
        </div>
        <div className="flex-1 pb-4 border-b border-[#EFEFE9] group-last:border-0 pr-8">
          <h4 className="text-sm font-medium text-[#2A2A28] mb-1">{item.location}</h4>
          {item.notes && <p className="text-xs text-[#8A8A85] leading-relaxed font-light">{item.notes}</p>}
        </div>
        <button 
          onClick={handleDelete}
          className="absolute right-0 top-1 opacity-0 group-hover:opacity-100 transition-opacity text-[#BABAB5] hover:text-[#2A2A28]"
        >
          <Icon name="plus" size={16} className="rotate-45" />
        </button>
      </div>
    );
  }

  if (entry.type === 'expense') {
    const item = entry as ExpenseEntry;
    return (
      <div className="flex items-center justify-between py-4 border-b border-[#EFEFE9] last:border-0 group">
        <div>
          <span className="text-[9px] uppercase tracking-widest text-[#8DA399] font-bold block mb-1">{item.category}</span>
          <span className="text-sm font-medium text-[#2A2A28]">{item.description}</span>
        </div>
        <div className="flex items-center gap-4">
          <div className="text-sm font-medium tabular-nums text-[#2A2A28]">
            {item.currency} {item.amount.toLocaleString()}
          </div>
          <button 
            onClick={handleDelete}
            className="opacity-0 group-hover:opacity-100 transition-opacity text-[#BABAB5] hover:text-[#2A2A28]"
          >
            <Icon name="plus" size={16} className="rotate-45" />
          </button>
        </div>
      </div>
    );
  }

  if (entry.type === 'memory') {
    const item = entry as MemoryEntry;
    return (
      <div className="my-10 first:mt-0 group relative">
        {item.imageUrl && (
          <div className="mb-6 rounded-3xl overflow-hidden bg-[#F0F0EB]">
            <img src={item.imageUrl} alt="Memory" className="w-full h-56 object-cover hover:scale-105 transition-transform duration-700" />
          </div>
        )}
        <div className="max-w-[90%] mx-auto text-center">
          <p className="text-lg leading-relaxed text-[#2A2A28] serif italic mb-4">
            {item.content}
          </p>
          {item.mood && (
            <div className="flex justify-center items-center gap-3">
              <div className="h-[1px] w-4 bg-[#EFEFE9]" />
              <span className="text-[9px] uppercase tracking-[0.3em] text-[#8A8A85] font-semibold">{item.mood}</span>
              <div className="h-[1px] w-4 bg-[#EFEFE9]" />
            </div>
          )}
        </div>
        <button 
          onClick={handleDelete}
          className="absolute right-0 top-0 opacity-0 group-hover:opacity-100 transition-opacity text-[#BABAB5] hover:text-[#2A2A28]"
        >
          <Icon name="plus" size={16} className="rotate-45" />
        </button>
      </div>
    );
  }

  return null;
};

