import React, { useState, useEffect } from 'react';
import { AppTab, Trip, JournalEntry, EntryType, MemoryEntry, DayTimeline } from './types';
import { MOCK_TRIP } from './constants';
import DayCard from './components/DayCard';
import Navigation from './components/Navigation';
import Icon from './components/Icon';
import EntryForm from './components/EntryForm';
import TripSettingsForm from './components/TripSettingsForm';
import { polishMemory } from './services/geminiService';

const STORAGE_KEY = 'komorebi_trip_data_v2';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<AppTab>('itinerary');
  const [trip, setTrip] = useState<Trip>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        parsed.startDate = new Date(parsed.startDate);
        parsed.endDate = new Date(parsed.endDate);
        parsed.days = parsed.days.map((d: any) => ({
          ...d,
          date: new Date(d.date),
          entries: d.entries.map((e: any) => ({
            ...e,
            timestamp: new Date(e.timestamp)
          }))
        }));
        return parsed;
      } catch (e) {
        return MOCK_TRIP;
      }
    }
    return MOCK_TRIP;
  });

  const [isScrolled, setIsScrolled] = useState(false);
  const [activeForm, setActiveForm] = useState<EntryType | null>(null);
  const [editingEntry, setEditingEntry] = useState<{ dayId: string; entry: JournalEntry } | null>(null);
  const [showTripSettings, setShowTripSettings] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [loadingAI, setLoadingAI] = useState(false);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(trip));
  }, [trip]);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 40);
    };
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // 更新旅程基礎設定並重新計算天數
  const handleSaveTripSettings = (title: string, start: Date, end: Date) => {
    const newDays: DayTimeline[] = [];
    const diffTime = Math.abs(end.getTime() - start.getTime());
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)) + 1;

    for (let i = 0; i < diffDays; i++) {
      const currentDate = new Date(start);
      currentDate.setDate(start.getDate() + i);

      // 嘗試找回原本對應日期的紀錄
      const existingDay = trip.days.find(d => d.date.toDateString() === currentDate.toDateString());

      newDays.push({
        id: existingDay?.id || `day-${i + 1}-${Date.now()}`,
        date: currentDate,
        dayNumber: i + 1,
        entries: existingDay?.entries || []
      });
    }

    setTrip({
      ...trip,
      title,
      startDate: start,
      endDate: end,
      days: newDays
    });
    setShowTripSettings(false);
  };

  const handleSaveEntry = async (data: Partial<JournalEntry>) => {
    const formType = activeForm || editingEntry?.entry.type;
    if (!formType) return;

    let finalData = { ...data };

    if (formType === 'memory') {
      const memoryData = data as Partial<MemoryEntry>;
      const originalContent = editingEntry?.entry.type === 'memory' ? (editingEntry.entry as MemoryEntry).content : '';

      if (memoryData.content && memoryData.content !== originalContent) {
        setLoadingAI(true);
        const polished = await polishMemory(memoryData.content);
        (finalData as any).content = polished;
        setLoadingAI(false);
      }
    }

    if (editingEntry) {
      const updatedDays = trip.days.map(day => {
        if (day.id === editingEntry.dayId) {
          return {
            ...day,
            entries: day.entries.map(e => e.id === editingEntry.entry.id ? { ...e, ...finalData } : e)
          };
        }
        return day;
      });
      setTrip({ ...trip, days: updatedDays as any });
    } else {
      const newEntry: JournalEntry = {
        id: Date.now().toString(),
        timestamp: new Date(),
        type: formType,
        currency: 'JPY',
        ...finalData
      } as JournalEntry;

      const updatedDays = [...trip.days];
      // 預設新增到第一天
      if (updatedDays.length > 0) {
        updatedDays[0].entries = [newEntry, ...updatedDays[0].entries];
      }
      setTrip({ ...trip, days: updatedDays });
    }

    setActiveForm(null);
    setEditingEntry(null);
  };

  const handleDeleteEntry = (dayId: string, entryId: string) => {
    const updatedDays = trip.days.map(day => {
      if (day.id === dayId) {
        return {
          ...day,
          entries: day.entries.filter(e => e.id !== entryId)
        };
      }
      return day;
    });
    setTrip({ ...trip, days: updatedDays });
  };

  const handleEditEntryTrigger = (dayId: string, entry: JournalEntry) => {
    setEditingEntry({ dayId, entry });
  };

  return (
    <div className="min-h-screen pb-40 max-w-lg mx-auto bg-[#FDFDFB] selection:bg-[#8DA399]/20">
      {/* Editorial Header */}
      <header 
        onClick={() => !isScrolled && setShowTripSettings(true)}
        className={`sticky top-0 z-40 transition-all duration-700 px-8 flex flex-col justify-end cursor-pointer ${isScrolled ? 'h-24 bg-white/90 backdrop-blur-lg border-b border-[#EFEFE9]' : 'h-48 bg-transparent'}`}
      >
        <div className="flex justify-between items-end pb-6">
          <div className="transition-all duration-700">
            {!isScrolled && (
              <span className="text-[10px] font-bold uppercase tracking-[0.5em] text-[#8DA399] block mb-2">當前旅程</span>
            )}
            <h1 className={`font-medium tracking-tight text-[#2A2A28] serif transition-all duration-700 ${isScrolled ? 'text-xl' : 'text-4xl'}`}>
              {trip.title}
            </h1>
            {!isScrolled && (
              <p className="text-xs text-[#8A8A85] mt-3 tracking-wide flex items-center gap-2">
                共 {trip.days.length} 天之旅 <span className="opacity-30">|</span> 點擊編輯旅程設定
              </p>
            )}
          </div>
          <button 
            onClick={(e) => { e.stopPropagation(); if(confirm('要重設所有旅程資料嗎？')) { localStorage.removeItem(STORAGE_KEY); window.location.reload(); } }}
            className={`transition-opacity duration-500 p-2 ${isScrolled ? 'opacity-100' : 'opacity-40 hover:opacity-100'}`}
          >
            <Icon name="calendar" size={18} className="text-[#BABAB5]" />
          </button>
        </div>
      </header>

      {/* Main Content Area */}
      <main className="px-8 mt-10">
        {activeTab === 'itinerary' && (
          <div className="animate-in fade-in duration-1000">
            {trip.days.map((day) => (
              <DayCard 
                key={day.id} 
                day={day} 
                onDeleteEntry={handleDeleteEntry} 
                onEditEntry={handleEditEntryTrigger} 
              />
            ))}
          </div>
        )}

        {activeTab === 'journal' && (
          <div className="animate-in fade-in slide-in-from-bottom-2 duration-700">
            <h2 className="text-xs font-black uppercase tracking-[0.4em] text-[#8A8A85] mb-12 border-b border-[#EFEFE9] pb-4">反思與札記</h2>
            <div className="space-y-16">
              {trip.days.flatMap(d => d.entries.map(e => ({ ...e, dayId: d.id }))).filter(e => e.type === 'memory').map((entry: any) => (
                <div 
                  key={entry.id} 
                  onClick={() => handleEditEntryTrigger(entry.dayId, entry)}
                  className="group relative cursor-pointer active:opacity-60 transition-opacity"
                >
                  <p className="serif text-xl leading-relaxed text-[#2A2A28] italic">「{entry.content}」</p>
                  <div className="flex items-center gap-4 mt-6">
                    <span className="text-[9px] font-bold uppercase tracking-widest text-[#8DA399]">
                      {entry.mood || '記事'}
                    </span>
                    <div className="h-[1px] flex-1 bg-[#EFEFE9]" />
                    <button 
                      onClick={(e) => { e.stopPropagation(); handleDeleteEntry(entry.dayId, entry.id); }} 
                      className="text-[#BABAB5] hover:text-[#2A2A28] p-1"
                    >
                      <Icon name="plus" size={14} className="rotate-45" />
                    </button>
                  </div>
                </div>
              ))}
              {trip.days.flatMap(d => d.entries).filter(e => e.type === 'memory').length === 0 && (
                <p className="text-center text-sm text-[#BABAB5] italic py-20">還沒有留下任何心情筆記...</p>
              )}
            </div>
          </div>
        )}

        {activeTab === 'expenses' && (
          <div className="animate-in fade-in slide-in-from-bottom-2 duration-700">
             <h2 className="text-xs font-black uppercase tracking-[0.4em] text-[#8A8A85] mb-12 border-b border-[#EFEFE9] pb-4">支出明細</h2>
             <div className="space-y-10">
                {trip.days.map(day => {
                  const dayExpense = day.entries.filter(e => e.type === 'expense');
                  if (dayExpense.length === 0) return null;
                  return (
                    <div key={day.id}>
                      <span className="text-[10px] font-black uppercase tracking-widest text-[#2A2A28] mb-4 block">第 {day.dayNumber} 天</span>
                      {dayExpense.map((e: any) => (
                        <div 
                          key={e.id} 
                          onClick={() => handleEditEntryTrigger(day.id, e)}
                          className="flex justify-between py-3 border-b border-[#EFEFE9] last:border-0 group cursor-pointer active:opacity-60 transition-opacity"
                        >
                          <span className="text-sm font-light text-[#2A2A28]">{e.description}</span>
                          <div className="flex items-center gap-4">
                            <span className="text-sm font-medium tabular-nums">{e.amount.toLocaleString()} JPY</span>
                            <button 
                              onClick={(event) => { event.stopPropagation(); handleDeleteEntry(day.id, e.id); }} 
                              className="opacity-0 group-hover:opacity-100 text-[#BABAB5] hover:text-black p-1"
                            >
                              <Icon name="plus" size={14} className="rotate-45" />
                            </button>
                          </div>
                        </div>
                      ))}
                    </div>
                  );
                })}
                {trip.days.every(d => d.entries.filter(e => e.type === 'expense').length === 0) && (
                  <p className="text-center text-sm text-[#BABAB5] italic py-20">目前沒有任何開支紀錄。</p>
                )}
             </div>
          </div>
        )}

        {activeTab === 'trips' && (
           <div className="animate-in fade-in slide-in-from-bottom-2 duration-700 flex flex-col items-center justify-center py-40 border border-[#EFEFE9] rounded-[40px] bg-white/40">
              <span className="text-[10px] uppercase tracking-[0.4em] text-[#BABAB5] font-bold serif italic">尚未有其他歷史典藏</span>
           </div>
        )}
      </main>

      {/* AI Loader */}
      {loadingAI && (
        <div className="fixed inset-0 bg-white/80 backdrop-blur-xl z-[200] flex flex-col items-center justify-center">
          <div className="w-10 h-10 border border-[#2A2A28]/10 border-t-[#8DA399] rounded-full animate-spin mb-6" />
          <p className="serif italic text-sm tracking-wide text-[#2A2A28]">正在修飾您的回憶...</p>
        </div>
      )}

      {/* Input Overlay (Edit or Add) */}
      {(activeForm || editingEntry) && (
        <EntryForm 
          type={activeForm || editingEntry!.entry.type} 
          initialData={editingEntry?.entry}
          onClose={() => { setActiveForm(null); setEditingEntry(null); }} 
          onSave={handleSaveEntry} 
        />
      )}

      {/* Trip Settings Overlay */}
      {showTripSettings && (
        <TripSettingsForm 
          trip={trip} 
          onClose={() => setShowTripSettings(false)} 
          onSave={handleSaveTripSettings} 
        />
      )}

      {/* Simple Floating Trigger */}
      <div className="fixed bottom-36 right-10 z-50">
        <button 
          onClick={() => setShowAddModal(!showAddModal)}
          className={`w-14 h-14 rounded-full bg-[#2A2A28] text-white flex items-center justify-center shadow-2xl transition-all duration-500 hover:bg-[#8DA399] ${showAddModal ? 'rotate-45' : ''}`}
        >
          <Icon name="plus" size={24} />
        </button>

        {showAddModal && (
          <div className="absolute bottom-20 right-0 space-y-4 flex flex-col items-end animate-in fade-in slide-in-from-bottom-4 duration-500">
            <button 
              onClick={() => { setActiveForm('memory'); setShowAddModal(false); }}
              className="px-6 py-3 bg-white rounded-full shadow-lg border border-[#EFEFE9] text-[10px] font-black tracking-[0.2em] uppercase text-[#2A2A28] hover:border-[#8DA399] transition-colors whitespace-nowrap"
            >
              新增回憶
            </button>
            <button 
              onClick={() => { setActiveForm('itinerary'); setShowAddModal(false); }}
              className="px-6 py-3 bg-white rounded-full shadow-lg border border-[#EFEFE9] text-[10px] font-black tracking-[0.2em] uppercase text-[#2A2A28] hover:border-[#8DA399] transition-colors whitespace-nowrap"
            >
              新增行程
            </button>
            <button 
              onClick={() => { setActiveForm('expense'); setShowAddModal(false); }}
              className="px-6 py-3 bg-white rounded-full shadow-lg border border-[#EFEFE9] text-[10px] font-black tracking-[0.2em] uppercase text-[#2A2A28] hover:border-[#8DA399] transition-colors whitespace-nowrap"
            >
              新增支出
            </button>
          </div>
        )}
      </div>

      <Navigation activeTab={activeTab} onTabChange={setActiveTab} />
    </div>
  );
};

export default App;

import React from 'react';
import { 
  Map, 
  BookOpen, 
  CreditCard, 
  Compass, 
  Plus, 
  Calendar, 
  Clock, 
  MapPin, 
  Camera,
  ArrowRight,
  MoreHorizontal,
  Download,
  Printer,
  Share2
} from 'lucide-react';

interface IconProps {
  name: 'itinerary' | 'journal' | 'expenses' | 'trips' | 'plus' | 'calendar' | 'clock' | 'mapPin' | 'camera' | 'arrow' | 'more' | 'download' | 'printer' | 'share';
  size?: number;
  className?: string;
  onClick?: () => void;
}

const Icon: React.FC<IconProps> = ({ name, size = 20, className, onClick }) => {
  const icons = {
    itinerary: Map,
    journal: BookOpen,
    expenses: CreditCard,
    trips: Compass,
    plus: Plus,
    calendar: Calendar,
    clock: Clock,
    mapPin: MapPin,
    camera: Camera,
    arrow: ArrowRight,
    more: MoreHorizontal,
    download: Download,
    printer: Printer,
    share: Share2
  };

  const LucideIcon = icons[name];
  return <LucideIcon size={size} className={className} onClick={onClick} strokeWidth={1.5} />;
};

