import React, { useState } from 'react';
import { Trip, JournalEntry, ItineraryEntry, ExpenseEntry, MemoryEntry } from '../types';
import Icon from './Icon';

interface TripSettingsFormProps {
  trip: Trip;
  onSave: (title: string, start: Date, end: Date) => void;
  onClose: () => void;
}

const TripSettingsForm: React.FC<TripSettingsFormProps> = ({ trip, onSave, onClose }) => {
  const [title, setTitle] = useState(trip.title);
  const [start, setStart] = useState(trip.startDate.toISOString().split('T')[0]);
  const [end, setEnd] = useState(trip.endDate.toISOString().split('T')[0]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave(title, new Date(start), new Date(end));
  };

  const exportToCSV = () => {
    const headers = ['日期', '天數', '類型', '時間/類別', '地點/描述', '金額(JPY)', '筆記/內容'];
    const rows: string[][] = [headers];

    trip.days.forEach(day => {
      const dateStr = day.date.toLocaleDateString('zh-TW');
      day.entries.forEach(entry => {
        let row: string[] = [dateStr, `第 ${day.dayNumber} 天`];

        if (entry.type === 'itinerary') {
          const e = entry as ItineraryEntry;
          row.push('行程', e.time, e.location, '', e.notes || '');
        } else if (entry.type === 'expense') {
          const e = entry as ExpenseEntry;
          row.push('支出', e.category, e.description, e.amount.toString(), '');
        } else if (entry.type === 'memory') {
          const e = entry as MemoryEntry;
          row.push('回憶', e.mood || '', '', '', e.content);
        }

        // Escape CSV special characters
        const escapedRow = row.map(cell => {
          const str = cell.toString().replace(/"/g, '""');
          return `"${str}"`;
        });
        rows.push(escapedRow);
      });
    });

    const csvContent = "\uFEFF" + rows.map(e => e.join(",")).join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `${trip.title}_旅程紀錄.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="fixed inset-0 z-[110] bg-[#FDFDFB] animate-in slide-in-from-bottom duration-500 p-8 flex flex-col overflow-y-auto no-scrollbar print:hidden">
      <div className="flex justify-between items-center mb-12">
        <span className="text-[10px] font-black uppercase tracking-[0.5em] text-[#8DA399]">旅程設定</span>
        <button onClick={onClose} className="p-2 -mr-2">
          <Icon name="plus" size={24} className="rotate-45 text-[#BABAB5]" />
        </button>
      </div>

      <form onSubmit={handleSubmit} className="flex-1 flex flex-col gap-10">
        <div className="space-y-2">
          <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">旅程標題</label>
          <input 
            autoFocus
            type="text" 
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            className="w-full text-3xl serif outline-none bg-transparent border-b border-[#EFEFE9] pb-4 focus:border-[#8DA399] transition-colors"
            placeholder="例如：台北二日遊"
          />
        </div>

        <div className="grid grid-cols-2 gap-8">
          <div className="space-y-2">
            <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">開始日期</label>
            <input 
              type="date" 
              value={start}
              onChange={(e) => setStart(e.target.value)}
              className="w-full text-lg font-light outline-none bg-transparent border-b border-[#EFEFE9] pb-2 focus:border-[#8DA399] transition-colors"
            />
          </div>
          <div className="space-y-2">
            <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">結束日期</label>
            <input 
              type="date" 
              value={end}
              onChange={(e) => setEnd(e.target.value)}
              className="w-full text-lg font-light outline-none bg-transparent border-b border-[#EFEFE9] pb-2 focus:border-[#8DA399] transition-colors"
            />
          </div>
        </div>

        <div className="space-y-6 pt-6 border-t border-[#EFEFE9]">
          <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold block">備份與匯出</label>
          <div className="grid grid-cols-2 gap-4">
            <button 
              type="button"
              onClick={exportToCSV}
              className="flex items-center justify-center gap-3 py-4 border border-[#EFEFE9] rounded-2xl hover:border-[#8DA399] transition-colors group"
            >
              <Icon name="download" size={16} className="text-[#BABAB5] group-hover:text-[#8DA399]" />
              <span className="text-[10px] font-bold uppercase tracking-widest text-[#2A2A28]">匯出 CSV</span>
            </button>
            <button 
              type="button"
              onClick={handlePrint}
              className="flex items-center justify-center gap-3 py-4 border border-[#EFEFE9] rounded-2xl hover:border-[#8DA399] transition-colors group"
            >
              <Icon name="printer" size={16} className="text-[#BABAB5] group-hover:text-[#8DA399]" />
              <span className="text-[10px] font-bold uppercase tracking-widest text-[#2A2A28]">列印 PDF</span>
            </button>
          </div>
        </div>

        <div className="mt-auto pb-10">
          <p className="text-[10px] text-[#BABAB5] mb-6 italic text-center">
            * 更改日期將會根據區間自動調整行程天數。
          </p>
          <button 
            type="submit"
            className="w-full py-5 bg-[#2A2A28] text-white rounded-2xl text-[10px] font-black uppercase tracking-[0.4em] hover:bg-[#8DA399] transition-all shadow-lg active:scale-95"
          >
            儲存變更
          </button>
        </div>
      </form>
    </div>
  );
};

export default TripSettingsForm;

import React, { useState, useEffect } from 'react';
import { AppTab, Trip, JournalEntry, EntryType, MemoryEntry, DayTimeline } from './types';
import { MOCK_TRIP } from './constants';
import DayCard from './components/DayCard';
import Navigation from './components/Navigation';
import Icon from './components/Icon';
import EntryForm from './components/EntryForm';
import TripSettingsForm from './components/TripSettingsForm';
import { polishMemory } from './services/geminiService';

const STORAGE_KEY = 'komorebi_trip_data_v2';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<AppTab>('itinerary');
  const [trip, setTrip] = useState<Trip>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        parsed.startDate = new Date(parsed.startDate);
        parsed.endDate = new Date(parsed.endDate);
        parsed.days = parsed.days.map((d: any) => ({
          ...d,
          date: new Date(d.date),
          entries: d.entries.map((e: any) => ({
            ...e,
            timestamp: new Date(e.timestamp)
          }))
        }));
        return parsed;
      } catch (e) {
        return MOCK_TRIP;
      }
    }
    return MOCK_TRIP;
  });

  const [isScrolled, setIsScrolled] = useState(false);
  const [activeForm, setActiveForm] = useState<EntryType | null>(null);
  const [editingEntry, setEditingEntry] = useState<{ dayId: string; entry: JournalEntry } | null>(null);
  const [showTripSettings, setShowTripSettings] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [loadingAI, setLoadingAI] = useState(false);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(trip));
  }, [trip]);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 40);
    };
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const handleSaveTripSettings = (title: string, start: Date, end: Date) => {
    const newDays: DayTimeline[] = [];
    const diffTime = Math.abs(end.getTime() - start.getTime());
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)) + 1;

    for (let i = 0; i < diffDays; i++) {
      const currentDate = new Date(start);
      currentDate.setDate(start.getDate() + i);

      const existingDay = trip.days.find(d => d.date.toDateString() === currentDate.toDateString());

      newDays.push({
        id: existingDay?.id || `day-${i + 1}-${Date.now()}`,
        date: currentDate,
        dayNumber: i + 1,
        entries: existingDay?.entries || []
      });
    }

    setTrip({
      ...trip,
      title,
      startDate: start,
      endDate: end,
      days: newDays
    });
    setShowTripSettings(false);
  };

  const handleSaveEntry = async (data: Partial<JournalEntry>) => {
    const formType = activeForm || editingEntry?.entry.type;
    if (!formType) return;

    let finalData = { ...data };

    if (formType === 'memory') {
      const memoryData = data as Partial<MemoryEntry>;
      const originalContent = editingEntry?.entry.type === 'memory' ? (editingEntry.entry as MemoryEntry).content : '';

      if (memoryData.content && memoryData.content !== originalContent) {
        setLoadingAI(true);
        const polished = await polishMemory(memoryData.content);
        (finalData as any).content = polished;
        setLoadingAI(false);
      }
    }

    if (editingEntry) {
      const updatedDays = trip.days.map(day => {
        if (day.id === editingEntry.dayId) {
          return {
            ...day,
            entries: day.entries.map(e => e.id === editingEntry.entry.id ? { ...e, ...finalData } : e)
          };
        }
        return day;
      });
      setTrip({ ...trip, days: updatedDays as any });
    } else {
      const newEntry: JournalEntry = {
        id: Date.now().toString(),
        timestamp: new Date(),
        type: formType,
        currency: 'JPY',
        ...finalData
      } as JournalEntry;

      const updatedDays = [...trip.days];
      if (updatedDays.length > 0) {
        updatedDays[0].entries = [newEntry, ...updatedDays[0].entries];
      }
      setTrip({ ...trip, days: updatedDays });
    }

    setActiveForm(null);
    setEditingEntry(null);
  };

  const handleDeleteEntry = (dayId: string, entryId: string) => {
    const updatedDays = trip.days.map(day => {
      if (day.id === dayId) {
        return {
          ...day,
          entries: day.entries.filter(e => e.id !== entryId)
        };
      }
      return day;
    });
    setTrip({ ...trip, days: updatedDays });
  };

  const handleEditEntryTrigger = (dayId: string, entry: JournalEntry) => {
    setEditingEntry({ dayId, entry });
  };

  return (
    <div className="min-h-screen pb-40 max-w-lg mx-auto bg-[#FDFDFB] selection:bg-[#8DA399]/20 print:bg-white print:pb-0">
      {/* Editorial Header */}
      <header 
        onClick={() => !isScrolled && setShowTripSettings(true)}
        className={`sticky top-0 z-40 transition-all duration-700 px-8 flex flex-col justify-end cursor-pointer print:relative print:h-auto print:mb-12 print:border-b-2 print:border-black ${isScrolled ? 'h-24 bg-white/90 backdrop-blur-lg border-b border-[#EFEFE9]' : 'h-48 bg-transparent'}`}
      >
        <div className="flex justify-between items-end pb-6">
          <div className="transition-all duration-700">
            {!isScrolled && (
              <span className="text-[10px] font-bold uppercase tracking-[0.5em] text-[#8DA399] block mb-2 print:block">當前旅程</span>
            )}
            <h1 className={`font-medium tracking-tight text-[#2A2A28] serif transition-all duration-700 ${isScrolled ? 'text-xl' : 'text-4xl'} print:text-4xl`}>
              {trip.title}
            </h1>
            {!isScrolled && (
              <p className="text-xs text-[#8A8A85] mt-3 tracking-wide flex items-center gap-2 print:flex">
                共 {trip.days.length} 天之旅 <span className="opacity-30 print:hidden">|</span> <span className="print:hidden">點擊編輯旅程設定</span>
              </p>
            )}
          </div>
          <button 
            onClick={(e) => { e.stopPropagation(); if(confirm('要重設所有旅程資料嗎？')) { localStorage.removeItem(STORAGE_KEY); window.location.reload(); } }}
            className={`transition-opacity duration-500 p-2 print:hidden ${isScrolled ? 'opacity-100' : 'opacity-40 hover:opacity-100'}`}
          >
            <Icon name="calendar" size={18} className="text-[#BABAB5]" />
          </button>
        </div>
      </header>

      {/* Main Content Area */}
      <main className="px-8 mt-10 print:mt-4">
        {activeTab === 'itinerary' && (
          <div className="animate-in fade-in duration-1000">
            {trip.days.map((day) => (
              <DayCard 
                key={day.id} 
                day={day} 
                onDeleteEntry={handleDeleteEntry} 
                onEditEntry={handleEditEntryTrigger} 
              />
            ))}
          </div>
        )}

        {activeTab === 'journal' && (
          <div className="animate-in fade-in slide-in-from-bottom-2 duration-700 print:block">
            <h2 className="text-xs font-black uppercase tracking-[0.4em] text-[#8A8A85] mb-12 border-b border-[#EFEFE9] pb-4 print:text-black">反思與札記</h2>
            <div className="space-y-16">
              {trip.days.flatMap(d => d.entries.map(e => ({ ...e, dayId: d.id }))).filter(e => e.type === 'memory').map((entry: any) => (
                <div 
                  key={entry.id} 
                  onClick={() => handleEditEntryTrigger(entry.dayId, entry)}
                  className="group relative cursor-pointer active:opacity-60 transition-opacity print:page-break-inside-avoid"
                >
                  <p className="serif text-xl leading-relaxed text-[#2A2A28] italic">「{entry.content}」</p>
                  <div className="flex items-center gap-4 mt-6">
                    <span className="text-[9px] font-bold uppercase tracking-widest text-[#8DA399] print:text-black">
                      {entry.mood || '記事'}
                    </span>
                    <div className="h-[1px] flex-1 bg-[#EFEFE9] print:bg-black/10" />
                    <button 
                      onClick={(e) => { e.stopPropagation(); handleDeleteEntry(entry.dayId, entry.id); }} 
                      className="text-[#BABAB5] hover:text-[#2A2A28] p-1 print:hidden"
                    >
                      <Icon name="plus" size={14} className="rotate-45" />
                    </button>
                  </div>
                </div>
              ))}
              {trip.days.flatMap(d => d.entries).filter(e => e.type === 'memory').length === 0 && (
                <p className="text-center text-sm text-[#BABAB5] italic py-20">還沒有留下任何心情筆記...</p>
              )}
            </div>
          </div>
        )}

        {activeTab === 'expenses' && (
          <div className="animate-in fade-in slide-in-from-bottom-2 duration-700 print:block">
             <h2 className="text-xs font-black uppercase tracking-[0.4em] text-[#8A8A85] mb-12 border-b border-[#EFEFE9] pb-4 print:text-black">支出明細</h2>
             <div className="space-y-10">
                {trip.days.map(day => {
                  const dayExpense = day.entries.filter(e => e.type === 'expense');
                  if (dayExpense.length === 0) return null;
                  return (
                    <div key={day.id} className="print:page-break-inside-avoid">
                      <span className="text-[10px] font-black uppercase tracking-widest text-[#2A2A28] mb-4 block">第 {day.dayNumber} 天</span>
                      {dayExpense.map((e: any) => (
                        <div 
                          key={e.id} 
                          onClick={() => handleEditEntryTrigger(day.id, e)}
                          className="flex justify-between py-3 border-b border-[#EFEFE9] last:border-0 group cursor-pointer active:opacity-60 transition-opacity print:border-black/5"
                        >
                          <span className="text-sm font-light text-[#2A2A28]">{e.description}</span>
                          <div className="flex items-center gap-4">
                            <span className="text-sm font-medium tabular-nums">{e.amount.toLocaleString()} JPY</span>
                            <button 
                              onClick={(event) => { event.stopPropagation(); handleDeleteEntry(day.id, e.id); }} 
                              className="opacity-0 group-hover:opacity-100 text-[#BABAB5] hover:text-black p-1 print:hidden"
                            >
                              <Icon name="plus" size={14} className="rotate-45" />
                            </button>
                          </div>
                        </div>
                      ))}
                    </div>
                  );
                })}
                {trip.days.every(d => d.entries.filter(e => e.type === 'expense').length === 0) && (
                  <p className="text-center text-sm text-[#BABAB5] italic py-20">目前沒有任何開支紀錄。</p>
                )}
             </div>
          </div>
        )}

        {activeTab === 'trips' && (
           <div className="animate-in fade-in slide-in-from-bottom-2 duration-700 flex flex-col items-center justify-center py-40 border border-[#EFEFE9] rounded-[40px] bg-white/40 print:hidden">
              <span className="text-[10px] uppercase tracking-[0.4em] text-[#BABAB5] font-bold serif italic">尚未有其他歷史典藏</span>
           </div>
        )}
      </main>

      {/* AI Loader */}
      {loadingAI && (
        <div className="fixed inset-0 bg-white/80 backdrop-blur-xl z-[200] flex flex-col items-center justify-center print:hidden">
          <div className="w-10 h-10 border border-[#2A2A28]/10 border-t-[#8DA399] rounded-full animate-spin mb-6" />
          <p className="serif italic text-sm tracking-wide text-[#2A2A28]">正在修飾您的回憶...</p>
        </div>
      )}

      {/* Input Overlay (Edit or Add) */}
      {(activeForm || editingEntry) && (
        <EntryForm 
          type={activeForm || editingEntry!.entry.type} 
          initialData={editingEntry?.entry}
          onClose={() => { setActiveForm(null); setEditingEntry(null); }} 
          onSave={handleSaveEntry} 
        />
      )}

      {/* Trip Settings Overlay */}
      {showTripSettings && (
        <TripSettingsForm 
          trip={trip} 
          onClose={() => setShowTripSettings(false)} 
          onSave={handleSaveTripSettings} 
        />
      )}

      {/* Simple Floating Trigger */}
      <div className="fixed bottom-36 right-10 z-50 print:hidden">
        <button 
          onClick={() => setShowAddModal(!showAddModal)}
          className={`w-14 h-14 rounded-full bg-[#2A2A28] text-white flex items-center justify-center shadow-2xl transition-all duration-500 hover:bg-[#8DA399] ${showAddModal ? 'rotate-45' : ''}`}
        >
          <Icon name="plus" size={24} />
        </button>

        {showAddModal && (
          <div className="absolute bottom-20 right-0 space-y-4 flex flex-col items-end animate-in fade-in slide-in-from-bottom-4 duration-500">
            <button 
              onClick={() => { setActiveForm('memory'); setShowAddModal(false); }}
              className="px-6 py-3 bg-white rounded-full shadow-lg border border-[#EFEFE9] text-[10px] font-black tracking-[0.2em] uppercase text-[#2A2A28] hover:border-[#8DA399] transition-colors whitespace-nowrap"
            >
              新增回憶
            </button>
            <button 
              onClick={() => { setActiveForm('itinerary'); setShowAddModal(false); }}
              className="px-6 py-3 bg-white rounded-full shadow-lg border border-[#EFEFE9] text-[10px] font-black tracking-[0.2em] uppercase text-[#2A2A28] hover:border-[#8DA399] transition-colors whitespace-nowrap"
            >
              新增行程
            </button>
            <button 
              onClick={() => { setActiveForm('expense'); setShowAddModal(false); }}
              className="px-6 py-3 bg-white rounded-full shadow-lg border border-[#EFEFE9] text-[10px] font-black tracking-[0.2em] uppercase text-[#2A2A28] hover:border-[#8DA399] transition-colors whitespace-nowrap"
            >
              新增支出
            </button>
          </div>
        )}
      </div>

      <Navigation activeTab={activeTab} onTabChange={setActiveTab} />
    </div>
  );
};

export default App;

export type EntryType = 'itinerary' | 'expense' | 'memory';

export interface BaseEntry {
  id: string;
  timestamp: Date;
  type: EntryType;
}

export interface ItineraryEntry extends BaseEntry {
  type: 'itinerary';
  time: string;
  location: string;
  notes?: string;
  // 整合支出欄位
  expenseAmount?: number;
  expenseCategory?: string;
}

export interface ExpenseEntry extends BaseEntry {
  type: 'expense';
  amount: number;
  category: string;
  currency: string;
  description: string;
}

export interface MemoryEntry extends BaseEntry {
  type: 'memory';
  content: string;
  imageUrl?: string;
  mood?: string;
}

export type JournalEntry = ItineraryEntry | ExpenseEntry | MemoryEntry;

export interface DayTimeline {
  id: string;
  date: Date;
  dayNumber: number;
  entries: JournalEntry[];
}

export interface Trip {
  id: string;
  title: string;
  startDate: Date;
  endDate: Date;
  coverImage?: string;
  days: DayTimeline[];
}

export type AppTab = 'itinerary' | 'journal' | 'expenses' | 'trips';

import React, { useState, useEffect } from 'react';
import { EntryType, JournalEntry, ItineraryEntry } from '../types';
import Icon from './Icon';

interface EntryFormProps {
  type: EntryType;
  initialData?: Partial<JournalEntry>;
  onSave: (data: Partial<JournalEntry>) => void;
  onClose: () => void;
}

const EntryForm: React.FC<EntryFormProps> = ({ type, initialData, onSave, onClose }) => {
  const getCurrentTime = () => {
    const now = new Date();
    return now.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: true });
  };

  const [formData, setFormData] = useState<any>({
    time: getCurrentTime(),
    location: '',
    notes: '',
    expenseAmount: '',
    expenseCategory: '餐飲',
    amount: '',
    category: '餐飲',
    description: '',
    content: '',
    mood: '平靜'
  });

  useEffect(() => {
    if (initialData) {
      setFormData((prev: any) => ({
        ...prev,
        ...initialData
      }));
    }
  }, [initialData]);

  const isEdit = !!initialData?.id;

  const typeLabels = {
    itinerary: isEdit ? '編輯事件' : '新增行程事件',
    expense: isEdit ? '編輯支出' : '記錄額外支出',
    memory: isEdit ? '編輯回憶' : '捕捉此刻回憶'
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const dataToSave = { ...formData };
    // 轉換數字型態
    if (dataToSave.expenseAmount) dataToSave.expenseAmount = parseFloat(dataToSave.expenseAmount);
    if (dataToSave.amount) dataToSave.amount = parseFloat(dataToSave.amount);

    onSave(dataToSave);
  };

  return (
    <div className="fixed inset-0 z-[100] bg-white animate-in slide-in-from-bottom duration-500 p-8 flex flex-col overflow-y-auto no-scrollbar">
      <div className="flex justify-between items-center mb-12">
        <span className="text-[10px] font-black uppercase tracking-[0.5em] text-[#8DA399]">{typeLabels[type]}</span>
        <button onClick={onClose} className="p-2 -mr-2">
          <Icon name="plus" size={24} className="rotate-45 text-[#BABAB5]" />
        </button>
      </div>

      <form onSubmit={handleSubmit} className="flex-1 flex flex-col gap-8">
        {type === 'itinerary' && (
          <>
            <div className="grid grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">時間</label>
                <input 
                  type="text" 
                  value={formData.time}
                  onChange={(e) => setFormData({...formData, time: e.target.value})}
                  className="w-full text-xl font-medium outline-none bg-transparent border-b border-[#EFEFE9] pb-2 focus:border-[#8DA399] transition-colors"
                  placeholder="12:00 PM"
                />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">支出金額 (JPY)</label>
                <input 
                  type="number" 
                  value={formData.expenseAmount}
                  onChange={(e) => setFormData({...formData, expenseAmount: e.target.value})}
                  className="w-full text-xl font-medium outline-none bg-transparent border-b border-[#EFEFE9] pb-2 focus:border-[#8DA399] transition-colors"
                  placeholder="可選填"
                />
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">地點 / 活動</label>
              <input 
                autoFocus
                type="text" 
                value={formData.location}
                onChange={(e) => setFormData({...formData, location: e.target.value})}
                className="w-full text-2xl font-medium outline-none bg-transparent border-b border-[#EFEFE9] pb-2 focus:border-[#8DA399] transition-colors"
                placeholder="目的地或活動名稱"
              />
            </div>

            <div className="space-y-2">
              <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">備註說明</label>
              <textarea 
                value={formData.notes}
                onChange={(e) => setFormData({...formData, notes: e.target.value})}
                className="w-full text-sm font-light outline-none bg-transparent border-b border-[#EFEFE9] pb-2 min-h-[80px] resize-none focus:border-[#8DA399] transition-colors"
                placeholder="寫下一些細節..."
              />
            </div>
          </>
        )}

        {/* 保持其他表單類型簡單 */}
        {type === 'expense' && (
           <div className="space-y-8">
              <div className="space-y-2">
                <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">金額 (JPY)</label>
                <input type="number" value={formData.amount} onChange={(e) => setFormData({...formData, amount: e.target.value})} className="w-full text-4xl font-light outline-none border-b border-[#EFEFE9] pb-2" placeholder="0" />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">描述</label>
                <input type="text" value={formData.description} onChange={(e) => setFormData({...formData, description: e.target.value})} className="w-full text-2xl font-medium outline-none border-b border-[#EFEFE9] pb-2" placeholder="支出項目" />
              </div>
