        {type === 'memory' && (
           <div className="space-y-4">
              <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">此刻的感觸</label>
              <textarea autoFocus value={formData.content} onChange={(e) => setFormData({...formData, content: e.target.value})} className="w-full text-xl serif italic leading-relaxed outline-none min-h-[200px] resize-none" placeholder="寫下你的感覺..." />
           </div>
