import React from 'react';
import { JournalEntry, ItineraryEntry, ExpenseEntry, MemoryEntry } from '../types';
import Icon from './Icon';

interface EntryItemProps {
  entry: JournalEntry;
  onDelete?: (id: string) => void;
  onEdit?: (entry: JournalEntry) => void;
}

const EntryItem: React.FC<EntryItemProps> = ({ entry, onDelete, onEdit }) => {
  const handleDelete = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (onDelete && confirm('確定要刪除這筆紀錄嗎？')) {
      onDelete(entry.id);
    }
  };

  const handleEdit = () => {
    if (onEdit) onEdit(entry);
  };

  if (entry.type === 'itinerary') {
    const item = entry as ItineraryEntry;
    return (
      <div 
        onClick={handleEdit}
        className="relative pl-12 mb-10 group cursor-pointer active:opacity-70 transition-all"
      >
        {/* Timeline Indicator */}
        <div className="absolute left-[3px] top-2 w-[10px] h-[10px] rounded-full bg-white border-2 border-[#8DA399] z-10" />

        <div className="bg-white rounded-2xl p-5 border border-[#EFEFE9] shadow-sm hover:shadow-md transition-shadow relative">
          <div className="flex justify-between items-start mb-2">
            <span className="text-[10px] font-bold text-[#8DA399] tracking-widest uppercase">{item.time}</span>
            {item.expenseAmount ? (
              <span className="bg-[#F8F8F5] px-3 py-1 rounded-full text-[10px] font-bold text-[#2A2A28] tabular-nums">
                ¥{item.expenseAmount.toLocaleString()}
              </span>
            ) : null}
          </div>

          <h4 className="text-base font-semibold text-[#2A2A28] mb-1">{item.location}</h4>
          {item.notes && <p className="text-xs text-[#8A8A85] leading-relaxed font-light line-clamp-2">{item.notes}</p>}

          <button 
            onClick={handleDelete}
            className="absolute -right-2 -top-2 bg-white rounded-full shadow-md opacity-0 group-hover:opacity-100 transition-opacity text-[#BABAB5] hover:text-red-400 p-1 border border-[#EFEFE9]"
          >
            <Icon name="plus" size={14} className="rotate-45" />
          </button>
        </div>
      </div>
    );
  }

  // 其他類型（回憶、獨立支出）保持美觀
  if (entry.type === 'memory') {
    const item = entry as MemoryEntry;
    return (
      <div onClick={handleEdit} className="my-12 px-6 relative cursor-pointer group">
        <div className="h-[1px] w-full bg-[#EFEFE9] absolute top-1/2 left-0 -z-10" />
        <div className="bg-[#FDFDFB] px-4 mx-auto max-w-[90%] text-center">
          <p className="text-base leading-relaxed text-[#2A2A28] serif italic italic-font">「{item.content}」</p>
          <span className="text-[9px] uppercase tracking-[0.3em] text-[#8DA399] font-bold mt-4 block">{item.mood || '記事'}</span>
        </div>
        <button onClick={handleDelete} className="absolute right-0 top-0 opacity-0 group-hover:opacity-100 p-2 text-[#BABAB5]"><Icon name="plus" size={14} className="rotate-45" /></button>
      </div>
    );
  }

  // 如果是獨立的支出（舊資料），仍然顯示
  if (entry.type === 'expense') {
    const item = entry as ExpenseEntry;
    return (
      <div onClick={handleEdit} className="flex justify-between items-center py-4 px-5 border border-dashed border-[#EFEFE9] rounded-2xl mb-4 group cursor-pointer">
        <div>
          <span className="text-[9px] text-[#8DA399] font-bold uppercase block">{item.category}</span>
          <span className="text-sm font-medium">{item.description}</span>
        </div>
        <div className="flex items-center gap-4">
          <span className="text-sm font-bold">¥{item.amount.toLocaleString()}</span>
          <button onClick={handleDelete} className="opacity-0 group-hover:opacity-100 p-1 text-[#BABAB5]"><Icon name="plus" size={14} className="rotate-45" /></button>
        </div>
      </div>
    );
  }

  return null;
};

export default EntryItem;

import React from 'react';
import { DayTimeline, JournalEntry, ItineraryEntry, ExpenseEntry } from '../types';
import EntryItem from './EntryItem';
import Icon from './Icon';

interface DayCardProps {
  day: DayTimeline;
  onDeleteEntry: (dayId: string, entryId: string) => void;
  onEditEntry: (dayId: string, entry: JournalEntry) => void;
}

const DayCard: React.FC<DayCardProps> = ({ day, onDeleteEntry, onEditEntry }) => {
  const formattedDate = day.date.toLocaleDateString('zh-TW', {
    month: 'long',
    day: 'numeric',
  });

  const weekday = day.date.toLocaleDateString('zh-TW', { weekday: 'long' });

  // 計算當日總支出 (包含行程內的支出與獨立支出)
  const totalExpense = day.entries.reduce((sum, entry) => {
    if (entry.type === 'itinerary') {
      return sum + ((entry as ItineraryEntry).expenseAmount || 0);
    } else if (entry.type === 'expense') {
      return sum + (entry as ExpenseEntry).amount;
    }
    return sum;
  }, 0);

  return (
    <div className="mb-20 last:mb-0 fade-in-section">
      {/* Date Header */}
      <div className="mb-10 pl-2">
        <div className="flex items-center gap-4 mb-2">
          <span className="text-[11px] font-black uppercase tracking-[0.4em] text-[#2A2A28]">DAY {day.dayNumber}</span>
          <div className="h-[1px] flex-1 bg-[#2A2A28]/10" />
        </div>
        <h2 className="text-3xl font-medium tracking-tight serif text-[#2A2A28]">{formattedDate}</h2>
        <p className="text-[10px] uppercase tracking-widest text-[#8A8A85] font-medium mt-1">{weekday}</p>
      </div>

      {/* Timeline Container */}
      <div className="relative pl-1">
        {/* Vertical Line */}
        {day.entries.filter(e => e.type === 'itinerary').length > 0 && (
          <div className="absolute left-[7px] top-2 bottom-8 w-[2px] bg-[#EFEFE9]" />
        )}

        {day.entries.length === 0 ? (
          <div className="ml-12 py-16 flex flex-col items-center justify-center text-[#8A8A85] border border-dashed border-[#EFEFE9] rounded-[32px] bg-white/40">
            <Icon name="plus" size={20} className="mb-3 opacity-30" />
            <span className="text-[10px] tracking-[0.3em] uppercase font-bold">目前沒有任何行程</span>
          </div>
        ) : (
          <div className="flex flex-col">
            {day.entries.map((entry) => (
              <EntryItem 
                key={entry.id} 
                entry={entry} 
                onDelete={(entryId) => onDeleteEntry(day.id, entryId)}
                onEdit={(entryData) => onEditEntry(day.id, entryData)}
              />
            ))}
          </div>
        )}
      </div>

      {/* Daily Summary Footer */}
      {totalExpense > 0 && (
        <div className="mt-4 ml-12 py-4 px-6 bg-[#F8F8F5] rounded-2xl flex justify-between items-center border border-[#EFEFE9]/50">
          <span className="text-[10px] font-black uppercase tracking-[0.3em] text-[#8DA399]">Today Total</span>
          <span className="text-base font-bold text-[#2A2A28] tabular-nums">¥ {totalExpense.toLocaleString()}</span>
        </div>
      )}
    </div>
  );
};

export default DayCard;

import React, { useState, useEffect } from 'react';
import { AppTab, Trip, JournalEntry, EntryType, MemoryEntry, DayTimeline, ItineraryEntry } from './types';
import { MOCK_TRIP } from './constants';
import DayCard from './components/DayCard';
import Navigation from './components/Navigation';
import Icon from './components/Icon';
import EntryForm from './components/EntryForm';
import TripSettingsForm from './components/TripSettingsForm';
import { polishMemory } from './services/geminiService';

const STORAGE_KEY = 'komorebi_trip_data_v3'; // Version bump for data structure change

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<AppTab>('itinerary');
  const [trip, setTrip] = useState<Trip>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        parsed.startDate = new Date(parsed.startDate);
        parsed.endDate = new Date(parsed.endDate);
        parsed.days = parsed.days.map((d: any) => ({
          ...d,
          date: new Date(d.date),
          entries: d.entries.map((e: any) => ({
            ...e,
            timestamp: new Date(e.timestamp)
          }))
        }));
        return parsed;
      } catch (e) {
        return MOCK_TRIP;
      }
    }
    return MOCK_TRIP;
  });

  const [isScrolled, setIsScrolled] = useState(false);
  const [activeForm, setActiveForm] = useState<EntryType | null>(null);
  const [editingEntry, setEditingEntry] = useState<{ dayId: string; entry: JournalEntry } | null>(null);
  const [showTripSettings, setShowTripSettings] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [loadingAI, setLoadingAI] = useState(false);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(trip));
  }, [trip]);

  useEffect(() => {
    const handleScroll = () => setIsScrolled(window.scrollY > 40);
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const handleSaveTripSettings = (title: string, start: Date, end: Date) => {
    const newDays: DayTimeline[] = [];
    const diffDays = Math.ceil(Math.abs(end.getTime() - start.getTime()) / (1000 * 60 * 60 * 24)) + 1;

    for (let i = 0; i < diffDays; i++) {
      const currentDate = new Date(start);
      currentDate.setDate(start.getDate() + i);
      const existingDay = trip.days.find(d => d.date.toDateString() === currentDate.toDateString());
      newDays.push({
        id: existingDay?.id || `day-${i + 1}-${Date.now()}`,
        date: currentDate,
        dayNumber: i + 1,
        entries: existingDay?.entries || []
      });
    }

    setTrip({ ...trip, title, startDate: start, endDate: end, days: newDays });
    setShowTripSettings(false);
  };

  const handleSaveEntry = async (data: Partial<JournalEntry>) => {
    const formType = activeForm || editingEntry?.entry.type;
    if (!formType) return;

    let finalData = { ...data };

    if (formType === 'memory') {
      const memoryData = data as Partial<MemoryEntry>;
      const originalContent = editingEntry?.entry.type === 'memory' ? (editingEntry.entry as MemoryEntry).content : '';
      if (memoryData.content && memoryData.content !== originalContent) {
        setLoadingAI(true);
        const polished = await polishMemory(memoryData.content);
        (finalData as any).content = polished;
        setLoadingAI(false);
      }
    }

    if (editingEntry) {
      const updatedDays = trip.days.map(day => {
        if (day.id === editingEntry.dayId) {
          return {
            ...day,
            entries: day.entries.map(e => e.id === editingEntry.entry.id ? { ...e, ...finalData } : e)
          };
        }
        return day;
      });
      setTrip({ ...trip, days: updatedDays as any });
    } else {
      const newEntry: JournalEntry = {
        id: Date.now().toString(),
        timestamp: new Date(),
        type: formType,
        currency: 'JPY',
        ...finalData
      } as JournalEntry;

      const updatedDays = [...trip.days];
      if (updatedDays.length > 0) {
        // 排序行程：按時間字串簡單排序
        const dayToUpdate = updatedDays[0];
        dayToUpdate.entries = [...dayToUpdate.entries, newEntry].sort((a, b) => {
          if (a.type === 'itinerary' && b.type === 'itinerary') {
             return (a as ItineraryEntry).time.localeCompare((b as ItineraryEntry).time);
          }
          return 0;
        });
      }
      setTrip({ ...trip, days: updatedDays });
    }

    setActiveForm(null);
    setEditingEntry(null);
  };

  const handleDeleteEntry = (dayId: string, entryId: string) => {
    const updatedDays = trip.days.map(day => {
      if (day.id === dayId) {
        return { ...day, entries: day.entries.filter(e => e.id !== entryId) };
      }
      return day;
    });
    setTrip({ ...trip, days: updatedDays });
  };

  const handleEditEntryTrigger = (dayId: string, entry: JournalEntry) => {
    setEditingEntry({ dayId, entry });
  };

  return (
    <div className="min-h-screen pb-40 max-w-lg mx-auto bg-[#FDFDFB] selection:bg-[#8DA399]/20 print:bg-white print:pb-0">
      <header 
        onClick={() => !isScrolled && setShowTripSettings(true)}
        className={`sticky top-0 z-40 transition-all duration-700 px-8 flex flex-col justify-end cursor-pointer print:relative print:mb-12 print:border-b-2 print:border-black ${isScrolled ? 'h-24 bg-white/95 backdrop-blur-lg border-b border-[#EFEFE9]' : 'h-48 bg-transparent'}`}
      >
        <div className="flex justify-between items-end pb-6">
          <div className="transition-all duration-700">
            {!isScrolled && <span className="text-[10px] font-bold uppercase tracking-[0.5em] text-[#8DA399] block mb-2">My Journey</span>}
            <h1 className={`font-semibold tracking-tight text-[#2A2A28] serif transition-all duration-700 ${isScrolled ? 'text-xl' : 'text-4xl'}`}>
              {trip.title}
            </h1>
            {!isScrolled && <p className="text-[11px] text-[#8A8A85] mt-3 tracking-wide font-medium">EXPLORING — {trip.days.length} DAYS</p>}
          </div>
          <button onClick={(e) => { e.stopPropagation(); if(confirm('重設所有資料？')) { localStorage.removeItem(STORAGE_KEY); window.location.reload(); } }} className="p-2 opacity-40 hover:opacity-100 print:hidden transition-opacity">
            <Icon name="calendar" size={18} />
          </button>
        </div>
      </header>

      <main className="px-6 mt-10 print:mt-4">
        {activeTab === 'itinerary' && (
          <div className="animate-in fade-in duration-700">
            {trip.days.map((day) => (
              <DayCard key={day.id} day={day} onDeleteEntry={handleDeleteEntry} onEditEntry={handleEditEntryTrigger} />
            ))}
          </div>
        )}

        {activeTab === 'journal' && (
          <div className="animate-in fade-in slide-in-from-bottom-2 duration-700">
            <h2 className="text-[10px] font-black uppercase tracking-[0.4em] text-[#8A8A85] mb-12 border-b border-[#EFEFE9] pb-4">Memories & Reflections</h2>
            <div className="space-y-16">
              {trip.days.flatMap(d => d.entries.map(e => ({ ...e, dayId: d.id }))).filter(e => e.type === 'memory').map((entry: any) => (
                <div key={entry.id} onClick={() => handleEditEntryTrigger(entry.dayId, entry)} className="cursor-pointer active:opacity-60 transition-opacity">
                  <p className="serif text-xl leading-relaxed text-[#2A2A28] italic text-center">「{entry.content}」</p>
                  <div className="flex items-center gap-4 mt-8">
                     <div className="h-[1px] flex-1 bg-[#EFEFE9]" />
                     <span className="text-[9px] font-bold uppercase tracking-widest text-[#8DA399]">{entry.mood || '記事'}</span>
                     <div className="h-[1px] flex-1 bg-[#EFEFE9]" />
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'expenses' && (
           <div className="animate-in fade-in slide-in-from-bottom-2 duration-700">
              <h2 className="text-[10px] font-black uppercase tracking-[0.4em] text-[#8A8A85] mb-12 border-b border-[#EFEFE9] pb-4">Finance Overview</h2>
              {trip.days.map(day => {
                const dayExpenses = day.entries.filter(e => (e.type === 'itinerary' && (e as ItineraryEntry).expenseAmount) || e.type === 'expense');
                if (dayExpenses.length === 0) return null;
                return (
                  <div key={day.id} className="mb-10">
                    <span className="text-[10px] font-black text-[#2A2A28] mb-4 block uppercase tracking-widest">DAY {day.dayNumber}</span>
                    {dayExpenses.map((e: any) => (
                      <div key={e.id} onClick={() => handleEditEntryTrigger(day.id, e)} className="flex justify-between py-4 border-b border-[#EFEFE9] last:border-0 cursor-pointer">
                        <span className="text-sm font-medium text-[#2A2A28]">{e.type === 'itinerary' ? e.location : e.description}</span>
                        <span className="text-sm font-bold tabular-nums">¥ {(e.expenseAmount || e.amount).toLocaleString()}</span>
                      </div>
                    ))}
                  </div>
                );
              })}
           </div>
        )}

        {activeTab === 'trips' && (
           <div className="py-40 text-center text-[#BABAB5] border border-dashed border-[#EFEFE9] rounded-[40px]">
              <span className="text-[10px] font-bold uppercase tracking-widest">No Archived Trips Yet</span>
           </div>
        )}
      </main>

      {(activeForm || editingEntry) && (
        <EntryForm 
          type={activeForm || editingEntry!.entry.type} 
          initialData={editingEntry?.entry}
          onClose={() => { setActiveForm(null); setEditingEntry(null); }} 
          onSave={handleSaveEntry} 
        />
      )}

      {showTripSettings && <TripSettingsForm trip={trip} onClose={() => setShowTripSettings(false)} onSave={handleSaveTripSettings} />}

      {loadingAI && (
        <div className="fixed inset-0 bg-white/80 backdrop-blur-xl z-[200] flex flex-col items-center justify-center">
          <div className="w-8 h-8 border-2 border-[#8DA399] border-t-transparent rounded-full animate-spin mb-4" />
          <p className="serif italic text-sm text-[#2A2A28]">Polishing your thoughts...</p>
        </div>
      )}

      <div className="fixed bottom-36 right-8 z-50 print:hidden">
        <button onClick={() => setShowAddModal(!showAddModal)} className={`w-14 h-14 rounded-full bg-[#2A2A28] text-white flex items-center justify-center shadow-xl transition-all duration-500 ${showAddModal ? 'rotate-45 bg-[#8DA399]' : ''}`}>
          <Icon name="plus" size={24} />
        </button>
        {showAddModal && (
          <div className="absolute bottom-20 right-0 space-y-3 flex flex-col items-end animate-in fade-in slide-in-from-bottom-4 duration-300">
            <button onClick={() => { setActiveForm('itinerary'); setShowAddModal(false); }} className="px-6 py-3 bg-white rounded-full shadow-lg border border-[#EFEFE9] text-[10px] font-black uppercase tracking-widest hover:border-[#8DA399] transition-colors">行程事件</button>
            <button onClick={() => { setActiveForm('memory'); setShowAddModal(false); }} className="px-6 py-3 bg-white rounded-full shadow-lg border border-[#EFEFE9] text-[10px] font-black uppercase tracking-widest hover:border-[#8DA399] transition-colors">心情回憶</button>
          </div>
        )}
      </div>

      <Navigation activeTab={activeTab} onTabChange={setActiveTab} />
    </div>
  );
};

export default App;

export type EntryType = 'itinerary' | 'expense';

export interface BaseEntry {
  id: string;
  timestamp: Date;
  type: EntryType;
}

export interface ItineraryEntry extends BaseEntry {
  type: 'itinerary';
  time: string;
  location: string;
  notes?: string;
  expenseAmount?: number;
  expenseCategory?: string;
  // 整合回憶欄位
  reflection?: string;
}

export interface ExpenseEntry extends BaseEntry {
  type: 'expense';
  amount: number;
  category: string;
  currency: string;
  description: string;
}

export type JournalEntry = ItineraryEntry | ExpenseEntry;

export interface DayTimeline {
  id: string;
  date: Date;
  dayNumber: number;
  entries: JournalEntry[];
}

export interface Trip {
  id: string;
  title: string;
  startDate: Date;
  endDate: Date;
  coverImage?: string;
  days: DayTimeline[];
}

export type AppTab = 'itinerary' | 'expenses' | 'trips';

import React, { useState, useEffect } from 'react';
import { EntryType, JournalEntry, ItineraryEntry } from '../types';
import Icon from './Icon';
import { polishMemory } from '../services/geminiService';

interface EntryFormProps {
  type: EntryType;
  initialData?: Partial<JournalEntry>;
  onSave: (data: Partial<JournalEntry>) => void;
  onClose: () => void;
}

const EntryForm: React.FC<EntryFormProps> = ({ type, initialData, onSave, onClose }) => {
  const getCurrentTime = () => {
    const now = new Date();
    return now.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: true });
  };

  const [formData, setFormData] = useState<any>({
    time: getCurrentTime(),
    location: '',
    notes: '',
    expenseAmount: '',
    expenseCategory: '餐飲',
    reflection: '',
    amount: '',
    category: '餐飲',
    description: ''
  });

  const [isPolishing, setIsPolishing] = useState(false);

  useEffect(() => {
    if (initialData) {
      setFormData((prev: any) => ({
        ...prev,
        ...initialData
      }));
    }
  }, [initialData]);

  const handleAIAction = async () => {
    if (!formData.reflection || isPolishing) return;
    setIsPolishing(true);
    const polished = await polishMemory(formData.reflection);
    setFormData({ ...formData, reflection: polished });
    setIsPolishing(false);
  };

  const isEdit = !!initialData?.id;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const dataToSave = { ...formData };
    if (dataToSave.expenseAmount) dataToSave.expenseAmount = parseFloat(dataToSave.expenseAmount);
    if (dataToSave.amount) dataToSave.amount = parseFloat(dataToSave.amount);
    onSave(dataToSave);
  };

  return (
    <div className="fixed inset-0 z-[100] bg-[#FDFDFB] animate-in slide-in-from-bottom duration-500 p-8 flex flex-col overflow-y-auto no-scrollbar">
      <div className="flex justify-between items-center mb-10">
        <span className="text-[10px] font-black uppercase tracking-[0.5em] text-[#8DA399]">
          {isEdit ? '編輯紀錄' : '新增紀錄'}
        </span>
        <button onClick={onClose} className="p-2 -mr-2 text-[#BABAB5]">
          <Icon name="plus" size={24} className="rotate-45" />
        </button>
      </div>

      <form onSubmit={handleSubmit} className="flex-1 flex flex-col gap-8">
        {type === 'itinerary' ? (
          <>
            <div className="grid grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">時間</label>
                <input 
                  type="text" 
                  value={formData.time}
                  onChange={(e) => setFormData({...formData, time: e.target.value})}
                  className="w-full text-lg font-medium outline-none bg-transparent border-b border-[#EFEFE9] pb-2 focus:border-[#8DA399] transition-colors"
                  placeholder="12:00 PM"
                />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">支出 (JPY)</label>
                <input 
                  type="number" 
                  value={formData.expenseAmount}
                  onChange={(e) => setFormData({...formData, expenseAmount: e.target.value})}
                  className="w-full text-lg font-medium outline-none bg-transparent border-b border-[#EFEFE9] pb-2 focus:border-[#8DA399] transition-colors"
                  placeholder="選填"
                />
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">地點 / 活動</label>
              <input 
                autoFocus
                type="text" 
                value={formData.location}
                onChange={(e) => setFormData({...formData, location: e.target.value})}
                className="w-full text-2xl font-medium outline-none bg-transparent border-b border-[#EFEFE9] pb-2 focus:border-[#8DA399] transition-colors"
                placeholder="目的地"
              />
            </div>

            <div className="space-y-2">
              <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">一般備註</label>
              <input 
                type="text"
                value={formData.notes}
                onChange={(e) => setFormData({...formData, notes: e.target.value})}
                className="w-full text-sm font-light outline-none bg-transparent border-b border-[#EFEFE9] pb-2 focus:border-[#8DA399] transition-colors"
                placeholder="簡單備註..."
              />
            </div>

            <div className="space-y-3 pt-4 border-t border-[#EFEFE9]">
              <div className="flex justify-between items-center">
                <label className="text-[10px] uppercase tracking-widest text-[#8DA399] font-bold">此刻的感觸回憶</label>
                <button 
                  type="button"
                  onClick={handleAIAction}
                  disabled={!formData.reflection || isPolishing}
                  className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full text-[9px] font-bold tracking-widest uppercase transition-all ${isPolishing ? 'bg-[#F0F0F0] text-[#BABAB5]' : 'bg-[#8DA399]/10 text-[#8DA399] hover:bg-[#8DA399] hover:text-white'}`}
                >
                  {isPolishing ? 'AI 修飾中...' : 'AI 修飾文筆'}
                </button>
              </div>
              <textarea 
                value={formData.reflection}
                onChange={(e) => setFormData({...formData, reflection: e.target.value})}
                className="w-full text-lg serif italic leading-relaxed outline-none bg-transparent min-h-[120px] resize-none border-none p-0 focus:ring-0"
                placeholder="在這裡寫下你的心情筆記..."
              />
            </div>
          </>
        ) : (
          <div className="space-y-8">
             <div className="space-y-2">
               <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">金額 (JPY)</label>
               <input type="number" value={formData.amount} onChange={(e) => setFormData({...formData, amount: e.target.value})} className="w-full text-4xl font-light outline-none border-b border-[#EFEFE9] pb-2" placeholder="0" />
             </div>
             <div className="space-y-2">
               <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">描述</label>
               <input type="text" value={formData.description} onChange={(e) => setFormData({...formData, description: e.target.value})} className="w-full text-2xl font-medium outline-none border-b border-[#EFEFE9] pb-2" placeholder="支出項目" />
             </div>
          </div>
        )}

        <div className="mt-auto pb-10">
          <button type="submit" className="w-full py-5 bg-[#2A2A28] text-white rounded-2xl text-[10px] font-black uppercase tracking-[0.4em] hover:bg-[#8DA399] transition-all shadow-lg active:scale-95">
            {isEdit ? '更新此頁紀錄' : '儲存此頁紀錄'}
          </button>
        </div>
      </form>
    </div>
  );
};

export default EntryForm;

import React from 'react';
import { JournalEntry, ItineraryEntry, ExpenseEntry } from '../types';
import Icon from './Icon';

interface EntryItemProps {
  entry: JournalEntry;
  onDelete?: (id: string) => void;
  onEdit?: (entry: JournalEntry) => void;
}

const EntryItem: React.FC<EntryItemProps> = ({ entry, onDelete, onEdit }) => {
  const handleDelete = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (onDelete && confirm('確定要刪除這筆紀錄嗎？')) {
      onDelete(entry.id);
    }
  };

  const handleEdit = () => {
    if (onEdit) onEdit(entry);
  };

  if (entry.type === 'itinerary') {
    const item = entry as ItineraryEntry;
    return (
      <div 
        onClick={handleEdit}
        className="relative pl-12 mb-12 group cursor-pointer active:opacity-70 transition-all"
      >
        <div className="absolute left-[3px] top-2 w-[10px] h-[10px] rounded-full bg-white border-2 border-[#8DA399] z-10" />

        <div className="bg-white rounded-[24px] p-6 border border-[#EFEFE9] shadow-sm hover:shadow-md transition-shadow relative">
          <div className="flex justify-between items-start mb-3">
            <span className="text-[10px] font-bold text-[#8DA399] tracking-widest uppercase">{item.time}</span>
            {item.expenseAmount ? (
              <span className="bg-[#F8F8F5] px-3 py-1 rounded-full text-[10px] font-bold text-[#2A2A28] tabular-nums">
                ¥{item.expenseAmount.toLocaleString()}
              </span>
            ) : null}
          </div>

          <h4 className="text-lg font-semibold text-[#2A2A28] mb-1">{item.location}</h4>
          {item.notes && <p className="text-xs text-[#8A8A85] leading-relaxed font-light mb-4">{item.notes}</p>}

          {item.reflection && (
            <div className="mt-4 pt-4 border-t border-[#F8F8F5]">
              <p className="serif italic text-[#2A2A28] leading-relaxed text-sm opacity-80">
                「{item.reflection}」
              </p>
            </div>
          )}

          <button 
            onClick={handleDelete}
            className="absolute -right-2 -top-2 bg-white rounded-full shadow-md opacity-0 group-hover:opacity-100 transition-opacity text-[#BABAB5] hover:text-red-400 p-1 border border-[#EFEFE9]"
          >
            <Icon name="plus" size={14} className="rotate-45" />
          </button>
        </div>
      </div>
    );
  }

  if (entry.type === 'expense') {
    const item = entry as ExpenseEntry;
    return (
      <div onClick={handleEdit} className="ml-12 flex justify-between items-center py-4 px-5 border border-dashed border-[#EFEFE9] rounded-2xl mb-4 group cursor-pointer">
        <div>
          <span className="text-[9px] text-[#8DA399] font-bold uppercase block">{item.category}</span>
          <span className="text-sm font-medium">{item.description}</span>
        </div>
        <div className="flex items-center gap-4">
          <span className="text-sm font-bold">¥{item.amount.toLocaleString()}</span>
          <button onClick={handleDelete} className="opacity-0 group-hover:opacity-100 p-1 text-[#BABAB5]"><Icon name="plus" size={14} className="rotate-45" /></button>
        </div>
      </div>
    );
  }

  return null;
};

export default EntryItem;

