            <h1 className={`font-semibold tracking-tight text-[#2A2A28] serif transition-all duration-700 ${isScrolled ? 'text-xl' : 'text-4xl'}`}>
              {trip.title}
            </h1>
            {!isScrolled && <p className="text-[11px] text-[#8A8A85] mt-3 tracking-wide font-medium">EXPLORING — {trip.days.length} 天之旅</p>}
          </div>
          <button onClick={(e) => { e.stopPropagation(); if(confirm('確定要清除所有旅程資料並重設嗎？')) { localStorage.removeItem(STORAGE_KEY); window.location.reload(); } }} className="p-2 opacity-40 hover:opacity-100 print:hidden transition-opacity">
            <Icon name="calendar" size={18} />
          </button>
        </div>
      </header>

      <main className="px-6 mt-10 print:mt-4">
        {activeTab === 'itinerary' && (
          <div className="animate-in fade-in duration-700">
            {trip.days.map((day) => (
              <DayCard 
                key={day.id} 
                day={day} 
                onDeleteEntry={handleDeleteEntry} 
                onEditEntry={handleEditEntryTrigger}
                onAddEntryToDay={handleAddEntryToDay}
              />
            ))}
          </div>
        )}

        {activeTab === 'expenses' && (
           <div className="animate-in fade-in slide-in-from-bottom-2 duration-700">
              <h2 className="text-[10px] font-black uppercase tracking-[0.4em] text-[#8A8A85] mb-12 border-b border-[#EFEFE9] pb-4">開支總覽</h2>
              {trip.days.map(day => {
                const dayExpenses = day.entries.filter(e => (e.type === 'itinerary' && (e as ItineraryEntry).expenseAmount) || e.type === 'expense');
                if (dayExpenses.length === 0) return null;
                return (
                  <div key={day.id} className="mb-10">
                    <span className="text-[10px] font-black text-[#2A2A28] mb-4 block uppercase tracking-widest">DAY {day.dayNumber}</span>
                    {dayExpenses.map((e: any) => (
                      <div key={e.id} onClick={() => handleEditEntryTrigger(day.id, e)} className="flex justify-between py-4 border-b border-[#EFEFE9] last:border-0 cursor-pointer">
                        <span className="text-sm font-medium text-[#2A2A28]">{e.type === 'itinerary' ? e.location : e.description}</span>
                        <span className="text-sm font-bold tabular-nums">¥ {(e.expenseAmount || e.amount).toLocaleString()}</span>
                      </div>
                    ))}
                  </div>
                );
              })}
              {trip.days.every(d => d.entries.filter(e => (e.type === 'itinerary' && (e as ItineraryEntry).expenseAmount) || e.type === 'expense').length === 0) && (
                <div className="py-20 text-center text-[#BABAB5]">
                  <p className="text-xs tracking-widest uppercase font-bold">尚無支出紀錄</p>
                </div>
              )}
           </div>
        )}

        {activeTab === 'trips' && (
           <div className="py-40 text-center text-[#BABAB5] border border-dashed border-[#EFEFE9] rounded-[40px]">
              <span className="text-[10px] font-bold uppercase tracking-widest">目前沒有典藏旅程</span>
           </div>
        )}
      </main>

      {(activeForm || editingEntry) && (
        <EntryForm 
          type={activeForm || editingEntry!.entry.type} 
          initialData={editingEntry?.entry}
          onClose={() => { setActiveForm(null); setEditingEntry(null); setTargetDayId(null); }} 
          onSave={handleSaveEntry} 
        />
      )}

      {showTripSettings && <TripSettingsForm trip={trip} onClose={() => setShowTripSettings(false)} onSave={handleSaveTripSettings} />}

      <div className="fixed bottom-36 right-8 z-50 print:hidden">
        <button 
          onClick={() => setActiveForm('itinerary')}
          className="w-14 h-14 rounded-full bg-[#2A2A28] text-white flex items-center justify-center shadow-xl hover:bg-[#8DA399] transition-all active:scale-90"
        >
          <Icon name="plus" size={24} />
        </button>
      </div>

      <Navigation activeTab={activeTab} onTabChange={setActiveTab} />
    </div>
  );
};

