export default TripSettingsForm;

import React, { useState, useEffect, useCallback } from 'react';
import { AppTab, Trip, JournalEntry, EntryType, DayTimeline, ItineraryEntry, ExpenseEntry } from './types';
import { INITIAL_TRIP } from './constants';
import DayCard from './components/DayCard';
import Navigation from './components/Navigation';
import Icon from './components/Icon';
import EntryForm from './components/EntryForm';
import TripSettingsForm from './components/TripSettingsForm';

const STORAGE_KEY = 'komorebi_trip_data_v6';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<AppTab>('itinerary');
  const [trip, setTrip] = useState<Trip>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        parsed.startDate = new Date(parsed.startDate);
        parsed.endDate = new Date(parsed.endDate);
        parsed.days = parsed.days.map((d: any) => ({
          ...d,
          date: new Date(d.date),
          entries: d.entries.map((e: any) => ({
            ...e,
            timestamp: new Date(e.timestamp)
          }))
        }));
        return parsed;
      } catch (e) {
        return INITIAL_TRIP;
      }
    }
    return INITIAL_TRIP;
  });

  const [isScrolled, setIsScrolled] = useState(false);
  const [activeForm, setActiveForm] = useState<EntryType | null>(null);
  const [targetDayId, setTargetDayId] = useState<string | null>(null);
  const [editingEntry, setEditingEntry] = useState<{ dayId: string; entry: JournalEntry } | null>(null);
  const [showTripSettings, setShowTripSettings] = useState(false);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(trip));
  }, [trip]);

  useEffect(() => {
    const handleScroll = () => setIsScrolled(window.scrollY > 40);
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const handleSaveTripSettings = (title: string, start: Date, end: Date) => {
    const newDays: DayTimeline[] = [];
    const diffTime = Math.abs(end.getTime() - start.getTime());
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)) + 1;

    for (let i = 0; i < diffDays; i++) {
      const currentDate = new Date(start);
      currentDate.setDate(start.getDate() + i);
      const existingDay = trip.days.find(d => d.date.toDateString() === currentDate.toDateString());
      newDays.push({
        id: existingDay?.id || `day-${i + 1}-${Date.now()}`,
        date: currentDate,
        dayNumber: i + 1,
        entries: existingDay?.entries || []
      });
    }

    setTrip(prev => ({ ...prev, title, startDate: start, endDate: end, days: newDays }));
    setShowTripSettings(false);
  };

  const handleImportData = (entries: { date: string, entry: JournalEntry }[]) => {
    let matchCount = 0;

    setTrip(prev => {
      const updatedDays = prev.days.map(day => {
        // 將 day.date 轉為 YYYY-MM-DD
        const y = day.date.getFullYear();
        const m = String(day.date.getMonth() + 1).padStart(2, '0');
        const d = String(day.date.getDate()).padStart(2, '0');
        const dayKey = `${y}-${m}-${d}`;

        const newEntriesForDay = entries
          .filter(item => {
            const isMatch = item.date === dayKey;
            if (isMatch) matchCount++;
            return isMatch;
          })
          .map(item => item.entry);

        if (newEntriesForDay.length === 0) return day;

        const mergedEntries = [...day.entries, ...newEntriesForDay].sort((a, b) => {
          if (a.type === 'itinerary' && b.type === 'itinerary') {
            return (a as ItineraryEntry).time.localeCompare((b as ItineraryEntry).time);
          }
          return 0;
        });

        return { ...day, entries: mergedEntries };
      });
      return { ...prev, days: updatedDays };
    });

    if (matchCount > 0) {
      alert(`成功匯入 ${matchCount} 筆資料！`);
    } else {
      alert('匯入完成，但沒有資料匹配目前的旅程日期範圍。請確認 CSV 中的日期（如 12/20）是否在旅程區間內。');
    }
  };

  const handleSaveEntry = (data: Partial<JournalEntry>) => {
    const formType = activeForm || editingEntry?.entry.type;
    if (!formType) return;

    if (editingEntry) {
      setTrip(prev => {
        const updatedDays = prev.days.map(day => {
          if (day.id === editingEntry.dayId) {
            return {
              ...day,
              entries: day.entries.map(e => e.id === editingEntry.entry.id ? { ...e, ...data } : e)
            };
          }
          return day;
        });
        return { ...prev, days: updatedDays };
      });
    } else {
      const newEntry: JournalEntry = {
        id: Date.now().toString(),
        timestamp: new Date(),
        type: formType,
        ...data
      } as JournalEntry;

      setTrip(prev => {
        const updatedDays = prev.days.map(day => {
          const isTargetDay = targetDayId ? day.id === targetDayId : day.id === prev.days[0]?.id;

          if (isTargetDay) {
            const sortedEntries = [...day.entries, newEntry].sort((a, b) => {
              if (a.type === 'itinerary' && b.type === 'itinerary') {
                return (a as ItineraryEntry).time.localeCompare((b as ItineraryEntry).time);
              }
              return 0;
            });
            return { ...day, entries: sortedEntries };
          }
          return day;
        });
        return { ...prev, days: updatedDays };
      });
    }

    setActiveForm(null);
    setTargetDayId(null);
    setEditingEntry(null);
  };

  const handleAddEntryToDay = (dayId: string, type: EntryType) => {
    setTargetDayId(dayId);
    setActiveForm(type);
  };

  const handleDeleteEntry = useCallback((dayId: string, entryId: string) => {
    setTrip(prev => {
      const updatedDays = prev.days.map(day => {
        if (day.id === dayId) {
          return { 
            ...day, 
            entries: day.entries.filter(e => e.id !== entryId) 
          };
        }
        return day;
      });
      return { ...prev, days: updatedDays };
    });
  }, []);

  const handleEditEntryTrigger = (dayId: string, entry: JournalEntry) => {
    setEditingEntry({ dayId, entry });
  };

  const handlePrintPDF = () => {
    setShowTripSettings(false);
    setTimeout(() => {
      window.print();
    }, 500);
  };

  return (
    <div className="min-h-screen pb-40 max-w-lg mx-auto bg-[#FDFDFB] selection:bg-[#8DA399]/20 print:bg-white print:pb-0">
      <header 
        onClick={() => !isScrolled && setShowTripSettings(true)}
        className={`sticky top-0 z-40 transition-all duration-700 px-8 flex flex-col justify-end cursor-pointer print:relative print:mb-12 print:border-b-2 print:border-black ${isScrolled ? 'h-24 bg-white/95 backdrop-blur-lg border-b border-[#EFEFE9]' : 'h-48 bg-transparent'}`}
      >
        <div className="flex justify-between items-end pb-6">
          <div className="transition-all duration-700">
            {!isScrolled && <span className="text-[10px] font-bold uppercase tracking-[0.5em] text-[#8DA399] block mb-2">旅程計劃</span>}
            <h1 className={`font-semibold tracking-tight text-[#2A2A28] serif transition-all duration-700 ${isScrolled ? 'text-xl' : 'text-4xl'}`}>
              {trip.title}
            </h1>
            {!isScrolled && <p className="text-[11px] text-[#8A8A85] mt-3 tracking-wide font-medium">EXPLORING — {trip.days.length} 天之旅</p>}
          </div>
          <button onClick={(e) => { e.stopPropagation(); if(confirm('確定要清除所有旅程資料並重設嗎？')) { localStorage.removeItem(STORAGE_KEY); window.location.reload(); } }} className="p-2 opacity-40 hover:opacity-100 print:hidden transition-opacity">
            <Icon name="calendar" size={18} />
          </button>
        </div>
      </header>

      <main className="px-6 mt-10 print:mt-4">
        {activeTab === 'itinerary' && (
          <div className="animate-in fade-in duration-700">
            {trip.days.map((day) => (
              <DayCard 
                key={day.id} 
                day={day} 
                onDeleteEntry={handleDeleteEntry} 
                onEditEntry={handleEditEntryTrigger}
                onAddEntryToDay={handleAddEntryToDay}
              />
            ))}
          </div>
        )}

        {activeTab === 'expenses' && (
           <div className="animate-in fade-in slide-in-from-bottom-2 duration-700">
              <h2 className="text-[10px] font-black uppercase tracking-[0.4em] text-[#8A8A85] mb-12 border-b border-[#EFEFE9] pb-4">開支總覽</h2>
              {trip.days.map(day => {
                const dayExpenses = day.entries.filter(e => (e.type === 'itinerary' && (e as ItineraryEntry).expenseAmount) || e.type === 'expense');
                if (dayExpenses.length === 0) return null;
                return (
                  <div key={day.id} className="mb-10">
                    <span className="text-[10px] font-black text-[#2A2A28] mb-4 block uppercase tracking-widest">DAY {day.dayNumber}</span>
                    {dayExpenses.map((e: any) => (
                      <div key={e.id} onClick={() => handleEditEntryTrigger(day.id, e)} className="flex justify-between py-4 border-b border-[#EFEFE9] last:border-0 cursor-pointer">
