import React, { useState, useEffect } from 'react';
import { EntryType, JournalEntry, ItineraryEntry } from '../types';
import { EXPENSE_CATEGORIES } from '../constants';
import Icon from './Icon';

interface EntryFormProps {
  type: EntryType;
  initialData?: Partial<JournalEntry>;
  onSave: (data: Partial<JournalEntry>) => void;
  onClose: () => void;
}

const EntryForm: React.FC<EntryFormProps> = ({ type, initialData, onSave, onClose }) => {
  const getCurrentTimeRaw = () => {
    const now = new Date();
    return now.toTimeString().slice(0, 5); // 格式如 "14:30"
  };

  const [formData, setFormData] = useState<any>({
    time: getCurrentTimeRaw(),
    location: '',
    notes: '',
    expenseAmount: '',
    expenseCategory: '飲食',
    reflection: '',
    amount: '',
    category: '飲食',
    description: ''
  });

  useEffect(() => {
    if (initialData) {
      let time = formData.time;
      if (initialData.type === 'itinerary' && (initialData as any).time) {
        const timeStr = (initialData as any).time;
        if (timeStr.includes('AM') || timeStr.includes('PM')) {
           const [t, modifier] = timeStr.split(' ');
           let [hours, minutes] = t.split(':');
           if (hours === '12') hours = '00';
           if (modifier === 'PM') hours = String(parseInt(hours, 10) + 12).padStart(2, '0');
           time = `${hours}:${minutes}`;
        } else {
           time = timeStr;
        }
      }

      setFormData((prev: any) => ({
        ...prev,
        ...initialData,
        time: time
      }));
    }
  }, [initialData]);

  const isEdit = !!initialData?.id;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const dataToSave = { ...formData };

    if (type === 'itinerary' && dataToSave.time) {
      const [h, m] = dataToSave.time.split(':');
      const hour = parseInt(h, 10);
      const ampm = hour >= 12 ? 'PM' : 'AM';
      const displayHour = hour % 12 || 12;
      dataToSave.time = `${String(displayHour).padStart(2, '0')}:${m} ${ampm}`;
    }

    if (dataToSave.expenseAmount !== '') dataToSave.expenseAmount = parseFloat(dataToSave.expenseAmount);
    if (dataToSave.amount !== '') dataToSave.amount = parseFloat(dataToSave.amount);

    onSave(dataToSave);
  };

  const CategorySelector = ({ value, onChange, label }: { value: string, onChange: (v: string) => void, label: string }) => (
    <div className="space-y-3">
      <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">{label}</label>
      <div className="flex flex-wrap gap-2">
        {EXPENSE_CATEGORIES.map((cat) => (
          <button
            key={cat.id}
            type="button"
            onClick={() => onChange(cat.label)}
            className={`px-4 py-2 rounded-full text-[11px] font-bold tracking-wider transition-all border ${
              value === cat.label 
                ? 'bg-[#8DA399] border-[#8DA399] text-white shadow-md' 
                : 'bg-white border-[#EFEFE9] text-[#8A8A85] hover:border-[#8DA399]'
            }`}
          >
            {cat.label}
          </button>
        ))}
      </div>
    </div>
  );

  return (
    <div className="fixed inset-0 z-[100] bg-[#FDFDFB] animate-in slide-in-from-bottom duration-500 p-8 flex flex-col overflow-y-auto no-scrollbar">
      <div className="flex justify-between items-center mb-10">
        <span className="text-[10px] font-black uppercase tracking-[0.5em] text-[#8DA399]">
          {isEdit ? '編輯紀錄' : '新增紀錄'}
        </span>
        <button onClick={onClose} className="p-2 -mr-2 text-[#BABAB5] hover:text-[#2A2A28] transition-colors">
          <Icon name="plus" size={24} className="rotate-45" />
        </button>
      </div>

      <form onSubmit={handleSubmit} className="flex-1 flex flex-col gap-8">
        {type === 'itinerary' ? (
          <>
            <div className="grid grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">時間</label>
                <div className="relative">
                  <input 
                    type="time" 
                    value={formData.time}
                    onChange={(e) => setFormData({...formData, time: e.target.value})}
                    className="w-full text-lg font-medium outline-none bg-transparent border-b border-[#EFEFE9] pb-2 focus:border-[#8DA399] transition-colors appearance-none"
                  />
                  <div className="absolute right-0 bottom-3 pointer-events-none text-[#BABAB5]">
                    <Icon name="clock" size={14} />
                  </div>
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">支出 (JPY)</label>
                <input 
                  type="number" 
                  value={formData.expenseAmount}
                  onChange={(e) => setFormData({...formData, expenseAmount: e.target.value})}
                  className="w-full text-lg font-medium outline-none bg-transparent border-b border-[#EFEFE9] pb-2 focus:border-[#8DA399] transition-colors"
                  placeholder="選填"
                />
              </div>
            </div>

            {formData.expenseAmount > 0 && (
              <CategorySelector 
                label="支出類別" 
                value={formData.expenseCategory} 
                onChange={(v) => setFormData({...formData, expenseCategory: v})} 
              />
            )}

            <div className="space-y-2">
              <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">地點 / 活動</label>
              <input 
                autoFocus
                type="text" 
                value={formData.location}
                onChange={(e) => setFormData({...formData, location: e.target.value})}
                className="w-full text-2xl font-medium outline-none bg-transparent border-b border-[#EFEFE9] pb-2 focus:border-[#8DA399] transition-colors"
                placeholder="目的地"
              />
            </div>

            <div className="space-y-2">
              <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">一般備註</label>
              <input 
                type="text"
                value={formData.notes}
                onChange={(e) => setFormData({...formData, notes: e.target.value})}
                className="w-full text-sm font-light outline-none bg-transparent border-b border-[#EFEFE9] pb-2 focus:border-[#8DA399] transition-colors"
                placeholder="簡單備註..."
              />
            </div>

            <div className="space-y-3 pt-4 border-t border-[#EFEFE9]">
              <label className="text-[10px] uppercase tracking-widest text-[#8DA399] font-bold">此刻的感觸回憶</label>
              <textarea 
                value={formData.reflection}
                onChange={(e) => setFormData({...formData, reflection: e.target.value})}
                className="w-full text-lg serif italic leading-relaxed outline-none bg-transparent min-h-[120px] resize-none border-none p-0 focus:ring-0"
                placeholder="在這裡寫下你的心情筆記..."
              />
            </div>
          </>
        ) : (
          <div className="space-y-8">
             <div className="space-y-2">
               <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">金額 (JPY)</label>
               <input type="number" value={formData.amount} onChange={(e) => setFormData({...formData, amount: e.target.value})} className="w-full text-4xl font-light outline-none border-b border-[#EFEFE9] pb-2" placeholder="0" />
             </div>

             <CategorySelector 
                label="支出類別" 
                value={formData.category} 
                onChange={(v) => setFormData({...formData, category: v})} 
              />

             <div className="space-y-2">
               <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">描述</label>
               <input type="text" value={formData.description} onChange={(e) => setFormData({...formData, description: e.target.value})} className="w-full text-2xl font-medium outline-none border-b border-[#EFEFE9] pb-2" placeholder="支出項目" />
             </div>
          </div>
        )}

        <div className="mt-auto pb-10">
          <button type="submit" className="w-full py-5 bg-[#2A2A28] text-white rounded-2xl text-[10px] font-black uppercase tracking-[0.4em] hover:bg-[#8DA399] transition-all shadow-lg active:scale-95">
            {isEdit ? '更新此頁紀錄' : '儲存此頁紀錄'}
          </button>
        </div>
      </form>
    </div>
  );
};

export default EntryForm;

import React from 'react';
import { JournalEntry, ItineraryEntry, ExpenseEntry } from '../types';
import Icon from './Icon';

interface EntryItemProps {
  entry: JournalEntry;
  onDelete?: (id: string) => void;
  onEdit?: (entry: JournalEntry) => void;
}

const EntryItem: React.FC<EntryItemProps> = ({ entry, onDelete, onEdit }) => {
  const handleDelete = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (onDelete && confirm('確定要刪除這筆紀錄嗎？')) {
      onDelete(entry.id);
    }
  };

  const handleEdit = () => {
    if (onEdit) onEdit(entry);
  };

  if (entry.type === 'itinerary') {
    const item = entry as ItineraryEntry;
    return (
      <div 
        onClick={handleEdit}
        className="relative pl-12 mb-12 group cursor-pointer active:opacity-70 transition-all"
      >
        <div className="absolute left-[3px] top-2 w-[10px] h-[10px] rounded-full bg-white border-2 border-[#8DA399] z-10" />

        <div className="bg-white rounded-[24px] p-6 border border-[#EFEFE9] shadow-sm hover:shadow-md transition-shadow relative">
          <div className="flex justify-between items-start mb-3">
            <span className="text-[10px] font-bold text-[#8DA399] tracking-widest uppercase">{item.time}</span>
            {item.expenseAmount ? (
              <div className="flex flex-col items-end gap-1">
                <span className="bg-[#F8F8F5] px-3 py-1 rounded-full text-[10px] font-bold text-[#2A2A28] tabular-nums border border-[#EFEFE9]">
                  ¥{item.expenseAmount.toLocaleString()}
                </span>
                {item.expenseCategory && (
                  <span className="text-[8px] font-bold text-[#BABAB5] uppercase tracking-tighter mr-1">{item.expenseCategory}</span>
                )}
              </div>
            ) : null}
          </div>

          <h4 className="text-lg font-semibold text-[#2A2A28] mb-1">{item.location}</h4>
          {item.notes && <p className="text-xs text-[#8A8A85] leading-relaxed font-light mb-4">{item.notes}</p>}

          {item.reflection && (
            <div className="mt-4 pt-4 border-t border-[#F8F8F5]">
              <p className="serif italic text-[#2A2A28] leading-relaxed text-sm opacity-80">
                「{item.reflection}」
              </p>
            </div>
          )}

          <button 
            onClick={handleDelete}
            className="absolute -right-2 -top-2 bg-white rounded-full shadow-md opacity-0 group-hover:opacity-100 transition-opacity text-[#BABAB5] hover:text-red-400 p-1 border border-[#EFEFE9]"
          >
            <Icon name="plus" size={14} className="rotate-45" />
          </button>
        </div>
      </div>
    );
  }

  if (entry.type === 'expense') {
    const item = entry as ExpenseEntry;
    return (
      <div onClick={handleEdit} className="ml-12 flex justify-between items-center py-4 px-5 border border-dashed border-[#EFEFE9] rounded-2xl mb-4 group cursor-pointer bg-white/50 hover:bg-white transition-colors">
        <div>
          <span className="text-[9px] text-[#8DA399] font-bold uppercase block tracking-widest">{item.category}</span>
          <span className="text-sm font-medium">{item.description}</span>
        </div>
        <div className="flex items-center gap-4">
          <span className="text-sm font-bold tabular-nums">¥{item.amount.toLocaleString()}</span>
          <button onClick={handleDelete} className="opacity-0 group-hover:opacity-100 p-1 text-[#BABAB5]"><Icon name="plus" size={14} className="rotate-45" /></button>
        </div>
      </div>
    );
  }

  return null;
};

export default EntryItem;

