import Icon from './Icon';

interface DayCardProps {
  day: DayTimeline;
  onDeleteEntry: (dayId: string, entryId: string) => void;
  onEditEntry: (dayId: string, entry: JournalEntry) => void;
  onAddEntryToDay: (dayId: string, type: EntryType) => void;
}

const DayCard: React.FC<DayCardProps> = ({ day, onDeleteEntry, onEditEntry, onAddEntryToDay }) => {
  const formattedDate = day.date.toLocaleDateString('zh-TW', {
    year: 'numeric',
    month: 'long',
    day: 'numeric',
  });

  const weekday = day.date.toLocaleDateString('zh-TW', { weekday: 'long' });

  // 計算當日總支出
  const totalExpense = day.entries.reduce((sum, entry) => {
    if (entry.type === 'itinerary') {
      return sum + ((entry as ItineraryEntry).expenseAmount || 0);
    } else if (entry.type === 'expense') {
      return sum + (entry as ExpenseEntry).amount;
    }
    return sum;
  }, 0);

  return (
    <div className="mb-20 last:mb-0 fade-in-section">
      {/* Date Header */}
      <div className="mb-10 pl-2 pr-2 flex justify-between items-end">
        <div>
          <div className="flex items-center gap-4 mb-2">
            <span className="text-[11px] font-black uppercase tracking-[0.4em] text-[#2A2A28]">DAY {day.dayNumber}</span>
            <div className="h-[1px] w-12 bg-[#2A2A28]/10" />
          </div>
          <h2 className="text-3xl font-medium tracking-tight serif text-[#2A2A28]">{formattedDate}</h2>
          <p className="text-[10px] uppercase tracking-widest text-[#8A8A85] font-medium mt-1">{weekday}</p>
        </div>

        {/* 指向該日的新增按鈕 */}
        <button 
          onClick={() => onAddEntryToDay(day.id, 'itinerary')}
          className="flex items-center justify-center w-10 h-10 rounded-full border border-[#EFEFE9] text-[#BABAB5] hover:text-[#8DA399] hover:border-[#8DA399] transition-all active:scale-90 bg-white shadow-sm mb-1"
          title="在此日新增行程"
        >
          <Icon name="plus" size={18} />
        </button>
      </div>

      {/* Timeline Container */}
      <div className="relative pl-1">
        {/* Vertical Line */}
        {day.entries.filter(e => e.type === 'itinerary').length > 0 && (
          <div className="absolute left-[7px] top-2 bottom-8 w-[2px] bg-[#EFEFE9]" />
        )}

        {day.entries.length === 0 ? (
          <div 
            onClick={() => onAddEntryToDay(day.id, 'itinerary')}
            className="ml-12 py-16 flex flex-col items-center justify-center text-[#8A8A85] border border-dashed border-[#EFEFE9] rounded-[32px] bg-white/40 cursor-pointer hover:bg-white/60 transition-colors"
          >
            <Icon name="plus" size={20} className="mb-3 opacity-30" />
            <span className="text-[10px] tracking-[0.3em] uppercase font-bold">點擊開始規劃這一天</span>
          </div>
        ) : (
          <div className="flex flex-col">
            {day.entries.map((entry) => (
              <EntryItem 
                key={entry.id} 
                entry={entry} 
                onDelete={(entryId) => onDeleteEntry(day.id, entryId)}
                onEdit={(entryData) => onEditEntry(day.id, entryData)}
              />
            ))}
          </div>
        )}
      </div>

      {/* Daily Summary Footer */}
      {totalExpense > 0 && (
        <div className="mt-4 ml-12 py-4 px-6 bg-[#F8F8F5] rounded-2xl flex justify-between items-center border border-[#EFEFE9]/50">
          <span className="text-[10px] font-black uppercase tracking-[0.3em] text-[#8DA399]">Today Total</span>
          <span className="text-base font-bold text-[#2A2A28] tabular-nums">¥ {totalExpense.toLocaleString()}</span>
        </div>
      )}
    </div>
  );
};

