import React, { useState, useRef } from 'react';
import { Trip, JournalEntry, ItineraryEntry, ExpenseEntry } from '../types';
import Icon from './Icon';

interface TripSettingsFormProps {
  trip: Trip;
  onSave: (title: string, start: Date, end: Date) => void;
  onImport: (entries: { date: string, entry: JournalEntry }[]) => void;
  onClose: () => void;
  onPrint: () => void;
}

const TripSettingsForm: React.FC<TripSettingsFormProps> = ({ trip, onSave, onImport, onClose, onPrint }) => {
  const [title, setTitle] = useState(trip.title);
  const [start, setStart] = useState(trip.startDate.toISOString().split('T')[0]);
  const [end, setEnd] = useState(trip.endDate.toISOString().split('T')[0]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Fix: Define tripYear in component scope so it can be accessed in JSX
  const tripYear = trip.startDate.getFullYear();

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave(title, new Date(start), new Date(end));
  };

  const exportToCSV = () => {
    const headers = ['日期', '天數', '類型', '時間/類別', '地點/描述', '金額(JPY)', '筆記/內容'];
    const rows: string[][] = [headers];

    trip.days.forEach(day => {
      const dateStr = day.date.toLocaleDateString('zh-TW');
      day.entries.forEach(entry => {
        let row: string[] = [dateStr, `第 ${day.dayNumber} 天`];

        if (entry.type === 'itinerary') {
          const e = entry as ItineraryEntry;
          const combinedNotes = [e.notes, e.reflection ? `感觸: ${e.reflection}` : ''].filter(Boolean).join(' | ');
          row.push('行程', e.time, e.location, e.expenseAmount?.toString() || '', combinedNotes);
        } else if (entry.type === 'expense') {
          const e = entry as ExpenseEntry;
          row.push('支出', e.category, e.description, e.amount.toString(), '');
        }

        const escapedRow = row.map(cell => {
          const str = cell ? cell.toString().replace(/"/g, '""') : '';
          return `"${str}"`;
        });
        rows.push(escapedRow);
      });
    });

    const csvContent = "\uFEFF" + rows.map(e => e.join(",")).join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `${trip.title}_旅程紀錄.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleImportClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const text = e.target?.result as string;
        const lines = text.split(/\r?\n/).filter(line => line.trim() !== '');

        if (lines.length < 2) {
          alert('CSV 檔案為空或內容不全。');
          return;
        }

        const entries: { date: string, entry: JournalEntry }[] = [];
        // 以旅程開始日期為基準年份
        const tripYearForImport = trip.startDate.getFullYear();

        const splitCSV = (line: string) => {
          const result = [];
          let current = '';
          let inQuotes = false;
          for (let i = 0; i < line.length; i++) {
            const char = line[i];
            if (char === '"') inQuotes = !inQuotes;
            else if (char === ',' && !inQuotes) {
              result.push(current.trim());
              current = '';
            } else current += char;
          }
          result.push(current.trim());
          return result;
        };

        for (let i = 1; i < lines.length; i++) {
          const cells = splitCSV(lines[i]);
          if (cells.length < 5) continue;

          let [rawDate, , type, rawTime, locOrDesc, amountStr, notesStr] = cells;

          // 1. 強健的日期解析 (支援 12/20, 2024/12/20, 12-20 等)
          let finalDateStr = '';
          const dateNums = rawDate.match(/(\d+)/g);
          if (dateNums) {
            let y = tripYearForImport, m = 0, d = 0;
            if (dateNums.length === 2) {
              m = parseInt(dateNums[0]);
              d = parseInt(dateNums[1]);
            } else if (dateNums.length >= 3) {
              y = parseInt(dateNums[0]);
              if (y < 100) y += 2000;
              m = parseInt(dateNums[1]);
              d = parseInt(dateNums[2]);
            }
            if (m > 0 && m <= 12 && d > 0 && d <= 31) {
              finalDateStr = `${y}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
            }
          }

          if (!finalDateStr) continue;

          // 2. 時間正規化 (9:06 -> 09:06)
          let finalTime = rawTime || '12:00';
          if (finalTime.includes(':')) {
            const timeParts = finalTime.split(':');
            if (timeParts.length === 2) {
              const h = timeParts[0].padStart(2, '0');
              const min = timeParts[1].padStart(2, '0');
              finalTime = `${h}:${min}`;
            }
          }

          const id = `import-${Date.now()}-${i}`;
          const cleanAmount = (val: string) => parseFloat(val.replace(/[^\d.]/g, '')) || 0;

          // 判定類型：除了明確包含「支出」字樣的，其餘皆視為行程
          const isExpense = type.includes('支出') || type.includes('帳務') || type.includes('費用');

          if (isExpense) {
            entries.push({
              date: finalDateStr,
              entry: {
                id,
                timestamp: new Date(),
                type: 'expense',
                category: rawTime || '其他',
                description: locOrDesc || '支出項目',
                amount: cleanAmount(amountStr),
                currency: 'JPY'
              } as ExpenseEntry
            });
          } else {
            // 行程類型：將原始標籤（如「交通」）放入 notes 以供辨識
            const notePrefix = type && !['行程', 'Day'].some(s => type.includes(s)) ? `[${type}] ` : '';
            entries.push({
              date: finalDateStr,
              entry: {
                id,
                timestamp: new Date(),
                type: 'itinerary',
                time: finalTime,
                location: locOrDesc || '未命名地點',
                notes: notePrefix + (notesStr || ''),
                reflection: '',
                expenseAmount: amountStr ? cleanAmount(amountStr) : 0
              } as ItineraryEntry
            });
          }
        }

        if (entries.length > 0) {
          onImport(entries);
        } else {
          alert('找不到符合格式的旅程資料。請確認 CSV 第一欄為正確的日期（如 12/20）。');
        }
      } catch (err) {
        console.error('Import error:', err);
        alert('解析檔案失敗。請確保檔案編碼為 UTF-8 且欄位正確。');
      }
      if (fileInputRef.current) fileInputRef.current.value = '';
    };
    reader.readAsText(file);
  };

  return (
    <div className="fixed inset-0 z-[110] bg-[#FDFDFB] animate-in slide-in-from-bottom duration-500 p-8 flex flex-col overflow-y-auto no-scrollbar print:hidden">
      <div className="flex justify-between items-center mb-12">
        <span className="text-[10px] font-black uppercase tracking-[0.5em] text-[#8DA399]">旅程設定</span>
        <button onClick={onClose} className="p-2 -mr-2">
          <Icon name="plus" size={24} className="rotate-45 text-[#BABAB5]" />
        </button>
      </div>

      <form onSubmit={handleSubmit} className="flex-1 flex flex-col gap-10">
        <div className="space-y-2">
          <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">旅程標題</label>
          <input 
            autoFocus
            type="text" 
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            className="w-full text-3xl serif outline-none bg-transparent border-b border-[#EFEFE9] pb-4 focus:border-[#8DA399] transition-colors"
            placeholder="例如：東京散策"
          />
        </div>

        <div className="grid grid-cols-2 gap-8">
          <div className="space-y-2">
            <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">開始日期</label>
            <input 
              type="date" 
              value={start}
              onChange={(e) => setStart(e.target.value)}
              className="w-full text-lg font-light outline-none bg-transparent border-b border-[#EFEFE9] pb-2 focus:border-[#8DA399] transition-colors"
            />
          </div>
          <div className="space-y-2">
            <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">結束日期</label>
            <input 
              type="date" 
              value={end}
              onChange={(e) => setEnd(e.target.value)}
              className="w-full text-lg font-light outline-none bg-transparent border-b border-[#EFEFE9] pb-2 focus:border-[#8DA399] transition-colors"
            />
          </div>
        </div>

        <div className="space-y-6 pt-6 border-t border-[#EFEFE9]">
          <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold block">備份與同步</label>
          <div className="grid grid-cols-2 gap-4">
            <button 
              type="button"
              onClick={exportToCSV}
              className="flex items-center justify-center gap-3 py-4 border border-[#EFEFE9] rounded-2xl hover:border-[#8DA399] transition-colors group bg-white shadow-sm"
            >
              <Icon name="download" size={16} className="text-[#BABAB5] group-hover:text-[#8DA399]" />
              <span className="text-[10px] font-bold uppercase tracking-widest text-[#2A2A28]">匯出 CSV</span>
            </button>
            <button 
              type="button"
              onClick={handleImportClick}
              className="flex items-center justify-center gap-3 py-4 border border-[#EFEFE9] rounded-2xl hover:border-[#8DA399] transition-colors group bg-white shadow-sm"
            >
              <Icon name="upload" size={16} className="text-[#BABAB5] group-hover:text-[#8DA399]" />
              <span className="text-[10px] font-bold uppercase tracking-widest text-[#2A2A28]">匯入 CSV</span>
            </button>
            <input 
              type="file" 
              ref={fileInputRef} 
              onChange={handleFileChange} 
              accept=".csv" 
              className="hidden" 
            />
          </div>

          <button 
            type="button"
            onClick={onPrint}
            className="w-full flex items-center justify-center gap-4 py-6 bg-[#F8F8F5] border border-[#EFEFE9] rounded-2xl hover:bg-[#2A2A28] hover:text-white transition-all group shadow-sm active:scale-95"
          >
            <Icon name="printer" size={18} className="text-[#8DA399] group-hover:text-white" />
            <span className="text-[11px] font-black uppercase tracking-[0.3em]">匯出 PDF (手帳版排版)</span>
          </button>

          <div className="p-6 bg-[#F8F8F5] rounded-[24px] border border-[#EFEFE9] space-y-4">
             <div className="flex items-center gap-2">
                <Icon name="more" size={14} className="text-[#8DA399]" />
                <span className="text-[9px] font-black uppercase tracking-[0.2em] text-[#8DA399]">CSV 匯入故障排除</span>
             </div>
             <div className="space-y-3 text-[10px] text-[#8A8A85] leading-relaxed">
               <p>
                 <strong className="text-[#2A2A28] block mb-1">1. 日期範圍檢查（最重要）</strong>
                 您的 CSV 日期為 <span className="underline italic">12/20</span>，請確保上方旅程的「開始」與「結束」日期涵蓋了 <span className="text-[#2A2A28] font-bold">12月</span>。
               </p>
               <p>
                 <strong className="text-[#2A2A28] block mb-1">2. 欄位順序與內容</strong>
                 系統會根據第三欄識別類型：
               </p>
               <div className="bg-[#2A2A28]/5 p-3 rounded-lg overflow-x-auto">
                 <pre className="font-mono text-[9px] text-[#2A2A28] leading-tight">
                   日期,天數,類型,時間,地點,金額,筆記<br/>
                   12/20,Day 1,交通,09:00,東京車站,1000,JR<br/>
                   12/20,Day 1,飲食,12:00,拉麵店,1500,午餐<br/>
                   12/20,Day 1,支出,其他,藥妝,5000,伴手禮
                 </pre>
               </div>
               <p>
                 <strong className="text-[#2A2A28] block mb-1">3. 年份補全</strong>
                 若 CSV 只有 12/20，系統會自動補上您目前旅程設定的年份（{tripYear}）。
               </p>
             </div>
          </div>
        </div>

        <div className="mt-auto pb-10">
          <button 
            type="submit"
            className="w-full py-5 bg-[#2A2A28] text-white rounded-2xl text-[10px] font-black uppercase tracking-[0.4em] hover:bg-[#8DA399] transition-all shadow-lg active:scale-95"
          >
            儲存旅程設定
          </button>
        </div>
      </form>
    </div>
  );
};

export default TripSettingsForm;

import React, { useState, useEffect, useCallback } from 'react';
import { AppTab, Trip, JournalEntry, EntryType, DayTimeline, ItineraryEntry, ExpenseEntry } from './types';
import { INITIAL_TRIP } from './constants';
import DayCard from './components/DayCard';
import Navigation from './components/Navigation';
import Icon from './components/Icon';
import EntryForm from './components/EntryForm';
import TripSettingsForm from './components/TripSettingsForm';

const STORAGE_KEY = 'komorebi_trip_data_v6';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<AppTab>('itinerary');
  const [trip, setTrip] = useState<Trip>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        parsed.startDate = new Date(parsed.startDate);
        parsed.endDate = new Date(parsed.endDate);
        parsed.days = parsed.days.map((d: any) => ({
          ...d,
          date: new Date(d.date),
          entries: d.entries.map((e: any) => ({
            ...e,
            timestamp: new Date(e.timestamp)
          }))
        }));
        return parsed;
      } catch (e) {
        return INITIAL_TRIP;
      }
    }
    return INITIAL_TRIP;
  });

  const [isScrolled, setIsScrolled] = useState(false);
  const [activeForm, setActiveForm] = useState<EntryType | null>(null);
  const [targetDayId, setTargetDayId] = useState<string | null>(null);
  const [editingEntry, setEditingEntry] = useState<{ dayId: string; entry: JournalEntry } | null>(null);
  const [showTripSettings, setShowTripSettings] = useState(false);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(trip));
  }, [trip]);

  useEffect(() => {
    const handleScroll = () => setIsScrolled(window.scrollY > 40);
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const handleSaveTripSettings = (title: string, start: Date, end: Date) => {
    const newDays: DayTimeline[] = [];
    const diffTime = Math.abs(end.getTime() - start.getTime());
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)) + 1;

    for (let i = 0; i < diffDays; i++) {
      const currentDate = new Date(start);
      currentDate.setDate(start.getDate() + i);
      const existingDay = trip.days.find(d => d.date.toDateString() === currentDate.toDateString());
      newDays.push({
        id: existingDay?.id || `day-${i + 1}-${Date.now()}`,
        date: currentDate,
        dayNumber: i + 1,
        entries: existingDay?.entries || []
      });
    }

    setTrip(prev => ({ ...prev, title, startDate: start, endDate: end, days: newDays }));
    setShowTripSettings(false);
  };

  const handleImportData = (entries: { date: string, entry: JournalEntry }[]) => {
    let matchCount = 0;
    const unmatchedDates = new Set<string>();

    // 同步計算新的 days 陣列
    const updatedDays = trip.days.map(day => {
      const y = day.date.getFullYear();
      const m = String(day.date.getMonth() + 1).padStart(2, '0');
      const d = String(day.date.getDate()).padStart(2, '0');
      const dayKey = `${y}-${m}-${d}`;

      const newEntriesForDay = entries
        .filter(item => {
          const isMatch = item.date === dayKey;
          if (isMatch) matchCount++;
          return isMatch;
        })
        .map(item => item.entry);

      if (newEntriesForDay.length === 0) return day;

      const mergedEntries: JournalEntry[] = [...day.entries, ...newEntriesForDay].sort((a, b) => {
        if (a.type === 'itinerary' && b.type === 'itinerary') {
          return (a as ItineraryEntry).time.localeCompare((b as ItineraryEntry).time);
        }
        return 0;
      });

      return { ...day, entries: mergedEntries };
    });

    // 檢查未匹配日期
    entries.forEach(item => {
      const isMatched = updatedDays.some(day => {
        const y = day.date.getFullYear();
        const m = String(day.date.getMonth() + 1).padStart(2, '0');
        const d = String(day.date.getDate()).padStart(2, '0');
        return `${y}-${m}-${d}` === item.date;
      });
      if (!isMatched) unmatchedDates.add(item.date);
    });

    if (matchCount > 0) {
      setTrip(prev => ({ ...prev, days: updatedDays }));
      let msg = `成功匯入 ${matchCount} 筆資料！`;
      if (unmatchedDates.size > 0) {
        msg += `\n\n注意：有 ${unmatchedDates.size} 個日期（如 ${Array.from(unmatchedDates)[0]}）不在目前的旅程日期範圍內，因此未匯入。請先點擊標題修改旅程日期。`;
      }
      alert(msg);
    } else {
      const sample = entries[0]?.date || "未知日期";
      alert(`匯入失敗：找不到匹配的日期。\n\nCSV 的第一筆日期為 ${sample}，但目前的旅程範圍是 ${trip.startDate.toLocaleDateString()} 到 ${trip.endDate.toLocaleDateString()}。\n\n請確保：\n1. 設定中的旅程日期包含 ${sample}\n2. CSV 第一欄為 YYYY/MM/DD 格式`);
    }
  };

  const handleSaveEntry = (data: Partial<JournalEntry>) => {
    const formType = activeForm || editingEntry?.entry.type;
    if (!formType) return;

    if (editingEntry) {
      setTrip(prev => {
        const updatedDays: DayTimeline[] = prev.days.map(day => {
          if (day.id === editingEntry.dayId) {
            return {
              ...day,
              entries: day.entries.map(e => 
                e.id === editingEntry.entry.id ? ({ ...e, ...data } as JournalEntry) : e
              )
            };
          }
          return day;
        });
        return { ...prev, days: updatedDays };
      });
    } else {
      const newEntry: JournalEntry = {
        id: Date.now().toString(),
        timestamp: new Date(),
        type: formType,
        ...data
      } as any;

      setTrip(prev => {
        const updatedDays: DayTimeline[] = prev.days.map(day => {
          const isTargetDay = targetDayId ? day.id === targetDayId : day.id === prev.days[0]?.id;

          if (isTargetDay) {
            const sortedEntries: JournalEntry[] = [...day.entries, newEntry].sort((a, b) => {
              if (a.type === 'itinerary' && b.type === 'itinerary') {
                return (a as ItineraryEntry).time.localeCompare((b as ItineraryEntry).time);
              }
              return 0;
            });
            return { ...day, entries: sortedEntries };
          }
          return day;
        });
        return { ...prev, days: updatedDays };
      });
    }

    setActiveForm(null);
    setTargetDayId(null);
    setEditingEntry(null);
  };

  const handleAddEntryToDay = (dayId: string, type: EntryType) => {
    setTargetDayId(dayId);
    setActiveForm(type);
  };

  const handleDeleteEntry = useCallback((dayId: string, entryId: string) => {
    setTrip(prev => {
      const updatedDays = prev.days.map(day => {
        if (day.id === dayId) {
          return { 
            ...day, 
            entries: day.entries.filter(e => e.id !== entryId) 
          };
        }
        return day;
      });
      return { ...prev, days: updatedDays };
    });
  }, []);

  const handleEditEntryTrigger = (dayId: string, entry: JournalEntry) => {
    setEditingEntry({ dayId, entry });
  };

  const handlePrintPDF = () => {
    setShowTripSettings(false);
    setTimeout(() => {
      window.print();
    }, 500);
  };

  return (
    <div className="min-h-screen pb-40 max-w-lg mx-auto bg-[#FDFDFB] selection:bg-[#8DA399]/20 print:bg-white print:pb-0">
      <header 
        onClick={() => !isScrolled && setShowTripSettings(true)}
        className={`sticky top-0 z-40 transition-all duration-700 px-8 flex flex-col justify-end cursor-pointer print:relative print:mb-12 print:border-b-2 print:border-black ${isScrolled ? 'h-24 bg-white/95 backdrop-blur-lg border-b border-[#EFEFE9]' : 'h-48 bg-transparent'}`}
      >
        <div className="flex justify-between items-end pb-6">
          <div className="transition-all duration-700">
            {!isScrolled && <span className="text-[10px] font-bold uppercase tracking-[0.5em] text-[#8DA399] block mb-2">旅程計劃</span>}
            <h1 className={`font-semibold tracking-tight text-[#2A2A28] serif transition-all duration-700 ${isScrolled ? 'text-xl' : 'text-4xl'}`}>
              {trip.title}
            </h1>
            {!isScrolled && <p className="text-[11px] text-[#8A8A85] mt-3 tracking-wide font-medium">EXPLORING — {trip.days.length} 天之旅</p>}
          </div>
          <button onClick={(e) => { e.stopPropagation(); if(confirm('確定要清除所有旅程資料並重設嗎？')) { localStorage.removeItem(STORAGE_KEY); window.location.reload(); } }} className="p-2 opacity-40 hover:opacity-100 print:hidden transition-opacity">
            <Icon name="calendar" size={18} />
          </button>
        </div>
      </header>

      <main className="px-6 mt-10 print:mt-4">
        {activeTab === 'itinerary' && (
          <div className="animate-in fade-in duration-700">
            {trip.days.map((day) => (
              <DayCard 
                key={day.id} 
                day={day} 
                onDeleteEntry={handleDeleteEntry} 
                onEditEntry={handleEditEntryTrigger}
                onAddEntryToDay={handleAddEntryToDay}
              />
            ))}
          </div>
        )}

        {activeTab === 'expenses' && (
           <div className="animate-in fade-in slide-in-from-bottom-2 duration-700">
              <h2 className="text-[10px] font-black uppercase tracking-[0.4em] text-[#8A8A85] mb-12 border-b border-[#EFEFE9] pb-4">開支總覽</h2>
              {trip.days.map(day => {
                const dayExpenses = day.entries.filter(e => (e.type === 'itinerary' && (e as ItineraryEntry).expenseAmount) || e.type === 'expense');
                if (dayExpenses.length === 0) return null;
                return (
                  <div key={day.id} className="mb-10">
                    <span className="text-[10px] font-black text-[#2A2A28] mb-4 block uppercase tracking-widest">DAY {day.dayNumber}</span>
                    {dayExpenses.map((e: any) => (
                      <div key={e.id} onClick={() => handleEditEntryTrigger(day.id, e)} className="flex justify-between py-4 border-b border-[#EFEFE9] last:border-0 cursor-pointer">
                        <span className="text-sm font-medium text-[#2A2A28]">{e.type === 'itinerary' ? e.location : e.description}</span>
                        <span className="text-sm font-bold tabular-nums">¥ {(e.expenseAmount || e.amount).toLocaleString()}</span>
                      </div>
                    ))}
                  </div>
                );
              })}
              {trip.days.every(d => d.entries.filter(e => (e.type === 'itinerary' && (e as ItineraryEntry).expenseAmount) || e.type === 'expense').length === 0) && (
                <div className="py-20 text-center text-[#BABAB5]">
                  <p className="text-xs tracking-widest uppercase font-bold">尚無支出紀錄</p>
                </div>
              )}
           </div>
        )}

        {activeTab === 'trips' && (
           <div className="py-40 text-center text-[#BABAB5] border border-dashed border-[#EFEFE9] rounded-[40px]">
              <span className="text-[10px] font-bold uppercase tracking-widest">目前沒有典藏旅程</span>
           </div>
        )}
      </main>

      {(activeForm || editingEntry) && (
        <EntryForm 
          type={activeForm || editingEntry!.entry.type} 
          initialData={editingEntry?.entry}
          onClose={() => { setActiveForm(null); setEditingEntry(null); setTargetDayId(null); }} 
          onSave={handleSaveEntry} 
        />
      )}

      {showTripSettings && (
        <TripSettingsForm 
          trip={trip} 
          onClose={() => setShowTripSettings(false)} 
          onSave={handleSaveTripSettings}
          onImport={handleImportData}
          onPrint={handlePrintPDF}
        />
      )}

      <div className="fixed bottom-36 right-8 z-50 print:hidden">
        <button 
          onClick={() => setActiveForm('itinerary')}
          className="w-14 h-14 rounded-full bg-[#2A2A28] text-white flex items-center justify-center shadow-xl hover:bg-[#8DA399] transition-all active:scale-90"
        >
          <Icon name="plus" size={24} />
        </button>
      </div>

      <Navigation activeTab={activeTab} onTabChange={setActiveTab} />
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { Trip, JournalEntry, ItineraryEntry, ExpenseEntry } from '../types';
import Icon from './Icon';

interface TripSettingsFormProps {
  trip: Trip;
  onSave: (title: string, start: Date, end: Date) => void;
  onImport: (entries: { date: string, entry: JournalEntry }[]) => void;
  onClose: () => void;
  onPrint: () => void;
}

const TripSettingsForm: React.FC<TripSettingsFormProps> = ({ trip, onSave, onImport, onClose, onPrint }) => {
  const [title, setTitle] = useState(trip.title);
  const [start, setStart] = useState(trip.startDate.toISOString().split('T')[0]);
  const [end, setEnd] = useState(trip.endDate.toISOString().split('T')[0]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const tripYear = trip.startDate.getFullYear();

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave(title, new Date(start), new Date(end));
  };

  const exportToCSV = () => {
    const headers = ['日期', '天數', '類型', '時間/類別', '地點/描述', '金額(JPY)', '筆記/內容'];
    const rows: string[][] = [headers];

    trip.days.forEach(day => {
      const dateStr = day.date.toLocaleDateString('zh-TW');
      day.entries.forEach(entry => {
        let row: string[] = [dateStr, `第 ${day.dayNumber} 天`];

        if (entry.type === 'itinerary') {
          const e = entry as ItineraryEntry;
          const combinedNotes = [e.notes, e.reflection ? `感觸: ${e.reflection}` : ''].filter(Boolean).join(' | ');
          row.push('行程', e.time, e.location, e.expenseAmount?.toString() || '0', combinedNotes);
        } else if (entry.type === 'expense') {
          const e = entry as ExpenseEntry;
          row.push('支出', e.category, e.description, e.amount.toString(), '');
        }

        const escapedRow = row.map(cell => {
          const str = cell ? cell.toString().replace(/"/g, '""') : '';
          return `"${str}"`;
        });
        rows.push(escapedRow);
      });
    });

    const csvContent = "\uFEFF" + rows.map(e => e.join(",")).join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `${trip.title}_旅程紀錄.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleImportClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const text = e.target?.result as string;
        const lines = text.split(/\r?\n/).filter(line => line.trim() !== '');

        if (lines.length < 2) {
          alert('CSV 檔案為空或內容不全。');
          return;
        }

        const entries: { date: string, entry: JournalEntry }[] = [];
        const tripYearForImport = trip.startDate.getFullYear();

        const splitCSV = (line: string) => {
          const result = [];
          let current = '';
          let inQuotes = false;
          for (let i = 0; i < line.length; i++) {
            const char = line[i];
            if (char === '"') inQuotes = !inQuotes;
            else if (char === ',' && !inQuotes) {
              result.push(current.trim());
              current = '';
            } else current += char;
          }
          result.push(current.trim());
          return result;
        };

        for (let i = 1; i < lines.length; i++) {
          const cells = splitCSV(lines[i]);
          if (cells.length < 5) continue;

          let [rawDate, , type, rawTime, locOrDesc, amountStr, notesStr] = cells;

          let finalDateStr = '';
          const dateNums = rawDate.match(/(\d+)/g);
          if (dateNums) {
            let y = tripYearForImport, m = 0, d = 0;
            if (dateNums.length === 2) {
              m = parseInt(dateNums[0]);
              d = parseInt(dateNums[1]);
            } else if (dateNums.length >= 3) {
              // 支援 YYYY/MM/DD 或 DD/MM/YYYY 的基本判斷
              const first = parseInt(dateNums[0]);
              const last = parseInt(dateNums[2]);
              if (first > 1000) { // YYYY/MM/DD
                y = first; m = parseInt(dateNums[1]); d = last;
              } else if (last > 1000) { // DD/MM/YYYY
                y = last; m = parseInt(dateNums[1]); d = first;
              } else {
                y = first + 2000; m = parseInt(dateNums[1]); d = last;
              }
            }
            if (m > 0 && m <= 12 && d > 0 && d <= 31) {
              finalDateStr = `${y}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
            }
          }

          if (!finalDateStr) continue;

          let finalTime = rawTime || '12:00';
          if (finalTime.includes(':')) {
            const timeParts = finalTime.split(':');
            if (timeParts.length === 2) {
              const h = timeParts[0].padStart(2, '0');
              const min = timeParts[1].padStart(2, '0');
              finalTime = `${h}:${min}`;
            }
          }

          const id = `import-${Date.now()}-${i}`;
          const cleanAmount = (val: string) => {
            if (!val) return 0;
            const parsed = parseFloat(val.replace(/[^\d.]/g, ''));
            return isNaN(parsed) ? 0 : parsed;
          };

          const isExpense = type.includes('支出') || type.includes('帳務') || type.includes('費用');

          if (isExpense) {
            entries.push({
              date: finalDateStr,
              entry: {
                id,
                timestamp: new Date(),
                type: 'expense',
                category: rawTime || '其他',
                description: locOrDesc || '支出項目',
                amount: cleanAmount(amountStr),
                currency: 'JPY'
              } as ExpenseEntry
            });
          } else {
            const notePrefix = type && !['行程', '交通', '景點', '飲食', 'Day'].some(s => type.includes(s)) ? `[${type}] ` : '';
            entries.push({
              date: finalDateStr,
              entry: {
                id,
                timestamp: new Date(),
                type: 'itinerary',
                time: finalTime,
                location: locOrDesc || '未命名地點',
                notes: notePrefix + (notesStr || ''),
                reflection: '',
                expenseAmount: amountStr ? cleanAmount(amountStr) : 0
              } as ItineraryEntry
            });
          }
        }

        if (entries.length > 0) {
          onImport(entries);
        } else {
          alert('找不到符合格式的旅程資料。請確認 CSV 第一欄為正確的日期（如 2025/12/20）。');
        }
      } catch (err) {
        console.error('Import error:', err);
        alert('解析檔案失敗。請確保檔案編碼為 UTF-8 且欄位正確。');
      }
      if (fileInputRef.current) fileInputRef.current.value = '';
    };
    reader.readAsText(file);
  };

  return (
    <div className="fixed inset-0 z-[110] bg-[#FDFDFB] animate-in slide-in-from-bottom duration-500 p-8 flex flex-col overflow-y-auto no-scrollbar print:hidden">
      <div className="flex justify-between items-center mb-12">
        <span className="text-[10px] font-black uppercase tracking-[0.5em] text-[#8DA399]">旅程設定</span>
        <button onClick={onClose} className="p-2 -mr-2">
          <Icon name="plus" size={24} className="rotate-45 text-[#BABAB5]" />
        </button>
      </div>

      <form onSubmit={handleSubmit} className="flex-1 flex flex-col gap-10">
        <div className="space-y-2">
          <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">旅程標題</label>
          <input 
            autoFocus
            type="text" 
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            className="w-full text-3xl serif outline-none bg-transparent border-b border-[#EFEFE9] pb-4 focus:border-[#8DA399] transition-colors"
            placeholder="例如：東京散策"
          />
        </div>

        <div className="grid grid-cols-2 gap-8">
          <div className="space-y-2">
            <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">開始日期</label>
            <input 
              type="date" 
              value={start}
              onChange={(e) => setStart(e.target.value)}
              className="w-full text-lg font-light outline-none bg-transparent border-b border-[#EFEFE9] pb-2 focus:border-[#8DA399] transition-colors"
            />
          </div>
          <div className="space-y-2">
            <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">結束日期</label>
            <input 
              type="date" 
              value={end}
              onChange={(e) => setEnd(e.target.value)}
              className="w-full text-lg font-light outline-none bg-transparent border-b border-[#EFEFE9] pb-2 focus:border-[#8DA399] transition-colors"
            />
          </div>
        </div>

        <div className="space-y-6 pt-6 border-t border-[#EFEFE9]">
          <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold block">備份與同步</label>
          <div className="grid grid-cols-2 gap-4">
            <button 
              type="button"
              onClick={exportToCSV}
              className="flex items-center justify-center gap-3 py-4 border border-[#EFEFE9] rounded-2xl hover:border-[#8DA399] transition-colors group bg-white shadow-sm"
            >
              <Icon name="download" size={16} className="text-[#BABAB5] group-hover:text-[#8DA399]" />
              <span className="text-[10px] font-bold uppercase tracking-widest text-[#2A2A28]">匯出 CSV</span>
            </button>
            <button 
              type="button"
              onClick={handleImportClick}
              className="flex items-center justify-center gap-3 py-4 border border-[#EFEFE9] rounded-2xl hover:border-[#8DA399] transition-colors group bg-white shadow-sm"
            >
              <Icon name="upload" size={16} className="text-[#BABAB5] group-hover:text-[#8DA399]" />
              <span className="text-[10px] font-bold uppercase tracking-widest text-[#2A2A28]">匯入 CSV</span>
            </button>
            <input 
              type="file" 
              ref={fileInputRef} 
              onChange={handleFileChange} 
              accept=".csv" 
              className="hidden" 
            />
          </div>

          <button 
            type="button"
            onClick={onPrint}
            className="w-full flex items-center justify-center gap-4 py-6 bg-[#F8F8F5] border border-[#EFEFE9] rounded-2xl hover:bg-[#2A2A28] hover:text-white transition-all group shadow-sm active:scale-95"
          >
            <Icon name="printer" size={18} className="text-[#8DA399] group-hover:text-white" />
            <span className="text-[11px] font-black uppercase tracking-[0.3em]">匯出 PDF (手帳版排版)</span>
          </button>

          <div className="p-6 bg-[#F8F8F5] rounded-[24px] border border-[#EFEFE9] space-y-4">
             <div className="flex items-center gap-2">
                <Icon name="more" size={14} className="text-[#8DA399]" />
                <span className="text-[9px] font-black uppercase tracking-[0.2em] text-[#8DA399]">CSV 匯入指南</span>
             </div>
             <div className="space-y-3 text-[10px] text-[#8A8A85] leading-relaxed">
               <p>
                 <strong className="text-[#2A2A28] block mb-1">1. 設定旅程日期（必要）</strong>
                 請確保上方的「開始日期」涵蓋了 CSV 中的日期（例如：{tripYear}年）。
               </p>
               <p>
                 <strong className="text-[#2A2A28] block mb-1">2. 推薦格式範例</strong>
                 系統支援您提供的格式如下：
               </p>
               <div className="bg-[#2A2A28]/5 p-3 rounded-lg overflow-x-auto">
                 <pre className="font-mono text-[9px] text-[#2A2A28] leading-tight">
                   日期,天數,類型,時間/類別,地點/描述,金額,筆記/內容<br/>
                   2025/12/20,Day 1,交通,9:06,前往高鐵站,0,14分鐘<br/>
                   2025/12/20,Day 1,景點,11:21,華山文創,0,停留2小時<br/>
                   2025/12/20,Day 1,支出,飲食,午餐拉麵,1500,好吃
                 </pre>
               </div>
               <p>
                 <strong className="text-[#2A2A28] block mb-1">3. 自動修正</strong>
                 系統會自動將 <span className="italic">9:06</span> 補位為 <span className="italic">09:06</span> 以確保排序正確。
               </p>
             </div>
          </div>
        </div>

        <div className="mt-auto pb-10">
          <button 
            type="submit"
            className="w-full py-5 bg-[#2A2A28] text-white rounded-2xl text-[10px] font-black uppercase tracking-[0.4em] hover:bg-[#8DA399] transition-all shadow-lg active:scale-95"
          >
            儲存旅程設定
          </button>
        </div>
      </form>
    </div>
  );
};

export default TripSettingsForm;

import React, { useState, useEffect, useCallback } from 'react';
import { AppTab, Trip, JournalEntry, EntryType, DayTimeline, ItineraryEntry, ExpenseEntry } from './types';
import { INITIAL_TRIP } from './constants';
import DayCard from './components/DayCard';
import Navigation from './components/Navigation';
import Icon from './components/Icon';
import EntryForm from './components/EntryForm';
import TripSettingsForm from './components/TripSettingsForm';

const STORAGE_KEY = 'komorebi_trip_data_v6';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<AppTab>('itinerary');
  const [trip, setTrip] = useState<Trip>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        parsed.startDate = new Date(parsed.startDate);
        parsed.endDate = new Date(parsed.endDate);
        parsed.days = parsed.days.map((d: any) => ({
          ...d,
          date: new Date(d.date),
          entries: d.entries.map((e: any) => ({
            ...e,
            timestamp: new Date(e.timestamp)
          }))
        }));
        return parsed;
      } catch (e) {
        return INITIAL_TRIP;
      }
    }
    return INITIAL_TRIP;
  });

  const [isScrolled, setIsScrolled] = useState(false);
  const [activeForm, setActiveForm] = useState<EntryType | null>(null);
  const [targetDayId, setTargetDayId] = useState<string | null>(null);
  const [editingEntry, setEditingEntry] = useState<{ dayId: string; entry: JournalEntry } | null>(null);
  const [showTripSettings, setShowTripSettings] = useState(false);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(trip));
  }, [trip]);

  useEffect(() => {
    const handleScroll = () => setIsScrolled(window.scrollY > 40);
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const generateDaysBetween = (start: Date, end: Date, existingDays: DayTimeline[]): DayTimeline[] => {
    const newDays: DayTimeline[] = [];
    const diffTime = Math.abs(end.getTime() - start.getTime());
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)) + 1;

    for (let i = 0; i < diffDays; i++) {
      const currentDate = new Date(start);
      currentDate.setDate(start.getDate() + i);
      const dayStr = currentDate.toDateString();
      const existingDay = existingDays.find(d => d.date.toDateString() === dayStr);
      newDays.push({
        id: existingDay?.id || `day-${i + 1}-${Date.now()}-${i}`,
        date: currentDate,
        dayNumber: i + 1,
        entries: existingDay?.entries || []
      });
    }
    return newDays;
  };

  const handleSaveTripSettings = (title: string, start: Date, end: Date) => {
    const newDays = generateDaysBetween(start, end, trip.days);
    setTrip(prev => ({ ...prev, title, startDate: start, endDate: end, days: newDays }));
    setShowTripSettings(false);
  };

  const handleImportData = (entries: { date: string, entry: JournalEntry }[]) => {
    if (entries.length === 0) return;

    // 1. 找出 CSV 中的日期範圍
    const csvDateStrings = entries.map(e => e.date).sort();
    const minCsvDateStr = csvDateStrings[0];
    const maxCsvDateStr = csvDateStrings[csvDateStrings.length - 1];

    const minDate = new Date(minCsvDateStr);
    const maxDate = new Date(maxCsvDateStr);

    // 2. 檢查是否需要調整旅程範圍
    const isOutOfRange = minDate < trip.startDate || maxDate > trip.endDate;

    const performImport = (currentTrip: Trip) => {
      let matchCount = 0;
      const updatedDays = currentTrip.days.map(day => {
        const y = day.date.getFullYear();
        const m = String(day.date.getMonth() + 1).padStart(2, '0');
        const d = String(day.date.getDate()).padStart(2, '0');
        const dayKey = `${y}-${m}-${d}`;

        const newEntriesForDay = entries
          .filter(item => item.date === dayKey)
          .map(item => item.entry);

        if (newEntriesForDay.length === 0) return day;
        matchCount += newEntriesForDay.length;

        const mergedEntries = [...day.entries, ...newEntriesForDay].sort((a, b) => {
          if (a.type === 'itinerary' && b.type === 'itinerary') {
            return (a as ItineraryEntry).time.localeCompare((b as ItineraryEntry).time);
          }
          return 0;
        });

        return { ...day, entries: mergedEntries };
      });

      setTrip(prev => ({ ...prev, days: updatedDays }));
      alert(`成功匯入 ${matchCount} 筆行程資料！`);
    };

    if (isOutOfRange) {
      const confirmAdjust = confirm(
        `匯入資料包含 ${minCsvDateStr} 至 ${maxCsvDateStr}，超出了目前旅程的設定範圍。\n\n是否要自動調整旅程日期以完成匯入？`
      );
      if (confirmAdjust) {
        // 先自動調整日期範圍
        const finalStart = minDate < trip.startDate ? minDate : trip.startDate;
        const finalEnd = maxDate > trip.endDate ? maxDate : trip.endDate;
        const expandedDays = generateDaysBetween(finalStart, finalEnd, trip.days);
        const expandedTrip = { ...trip, startDate: finalStart, endDate: finalEnd, days: expandedDays };

        // 立即對擴展後的 Trip 執行匯入
        performImport(expandedTrip);
      }
    } else {
      performImport(trip);
    }
  };

  const handleSaveEntry = (data: Partial<JournalEntry>) => {
    const formType = activeForm || editingEntry?.entry.type;
    if (!formType) return;

    if (editingEntry) {
      setTrip(prev => {
        const updatedDays: DayTimeline[] = prev.days.map(day => {
          if (day.id === editingEntry.dayId) {
            return {
              ...day,
              entries: day.entries.map(e => 
                e.id === editingEntry.entry.id ? ({ ...e, ...data } as JournalEntry) : e
              )
            };
          }
          return day;
        });
        return { ...prev, days: updatedDays };
      });
    } else {
      const newEntry: JournalEntry = {
        id: Date.now().toString(),
        timestamp: new Date(),
        type: formType,
        ...data
      } as any;

      setTrip(prev => {
        const updatedDays: DayTimeline[] = prev.days.map(day => {
          const isTargetDay = targetDayId ? day.id === targetDayId : day.id === prev.days[0]?.id;

          if (isTargetDay) {
            const sortedEntries: JournalEntry[] = [...day.entries, newEntry].sort((a, b) => {
              if (a.type === 'itinerary' && b.type === 'itinerary') {
                return (a as ItineraryEntry).time.localeCompare((b as ItineraryEntry).time);
              }
              return 0;
            });
            return { ...day, entries: sortedEntries };
          }
          return day;
        });
        return { ...prev, days: updatedDays };
      });
    }

    setActiveForm(null);
    setTargetDayId(null);
    setEditingEntry(null);
  };

  const handleAddEntryToDay = (dayId: string, type: EntryType) => {
    setTargetDayId(dayId);
    setActiveForm(type);
  };

  const handleDeleteEntry = useCallback((dayId: string, entryId: string) => {
    setTrip(prev => {
      const updatedDays = prev.days.map(day => {
        if (day.id === dayId) {
          return { 
            ...day, 
            entries: day.entries.filter(e => e.id !== entryId) 
          };
        }
        return day;
      });
      return { ...prev, days: updatedDays };
    });
  }, []);

  const handleEditEntryTrigger = (dayId: string, entry: JournalEntry) => {
    setEditingEntry({ dayId, entry });
  };

  const handlePrintPDF = () => {
    setShowTripSettings(false);
    setTimeout(() => {
      window.print();
    }, 500);
  };

  return (
    <div className="min-h-screen pb-40 max-w-lg mx-auto bg-[#FDFDFB] selection:bg-[#8DA399]/20 print:bg-white print:pb-0">
      <header 
        onClick={() => !isScrolled && setShowTripSettings(true)}
        className={`sticky top-0 z-40 transition-all duration-700 px-8 flex flex-col justify-end cursor-pointer print:relative print:mb-12 print:border-b-2 print:border-black ${isScrolled ? 'h-24 bg-white/95 backdrop-blur-lg border-b border-[#EFEFE9]' : 'h-48 bg-transparent'}`}
      >
        <div className="flex justify-between items-end pb-6">
          <div className="transition-all duration-700">
            {!isScrolled && <span className="text-[10px] font-bold uppercase tracking-[0.5em] text-[#8DA399] block mb-2">旅程計劃</span>}
            <h1 className={`font-semibold tracking-tight text-[#2A2A28] serif transition-all duration-700 ${isScrolled ? 'text-xl' : 'text-4xl'}`}>
              {trip.title}
            </h1>
            {!isScrolled && <p className="text-[11px] text-[#8A8A85] mt-3 tracking-wide font-medium">EXPLORING — {trip.days.length} 天之旅</p>}
          </div>
          <button onClick={(e) => { e.stopPropagation(); if(confirm('確定要清除所有旅程資料並重設嗎？')) { localStorage.removeItem(STORAGE_KEY); window.location.reload(); } }} className="p-2 opacity-40 hover:opacity-100 print:hidden transition-opacity">
            <Icon name="calendar" size={18} />
          </button>
        </div>
      </header>

      <main className="px-6 mt-10 print:mt-4">
        {activeTab === 'itinerary' && (
          <div className="animate-in fade-in duration-700">
            {trip.days.map((day) => (
              <DayCard 
                key={day.id} 
                day={day} 
                onDeleteEntry={handleDeleteEntry} 
                onEditEntry={handleEditEntryTrigger}
                onAddEntryToDay={handleAddEntryToDay}
              />
            ))}
          </div>
        )}

        {activeTab === 'expenses' && (
           <div className="animate-in fade-in slide-in-from-bottom-2 duration-700">
              <h2 className="text-[10px] font-black uppercase tracking-[0.4em] text-[#8A8A85] mb-12 border-b border-[#EFEFE9] pb-4">開支總覽</h2>
              {trip.days.map(day => {
                const dayExpenses = day.entries.filter(e => (e.type === 'itinerary' && (e as ItineraryEntry).expenseAmount) || e.type === 'expense');
                if (dayExpenses.length === 0) return null;
                return (
                  <div key={day.id} className="mb-10">
                    <span className="text-[10px] font-black text-[#2A2A28] mb-4 block uppercase tracking-widest">DAY {day.dayNumber}</span>
                    {dayExpenses.map((e: any) => (
                      <div key={e.id} onClick={() => handleEditEntryTrigger(day.id, e)} className="flex justify-between py-4 border-b border-[#EFEFE9] last:border-0 cursor-pointer">
                        <span className="text-sm font-medium text-[#2A2A28]">{e.type === 'itinerary' ? e.location : e.description}</span>
                        <span className="text-sm font-bold tabular-nums">¥ {(e.expenseAmount || e.amount).toLocaleString()}</span>
                      </div>
                    ))}
                  </div>
                );
              })}
              {trip.days.every(d => d.entries.filter(e => (e.type === 'itinerary' && (e as ItineraryEntry).expenseAmount) || e.type === 'expense').length === 0) && (
                <div className="py-20 text-center text-[#BABAB5]">
                  <p className="text-xs tracking-widest uppercase font-bold">尚無支出紀錄</p>
                </div>
              )}
           </div>
        )}

        {activeTab === 'trips' && (
           <div className="py-40 text-center text-[#BABAB5] border border-dashed border-[#EFEFE9] rounded-[40px]">
              <span className="text-[10px] font-bold uppercase tracking-widest">目前沒有典藏旅程</span>
           </div>
        )}
      </main>

      {(activeForm || editingEntry) && (
        <EntryForm 
          type={activeForm || editingEntry!.entry.type} 
          initialData={editingEntry?.entry}
          onClose={() => { setActiveForm(null); setEditingEntry(null); setTargetDayId(null); }} 
          onSave={handleSaveEntry} 
        />
      )}

      {showTripSettings && (
        <TripSettingsForm 
          trip={trip} 
          onClose={() => setShowTripSettings(false)} 
          onSave={handleSaveTripSettings}
          onImport={handleImportData}
          onPrint={handlePrintPDF}
        />
      )}

      <div className="fixed bottom-36 right-8 z-50 print:hidden">
        <button 
          onClick={() => setActiveForm('itinerary')}
          className="w-14 h-14 rounded-full bg-[#2A2A28] text-white flex items-center justify-center shadow-xl hover:bg-[#8DA399] transition-all active:scale-90"
        >
          <Icon name="plus" size={24} />
        </button>
      </div>

      <Navigation activeTab={activeTab} onTabChange={setActiveTab} />
    </div>
  );
};

