          <Icon name="plus" size={24} className="rotate-45 text-[#BABAB5]" />
        </button>
      </div>

      <form onSubmit={handleSubmit} className="flex-1 flex flex-col gap-10">
        <div className="space-y-2">
          <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">旅程標題</label>
          <input 
            autoFocus
            type="text" 
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            className="w-full text-3xl serif outline-none bg-transparent border-b border-[#EFEFE9] pb-4 focus:border-[#8DA399] transition-colors"
            placeholder="例如：東京散策"
          />
        </div>

        <div className="grid grid-cols-2 gap-8">
          <div className="space-y-2">
            <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">開始日期</label>
            <input 
              type="date" 
              value={start}
              onChange={(e) => setStart(e.target.value)}
              className="w-full text-lg font-light outline-none bg-transparent border-b border-[#EFEFE9] pb-2 focus:border-[#8DA399] transition-colors"
            />
          </div>
          <div className="space-y-2">
            <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">結束日期</label>
            <input 
              type="date" 
              value={end}
              onChange={(e) => setEnd(e.target.value)}
              className="w-full text-lg font-light outline-none bg-transparent border-b border-[#EFEFE9] pb-2 focus:border-[#8DA399] transition-colors"
            />
          </div>
        </div>

        <div className="space-y-6 pt-6 border-t border-[#EFEFE9]">
          <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold block">備份與同步</label>
          <div className="grid grid-cols-2 gap-4">
            <button 
              type="button"
              onClick={exportToCSV}
              className="flex items-center justify-center gap-3 py-4 border border-[#EFEFE9] rounded-2xl hover:border-[#8DA399] transition-colors group bg-white shadow-sm"
            >
              <Icon name="download" size={16} className="text-[#BABAB5] group-hover:text-[#8DA399]" />
              <span className="text-[10px] font-bold uppercase tracking-widest text-[#2A2A28]">匯出 CSV</span>
            </button>
            <button 
              type="button"
              onClick={handleImportClick}
              className="flex items-center justify-center gap-3 py-4 border border-[#EFEFE9] rounded-2xl hover:border-[#8DA399] transition-colors group bg-white shadow-sm"
