import React, { useState, useRef } from 'react';
import { Trip, JournalEntry, ItineraryEntry, ExpenseEntry } from '../types';
import Icon from './Icon';

interface TripSettingsFormProps {
  trip: Trip;
  onSave: (title: string, start: Date, end: Date) => void;
  onImport: (entries: { date: string, entry: JournalEntry }[]) => void;
  onClose: () => void;
  onPrint: () => void;
}

const TripSettingsForm: React.FC<TripSettingsFormProps> = ({ trip, onSave, onImport, onClose, onPrint }) => {
  const [title, setTitle] = useState(trip.title);
  const [start, setStart] = useState(trip.startDate.toISOString().split('T')[0]);
  const [end, setEnd] = useState(trip.endDate.toISOString().split('T')[0]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const tripYear = trip.startDate.getFullYear();

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave(title, new Date(start), new Date(end));
  };

  const exportToCSV = () => {
    const headers = ['日期', '天數', '類型', '時間/類別', '地點/描述', '金額(JPY)', '筆記/內容'];
    const rows: string[][] = [headers];

    trip.days.forEach(day => {
      const dateStr = day.date.toLocaleDateString('zh-TW');
      day.entries.forEach(entry => {
        let row: string[] = [dateStr, `第 ${day.dayNumber} 天`];

        if (entry.type === 'itinerary') {
          const e = entry as ItineraryEntry;
          const combinedNotes = [e.notes, e.reflection ? `感觸: ${e.reflection}` : ''].filter(Boolean).join(' | ');
          row.push('行程', e.time, e.location, e.expenseAmount?.toString() || '0', combinedNotes);
        } else if (entry.type === 'expense') {
          const e = entry as ExpenseEntry;
          row.push('支出', e.category, e.description, e.amount.toString(), '');
        }

        const escapedRow = row.map(cell => {
          const str = cell ? cell.toString().replace(/"/g, '""') : '';
          return `"${str}"`;
        });
        rows.push(escapedRow);
      });
    });

    const csvContent = "\uFEFF" + rows.map(e => e.join(",")).join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `${trip.title}_旅程紀錄.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleImportClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();

    reader.onerror = () => {
      alert("讀取檔案時發生錯誤。請確認檔案是否損毀或被其他程式佔用。");
    };

    reader.onload = (e) => {
      try {
        const text = e.target?.result as string;
        if (!text) {
          alert("檔案為空，無法匯入。");
          return;
        }

        const lines = text.split(/\r?\n/).filter(line => line.trim() !== '');
        if (lines.length < 2) {
          alert('CSV 內容不足（至少需包含標題列與一列資料）。');
          return;
        }

        const entries: { date: string, entry: JournalEntry }[] = [];
        const tripYearForImport = trip.startDate.getFullYear();

        const splitCSV = (line: string) => {
          const result = [];
          let current = '';
          let inQuotes = false;
          for (let i = 0; i < line.length; i++) {
            const char = line[i];
            if (char === '"') inQuotes = !inQuotes;
            else if (char === ',' && !inQuotes) {
              result.push(current.trim());
              current = '';
            } else current += char;
          }
          result.push(current.trim());
          return result;
        };

        for (let i = 1; i < lines.length; i++) {
          const cells = splitCSV(lines[i]);
          if (cells.length < 5) continue;

          let [rawDate, , type, rawTime, locOrDesc, amountStr, notesStr] = cells;

          let finalDateStr = '';
          const dateNums = rawDate.match(/(\d+)/g);
          if (dateNums) {
            let y = tripYearForImport, m = 0, d = 0;
            if (dateNums.length === 2) {
              m = parseInt(dateNums[0]);
              d = parseInt(dateNums[1]);
            } else if (dateNums.length >= 3) {
              const val1 = parseInt(dateNums[0]);
              const val2 = parseInt(dateNums[1]);
              const val3 = parseInt(dateNums[2]);

              if (val1 > 1000) { y = val1; m = val2; d = val3; } 
              else if (val3 > 1000) { y = val3; m = val2; d = val1; } 
              else { y = val1 + 2000; m = val2; d = val3; }
            }
            if (m > 0 && m <= 12 && d > 0 && d <= 31) {
              finalDateStr = `${y}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
            }
          }

          if (!finalDateStr) continue;

          let finalTime = rawTime || '12:00';
          if (finalTime.includes(':')) {
            const timeParts = finalTime.split(':');
            if (timeParts.length === 2) {
              const h = timeParts[0].padStart(2, '0');
              const min = timeParts[1].padStart(2, '0');
              finalTime = `${h}:${min}`;
            }
          }

          const id = `import-${Date.now()}-${i}`;
          const cleanAmount = (val: string) => {
            if (!val || val === '0') return 0;
            const parsed = parseFloat(val.replace(/[^\d.]/g, ''));
            return isNaN(parsed) ? 0 : parsed;
          };

          const isExpense = type.includes('支出') || type.includes('帳務') || type.includes('費用');

          if (isExpense) {
            entries.push({
              date: finalDateStr,
              entry: {
                id,
                timestamp: new Date(),
                type: 'expense',
                category: rawTime || '其他',
                description: locOrDesc || '支出項目',
                amount: cleanAmount(amountStr),
                currency: 'JPY'
              } as ExpenseEntry
            });
          } else {
            const notePrefix = type && !['行程', '交通', '景點', '飲食', 'Day'].some(s => type.includes(s)) ? `[${type}] ` : '';
            entries.push({
              date: finalDateStr,
              entry: {
                id,
                timestamp: new Date(),
                type: 'itinerary',
                time: finalTime,
                location: locOrDesc || '未命名地點',
                notes: notePrefix + (notesStr || ''),
                reflection: '',
                expenseAmount: cleanAmount(amountStr)
              } as ItineraryEntry
            });
          }
        }

        if (entries.length > 0) {
          onImport(entries);
        } else {
          alert('解析失敗：找不到符合格式的資料行。請確認 CSV 第一欄為日期，並檢查是否有正確的分隔符號。');
        }
      } catch (err) {
        console.error('Import error:', err);
        alert(`匯入出錯：${err instanceof Error ? err.message : '未知錯誤'}。請確保檔案為 UTF-8 編碼。`);
      }
      if (fileInputRef.current) fileInputRef.current.value = '';
    };
    reader.readAsText(file);
  };

  return (
    <div className="fixed inset-0 z-[110] bg-[#FDFDFB] animate-in slide-in-from-bottom duration-500 p-8 flex flex-col overflow-y-auto no-scrollbar print:hidden">
      <div className="flex justify-between items-center mb-12">
        <span className="text-[10px] font-black uppercase tracking-[0.5em] text-[#8DA399]">旅程設定</span>
        <button onClick={onClose} className="p-2 -mr-2">
          <Icon name="plus" size={24} className="rotate-45 text-[#BABAB5]" />
        </button>
      </div>

      <form onSubmit={handleSubmit} className="flex-1 flex flex-col gap-10">
        <div className="space-y-2">
          <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">旅程標題</label>
          <input 
            autoFocus
            type="text" 
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            className="w-full text-3xl serif outline-none bg-transparent border-b border-[#EFEFE9] pb-4 focus:border-[#8DA399] transition-colors"
            placeholder="例如：東京散策"
          />
        </div>

        <div className="grid grid-cols-2 gap-8">
          <div className="space-y-2">
            <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">開始日期</label>
            <input 
              type="date" 
              value={start}
              onChange={(e) => setStart(e.target.value)}
              className="w-full text-lg font-light outline-none bg-transparent border-b border-[#EFEFE9] pb-2 focus:border-[#8DA399] transition-colors"
            />
          </div>
          <div className="space-y-2">
            <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">結束日期</label>
            <input 
              type="date" 
              value={end}
              onChange={(e) => setEnd(e.target.value)}
              className="w-full text-lg font-light outline-none bg-transparent border-b border-[#EFEFE9] pb-2 focus:border-[#8DA399] transition-colors"
            />
          </div>
        </div>

        <div className="space-y-6 pt-6 border-t border-[#EFEFE9]">
          <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold block">備份與同步</label>
          <div className="grid grid-cols-2 gap-4">
            <button 
              type="button"
              onClick={exportToCSV}
              className="flex items-center justify-center gap-3 py-4 border border-[#EFEFE9] rounded-2xl hover:border-[#8DA399] transition-colors group bg-white shadow-sm"
            >
              <Icon name="download" size={16} className="text-[#BABAB5] group-hover:text-[#8DA399]" />
              <span className="text-[10px] font-bold uppercase tracking-widest text-[#2A2A28]">匯出 CSV</span>
            </button>
            <button 
              type="button"
              onClick={handleImportClick}
              className="flex items-center justify-center gap-3 py-4 border border-[#EFEFE9] rounded-2xl hover:border-[#8DA399] transition-colors group bg-white shadow-sm"
            >
              <Icon name="upload" size={16} className="text-[#BABAB5] group-hover:text-[#8DA399]" />
              <span className="text-[10px] font-bold uppercase tracking-widest text-[#2A2A28]">匯入 CSV</span>
            </button>
            <input 
              type="file" 
              ref={fileInputRef} 
              onChange={handleFileChange} 
              accept=".csv" 
              className="hidden" 
            />
          </div>

          <button 
            type="button"
            onClick={onPrint}
            className="w-full flex items-center justify-center gap-4 py-6 bg-[#F8F8F5] border border-[#EFEFE9] rounded-2xl hover:bg-[#2A2A28] hover:text-white transition-all group shadow-sm active:scale-95"
          >
            <Icon name="printer" size={18} className="text-[#8DA399] group-hover:text-white" />
            <span className="text-[11px] font-black uppercase tracking-[0.3em]">匯出 PDF (手帳版排版)</span>
          </button>

          <div className="p-6 bg-[#F8F8F5] rounded-[24px] border border-[#EFEFE9] space-y-6">
             <div className="flex items-center gap-2">
                <Icon name="more" size={14} className="text-[#8DA399]" />
                <span className="text-[9px] font-black uppercase tracking-[0.2em] text-[#8DA399]">CSV 匯入詳盡指南</span>
             </div>

             <div className="space-y-4 text-[10px] text-[#8A8A85] leading-relaxed">
               <div>
                 <strong className="text-[#2A2A28] block mb-1 underline">A. 欄位定義與解析邏輯</strong>
                 <ul className="list-disc list-inside space-y-1 ml-1">
                   <li><span className="text-[#2A2A28] font-medium">類型：</span>若包含「支出、帳務、費用」會歸類為帳本；其餘標籤（如「交通、景點」）會轉為行程，並將標籤保留於備註中。</li>
                   <li><span className="text-[#2A2A28] font-medium">金額：</span>系統會自動過濾非數字字元（如 ¥、$）。若該列為行程但金額大於 0，會同步顯示於該行程的開支欄。</li>
                   <li><span className="text-[#2A2A28] font-medium">日期：</span>支援 YYYY/MM/DD 或 MM/DD 格式。單獨 MM/DD 會使用目前旅程的年份。</li>
                 </ul>
               </div>

               <div className="bg-[#2A2A28]/5 p-3 rounded-lg overflow-x-auto">
                 <pre className="font-mono text-[9px] text-[#2A2A28] leading-tight">
                   日期,天數,類型,時間/類別,地點/描述,金額,筆記/內容<br/>
                   2025/12/20,Day 1,交通,9:06,前往高鐵站,0,14分鐘<br/>
                   2025/12/20,Day 1,支出,飲食,午餐拉麵,1500,好吃
                 </pre>
               </div>

               <div>
                 <strong className="text-[#2A2A28] block mb-1 underline">B. 常見匯入錯誤診斷</strong>
                 <div className="space-y-3">
                   <div className="flex gap-2 items-start">
                     <span className="px-1.5 py-0.5 bg-red-50 text-red-500 rounded font-bold shrink-0">錯誤</span>
                     <p>顯示「找不到匹配的日期」</p>
                   </div>
                   <div className="flex gap-2 items-start pl-4 border-l-2 border-[#EFEFE9]">
                     <span className="px-1.5 py-0.5 bg-green-50 text-green-600 rounded font-bold shrink-0">解法</span>
                     <p>檢查 CSV 日期是否正確，或是否超出了旅程設定的範圍。系統現在會詢問是否自動調整日期。</p>
                   </div>

                   <div className="flex gap-2 items-start">
                     <span className="px-1.5 py-0.5 bg-red-50 text-red-500 rounded font-bold shrink-0">錯誤</span>
                     <p>內容出現亂碼</p>
                   </div>
                   <div className="flex gap-2 items-start pl-4 border-l-2 border-[#EFEFE9]">
                     <span className="px-1.5 py-0.5 bg-green-50 text-green-600 rounded font-bold shrink-0">解法</span>
                     <p>請確保 CSV 存檔時選擇為 <span className="font-bold">UTF-8 編碼</span>（尤其是使用 Excel 編輯後匯出時）。</p>
                   </div>
                 </div>
               </div>
             </div>
          </div>
        </div>

        <div className="mt-auto pb-10">
          <button 
            type="submit"
            className="w-full py-5 bg-[#2A2A28] text-white rounded-2xl text-[10px] font-black uppercase tracking-[0.4em] hover:bg-[#8DA399] transition-all shadow-lg active:scale-95"
          >
            儲存旅程設定
          </button>
        </div>
      </form>
    </div>
  );
};

export default TripSettingsForm;

import React, { useState, useEffect, useCallback } from 'react';
import { AppTab, Trip, JournalEntry, EntryType, DayTimeline, ItineraryEntry, ExpenseEntry } from './types';
import { INITIAL_TRIP } from './constants';
import DayCard from './components/DayCard';
import Navigation from './components/Navigation';
import Icon from './components/Icon';
import EntryForm from './components/EntryForm';
import TripSettingsForm from './components/TripSettingsForm';

const STORAGE_KEY = 'komorebi_trip_data_v6';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<AppTab>('itinerary');
  const [trip, setTrip] = useState<Trip>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        parsed.startDate = new Date(parsed.startDate);
        parsed.endDate = new Date(parsed.endDate);
        parsed.days = parsed.days.map((d: any) => ({
          ...d,
          date: new Date(d.date),
          entries: d.entries.map((e: any) => ({
            ...e,
            timestamp: new Date(e.timestamp)
          }))
        }));
        return parsed;
      } catch (e) {
        return INITIAL_TRIP;
      }
    }
    return INITIAL_TRIP;
  });

  const [isScrolled, setIsScrolled] = useState(false);
  const [activeForm, setActiveForm] = useState<EntryType | null>(null);
  const [targetDayId, setTargetDayId] = useState<string | null>(null);
  const [editingEntry, setEditingEntry] = useState<{ dayId: string; entry: JournalEntry } | null>(null);
  const [showTripSettings, setShowTripSettings] = useState(false);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(trip));
  }, [trip]);

  useEffect(() => {
    const handleScroll = () => setIsScrolled(window.scrollY > 40);
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const generateDaysBetween = (start: Date, end: Date, existingDays: DayTimeline[]): DayTimeline[] => {
    const newDays: DayTimeline[] = [];
    // 確保時間歸零以進行精確的天數計算
    const s = new Date(start); s.setHours(0,0,0,0);
    const e = new Date(end); e.setHours(0,0,0,0);

    const diffTime = Math.abs(e.getTime() - s.getTime());
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)) + 1;

    for (let i = 0; i < diffDays; i++) {
      const currentDate = new Date(s);
      currentDate.setDate(s.getDate() + i);
      const dayStr = currentDate.toDateString();
      const existingDay = existingDays.find(d => d.date.toDateString() === dayStr);
      newDays.push({
        id: existingDay?.id || `day-${i + 1}-${Date.now()}-${i}`,
        date: currentDate,
        dayNumber: i + 1,
        entries: existingDay?.entries || []
      });
    }
    return newDays;
  };

  const handleSaveTripSettings = (title: string, start: Date, end: Date) => {
    const newDays = generateDaysBetween(start, end, trip.days);
    setTrip(prev => ({ ...prev, title, startDate: start, endDate: end, days: newDays }));
    setShowTripSettings(false);
  };

  const handleImportData = (entries: { date: string, entry: JournalEntry }[]) => {
    try {
      if (!entries || entries.length === 0) {
        alert("匯入失敗：接收到的行程資料為空。");
        return;
      }

      // 取得 CSV 日期範圍
      const sortedDates = entries.map(e => new Date(e.date).getTime()).sort((a, b) => a - b);
      const minDate = new Date(sortedDates[0]);
      const maxDate = new Date(sortedDates[sortedDates.length - 1]);

      const minDateStr = `${minDate.getFullYear()}/${minDate.getMonth()+1}/${minDate.getDate()}`;
      const maxDateStr = `${maxDate.getFullYear()}/${maxDate.getMonth()+1}/${maxDate.getDate()}`;

      // 檢查是否超出目前範圍
      const isOutOfRange = minDate < trip.startDate || maxDate > trip.endDate;

      const performImport = (targetTrip: Trip) => {
        let matchCount = 0;
        const updatedDays = targetTrip.days.map(day => {
          const y = day.date.getFullYear();
          const m = String(day.date.getMonth() + 1).padStart(2, '0');
          const d = String(day.date.getDate()).padStart(2, '0');
          const dayKey = `${y}-${m}-${d}`;

          const newEntriesForDay = entries
            .filter(item => item.date === dayKey)
            .map(item => item.entry);

          if (newEntriesForDay.length === 0) return day;
          matchCount += newEntriesForDay.length;

          const mergedEntries = [...day.entries, ...newEntriesForDay].sort((a, b) => {
            if (a.type === 'itinerary' && b.type === 'itinerary') {
              return (a as ItineraryEntry).time.localeCompare((b as ItineraryEntry).time);
            }
            return 0;
          });

          return { ...day, entries: mergedEntries };
        });

        if (matchCount > 0) {
          setTrip({ ...targetTrip, days: updatedDays });
          alert(`🎉 匯入成功！\n\n共匯入 ${matchCount} 筆資料到行程表中。`);
        } else {
          alert(`⚠️ 匹配失敗\n\n雖然解析了 ${entries.length} 筆資料，但沒有一筆日期落在旅程範圍 (${targetTrip.startDate.toLocaleDateString()} ~ ${targetTrip.endDate.toLocaleDateString()}) 之內。`);
        }
      };

      if (isOutOfRange) {
        const confirmMsg = `CSV 包含日期 ${minDateStr} ~ ${maxDateStr}，超出了目前旅程設定。\n\n是否要自動調整旅程起訖日並完成匯入？`;
        if (confirm(confirmMsg)) {
          const finalStart = minDate < trip.startDate ? minDate : trip.startDate;
          const finalEnd = maxDate > trip.endDate ? maxDate : trip.endDate;
          const expandedDays = generateDaysBetween(finalStart, finalEnd, trip.days);
          const expandedTrip = { ...trip, startDate: finalStart, endDate: finalEnd, days: expandedDays };
          performImport(expandedTrip);
        } else {
          alert("匯入已取消。原因：日期不在設定範圍內。");
        }
      } else {
        performImport(trip);
      }
    } catch (err) {
      alert(`系統錯誤：${err instanceof Error ? err.message : '處理匯入資料時發生未知錯誤'}`);
    }
  };

  const handleSaveEntry = (data: Partial<JournalEntry>) => {
    const formType = activeForm || editingEntry?.entry.type;
    if (!formType) return;

    if (editingEntry) {
      setTrip(prev => {
        const updatedDays: DayTimeline[] = prev.days.map(day => {
          if (day.id === editingEntry.dayId) {
            return {
              ...day,
              entries: day.entries.map(e => 
                e.id === editingEntry.entry.id ? ({ ...e, ...data } as JournalEntry) : e
              )
            };
          }
          return day;
        });
        return { ...prev, days: updatedDays };
      });
    } else {
      const newEntry: JournalEntry = {
        id: Date.now().toString(),
        timestamp: new Date(),
        type: formType,
        ...data
      } as any;

      setTrip(prev => {
        const updatedDays: DayTimeline[] = prev.days.map(day => {
          const isTargetDay = targetDayId ? day.id === targetDayId : day.id === prev.days[0]?.id;

          if (isTargetDay) {
            const sortedEntries: JournalEntry[] = [...day.entries, newEntry].sort((a, b) => {
              if (a.type === 'itinerary' && b.type === 'itinerary') {
                return (a as ItineraryEntry).time.localeCompare((b as ItineraryEntry).time);
              }
              return 0;
            });
            return { ...day, entries: sortedEntries };
          }
          return day;
        });
        return { ...prev, days: updatedDays };
      });
    }

    setActiveForm(null);
    setTargetDayId(null);
    setEditingEntry(null);
  };

  const handleAddEntryToDay = (dayId: string, type: EntryType) => {
    setTargetDayId(dayId);
    setActiveForm(type);
  };

  const handleDeleteEntry = useCallback((dayId: string, entryId: string) => {
    setTrip(prev => {
      const updatedDays = prev.days.map(day => {
        if (day.id === dayId) {
          return { 
            ...day, 
            entries: day.entries.filter(e => e.id !== entryId) 
          };
        }
        return day;
      });
      return { ...prev, days: updatedDays };
    });
  }, []);

  const handleEditEntryTrigger = (dayId: string, entry: JournalEntry) => {
    setEditingEntry({ dayId, entry });
  };

  const handlePrintPDF = () => {
    setShowTripSettings(false);
    setTimeout(() => {
      window.print();
    }, 500);
  };

  return (
    <div className="min-h-screen pb-40 max-w-lg mx-auto bg-[#FDFDFB] selection:bg-[#8DA399]/20 print:bg-white print:pb-0">
      <header 
        onClick={() => !isScrolled && setShowTripSettings(true)}
        className={`sticky top-0 z-40 transition-all duration-700 px-8 flex flex-col justify-end cursor-pointer print:relative print:mb-12 print:border-b-2 print:border-black ${isScrolled ? 'h-24 bg-white/95 backdrop-blur-lg border-b border-[#EFEFE9]' : 'h-48 bg-transparent'}`}
      >
        <div className="flex justify-between items-end pb-6">
          <div className="transition-all duration-700">
            {!isScrolled && <span className="text-[10px] font-bold uppercase tracking-[0.5em] text-[#8DA399] block mb-2">旅程計劃</span>}
            <h1 className={`font-semibold tracking-tight text-[#2A2A28] serif transition-all duration-700 ${isScrolled ? 'text-xl' : 'text-4xl'}`}>
              {trip.title}
            </h1>
            {!isScrolled && <p className="text-[11px] text-[#8A8A85] mt-3 tracking-wide font-medium">EXPLORING — {trip.days.length} 天之旅</p>}
          </div>
          <button onClick={(e) => { e.stopPropagation(); if(confirm('確定要清除所有旅程資料並重設嗎？')) { localStorage.removeItem(STORAGE_KEY); window.location.reload(); } }} className="p-2 opacity-40 hover:opacity-100 print:hidden transition-opacity">
            <Icon name="calendar" size={18} />
          </button>
        </div>
      </header>

      <main className="px-6 mt-10 print:mt-4">
        {activeTab === 'itinerary' && (
          <div className="animate-in fade-in duration-700">
            {trip.days.map((day) => (
              <DayCard 
                key={day.id} 
                day={day} 
                onDeleteEntry={handleDeleteEntry} 
                onEditEntry={handleEditEntryTrigger}
                onAddEntryToDay={handleAddEntryToDay}
              />
            ))}
          </div>
        )}

        {activeTab === 'expenses' && (
           <div className="animate-in fade-in slide-in-from-bottom-2 duration-700">
              <h2 className="text-[10px] font-black uppercase tracking-[0.4em] text-[#8A8A85] mb-12 border-b border-[#EFEFE9] pb-4">開支總覽</h2>
              {trip.days.map(day => {
                const dayExpenses = day.entries.filter(e => (e.type === 'itinerary' && (e as ItineraryEntry).expenseAmount) || e.type === 'expense');
                if (dayExpenses.length === 0) return null;
                return (
                  <div key={day.id} className="mb-10">
                    <span className="text-[10px] font-black text-[#2A2A28] mb-4 block uppercase tracking-widest">DAY {day.dayNumber}</span>
                    {dayExpenses.map((e: any) => (
                      <div key={e.id} onClick={() => handleEditEntryTrigger(day.id, e)} className="flex justify-between py-4 border-b border-[#EFEFE9] last:border-0 cursor-pointer">
                        <span className="text-sm font-medium text-[#2A2A28]">{e.type === 'itinerary' ? e.location : e.description}</span>
                        <span className="text-sm font-bold tabular-nums">¥ {(e.expenseAmount || e.amount).toLocaleString()}</span>
                      </div>
                    ))}
                  </div>
                );
              })}
              {trip.days.every(d => d.entries.filter(e => (e.type === 'itinerary' && (e as ItineraryEntry).expenseAmount) || e.type === 'expense').length === 0) && (
                <div className="py-20 text-center text-[#BABAB5]">
                  <p className="text-xs tracking-widest uppercase font-bold">尚無支出紀錄</p>
                </div>
              )}
           </div>
        )}

        {activeTab === 'trips' && (
           <div className="py-40 text-center text-[#BABAB5] border border-dashed border-[#EFEFE9] rounded-[40px]">
              <span className="text-[10px] font-bold uppercase tracking-widest">目前沒有典藏旅程</span>
           </div>
        )}
      </main>

      {(activeForm || editingEntry) && (
        <EntryForm 
          type={activeForm || editingEntry!.entry.type} 
          initialData={editingEntry?.entry}
          onClose={() => { setActiveForm(null); setEditingEntry(null); setTargetDayId(null); }} 
          onSave={handleSaveEntry} 
        />
      )}

      {showTripSettings && (
        <TripSettingsForm 
          trip={trip} 
          onClose={() => setShowTripSettings(false)} 
          onSave={handleSaveTripSettings}
          onImport={handleImportData}
          onPrint={handlePrintPDF}
        />
      )}

      <div className="fixed bottom-36 right-8 z-50 print:hidden">
        <button 
          onClick={() => setActiveForm('itinerary')}
          className="w-14 h-14 rounded-full bg-[#2A2A28] text-white flex items-center justify-center shadow-xl hover:bg-[#8DA399] transition-all active:scale-90"
        >
          <Icon name="plus" size={24} />
        </button>
      </div>

      <Navigation activeTab={activeTab} onTabChange={setActiveTab} />
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { Trip, JournalEntry, ItineraryEntry, ExpenseEntry } from '../types';
import Icon from './Icon';

interface TripSettingsFormProps {
  trip: Trip;
  onSave: (title: string, start: Date, end: Date) => void;
  onImport: (entries: { date: string, entry: JournalEntry }[]) => void;
  onClose: () => void;
  onPrint: () => void;
}

const TripSettingsForm: React.FC<TripSettingsFormProps> = ({ trip, onSave, onImport, onClose, onPrint }) => {
  const [title, setTitle] = useState(trip.title);
  const [start, setStart] = useState(trip.startDate.toISOString().split('T')[0]);
  const [end, setEnd] = useState(trip.endDate.toISOString().split('T')[0]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const tripYear = trip.startDate.getFullYear();

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave(title, new Date(start), new Date(end));
  };

  const exportToCSV = () => {
    const headers = ['日期', '天數', '類型', '時間/類別', '地點/描述', '金額(JPY)', '筆記/內容'];
    const rows: string[][] = [headers];

    trip.days.forEach(day => {
      const dateStr = day.date.toLocaleDateString('zh-TW');
      day.entries.forEach(entry => {
        let row: string[] = [dateStr, `第 ${day.dayNumber} 天`];

        if (entry.type === 'itinerary') {
          const e = entry as ItineraryEntry;
          const combinedNotes = [e.notes, e.reflection ? `感觸: ${e.reflection}` : ''].filter(Boolean).join(' | ');
          row.push('行程', e.time, e.location, e.expenseAmount?.toString() || '0', combinedNotes);
        } else if (entry.type === 'expense') {
          const e = entry as ExpenseEntry;
          row.push('支出', e.category, e.description, e.amount.toString(), '');
        }

        const escapedRow = row.map(cell => {
          const str = cell ? cell.toString().replace(/"/g, '""') : '';
          return `"${str}"`;
        });
        rows.push(escapedRow);
      });
    });

    const csvContent = "\uFEFF" + rows.map(e => e.join(",")).join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `${trip.title}_旅程紀錄.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleImportClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();

    reader.onerror = () => {
      alert("❌ 讀取檔案失敗。請確保檔案未被鎖定或損毀。");
    };

    reader.onload = (e) => {
      try {
        const text = e.target?.result as string;
        if (!text || text.trim().length === 0) {
          alert("❌ 檔案內容為空，無法讀取任何資料。");
          return;
        }

        const lines = text.split(/\r?\n/).filter(line => line.trim() !== '');
        if (lines.length < 2) {
          alert(`📊 讀取到 ${lines.length} 行內容，但這不足以構成一個包含標題與內容的旅程檔案。`);
          return;
        }

        const entries: { date: string, entry: JournalEntry }[] = [];
        const currentYear = trip.startDate.getFullYear();

        const splitCSV = (line: string) => {
          const result = [];
          let current = '';
          let inQuotes = false;
          for (let i = 0; i < line.length; i++) {
            const char = line[i];
            if (char === '"') inQuotes = !inQuotes;
            else if (char === ',' && !inQuotes) {
              result.push(current.trim());
              current = '';
            } else current += char;
          }
          result.push(current.trim());
          return result;
        };

        for (let i = 1; i < lines.length; i++) {
          const cells = splitCSV(lines[i]);
          if (cells.length < 5) continue;

          let [rawDate, , type, rawTime, locOrDesc, amountStr, notesStr] = cells;

          let finalDateStr = '';
          const dateNums = rawDate.match(/(\d+)/g);
          if (dateNums) {
            let y = currentYear, m = 0, d = 0;
            if (dateNums.length === 2) {
              m = parseInt(dateNums[0]);
              d = parseInt(dateNums[1]);
            } else if (dateNums.length >= 3) {
              const val1 = parseInt(dateNums[0]);
              const val2 = parseInt(dateNums[1]);
              const val3 = parseInt(dateNums[2]);

              if (val1 > 1000) { y = val1; m = val2; d = val3; } 
              else if (val3 > 1000) { y = val3; m = val2; d = val1; } 
              else { y = val1 + 2000; m = val2; d = val3; }
            }
            if (m > 0 && m <= 12 && d > 0 && d <= 31) {
              finalDateStr = `${y}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
            }
          }

          if (!finalDateStr) continue;

          let finalTime = rawTime || '12:00';
          if (finalTime.includes(':')) {
            const timeParts = finalTime.split(':');
            if (timeParts.length === 2) {
              const h = timeParts[0].padStart(2, '0');
              const min = timeParts[1].padStart(2, '0');
              finalTime = `${h}:${min}`;
            }
          }

          const id = `import-${Date.now()}-${i}`;
          const cleanAmount = (val: string) => {
            if (!val || val === '0') return 0;
            const parsed = parseFloat(val.replace(/[^\d.]/g, ''));
            return isNaN(parsed) ? 0 : parsed;
          };

          const typeStr = type.toLowerCase();
          const isExpense = typeStr.includes('支出') || typeStr.includes('帳務') || typeStr.includes('費用');

          if (isExpense) {
            entries.push({
              date: finalDateStr,
              entry: {
                id,
                timestamp: new Date(),
                type: 'expense',
                category: rawTime || '其他',
                description: locOrDesc || '支出項目',
                amount: cleanAmount(amountStr),
                currency: 'JPY'
              } as ExpenseEntry
            });
          } else {
            const notePrefix = type && !['行程', '交通', '景點', '飲食', 'Day'].some(s => typeStr.includes(s.toLowerCase())) ? `[${type}] ` : '';
            entries.push({
              date: finalDateStr,
              entry: {
                id,
                timestamp: new Date(),
                type: 'itinerary',
                time: finalTime,
                location: locOrDesc || '未命名地點',
                notes: notePrefix + (notesStr || ''),
                reflection: '',
                expenseAmount: cleanAmount(amountStr)
              } as ItineraryEntry
            });
          }
        }

        if (entries.length > 0) {
          onImport(entries);
        } else {
          alert('❓ 解析結果為 0\n\n檔案中有資料行，但無法解析出正確的日期或格式。請確保第一欄是日期（如 12/20）。');
        }
      } catch (err) {
        alert(`❌ 讀取過程中出錯：${err instanceof Error ? err.message : '未知錯誤'}`);
      }
      if (fileInputRef.current) fileInputRef.current.value = '';
    };

    // 嘗試使用 UTF-8 讀取
    reader.readAsText(file);
  };

  return (
    <div className="fixed inset-0 z-[110] bg-[#FDFDFB] animate-in slide-in-from-bottom duration-500 p-8 flex flex-col overflow-y-auto no-scrollbar print:hidden">
      <div className="flex justify-between items-center mb-12">
        <span className="text-[10px] font-black uppercase tracking-[0.5em] text-[#8DA399]">旅程設定</span>
        <button onClick={onClose} className="p-2 -mr-2">
          <Icon name="plus" size={24} className="rotate-45 text-[#BABAB5]" />
        </button>
      </div>

      <form onSubmit={handleSubmit} className="flex-1 flex flex-col gap-10">
        <div className="space-y-2">
          <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">旅程標題</label>
          <input 
            autoFocus
            type="text" 
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            className="w-full text-3xl serif outline-none bg-transparent border-b border-[#EFEFE9] pb-4 focus:border-[#8DA399] transition-colors"
            placeholder="例如：東京散策"
          />
        </div>

        <div className="grid grid-cols-2 gap-8">
          <div className="space-y-2">
            <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">開始日期</label>
            <input 
              type="date" 
              value={start}
              onChange={(e) => setStart(e.target.value)}
              className="w-full text-lg font-light outline-none bg-transparent border-b border-[#EFEFE9] pb-2 focus:border-[#8DA399] transition-colors"
            />
          </div>
          <div className="space-y-2">
            <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">結束日期</label>
            <input 
              type="date" 
              value={end}
              onChange={(e) => setEnd(e.target.value)}
              className="w-full text-lg font-light outline-none bg-transparent border-b border-[#EFEFE9] pb-2 focus:border-[#8DA399] transition-colors"
            />
          </div>
        </div>

        <div className="space-y-6 pt-6 border-t border-[#EFEFE9]">
          <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold block">備份與同步</label>
          <div className="grid grid-cols-2 gap-4">
            <button 
              type="button"
              onClick={exportToCSV}
              className="flex items-center justify-center gap-3 py-4 border border-[#EFEFE9] rounded-2xl hover:border-[#8DA399] transition-colors group bg-white shadow-sm"
            >
              <Icon name="download" size={16} className="text-[#BABAB5] group-hover:text-[#8DA399]" />
              <span className="text-[10px] font-bold uppercase tracking-widest text-[#2A2A28]">匯出 CSV</span>
            </button>
            <button 
              type="button"
              onClick={handleImportClick}
              className="flex items-center justify-center gap-3 py-4 border border-[#EFEFE9] rounded-2xl hover:border-[#8DA399] transition-colors group bg-white shadow-sm"
            >
              <Icon name="upload" size={16} className="text-[#BABAB5] group-hover:text-[#8DA399]" />
              <span className="text-[10px] font-bold uppercase tracking-widest text-[#2A2A28]">匯入 CSV</span>
            </button>
            <input 
              type="file" 
              ref={fileInputRef} 
              onChange={handleFileChange} 
              accept=".csv" 
              className="hidden" 
            />
          </div>

          <button 
            type="button"
            onClick={onPrint}
            className="w-full flex items-center justify-center gap-4 py-6 bg-[#F8F8F5] border border-[#EFEFE9] rounded-2xl hover:bg-[#2A2A28] hover:text-white transition-all group shadow-sm active:scale-95"
          >
            <Icon name="printer" size={18} className="text-[#8DA399] group-hover:text-white" />
            <span className="text-[11px] font-black uppercase tracking-[0.3em]">匯出 PDF (手帳版排版)</span>
          </button>

          <div className="p-6 bg-[#F8F8F5] rounded-[24px] border border-[#EFEFE9] space-y-6">
             <div className="flex items-center gap-2">
                <Icon name="more" size={14} className="text-[#8DA399]" />
                <span className="text-[9px] font-black uppercase tracking-[0.2em] text-[#8DA399]">CSV 匯入詳盡指南</span>
             </div>

             <div className="space-y-4 text-[10px] text-[#8A8A85] leading-relaxed">
               <div>
                 <strong className="text-[#2A2A28] block mb-1 underline">A. 欄位定義與解析邏輯</strong>
                 <ul className="list-disc list-inside space-y-1 ml-1">
                   <li><span className="text-[#2A2A28] font-medium">類型：</span>若包含「支出、帳務、費用」會歸類為帳本；其餘標籤（如「交通、景點」）會轉為行程，並將標籤保留於備註中。</li>
                   <li><span className="text-[#2A2A28] font-medium">金額：</span>系統會自動過濾非數字字元（如 ¥、$）。若該列為行程但金額大於 0，會同步顯示於該行程的開支欄。</li>
                   <li><span className="text-[#2A2A28] font-medium">日期：</span>支援 YYYY/MM/DD 或 MM/DD 格式。單獨 MM/DD 會使用目前旅程的年份。</li>
                 </ul>
               </div>

               <div className="bg-[#2A2A28]/5 p-3 rounded-lg overflow-x-auto">
                 <pre className="font-mono text-[9px] text-[#2A2A28] leading-tight">
                   日期,天數,類型,時間/類別,地點/描述,金額,筆記/內容<br/>
                   2025/12/20,Day 1,交通,9:06,前往高鐵站,0,14分鐘<br/>
                   2025/12/20,Day 1,支出,飲食,午餐拉麵,1500,好吃
                 </pre>
               </div>

               <div>
                 <strong className="text-[#2A2A28] block mb-1 underline">B. 常見匯入錯誤診斷</strong>
                 <div className="space-y-3">
                   <div className="flex gap-2 items-start">
                     <span className="px-1.5 py-0.5 bg-red-50 text-red-500 rounded font-bold shrink-0">錯誤</span>
                     <p>顯示「找不到匹配的日期」</p>
                   </div>
                   <div className="flex gap-2 items-start pl-4 border-l-2 border-[#EFEFE9]">
                     <span className="px-1.5 py-0.5 bg-green-50 text-green-600 rounded font-bold shrink-0">解法</span>
                     <p>檢查 CSV 日期是否正確，或是否超出了旅程設定的範圍。系統現在會詢問是否自動調整日期。</p>
                   </div>

                   <div className="flex gap-2 items-start">
                     <span className="px-1.5 py-0.5 bg-red-50 text-red-500 rounded font-bold shrink-0">錯誤</span>
                     <p>內容出現亂碼</p>
                   </div>
                   <div className="flex gap-2 items-start pl-4 border-l-2 border-[#EFEFE9]">
                     <span className="px-1.5 py-0.5 bg-green-50 text-green-600 rounded font-bold shrink-0">解法</span>
                     <p>請確保 CSV 存檔時選擇為 <span className="font-bold">UTF-8 編碼</span>（尤其是使用 Excel 編輯後匯出時）。</p>
                   </div>
                 </div>
               </div>
             </div>
          </div>
        </div>

        <div className="mt-auto pb-10">
          <button 
            type="submit"
            className="w-full py-5 bg-[#2A2A28] text-white rounded-2xl text-[10px] font-black uppercase tracking-[0.4em] hover:bg-[#8DA399] transition-all shadow-lg active:scale-95"
          >
            儲存旅程設定
          </button>
        </div>
      </form>
    </div>
  );
};

export default TripSettingsForm;

import React, { useState, useEffect, useCallback } from 'react';
import { AppTab, Trip, JournalEntry, EntryType, DayTimeline, ItineraryEntry, ExpenseEntry } from './types';
import { INITIAL_TRIP } from './constants';
import DayCard from './components/DayCard';
import Navigation from './components/Navigation';
import Icon from './components/Icon';
import EntryForm from './components/EntryForm';
import TripSettingsForm from './components/TripSettingsForm';

const STORAGE_KEY = 'komorebi_trip_data_v6';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<AppTab>('itinerary');
  const [trip, setTrip] = useState<Trip>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        parsed.startDate = new Date(parsed.startDate);
        parsed.endDate = new Date(parsed.endDate);
        parsed.days = parsed.days.map((d: any) => ({
          ...d,
          date: new Date(d.date),
          entries: d.entries.map((e: any) => ({
            ...e,
            timestamp: new Date(e.timestamp)
          }))
        }));
        return parsed;
      } catch (e) {
        return INITIAL_TRIP;
      }
    }
    return INITIAL_TRIP;
  });

  const [isScrolled, setIsScrolled] = useState(false);
  const [activeForm, setActiveForm] = useState<EntryType | null>(null);
  const [targetDayId, setTargetDayId] = useState<string | null>(null);
  const [editingEntry, setEditingEntry] = useState<{ dayId: string; entry: JournalEntry } | null>(null);
  const [showTripSettings, setShowTripSettings] = useState(false);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(trip));
  }, [trip]);

  useEffect(() => {
    const handleScroll = () => setIsScrolled(window.scrollY > 40);
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const generateDaysBetween = (start: Date, end: Date, existingDays: DayTimeline[]): DayTimeline[] => {
    const newDays: DayTimeline[] = [];
    const s = new Date(start); s.setHours(0,0,0,0);
    const e = new Date(end); e.setHours(0,0,0,0);
    const diffTime = Math.abs(e.getTime() - s.getTime());
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)) + 1;

    for (let i = 0; i < diffDays; i++) {
      const currentDate = new Date(s);
      currentDate.setDate(s.getDate() + i);
      const dayStr = currentDate.toDateString();
      const existingDay = existingDays.find(d => d.date.toDateString() === dayStr);
      newDays.push({
        id: existingDay?.id || `day-${i + 1}-${Date.now()}-${i}`,
        date: currentDate,
        dayNumber: i + 1,
        entries: existingDay?.entries || []
      });
    }
    return newDays;
  };

  const handleSaveTripSettings = (title: string, start: Date, end: Date) => {
    const newDays = generateDaysBetween(start, end, trip.days);
    setTrip(prev => ({ ...prev, title, startDate: start, endDate: end, days: newDays }));
    setShowTripSettings(false);
  };

  const handleImportData = (entries: { date: string, entry: JournalEntry }[]) => {
    try {
      if (!entries || entries.length === 0) {
        alert("📊 匯入失敗：CSV 解析後未發現任何有效行程。");
        return;
      }

      const sortedDates = entries.map(e => new Date(e.date).getTime()).sort((a, b) => a - b);
      const minDate = new Date(sortedDates[0]);
      const maxDate = new Date(sortedDates[sortedDates.length - 1]);

      const isOutOfRange = minDate < trip.startDate || maxDate > trip.endDate;

      const performImport = (targetTrip: Trip) => {
        let matchCount = 0;
        const updatedDays = targetTrip.days.map(day => {
          const y = day.date.getFullYear();
          const m = String(day.date.getMonth() + 1).padStart(2, '0');
          const d = String(day.date.getDate()).padStart(2, '0');
          const dayKey = `${y}-${m}-${d}`;

          const newEntriesForDay = entries
            .filter(item => item.date === dayKey)
            .map(item => item.entry);

          if (newEntriesForDay.length === 0) return day;
          matchCount += newEntriesForDay.length;

          const mergedEntries = [...day.entries, ...newEntriesForDay].sort((a, b) => {
            if (a.type === 'itinerary' && b.type === 'itinerary') {
              return (a as ItineraryEntry).time.localeCompare((b as ItineraryEntry).time);
            }
            return 0;
          });

          return { ...day, entries: mergedEntries };
        });

        if (matchCount > 0) {
          setTrip({ ...targetTrip, days: updatedDays });
          setShowTripSettings(false); // 成功後自動關閉設定視窗
          alert(`✨ 匯入成功！已將 ${matchCount} 筆行程加入到您的旅程中。`);
        } else {
          alert(`❓ 匹配失敗：解析了 ${entries.length} 筆資料，但沒有任何日期落在目前的旅程設定中。\n\n目前的旅程範圍：${targetTrip.startDate.toLocaleDateString()} ~ ${targetTrip.endDate.toLocaleDateString()}`);
        }
      };

      if (isOutOfRange) {
        if (confirm(`匯入的資料日期 (${minDate.toLocaleDateString()}~${maxDate.toLocaleDateString()}) 超出了目前旅程範圍。\n\n是否要自動擴展旅程日期範圍並匯入？`)) {
          const finalStart = minDate < trip.startDate ? minDate : trip.startDate;
          const finalEnd = maxDate > trip.endDate ? maxDate : trip.endDate;
          const expandedDays = generateDaysBetween(finalStart, finalEnd, trip.days);
          const expandedTrip = { ...trip, startDate: finalStart, endDate: finalEnd, days: expandedDays };
          performImport(expandedTrip);
        } else {
          alert("匯入已取消。原因：日期超出範圍。");
        }
      } else {
        performImport(trip);
      }
    } catch (err) {
      alert(`系統錯誤：${err instanceof Error ? err.message : '處理匯入時發生問題'}`);
    }
  };

  const handleSaveEntry = (data: Partial<JournalEntry>) => {
    const formType = activeForm || editingEntry?.entry.type;
    if (!formType) return;

    if (editingEntry) {
      setTrip(prev => {
        const updatedDays: DayTimeline[] = prev.days.map(day => {
          if (day.id === editingEntry.dayId) {
            return {
              ...day,
              entries: day.entries.map(e => 
                e.id === editingEntry.entry.id ? ({ ...e, ...data } as JournalEntry) : e
              )
            };
          }
          return day;
        });
        return { ...prev, days: updatedDays };
      });
    } else {
      const newEntry: JournalEntry = {
        id: Date.now().toString(),
        timestamp: new Date(),
        type: formType,
        ...data
      } as any;

      setTrip(prev => {
        const updatedDays: DayTimeline[] = prev.days.map(day => {
          const isTargetDay = targetDayId ? day.id === targetDayId : day.id === prev.days[0]?.id;

          if (isTargetDay) {
            const sortedEntries: JournalEntry[] = [...day.entries, newEntry].sort((a, b) => {
              if (a.type === 'itinerary' && b.type === 'itinerary') {
                return (a as ItineraryEntry).time.localeCompare((b as ItineraryEntry).time);
              }
              return 0;
            });
            return { ...day, entries: sortedEntries };
          }
          return day;
        });
        return { ...prev, days: updatedDays };
      });
    }

    setActiveForm(null);
    setTargetDayId(null);
    setEditingEntry(null);
  };

  const handleAddEntryToDay = (dayId: string, type: EntryType) => {
    setTargetDayId(dayId);
    setActiveForm(type);
  };

  const handleDeleteEntry = useCallback((dayId: string, entryId: string) => {
    setTrip(prev => {
      const updatedDays = prev.days.map(day => {
        if (day.id === dayId) {
          return { 
            ...day, 
            entries: day.entries.filter(e => e.id !== entryId) 
          };
        }
        return day;
      });
      return { ...prev, days: updatedDays };
    });
  }, []);

  const handleEditEntryTrigger = (dayId: string, entry: JournalEntry) => {
    setEditingEntry({ dayId, entry });
  };

  const handlePrintPDF = () => {
    setShowTripSettings(false);
    setTimeout(() => {
      window.print();
    }, 500);
  };

  return (
    <div className="min-h-screen pb-40 max-w-lg mx-auto bg-[#FDFDFB] selection:bg-[#8DA399]/20 print:bg-white print:pb-0">
      <header 
        onClick={() => !isScrolled && setShowTripSettings(true)}
        className={`sticky top-0 z-40 transition-all duration-700 px-8 flex flex-col justify-end cursor-pointer print:relative print:mb-12 print:border-b-2 print:border-black ${isScrolled ? 'h-24 bg-white/95 backdrop-blur-lg border-b border-[#EFEFE9]' : 'h-48 bg-transparent'}`}
      >
        <div className="flex justify-between items-end pb-6">
          <div className="transition-all duration-700">
            {!isScrolled && <span className="text-[10px] font-bold uppercase tracking-[0.5em] text-[#8DA399] block mb-2">旅程計劃</span>}
            <h1 className={`font-semibold tracking-tight text-[#2A2A28] serif transition-all duration-700 ${isScrolled ? 'text-xl' : 'text-4xl'}`}>
              {trip.title}
            </h1>
            {!isScrolled && <p className="text-[11px] text-[#8A8A85] mt-3 tracking-wide font-medium">EXPLORING — {trip.days.length} 天之旅</p>}
          </div>
          <button onClick={(e) => { e.stopPropagation(); if(confirm('確定要清除所有旅程資料並重設嗎？')) { localStorage.removeItem(STORAGE_KEY); window.location.reload(); } }} className="p-2 opacity-40 hover:opacity-100 print:hidden transition-opacity">
            <Icon name="calendar" size={18} />
          </button>
        </div>
      </header>

      <main className="px-6 mt-10 print:mt-4">
        {activeTab === 'itinerary' && (
          <div className="animate-in fade-in duration-700">
            {trip.days.map((day) => (
              <DayCard 
                key={day.id} 
                day={day} 
                onDeleteEntry={handleDeleteEntry} 
                onEditEntry={handleEditEntryTrigger}
                onAddEntryToDay={handleAddEntryToDay}
              />
            ))}
          </div>
        )}

        {activeTab === 'expenses' && (
           <div className="animate-in fade-in slide-in-from-bottom-2 duration-700">
              <h2 className="text-[10px] font-black uppercase tracking-[0.4em] text-[#8A8A85] mb-12 border-b border-[#EFEFE9] pb-4">開支總覽</h2>
              {trip.days.map(day => {
                const dayExpenses = day.entries.filter(e => (e.type === 'itinerary' && (e as ItineraryEntry).expenseAmount) || e.type === 'expense');
                if (dayExpenses.length === 0) return null;
                return (
                  <div key={day.id} className="mb-10">
                    <span className="text-[10px] font-black text-[#2A2A28] mb-4 block uppercase tracking-widest">DAY {day.dayNumber}</span>
                    {dayExpenses.map((e: any) => (
                      <div key={e.id} onClick={() => handleEditEntryTrigger(day.id, e)} className="flex justify-between py-4 border-b border-[#EFEFE9] last:border-0 cursor-pointer">
                        <span className="text-sm font-medium text-[#2A2A28]">{e.type === 'itinerary' ? e.location : e.description}</span>
                        <span className="text-sm font-bold tabular-nums">¥ {(e.expenseAmount || e.amount).toLocaleString()}</span>
                      </div>
                    ))}
                  </div>
                );
              })}
              {trip.days.every(d => d.entries.filter(e => (e.type === 'itinerary' && (e as ItineraryEntry).expenseAmount) || e.type === 'expense').length === 0) && (
                <div className="py-20 text-center text-[#BABAB5]">
                  <p className="text-xs tracking-widest uppercase font-bold">尚無支出紀錄</p>
                </div>
              )}
           </div>
        )}

        {activeTab === 'trips' && (
           <div className="py-40 text-center text-[#BABAB5] border border-dashed border-[#EFEFE9] rounded-[40px]">
              <span className="text-[10px] font-bold uppercase tracking-widest">目前沒有典藏旅程</span>
           </div>
        )}
      </main>

      {(activeForm || editingEntry) && (
        <EntryForm 
          type={activeForm || editingEntry!.entry.type} 
          initialData={editingEntry?.entry}
          onClose={() => { setActiveForm(null); setEditingEntry(null); setTargetDayId(null); }} 
          onSave={handleSaveEntry} 
        />
      )}

      {showTripSettings && (
        <TripSettingsForm 
          trip={trip} 
          onClose={() => setShowTripSettings(false)} 
          onSave={handleSaveTripSettings}
          onImport={handleImportData}
          onPrint={handlePrintPDF}
        />
      )}

      <div className="fixed bottom-36 right-8 z-50 print:hidden">
        <button 
          onClick={() => setActiveForm('itinerary')}
          className="w-14 h-14 rounded-full bg-[#2A2A28] text-white flex items-center justify-center shadow-xl hover:bg-[#8DA399] transition-all active:scale-90"
        >
          <Icon name="plus" size={24} />
        </button>
      </div>

      <Navigation activeTab={activeTab} onTabChange={setActiveTab} />
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { Trip, JournalEntry, ItineraryEntry, ExpenseEntry } from '../types';
import Icon from './Icon';

interface TripSettingsFormProps {
  trip: Trip;
  onSave: (title: string, start: Date, end: Date) => void;
  onImport: (entries: { date: string, entry: JournalEntry }[]) => void;
  onClose: () => void;
  onPrint: () => void;
}

const TripSettingsForm: React.FC<TripSettingsFormProps> = ({ trip, onSave, onImport, onClose, onPrint }) => {
  const [title, setTitle] = useState(trip.title);
  const [start, setStart] = useState(trip.startDate.toISOString().split('T')[0]);
  const [end, setEnd] = useState(trip.endDate.toISOString().split('T')[0]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave(title, new Date(start), new Date(end));
  };

  const exportToCSV = () => {
    const headers = ['日期', '天數', '類型', '時間/類別', '地點/描述', '金額(JPY)', '筆記/內容'];
    const rows: string[][] = [headers];

    trip.days.forEach(day => {
      const dateStr = day.date.toLocaleDateString('zh-TW');
      day.entries.forEach(entry => {
        let row: string[] = [dateStr, `第 ${day.dayNumber} 天`];

        if (entry.type === 'itinerary') {
          const e = entry as ItineraryEntry;
          const combinedNotes = [e.notes, e.reflection ? `感觸: ${e.reflection}` : ''].filter(Boolean).join(' | ');
          row.push('行程', e.time, e.location, e.expenseAmount?.toString() || '0', combinedNotes);
        } else if (entry.type === 'expense') {
          const e = entry as ExpenseEntry;
          row.push('支出', e.category, e.description, e.amount.toString(), '');
        }

        const escapedRow = row.map(cell => {
          const str = cell ? cell.toString().replace(/"/g, '""') : '';
          return `"${str}"`;
        });
        rows.push(escapedRow);
      });
    });

    const csvContent = "\uFEFF" + rows.map(e => e.join(",")).join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `${trip.title}_旅程紀錄.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleImportClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();

    reader.onerror = () => {
      alert("❌ 讀取檔案失敗。請確保檔案未被鎖定，且為標準 CSV 格式。");
    };

    reader.onload = (e) => {
      try {
        const text = e.target?.result as string;
        if (!text || text.trim().length === 0) {
          alert("❌ 檔案內容為空，無法讀取。");
          return;
        }

        const lines = text.split(/\r?\n/).filter(line => line.trim() !== '');
        if (lines.length < 2) {
          alert(`📊 讀取到 ${lines.length} 行，這可能不是有效的旅程 CSV (需標題+資料)。`);
          return;
        }

        const entries: { date: string, entry: JournalEntry }[] = [];
        const currentYear = trip.startDate.getFullYear();

        const splitCSV = (line: string) => {
          const result = [];
          let current = '';
          let inQuotes = false;
          for (let i = 0; i < line.length; i++) {
            const char = line[i];
            if (char === '"') inQuotes = !inQuotes;
            else if (char === ',' && !inQuotes) {
              result.push(current.trim());
              current = '';
            } else current += char;
          }
          result.push(current.trim());
          return result;
        };

        for (let i = 1; i < lines.length; i++) {
          const cells = splitCSV(lines[i]);
          if (cells.length < 5) continue;

          let [rawDate, , type, rawTime, locOrDesc, amountStr, notesStr] = cells;

          let finalDateStr = '';
          // 支援多種日期分隔符如 / 或 .
          const dateNums = rawDate.match(/(\d+)/g);
          if (dateNums) {
            let y = currentYear, m = 0, d = 0;
            if (dateNums.length === 2) {
              m = parseInt(dateNums[0]);
              d = parseInt(dateNums[1]);
            } else if (dateNums.length >= 3) {
              const val1 = parseInt(dateNums[0]);
              const val2 = parseInt(dateNums[1]);
              const val3 = parseInt(dateNums[2]);

              if (val1 > 1000) { y = val1; m = val2; d = val3; } 
              else if (val3 > 1000) { y = val3; m = val2; d = val1; } 
              else { y = val1 + 2000; m = val2; d = val3; }
            }
            if (m > 0 && m <= 12 && d > 0 && d <= 31) {
              finalDateStr = `${y}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
            }
          }

          if (!finalDateStr) continue;

          // 時間自動補齊
          let finalTime = rawTime || '12:00';
          if (finalTime.includes(':')) {
            const timeParts = finalTime.split(':');
            if (timeParts.length === 2) {
              const h = timeParts[0].padStart(2, '0');
              const min = timeParts[1].padStart(2, '0');
              finalTime = `${h}:${min}`;
            }
          }

          const id = `import-${Date.now()}-${i}`;
          const cleanAmount = (val: string) => {
            if (!val || val === '0') return 0;
            const parsed = parseFloat(val.replace(/[^\d.]/g, ''));
            return isNaN(parsed) ? 0 : parsed;
          };

          const typeStr = (type || "").toLowerCase();
          const isExpense = typeStr.includes('支出') || typeStr.includes('帳務') || typeStr.includes('費用') || typeStr.includes('expense');

          if (isExpense) {
            entries.push({
              date: finalDateStr,
              entry: {
                id,
                timestamp: new Date(),
                type: 'expense',
                category: rawTime || '其他',
                description: locOrDesc || '支出項目',
                amount: cleanAmount(amountStr),
                currency: 'JPY'
              } as ExpenseEntry
            });
          } else {
            const notePrefix = type && !['行程', '交通', '景點', '飲食', 'Day'].some(s => typeStr.includes(s.toLowerCase())) ? `[${type}] ` : '';
            entries.push({
              date: finalDateStr,
              entry: {
                id,
                timestamp: new Date(),
                type: 'itinerary',
                time: finalTime,
                location: locOrDesc || '未命名地點',
                notes: notePrefix + (notesStr || ''),
                reflection: '',
                expenseAmount: cleanAmount(amountStr)
              } as ItineraryEntry
            });
          }
        }

        if (entries.length > 0) {
          onImport(entries); // 由 App.tsx 觸發最終結果通知
        } else {
          alert('❓ 解析無果\n\n雖然讀取了檔案，但沒有找到符合格式的資料列。請確認 CSV 日期格式。');
        }
      } catch (err) {
        alert(`❌ 解析過程錯誤：${err instanceof Error ? err.message : '未知錯誤'}`);
      }
      if (fileInputRef.current) fileInputRef.current.value = '';
    };
    reader.readAsText(file);
  };

  return (
    <div className="fixed inset-0 z-[110] bg-[#FDFDFB] animate-in slide-in-from-bottom duration-500 p-8 flex flex-col overflow-y-auto no-scrollbar print:hidden">
      <div className="flex justify-between items-center mb-12">
        <span className="text-[10px] font-black uppercase tracking-[0.5em] text-[#8DA399]">旅程設定</span>
        <button onClick={onClose} className="p-2 -mr-2">
          <Icon name="plus" size={24} className="rotate-45 text-[#BABAB5]" />
        </button>
      </div>

      <form onSubmit={handleSubmit} className="flex-1 flex flex-col gap-10">
        <div className="space-y-2">
          <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">旅程標題</label>
          <input 
            autoFocus
            type="text" 
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            className="w-full text-3xl serif outline-none bg-transparent border-b border-[#EFEFE9] pb-4 focus:border-[#8DA399] transition-colors"
            placeholder="例如：東京散策"
          />
        </div>

        <div className="grid grid-cols-2 gap-8">
          <div className="space-y-2">
            <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">開始日期</label>
            <input 
              type="date" 
              value={start}
              onChange={(e) => setStart(e.target.value)}
              className="w-full text-lg font-light outline-none bg-transparent border-b border-[#EFEFE9] pb-2 focus:border-[#8DA399] transition-colors"
            />
          </div>
          <div className="space-y-2">
            <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">結束日期</label>
            <input 
              type="date" 
              value={end}
              onChange={(e) => setEnd(e.target.value)}
              className="w-full text-lg font-light outline-none bg-transparent border-b border-[#EFEFE9] pb-2 focus:border-[#8DA399] transition-colors"
            />
          </div>
        </div>

        <div className="space-y-6 pt-6 border-t border-[#EFEFE9]">
          <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold block">備份與同步</label>
          <div className="grid grid-cols-2 gap-4">
            <button 
              type="button"
              onClick={exportToCSV}
              className="flex items-center justify-center gap-3 py-4 border border-[#EFEFE9] rounded-2xl hover:border-[#8DA399] transition-colors group bg-white shadow-sm"
            >
              <Icon name="download" size={16} className="text-[#BABAB5] group-hover:text-[#8DA399]" />
              <span className="text-[10px] font-bold uppercase tracking-widest text-[#2A2A28]">匯出 CSV</span>
            </button>
            <button 
              type="button"
              onClick={handleImportClick}
              className="flex items-center justify-center gap-3 py-4 border border-[#EFEFE9] rounded-2xl hover:border-[#8DA399] transition-colors group bg-white shadow-sm"
            >
              <Icon name="upload" size={16} className="text-[#BABAB5] group-hover:text-[#8DA399]" />
              <span className="text-[10px] font-bold uppercase tracking-widest text-[#2A2A28]">匯入 CSV</span>
            </button>
            <input 
              type="file" 
              ref={fileInputRef} 
              onChange={handleFileChange} 
              accept=".csv" 
              className="hidden" 
            />
          </div>

          <button 
            type="button"
            onClick={onPrint}
            className="w-full flex items-center justify-center gap-4 py-6 bg-[#F8F8F5] border border-[#EFEFE9] rounded-2xl hover:bg-[#2A2A28] hover:text-white transition-all group shadow-sm active:scale-95"
          >
            <Icon name="printer" size={18} className="text-[#8DA399] group-hover:text-white" />
            <span className="text-[11px] font-black uppercase tracking-[0.3em]">匯出 PDF (手帳版排版)</span>
          </button>

          {/* 詳細指南卡片 */}
          <div className="p-6 bg-[#F8F8F5] rounded-[24px] border border-[#EFEFE9] space-y-6">
             <div className="flex items-center gap-2">
                <Icon name="more" size={14} className="text-[#8DA399]" />
                <span className="text-[9px] font-black uppercase tracking-[0.2em] text-[#8DA399]">CSV 匯入詳盡指南</span>
             </div>

             <div className="space-y-4 text-[10px] text-[#8A8A85] leading-relaxed">
               <div>
                 <strong className="text-[#2A2A28] block mb-1 underline">A. 欄位定義與解析邏輯</strong>
                 <ul className="list-disc list-inside space-y-1 ml-1">
                   <li><span className="text-[#2A2A28] font-medium">類型：</span>「支出、帳務、費用」歸為帳本；其餘如「交通、景點」轉為行程，標籤保留於備註。</li>
                   <li><span className="text-[#2A2A28] font-medium">金額：</span>自動過濾符號（如 ¥）。行程列若有金額，會顯示為該項目的單獨花費。</li>
                   <li><span className="text-[#2A2A28] font-medium">日期：</span>支援 YYYY/MM/DD 或 MM/DD (自動帶入當前年份)。</li>
                 </ul>
               </div>

               <div className="bg-[#2A2A28]/5 p-3 rounded-lg overflow-x-auto">
                 <pre className="font-mono text-[9px] text-[#2A2A28] leading-tight">
                   日期,天數,類型,時間/類別,地點/描述,金額,筆記/內容<br/>
                   2025/12/20,Day 1,交通,9:06,前往高鐵站,0,14分鐘<br/>
                   2025/12/20,Day 1,支出,飲食,午餐拉麵,1500,好吃
                 </pre>
               </div>

               <div>
                 <strong className="text-[#2A2A28] block mb-1 underline">B. 常見匯入錯誤診斷</strong>
                 <div className="space-y-3">
                   <div className="flex gap-2 items-start">
                     <span className="px-1.5 py-0.5 bg-red-50 text-red-500 rounded font-bold shrink-0">錯誤</span>
                     <p>彈窗顯示「找不到匹配的日期」</p>
                   </div>
                   <div className="flex gap-2 items-start pl-4 border-l-2 border-[#EFEFE9]">
                     <span className="px-1.5 py-0.5 bg-green-50 text-green-600 rounded font-bold shrink-0">解法</span>
                     <p>檢查 CSV 的日期欄。若日期正確但不在旅程範圍內，匯入時選擇「自動擴展範圍」。</p>
                   </div>

                   <div className="flex gap-2 items-start">
                     <span className="px-1.5 py-0.5 bg-red-50 text-red-500 rounded font-bold shrink-0">錯誤</span>
                     <p>顯示內容出現亂碼</p>
                   </div>
                   <div className="flex gap-2 items-start pl-4 border-l-2 border-[#EFEFE9]">
                     <span className="px-1.5 py-0.5 bg-green-50 text-green-600 rounded font-bold shrink-0">解法</span>
                     <p>請確保 CSV 存檔為 <span className="font-bold">UTF-8 編碼</span>。Excel 編輯後請另存新檔並選擇對應編碼。</p>
                   </div>
                 </div>
               </div>
             </div>
          </div>
        </div>

        <div className="mt-auto pb-10">
          <button 
            type="submit"
            className="w-full py-5 bg-[#2A2A28] text-white rounded-2xl text-[10px] font-black uppercase tracking-[0.4em] hover:bg-[#8DA399] transition-all shadow-lg active:scale-95"
          >
            儲存旅程設定
          </button>
        </div>
      </form>
    </div>
  );
};

export default TripSettingsForm;

import React, { useState, useEffect, useCallback } from 'react';
import { AppTab, Trip, JournalEntry, EntryType, DayTimeline, ItineraryEntry, ExpenseEntry } from './types';
import { INITIAL_TRIP } from './constants';
import DayCard from './components/DayCard';
import Navigation from './components/Navigation';
import Icon from './components/Icon';
import EntryForm from './components/EntryForm';
import TripSettingsForm from './components/TripSettingsForm';

const STORAGE_KEY = 'komorebi_trip_data_v6';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<AppTab>('itinerary');
  const [trip, setTrip] = useState<Trip>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        parsed.startDate = new Date(parsed.startDate);
        parsed.endDate = new Date(parsed.endDate);
        parsed.days = parsed.days.map((d: any) => ({
          ...d,
          date: new Date(d.date),
          entries: d.entries.map((e: any) => ({
            ...e,
            timestamp: new Date(e.timestamp)
          }))
        }));
        return parsed;
      } catch (e) {
        return INITIAL_TRIP;
      }
    }
    return INITIAL_TRIP;
  });

  const [isScrolled, setIsScrolled] = useState(false);
  const [activeForm, setActiveForm] = useState<EntryType | null>(null);
  const [targetDayId, setTargetDayId] = useState<string | null>(null);
  const [editingEntry, setEditingEntry] = useState<{ dayId: string; entry: JournalEntry } | null>(null);
  const [showTripSettings, setShowTripSettings] = useState(false);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(trip));
  }, [trip]);

  useEffect(() => {
    const handleScroll = () => setIsScrolled(window.scrollY > 40);
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const generateDaysBetween = (start: Date, end: Date, existingDays: DayTimeline[]): DayTimeline[] => {
    const newDays: DayTimeline[] = [];
    // Normalize to midnight local time for consistent comparison
    const s = new Date(start.getFullYear(), start.getMonth(), start.getDate());
    const e = new Date(end.getFullYear(), end.getMonth(), end.getDate());

    const diffTime = Math.abs(e.getTime() - s.getTime());
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)) + 1;

    for (let i = 0; i < diffDays; i++) {
      const currentDate = new Date(s);
      currentDate.setDate(s.getDate() + i);
      const dayStr = currentDate.toDateString();
      const existingDay = existingDays.find(d => d.date.toDateString() === dayStr);
      newDays.push({
        id: existingDay?.id || `day-${i + 1}-${Date.now()}-${i}`,
        date: currentDate,
        dayNumber: i + 1,
        entries: existingDay?.entries || []
      });
    }
    return newDays;
  };

  const handleSaveTripSettings = (title: string, start: Date, end: Date) => {
    const newDays = generateDaysBetween(start, end, trip.days);
    setTrip(prev => ({ ...prev, title, startDate: start, endDate: end, days: newDays }));
    setShowTripSettings(false);
  };

  const handleImportData = (entries: { date: string, entry: JournalEntry }[]) => {
    try {
      if (!entries || entries.length === 0) {
        alert("📊 匯入失敗：CSV 解析後未發現任何有效行程。");
        return;
      }

      // Calculate the bounds of the imported data
      const sortedDates = entries.map(e => {
        const [y, m, d] = e.date.split('-').map(Number);
        return new Date(y, m - 1, d).getTime();
      }).sort((a, b) => a - b);

      const minDate = new Date(sortedDates[0]);
      const maxDate = new Date(sortedDates[sortedDates.length - 1]);

      // Normalize current trip bounds for comparison
      const tripStart = new Date(trip.startDate.getFullYear(), trip.startDate.getMonth(), trip.startDate.getDate());
      const tripEnd = new Date(trip.endDate.getFullYear(), trip.endDate.getMonth(), trip.endDate.getDate());

      const isOutOfRange = minDate < tripStart || maxDate > tripEnd;

      const performImport = (targetTrip: Trip) => {
        let matchCount = 0;
        const updatedDays = targetTrip.days.map(day => {
          const y = day.date.getFullYear();
          const m = String(day.date.getMonth() + 1).padStart(2, '0');
          const d = String(day.date.getDate()).padStart(2, '0');
          const dayKey = `${y}-${m}-${d}`;

          const newEntriesForDay = entries
            .filter(item => item.date === dayKey)
            .map(item => item.entry);

          if (newEntriesForDay.length === 0) return day;
          matchCount += newEntriesForDay.length;

          const mergedEntries = [...day.entries, ...newEntriesForDay].sort((a, b) => {
            if (a.type === 'itinerary' && b.type === 'itinerary') {
              return (a as ItineraryEntry).time.localeCompare((b as ItineraryEntry).time);
            }
            return 0;
          });

          return { ...day, entries: mergedEntries };
        });

        if (matchCount > 0) {
          setTrip({ ...targetTrip, days: updatedDays });
          setShowTripSettings(false);
          setActiveTab('itinerary');
          alert(`✨ 匯入成功！已成功匹配並匯入 ${matchCount} 筆資料。`);
        } else {
          alert(`❓ 匹配失敗：解析了 ${entries.length} 筆資料，但沒有任何日期落在您的旅程範圍 (${targetTrip.startDate.toLocaleDateString()} ~ ${targetTrip.endDate.toLocaleDateString()})。`);
        }
      };

      if (isOutOfRange) {
        const confirmMsg = `匯入資料的日期範圍 (${minDate.toLocaleDateString()} ~ ${maxDate.toLocaleDateString()}) 超出了目前旅程的設定範圍。\n\n是否要「自動擴展」您的旅程起訖日以完成匯入？`;
        if (confirm(confirmMsg)) {
          const finalStart = minDate < tripStart ? minDate : tripStart;
          const finalEnd = maxDate > tripEnd ? maxDate : tripEnd;
          const expandedDays = generateDaysBetween(finalStart, finalEnd, trip.days);
          const expandedTrip = { ...trip, startDate: finalStart, endDate: finalEnd, days: expandedDays };
          performImport(expandedTrip);
        } else {
          alert("匯入已取消。資料日期不在目前旅程設定內。");
        }
      } else {
        performImport(trip);
      }
    } catch (err) {
      alert(`❌ 處理資料時發生錯誤：${err instanceof Error ? err.message : '未知錯誤'}`);
    }
  };

  const handleSaveEntry = (data: Partial<JournalEntry>) => {
    const formType = activeForm || editingEntry?.entry.type;
    if (!formType) return;

    if (editingEntry) {
      setTrip(prev => {
        const updatedDays: DayTimeline[] = prev.days.map(day => {
          if (day.id === editingEntry.dayId) {
            return {
              ...day,
              entries: day.entries.map(e => 
                e.id === editingEntry.entry.id ? ({ ...e, ...data } as JournalEntry) : e
              )
            };
          }
          return day;
        });
        return { ...prev, days: updatedDays };
      });
    } else {
      const newEntry: JournalEntry = {
        id: Date.now().toString(),
        timestamp: new Date(),
        type: formType,
        ...data
      } as any;

      setTrip(prev => {
        const updatedDays: DayTimeline[] = prev.days.map(day => {
          const isTargetDay = targetDayId ? day.id === targetDayId : day.id === prev.days[0]?.id;

          if (isTargetDay) {
            const sortedEntries: JournalEntry[] = [...day.entries, newEntry].sort((a, b) => {
              if (a.type === 'itinerary' && b.type === 'itinerary') {
                return (a as ItineraryEntry).time.localeCompare((b as ItineraryEntry).time);
              }
              return 0;
            });
            return { ...day, entries: sortedEntries };
          }
          return day;
        });
        return { ...prev, days: updatedDays };
      });
    }

    setActiveForm(null);
    setTargetDayId(null);
    setEditingEntry(null);
  };

  const handleAddEntryToDay = (dayId: string, type: EntryType) => {
    setTargetDayId(dayId);
    setActiveForm(type);
  };

  const handleDeleteEntry = useCallback((dayId: string, entryId: string) => {
    setTrip(prev => {
      const updatedDays = prev.days.map(day => {
        if (day.id === dayId) {
          return { 
            ...day, 
            entries: day.entries.filter(e => e.id !== entryId) 
          };
        }
        return day;
      });
      return { ...prev, days: updatedDays };
    });
  }, []);

  const handleEditEntryTrigger = (dayId: string, entry: JournalEntry) => {
    setEditingEntry({ dayId, entry });
  };

  const handlePrintPDF = () => {
    setShowTripSettings(false);
    setTimeout(() => {
      window.print();
    }, 500);
  };

  return (
    <div className="min-h-screen pb-40 max-w-lg mx-auto bg-[#FDFDFB] selection:bg-[#8DA399]/20 print:bg-white print:pb-0">
      <header 
        onClick={() => !isScrolled && setShowTripSettings(true)}
        className={`sticky top-0 z-40 transition-all duration-700 px-8 flex flex-col justify-end cursor-pointer print:relative print:mb-12 print:border-b-2 print:border-black ${isScrolled ? 'h-24 bg-white/95 backdrop-blur-lg border-b border-[#EFEFE9]' : 'h-48 bg-transparent'}`}
      >
        <div className="flex justify-between items-end pb-6">
          <div className="transition-all duration-700">
            {!isScrolled && <span className="text-[10px] font-bold uppercase tracking-[0.5em] text-[#8DA399] block mb-2">旅程計劃</span>}
            <h1 className={`font-semibold tracking-tight text-[#2A2A28] serif transition-all duration-700 ${isScrolled ? 'text-xl' : 'text-4xl'}`}>
              {trip.title}
            </h1>
            {!isScrolled && <p className="text-[11px] text-[#8A8A85] mt-3 tracking-wide font-medium">EXPLORING — {trip.days.length} 天之旅</p>}
          </div>
          <button onClick={(e) => { e.stopPropagation(); if(confirm('確定要清除所有旅程資料並重設嗎？')) { localStorage.removeItem(STORAGE_KEY); window.location.reload(); } }} className="p-2 opacity-40 hover:opacity-100 print:hidden transition-opacity">
            <Icon name="calendar" size={18} />
          </button>
        </div>
      </header>

      <main className="px-6 mt-10 print:mt-4">
        {activeTab === 'itinerary' && (
          <div className="animate-in fade-in duration-700">
            {trip.days.map((day) => (
              <DayCard 
                key={day.id} 
                day={day} 
                onDeleteEntry={handleDeleteEntry} 
                onEditEntry={handleEditEntryTrigger}
                onAddEntryToDay={handleAddEntryToDay}
              />
            ))}
          </div>
        )}

        {activeTab === 'expenses' && (
           <div className="animate-in fade-in slide-in-from-bottom-2 duration-700">
              <h2 className="text-[10px] font-black uppercase tracking-[0.4em] text-[#8A8A85] mb-12 border-b border-[#EFEFE9] pb-4">開支總覽</h2>
              {trip.days.map(day => {
                const dayExpenses = day.entries.filter(e => (e.type === 'itinerary' && (e as ItineraryEntry).expenseAmount) || e.type === 'expense');
                if (dayExpenses.length === 0) return null;
                return (
                  <div key={day.id} className="mb-10">
                    <span className="text-[10px] font-black text-[#2A2A28] mb-4 block uppercase tracking-widest">DAY {day.dayNumber}</span>
                    {dayExpenses.map((e: any) => (
                      <div key={e.id} onClick={() => handleEditEntryTrigger(day.id, e)} className="flex justify-between py-4 border-b border-[#EFEFE9] last:border-0 cursor-pointer">
                        <span className="text-sm font-medium text-[#2A2A28]">{e.type === 'itinerary' ? e.location : e.description}</span>
                        <span className="text-sm font-bold tabular-nums">¥ {(e.expenseAmount || e.amount).toLocaleString()}</span>
                      </div>
                    ))}
                  </div>
                );
              })}
              {trip.days.every(d => d.entries.filter(e => (e.type === 'itinerary' && (e as ItineraryEntry).expenseAmount) || e.type === 'expense').length === 0) && (
                <div className="py-20 text-center text-[#BABAB5]">
                  <p className="text-xs tracking-widest uppercase font-bold">尚無支出紀錄</p>
                </div>
              )}
           </div>
        )}

        {activeTab === 'trips' && (
           <div className="py-40 text-center text-[#BABAB5] border border-dashed border-[#EFEFE9] rounded-[40px]">
              <span className="text-[10px] font-bold uppercase tracking-widest">目前沒有典藏旅程</span>
           </div>
        )}
      </main>

      {(activeForm || editingEntry) && (
        <EntryForm 
          type={activeForm || editingEntry!.entry.type} 
          initialData={editingEntry?.entry}
          onClose={() => { setActiveForm(null); setEditingEntry(null); setTargetDayId(null); }} 
          onSave={handleSaveEntry} 
        />
      )}

      {showTripSettings && (
        <TripSettingsForm 
          trip={trip} 
          onClose={() => setShowTripSettings(false)} 
          onSave={handleSaveTripSettings}
          onImport={handleImportData}
          onPrint={handlePrintPDF}
        />
      )}

      <div className="fixed bottom-36 right-8 z-50 print:hidden">
        <button 
          onClick={() => setActiveForm('itinerary')}
          className="w-14 h-14 rounded-full bg-[#2A2A28] text-white flex items-center justify-center shadow-xl hover:bg-[#8DA399] transition-all active:scale-90"
        >
          <Icon name="plus" size={24} />
        </button>
      </div>

      <Navigation activeTab={activeTab} onTabChange={setActiveTab} />
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { Trip, JournalEntry, ItineraryEntry, ExpenseEntry } from '../types';
import Icon from './Icon';

interface TripSettingsFormProps {
  trip: Trip;
  onSave: (title: string, start: Date, end: Date) => void;
  onImport: (entries: { date: string, entry: JournalEntry }[]) => void;
  onClose: () => void;
  onPrint: () => void;
}

const TripSettingsForm: React.FC<TripSettingsFormProps> = ({ trip, onSave, onImport, onClose, onPrint }) => {
  const [title, setTitle] = useState(trip.title);
  const [start, setStart] = useState(trip.startDate.toISOString().split('T')[0]);
  const [end, setEnd] = useState(trip.endDate.toISOString().split('T')[0]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave(title, new Date(start), new Date(end));
  };

  const exportToCSV = () => {
    const headers = ['日期', '天數', '類型', '時間/類別', '地點/描述', '金額(JPY)', '筆記/內容'];
    const rows: string[][] = [headers];

    trip.days.forEach(day => {
      const dateStr = day.date.toLocaleDateString('zh-TW');
      day.entries.forEach(entry => {
        let row: string[] = [dateStr, `第 ${day.dayNumber} 天`];

        if (entry.type === 'itinerary') {
          const e = entry as ItineraryEntry;
          const combinedNotes = [e.notes, e.reflection ? `感觸: ${e.reflection}` : ''].filter(Boolean).join(' | ');
          row.push('行程', e.time, e.location, e.expenseAmount?.toString() || '0', combinedNotes);
        } else if (entry.type === 'expense') {
          const e = entry as ExpenseEntry;
          row.push('支出', e.category, e.description, e.amount.toString(), '');
        }

        const escapedRow = row.map(cell => {
          const str = cell ? cell.toString().replace(/"/g, '""') : '';
          return `"${str}"`;
        });
        rows.push(escapedRow);
      });
    });

    const csvContent = "\uFEFF" + rows.map(e => e.join(",")).join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `${trip.title}_旅程紀錄.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleImportClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    alert(`正在讀取檔案：${file.name}...`);

    const reader = new FileReader();

    reader.onerror = () => {
      alert("❌ 檔案讀取中斷或失敗。請確認該檔案未被其他程式佔用。");
    };

    reader.onload = (e) => {
      try {
        const text = e.target?.result as string;
        if (!text || text.trim().length === 0) {
          alert("❌ 檔案內容為空，無法讀取資料。");
          return;
        }

        const lines = text.split(/\r?\n/).filter(line => line.trim() !== '');
        if (lines.length < 2) {
          alert(`📊 資料行數不足：讀取到 ${lines.length} 行，至少需包含標題與一行資料。`);
          return;
        }

        const entries: { date: string, entry: JournalEntry }[] = [];
        const currentYear = trip.startDate.getFullYear();

        const splitCSV = (line: string) => {
          const result = [];
          let current = '';
          let inQuotes = false;
          for (let i = 0; i < line.length; i++) {
            const char = line[i];
            if (char === '"') inQuotes = !inQuotes;
            else if (char === ',' && !inQuotes) {
              result.push(current.trim());
              current = '';
            } else current += char;
          }
          result.push(current.trim());
          return result;
        };

        for (let i = 1; i < lines.length; i++) {
          const cells = splitCSV(lines[i]);
          // Require at least 5 columns to be useful (Date, Skip, Type, Time, Loc)
          if (cells.length < 5) continue;

          let rawDate = cells[0];
          let type = cells[2];
          let rawTime = cells[3];
          let locOrDesc = cells[4];
          let amountStr = cells[5] || '0';
          let notesStr = cells[6] || '';

          let finalDateStr = '';
          const dateNums = (rawDate || "").match(/(\d+)/g);
          if (dateNums) {
            let y = currentYear, m = 0, d = 0;
            if (dateNums.length === 2) {
              m = parseInt(dateNums[0]);
              d = parseInt(dateNums[1]);
            } else if (dateNums.length >= 3) {
              const val1 = parseInt(dateNums[0]);
              const val2 = parseInt(dateNums[1]);
              const val3 = parseInt(dateNums[2]);

              if (val1 > 1000) { y = val1; m = val2; d = val3; } 
              else if (val3 > 1000) { y = val3; m = val2; d = val1; } 
              else { y = val1 + 2000; m = val2; d = val3; }
            }
            if (m > 0 && m <= 12 && d > 0 && d <= 31) {
              finalDateStr = `${y}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
            }
          }

          if (!finalDateStr) continue;

          // Time formatting
          let finalTime = rawTime || '12:00';
          if (finalTime.includes(':')) {
            const timeParts = finalTime.split(':');
            if (timeParts.length === 2) {
              const h = timeParts[0].padStart(2, '0');
              const min = timeParts[1].padStart(2, '0');
              finalTime = `${h}:${min}`;
            }
          }

          const id = `import-${Date.now()}-${i}`;
          const cleanAmount = (val: any) => {
            if (val === undefined || val === null || val === '' || val === '0') return 0;
            const str = String(val);
            const parsed = parseFloat(str.replace(/[^\d.]/g, ''));
            return isNaN(parsed) ? 0 : parsed;
          };

          const typeStr = (type || "").toLowerCase();
          const isExpense = typeStr.includes('支出') || typeStr.includes('帳務') || typeStr.includes('費用') || typeStr.includes('expense');

          if (isExpense) {
            entries.push({
              date: finalDateStr,
              entry: {
                id,
                timestamp: new Date(),
                type: 'expense',
                category: rawTime || '其他',
                description: locOrDesc || '支出項目',
                amount: cleanAmount(amountStr),
                currency: 'JPY'
              } as ExpenseEntry
            });
          } else {
            const notePrefix = type && !['行程', '交通', '景點', '飲食', 'Day'].some(s => typeStr.includes(s.toLowerCase())) ? `[${type}] ` : '';
            entries.push({
              date: finalDateStr,
              entry: {
                id,
                timestamp: new Date(),
                type: 'itinerary',
                time: finalTime,
                location: locOrDesc || '未命名地點',
                notes: notePrefix + (notesStr || ''),
                reflection: '',
                expenseAmount: cleanAmount(amountStr)
              } as ItineraryEntry
            });
          }
        }

        if (entries.length > 0) {
          onImport(entries);
        } else {
          alert('❓ 解析無果：讀取了檔案但未發現任何符合格式的日期列。請確認 CSV 的第一欄是否為正確日期（如 2024/12/20）。');
        }
      } catch (err) {
        alert(`❌ 解析 CSV 時出錯：${err instanceof Error ? err.message : '未知錯誤'}。請確保檔案編碼為 UTF-8。`);
      }
      // Reset input value to allow re-selecting the same file
      if (fileInputRef.current) fileInputRef.current.value = '';
    };
    reader.readAsText(file);
  };

  return (
    <div className="fixed inset-0 z-[110] bg-[#FDFDFB] animate-in slide-in-from-bottom duration-500 p-8 flex flex-col overflow-y-auto no-scrollbar print:hidden">
      <div className="flex justify-between items-center mb-12">
        <span className="text-[10px] font-black uppercase tracking-[0.5em] text-[#8DA399]">旅程設定</span>
        <button onClick={onClose} className="p-2 -mr-2">
          <Icon name="plus" size={24} className="rotate-45 text-[#BABAB5]" />
        </button>
      </div>

      <form onSubmit={handleSubmit} className="flex-1 flex flex-col gap-10">
        <div className="space-y-2">
          <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">旅程標題</label>
          <input 
            autoFocus
            type="text" 
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            className="w-full text-3xl serif outline-none bg-transparent border-b border-[#EFEFE9] pb-4 focus:border-[#8DA399] transition-colors"
            placeholder="例如：東京散策"
          />
        </div>

        <div className="grid grid-cols-2 gap-8">
          <div className="space-y-2">
            <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">開始日期</label>
            <input 
              type="date" 
              value={start}
              onChange={(e) => setStart(e.target.value)}
              className="w-full text-lg font-light outline-none bg-transparent border-b border-[#EFEFE9] pb-2 focus:border-[#8DA399] transition-colors"
            />
          </div>
          <div className="space-y-2">
            <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">結束日期</label>
            <input 
              type="date" 
              value={end}
              onChange={(e) => setEnd(e.target.value)}
              className="w-full text-lg font-light outline-none bg-transparent border-b border-[#EFEFE9] pb-2 focus:border-[#8DA399] transition-colors"
            />
          </div>
        </div>

        <div className="space-y-6 pt-6 border-t border-[#EFEFE9]">
          <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold block">備份與同步</label>
          <div className="grid grid-cols-2 gap-4">
            <button 
              type="button"
              onClick={exportToCSV}
              className="flex items-center justify-center gap-3 py-4 border border-[#EFEFE9] rounded-2xl hover:border-[#8DA399] transition-colors group bg-white shadow-sm"
            >
              <Icon name="download" size={16} className="text-[#BABAB5] group-hover:text-[#8DA399]" />
              <span className="text-[10px] font-bold uppercase tracking-widest text-[#2A2A28]">匯出 CSV</span>
            </button>
            <button 
              type="button"
              onClick={handleImportClick}
              className="flex items-center justify-center gap-3 py-4 border border-[#EFEFE9] rounded-2xl hover:border-[#8DA399] transition-colors group bg-white shadow-sm"
            >
              <Icon name="upload" size={16} className="text-[#BABAB5] group-hover:text-[#8DA399]" />
              <span className="text-[10px] font-bold uppercase tracking-widest text-[#2A2A28]">匯入 CSV</span>
            </button>
            <input 
              type="file" 
              ref={fileInputRef} 
              onChange={handleFileChange} 
              accept=".csv" 
              className="hidden" 
            />
          </div>

          <button 
            type="button"
            onClick={onPrint}
            className="w-full flex items-center justify-center gap-4 py-6 bg-[#F8F8F5] border border-[#EFEFE9] rounded-2xl hover:bg-[#2A2A28] hover:text-white transition-all group shadow-sm active:scale-95"
          >
            <Icon name="printer" size={18} className="text-[#8DA399] group-hover:text-white" />
            <span className="text-[11px] font-black uppercase tracking-[0.3em]">匯出 PDF (手帳版排版)</span>
          </button>

          <div className="p-6 bg-[#F8F8F5] rounded-[24px] border border-[#EFEFE9] space-y-6">
             <div className="flex items-center gap-2">
                <Icon name="more" size={14} className="text-[#8DA399]" />
                <span className="text-[9px] font-black uppercase tracking-[0.2em] text-[#8DA399]">CSV 匯入詳盡指南</span>
             </div>

             <div className="space-y-4 text-[10px] text-[#8A8A85] leading-relaxed">
               <div>
                 <strong className="text-[#2A2A28] block mb-1 underline">A. 欄位定義與解析邏輯</strong>
                 <ul className="list-disc list-inside space-y-1 ml-1">
                   <li><span className="text-[#2A2A28] font-medium">類型：</span>「支出、帳務、費用」歸為帳本；其餘標籤（如「交通、景點」）轉為行程，標籤保留於備註。</li>
