             <span className="text-xs font-bold text-[#BABAB5] bg-white border border-[#EFEFE9] px-2 py-0.5 rounded-md">{weekday}</span>
          </div>
          <div className="h-[2px] w-full bg-gradient-to-r from-[#EFEFE9] to-transparent" />
