        >
          <Icon name="plus" size={20} className="group-hover:rotate-90 transition-transform duration-300" />
        </button>
      </div>

      {/* Timeline Section */}
      <div className="relative pl-2">
        {day.entries.filter(e => e.type === 'itinerary').length > 0 && (
          <div className="absolute left-[13px] top-6 bottom-10 w-[3px] rounded-full bg-gradient-to-b from-[#EFEFE9] via-[#EFEFE9] to-transparent" />
        )}

        {day.entries.length === 0 ? (
          <div 
            onClick={() => onAddEntryToDay(day.id, 'itinerary')}
            className="ml-14 py-16 flex flex-col items-center justify-center text-[#8A8A85] border-4 border-dashed border-white rounded-[40px] bg-white/30 cursor-pointer hover:bg-white/60 transition-all group"
          >
            <div className="w-12 h-12 rounded-full bg-white flex items-center justify-center shadow-sm mb-4 group-hover:scale-110 transition-transform">
               <Icon name="plus" size={20} className="opacity-40" />
            </div>
            <span className="text-[10px] tracking-[0.2em] uppercase font-black">點擊開啟今天的回憶</span>
          </div>
        ) : (
          <div className="space-y-4">
            {day.entries.map((entry) => (
              <EntryItem 
                key={entry.id} 
                entry={entry} 
                onDelete={(entryId) => onDeleteEntry(day.id, entryId)}
                onEdit={(entryData) => onEditEntry(day.id, entryData)}
              />
            ))}
          </div>
        )}
      </div>

      {/* Summary Tag */}
      {totalExpense > 0 && (
        <div className="mt-6 ml-14 flex items-center">
          <div className="px-4 py-2 bg-[#FDFDFB] border border-[#EFEFE9] rounded-2xl shadow-sm flex items-center gap-3">
            <span className="text-[9px] font-black uppercase tracking-widest text-[#8DA399]">Day Total</span>
            <div className="w-[1px] h-3 bg-[#EFEFE9]" />
            <span className="text-sm font-bold tabular-nums">¥ {totalExpense.toLocaleString()}</span>
          </div>
        </div>
      )}
    </div>
  );
};

export default DayCard;

import React from 'react';
import { JournalEntry, ItineraryEntry, ExpenseEntry } from '../types';
import Icon from './Icon';

interface EntryItemProps {
  entry: JournalEntry;
  onDelete?: (id: string) => void;
  onEdit?: (entry: JournalEntry) => void;
}

const EntryItem: React.FC<EntryItemProps> = ({ entry, onDelete, onEdit }) => {
