  if (entry.type === 'itinerary') {
    const item = entry as ItineraryEntry;
    return (
      <div 
        onClick={handleEdit}
        className="relative pl-14 mb-8 group cursor-pointer active:scale-[0.98] transition-all"
      >
        {/* Timeline Indicator */}
        <div className="absolute left-[8px] top-6 w-[12px] h-[12px] rounded-full bg-white border-2 border-[#8DA399] shadow-sm z-10" />

        {/* Card Body */}
        <div className="bg-white rounded-[32px] p-7 border border-[#EFEFE9] shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all relative overflow-hidden">
          {/* Subtle decoration */}
          <div className="absolute top-0 right-0 w-16 h-16 bg-[#FDFDFB] rounded-bl-[40px] -mr-4 -mt-4 z-0 border-l border-b border-[#F8F8F5]" />

          <div className="relative z-10">
            <div className="flex justify-between items-start mb-4">
              <div className="flex items-center gap-2">
                <Icon name="clock" size={12} className="text-[#8DA399]" />
                <span className="text-[11px] font-black text-[#8DA399] tracking-widest uppercase">{item.time}</span>
              </div>

              {item.expenseAmount ? (
                <div className="flex flex-col items-end">
                  <span className="text-sm font-black tabular-nums text-[#2A2A28]">
                    ¥{item.expenseAmount.toLocaleString()}
                  </span>
                  <span className="text-[8px] font-bold text-[#BABAB5] uppercase tracking-tighter">{item.expenseCategory || '飲食'}</span>
