            <h4 className="text-xl font-bold text-[#2A2A28] mb-2 serif leading-tight">{item.location}</h4>
            {item.notes && <p className="text-xs text-[#8A8A85] leading-relaxed font-medium mb-4">{item.notes}</p>}

            {item.reflection && (
              <div className="mt-5 p-4 bg-[#FAF9F6] rounded-2xl border-l-4 border-[#8DA399]/30 italic">
                <p className="serif text-[#2A2A28] leading-relaxed text-sm opacity-90">
                  「{item.reflection}」
                </p>
              </div>
            )}
          </div>

          <button 
            onClick={handleDelete}
            className="absolute right-4 bottom-4 bg-white/80 backdrop-blur-sm rounded-xl shadow-sm opacity-0 group-hover:opacity-100 transition-opacity text-[#BABAB5] hover:text-red-400 p-2 border border-[#EFEFE9]"
          >
            <Icon name="plus" size={14} className="rotate-45" />
          </button>
        </div>
      </div>
    );
  }

  if (entry.type === 'expense') {
    const item = entry as ExpenseEntry;
    return (
      <div 
        onClick={handleEdit} 
        className="ml-14 flex justify-between items-center py-5 px-6 border-2 border-dashed border-[#EFEFE9] rounded-[28px] group cursor-pointer bg-white/60 hover:bg-white hover:border-[#8DA399] transition-all hover:shadow-md"
      >
        <div className="flex items-center gap-4">
          <div className="w-8 h-8 rounded-full bg-[#EFEFE9] flex items-center justify-center text-[#8A8A85]">
             <Icon name="expenses" size={14} />
          </div>
          <div>
            <span className="text-[9px] text-[#8DA399] font-black uppercase block tracking-widest">{item.category}</span>
            <span className="text-sm font-bold text-[#2A2A28]">{item.description}</span>
          </div>
        </div>
        <div className="flex items-center gap-5">
          <span className="text-md font-black tabular-nums">¥{item.amount.toLocaleString()}</span>
          <button onClick={handleDelete} className="opacity-0 group-hover:opacity-100 p-1 text-[#BABAB5] hover:text-red-400 transition-all"><Icon name="plus" size={16} className="rotate-45" /></button>
        </div>
      </div>
    );
  }

  return null;
};

export default EntryItem;

import React, { useState, useEffect, useCallback } from 'react';
import { AppTab, Trip, JournalEntry, EntryType, DayTimeline, ItineraryEntry, ExpenseEntry } from './types';
import { INITIAL_TRIP, COLORS } from './constants';
import DayCard from './components/DayCard';
import Navigation from './components/Navigation';
import Icon from './components/Icon';
import EntryForm from './components/EntryForm';
import TripSettingsForm from './components/TripSettingsForm';

const STORAGE_KEY = 'komorebi_trip_data_v7';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<AppTab>('itinerary');
  const [trip, setTrip] = useState<Trip>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        parsed.startDate = new Date(parsed.startDate);
        parsed.endDate = new Date(parsed.endDate);
        parsed.days = parsed.days.map((d: any) => ({
          ...d,
          date: new Date(d.date),
          entries: d.entries.map((e: any) => ({
            ...e,
            timestamp: new Date(e.timestamp)
          }))
        }));
        return parsed;
      } catch (e) {
        return INITIAL_TRIP;
      }
    }
    return INITIAL_TRIP;
  });

  const [isScrolled, setIsScrolled] = useState(false);
  const [activeForm, setActiveForm] = useState<EntryType | null>(null);
  const [targetDayId, setTargetDayId] = useState<string | null>(null);
  const [editingEntry, setEditingEntry] = useState<{ dayId: string; entry: JournalEntry } | null>(null);
  const [showTripSettings, setShowTripSettings] = useState(false);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(trip));
  }, [trip]);

  useEffect(() => {
    const handleScroll = () => setIsScrolled(window.scrollY > 40);
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const generateDaysBetween = (start: Date, end: Date, existingDays: DayTimeline[]): DayTimeline[] => {
    const newDays: DayTimeline[] = [];
    // 使用精確的本地午夜時間進行計算
    const s = new Date(start.getFullYear(), start.getMonth(), start.getDate(), 0, 0, 0, 0);
    const e = new Date(end.getFullYear(), end.getMonth(), end.getDate(), 0, 0, 0, 0);

    // 計算毫秒差異，並考慮到夏令時間（雖然台灣沒有，但這是好習慣）
    const dayMs = 1000 * 60 * 60 * 24;
    const diffDays = Math.round((e.getTime() - s.getTime()) / dayMs) + 1;

    for (let i = 0; i < diffDays; i++) {
      const currentDate = new Date(s);
      currentDate.setDate(s.getDate() + i);
      const dayStr = currentDate.toDateString();
      const existingDay = existingDays.find(d => d.date.toDateString() === dayStr);
      newDays.push({
        id: existingDay?.id || `day-${Date.now()}-${i}`,
        date: currentDate,
        dayNumber: i + 1,
        entries: existingDay?.entries || []
      });
    }
    return newDays;
  };

  const handleSaveTripSettings = (title: string, start: Date, end: Date) => {
    const newDays = generateDaysBetween(start, end, trip.days);
    setTrip(prev => ({ ...prev, title, startDate: start, endDate: end, days: newDays }));
    setShowTripSettings(false);
  };

  const handleImportData = (entries: { date: string, entry: JournalEntry }[]) => {
    try {
      if (!entries || entries.length === 0) {
        alert("📊 匯入失敗：未發現有效行程。");
        return;
      }

      const importDates = entries.map(e => {
        const [y, m, d] = e.date.split('-').map(Number);
        return new Date(y, m - 1, d, 0, 0, 0, 0).getTime();
      }).filter(t => !isNaN(t));

      const minDate = new Date(Math.min(...importDates));
      const maxDate = new Date(Math.max(...importDates));

      const tripStart = new Date(trip.startDate.getFullYear(), trip.startDate.getMonth(), trip.startDate.getDate(), 0, 0, 0, 0);
      const tripEnd = new Date(trip.endDate.getFullYear(), trip.endDate.getMonth(), trip.endDate.getDate(), 0, 0, 0, 0);

      const performImport = (targetTrip: Trip) => {
        let matchCount = 0;
        const updatedDays = targetTrip.days.map(day => {
          const y = day.date.getFullYear();
          const m = String(day.date.getMonth() + 1).padStart(2, '0');
          const d = String(day.date.getDate()).padStart(2, '0');
          const dayKey = `${y}-${m}-${d}`;

          const newEntriesForDay = entries
            .filter(item => item.date === dayKey)
            .map(item => item.entry);

          if (newEntriesForDay.length === 0) return day;
          matchCount += newEntriesForDay.length;

          const mergedEntries = [...day.entries, ...newEntriesForDay].sort((a, b) => {
            if (a.type === 'itinerary' && b.type === 'itinerary') {
              return (a as ItineraryEntry).time.localeCompare((b as ItineraryEntry).time);
            }
            return 0;
          });

          return { ...day, entries: mergedEntries };
        });

        setTrip({ ...targetTrip, days: updatedDays });
        setShowTripSettings(false);
        setActiveTab('itinerary');
        alert(`✨ 成功！已匯入 ${matchCount} 筆資料。`);
      };

      if (minDate < tripStart || maxDate > tripEnd) {
        if (confirm(`匯入資料日期 (${new Date(minDate).toLocaleDateString()} ~ ${new Date(maxDate).toLocaleDateString()}) 超出目前範圍。\n\n是否要自動調整旅程範圍以匹配資料？`)) {
          const finalDays = generateDaysBetween(new Date(minDate), new Date(maxDate), trip.days);
          const expandedTrip = { ...trip, startDate: new Date(minDate), endDate: new Date(maxDate), days: finalDays };
          performImport(expandedTrip);
        }
      } else {
        performImport(trip);
      }
    } catch (err) {
      alert(`❌ 匯入錯誤：${err instanceof Error ? err.message : '未知錯誤'}`);
    }
  };

  // Fix: Added missing handleDeleteEntry function
  const handleDeleteEntry = (dayId: string, entryId: string) => {
    setTrip(prev => ({
      ...prev,
      days: prev.days.map(day => {
        if (day.id === dayId) {
          return {
            ...day,
            entries: day.entries.filter(e => e.id !== entryId)
          };
        }
        return day;
      })
    }));
  };

  // Fix: Added missing handleEditEntryTrigger function
  const handleEditEntryTrigger = (dayId: string, entry: JournalEntry) => {
    setEditingEntry({ dayId, entry });
  };

  // Fix: Added missing handleAddEntryToDay function
  const handleAddEntryToDay = (dayId: string, type: EntryType) => {
    setTargetDayId(dayId);
    setActiveForm(type);
  };

  // Fix: Added missing handlePrintPDF function
  const handlePrintPDF = () => {
    window.print();
  };

  const handleSaveEntry = (data: Partial<JournalEntry>) => {
    const formType = activeForm || editingEntry?.entry.type;
    if (!formType) return;

    if (editingEntry) {
      setTrip(prev => {
        const updatedDays = prev.days.map(day => {
          if (day.id === editingEntry.dayId) {
            return {
              ...day,
              entries: day.entries.map(e => e.id === editingEntry.entry.id ? ({ ...e, ...data } as JournalEntry) : e)
            };
          }
          return day;
        });
        return { ...prev, days: updatedDays };
      });
    } else {
      const newEntry: JournalEntry = { id: Date.now().toString(), timestamp: new Date(), type: formType, ...data } as any;
      setTrip(prev => {
        const updatedDays = prev.days.map(day => {
          if (targetDayId ? day.id === targetDayId : day.id === prev.days[0]?.id) {
            const sorted = [...day.entries, newEntry].sort((a, b) => {
              if (a.type === 'itinerary' && b.type === 'itinerary') return (a as ItineraryEntry).time.localeCompare((b as ItineraryEntry).time);
              return 0;
            });
            return { ...day, entries: sorted };
          }
          return day;
        });
        return { ...prev, days: updatedDays };
      });
    }
    setActiveForm(null);
    setTargetDayId(null);
    setEditingEntry(null);
  };

  return (
    <div className="min-h-screen pb-40 max-w-lg mx-auto bg-[#FAF9F6] relative overflow-x-hidden print:bg-white print:pb-0">
      {/* Decorative Blobs */}
      <div className="fixed top-20 -left-20 w-64 h-64 bg-[#E8F1EF]/40 rounded-full blur-3xl -z-10 animate-pulse" />
      <div className="fixed bottom-40 -right-20 w-80 h-80 bg-[#FFF5E1]/40 rounded-full blur-3xl -z-10" />

      <header 
        onClick={() => !isScrolled && setShowTripSettings(true)}
        className={`sticky top-0 z-40 transition-all duration-500 px-8 flex flex-col justify-end cursor-pointer print:relative ${isScrolled ? 'h-24 bg-white/80 backdrop-blur-xl border-b border-[#EFEFE9]' : 'h-56 bg-transparent'}`}
      >
        <div className="flex justify-between items-end pb-8">
          <div className="transition-all duration-500">
            {!isScrolled && (
              <div className="flex items-center gap-2 mb-3">
                 <span className="w-8 h-8 rounded-lg bg-[#8DA399] flex items-center justify-center text-white rotate-3">
                   <Icon name="trips" size={16} />
                 </span>
                 <span className="text-[10px] font-black uppercase tracking-[0.4em] text-[#8DA399]">Travel Log</span>
              </div>
            )}
            <h1 className={`font-bold tracking-tight text-[#2A2A28] serif transition-all duration-500 ${isScrolled ? 'text-xl' : 'text-5xl leading-tight'}`}>
              {trip.title}
            </h1>
            {!isScrolled && (
              <div className="flex items-center gap-4 mt-4">
                <p className="text-[11px] text-[#8A8A85] tracking-wide font-bold bg-white/50 px-3 py-1 rounded-full border border-[#EFEFE9]">
                  {trip.days.length} DAYS JOURNEY
                </p>
                <div className="flex -space-x-2">
                  {[1,2,3].map(i => <div key={i} className={`w-6 h-6 rounded-full border-2 border-white bg-slate-200`} />)}
                </div>
              </div>
            )}
          </div>
          <button onClick={(e) => { e.stopPropagation(); if(confirm('重設所有旅程嗎？')) { localStorage.removeItem(STORAGE_KEY); window.location.reload(); } }} className="p-3 bg-white rounded-2xl shadow-sm border border-[#EFEFE9] hover:bg-red-50 transition-colors print:hidden">
            <Icon name="calendar" size={18} className="text-[#BABAB5]" />
          </button>
        </div>
      </header>

      <main className="px-6 mt-6 print:mt-4 relative z-10">
        {activeTab === 'itinerary' && (
          <div className="space-y-4">
            {trip.days.map((day) => (
              <DayCard 
                key={day.id} 
                day={day} 
                onDeleteEntry={handleDeleteEntry} 
                onEditEntry={handleEditEntryTrigger}
                onAddEntryToDay={handleAddEntryToDay}
              />
            ))}
          </div>
        )}

        {activeTab === 'expenses' && (
           <div className="animate-in fade-in slide-in-from-bottom-4 duration-700 bg-white rounded-[40px] p-8 border border-[#EFEFE9] shadow-sm">
              <div className="flex items-center gap-3 mb-10">
                <div className="w-10 h-10 rounded-2xl bg-[#F9EBE7] flex items-center justify-center text-[#A67C74]">
                  <Icon name="expenses" size={20} />
                </div>
                <h2 className="text-xl font-bold serif">帳本統計</h2>
              </div>

              {trip.days.map(day => {
                const dayExpenses = day.entries.filter(e => (e.type === 'itinerary' && (e as ItineraryEntry).expenseAmount) || e.type === 'expense');
                if (dayExpenses.length === 0) return null;
                return (
                  <div key={day.id} className="mb-10 last:mb-0">
                    <div className="flex items-center gap-3 mb-4">
                      <span className="text-[10px] font-black text-[#8A8A85] uppercase tracking-widest">DAY {day.dayNumber}</span>
                      <div className="h-[1px] flex-1 bg-[#EFEFE9]" />
                    </div>
                    {dayExpenses.map((e: any) => (
                      <div key={e.id} onClick={() => handleEditEntryTrigger(day.id, e)} className="flex justify-between py-5 border-b border-[#F8F8F5] last:border-0 cursor-pointer hover:px-2 transition-all group">
                        <div className="flex flex-col">
                           <span className="text-sm font-bold text-[#2A2A28] group-hover:text-[#8DA399] transition-colors">{e.type === 'itinerary' ? e.location : e.description}</span>
                           <span className="text-[10px] font-bold text-[#BABAB5] uppercase mt-1 tracking-tighter">{e.type === 'itinerary' ? (e.expenseCategory || '一般') : e.category}</span>
                        </div>
                        <span className="text-md font-black tabular-nums self-center">¥ {(e.expenseAmount || e.amount).toLocaleString()}</span>
                      </div>
                    ))}
                  </div>
                );
              })}
           </div>
        )}

        {activeTab === 'trips' && (
           <div className="py-40 text-center bg-white/40 border-4 border-dashed border-white rounded-[40px]">
              <div className="w-20 h-20 bg-white rounded-full flex items-center justify-center mx-auto mb-6 shadow-sm">
                <Icon name="trips" size={32} className="text-[#BABAB5]" />
              </div>
              <p className="text-[12px] font-black uppercase tracking-widest text-[#BABAB5]">收藏空間準備中</p>
           </div>
        )}
      </main>

      {(activeForm || editingEntry) && (
        <EntryForm 
          type={activeForm || editingEntry!.entry.type} 
          initialData={editingEntry?.entry}
          onClose={() => { setActiveForm(null); setEditingEntry(null); setTargetDayId(null); }} 
          onSave={handleSaveEntry} 
        />
      )}

      {showTripSettings && (
        <TripSettingsForm 
          trip={trip} 
          onClose={() => setShowTripSettings(false)} 
          onSave={handleSaveTripSettings}
          onImport={handleImportData}
          onPrint={handlePrintPDF}
        />
      )}

      <div className="fixed bottom-36 right-8 z-50 print:hidden">
        <button 
          onClick={() => setActiveForm('itinerary')}
          className="w-16 h-16 rounded-[24px] bg-[#2A2A28] text-white flex items-center justify-center shadow-2xl hover:bg-[#8DA399] transition-all active:scale-90 hover:rotate-6"
        >
          <Icon name="plus" size={28} />
        </button>
      </div>

      <Navigation activeTab={activeTab} onTabChange={setActiveTab} />
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { AppTab, Trip, JournalEntry, EntryType, DayTimeline, ItineraryEntry, ExpenseEntry } from './types';
import { INITIAL_TRIP, COLORS } from './constants';
import DayCard from './components/DayCard';
import Navigation from './components/Navigation';
import Icon from './components/Icon';
import EntryForm from './components/EntryForm';
import TripSettingsForm from './components/TripSettingsForm';

const STORAGE_KEY = 'komorebi_trip_data_v8';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<AppTab>('itinerary');
  const [trip, setTrip] = useState<Trip>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        parsed.startDate = new Date(parsed.startDate);
        parsed.endDate = new Date(parsed.endDate);
        parsed.days = parsed.days.map((d: any) => ({
          ...d,
          date: new Date(d.date),
          entries: d.entries.map((e: any) => ({
            ...e,
            timestamp: new Date(e.timestamp)
          }))
        }));
        return parsed;
      } catch (e) {
        return INITIAL_TRIP;
      }
    }
    return INITIAL_TRIP;
  });

  const [isScrolled, setIsScrolled] = useState(false);
  const [activeForm, setActiveForm] = useState<EntryType | null>(null);
  const [targetDayId, setTargetDayId] = useState<string | null>(null);
  const [editingEntry, setEditingEntry] = useState<{ dayId: string; entry: JournalEntry } | null>(null);
  const [showTripSettings, setShowTripSettings] = useState(false);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(trip));
  }, [trip]);

  useEffect(() => {
    const handleScroll = () => setIsScrolled(window.scrollY > 40);
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const generateDaysBetween = (start: Date, end: Date, existingDays: DayTimeline[]): DayTimeline[] => {
    const newDays: DayTimeline[] = [];
    // 確保使用本地零點進行純日期計算，避免跨日問題
    const startDate = new Date(start.getFullYear(), start.getMonth(), start.getDate());
    const endDate = new Date(end.getFullYear(), end.getMonth(), end.getDate());

    const dayMs = 24 * 60 * 60 * 1000;
    const diffTime = endDate.getTime() - startDate.getTime();
    // 確保計算結果至少為 1 天，且精確處理除法
    const diffDays = Math.max(1, Math.floor(diffTime / dayMs) + 1);

    for (let i = 0; i < diffDays; i++) {
      const currentDate = new Date(startDate);
      currentDate.setDate(startDate.getDate() + i);
      const dateKey = currentDate.toDateString();

      const existingDay = existingDays.find(d => d.date.toDateString() === dateKey);
      newDays.push({
        id: existingDay?.id || `day-${Date.now()}-${i}`,
        date: currentDate,
        dayNumber: i + 1,
        entries: existingDay?.entries || []
      });
    }
    return newDays;
  };

  const handleSaveTripSettings = (title: string, start: Date, end: Date) => {
    const newDays = generateDaysBetween(start, end, trip.days);
    setTrip(prev => ({ ...prev, title, startDate: start, endDate: end, days: newDays }));
    setShowTripSettings(false);
  };

  const handleImportData = (entries: { date: string, entry: JournalEntry }[]) => {
    try {
      if (!entries || entries.length === 0) return;

      const importTimestamps = entries.map(e => {
        const [y, m, d] = e.date.split('-').map(Number);
        return new Date(y, m-1, d).getTime();
      });

      const minT = Math.min(...importTimestamps);
      const maxT = Math.max(...importTimestamps);
      const minDate = new Date(minT);
      const maxDate = new Date(maxT);

      const performImport = (targetTrip: Trip) => {
        let importedCount = 0;
        const updatedDays = targetTrip.days.map(day => {
          const y = day.date.getFullYear();
          const m = String(day.date.getMonth() + 1).padStart(2, '0');
          const d = String(day.date.getDate()).padStart(2, '0');
          const dayKey = `${y}-${m}-${d}`;

          const newEntriesForDay = entries
            .filter(item => item.date === dayKey)
            .map(item => item.entry);

          if (newEntriesForDay.length === 0) return day;
          importedCount += newEntriesForDay.length;

          const merged = [...day.entries, ...newEntriesForDay].sort((a, b) => {
            if (a.type === 'itinerary' && b.type === 'itinerary') {
              return (a as ItineraryEntry).time.localeCompare((b as ItineraryEntry).time);
            }
            return 0;
          });

          return { ...day, entries: merged };
        });

        setTrip({ ...targetTrip, days: updatedDays });
        setShowTripSettings(false);
        alert(`✨ 成功匯入 ${importedCount} 筆資料！`);
      };

      const currentStart = new Date(trip.startDate.getFullYear(), trip.startDate.getMonth(), trip.startDate.getDate()).getTime();
      const currentEnd = new Date(trip.endDate.getFullYear(), trip.endDate.getMonth(), trip.endDate.getDate()).getTime();

      if (minT < currentStart || maxT > currentEnd) {
        if (confirm(`匯入資料包含超出現有行程範圍的日期。\n是否自動擴展旅程天數？`)) {
          // 精確獲取新範圍：取現有範圍與匯入範圍的聯集
          const finalStart = new Date(Math.min(currentStart, minT));
          const finalEnd = new Date(Math.max(currentEnd, maxT));
          const expandedDays = generateDaysBetween(finalStart, finalEnd, trip.days);
          const expandedTrip = { ...trip, startDate: finalStart, endDate: finalEnd, days: expandedDays };
          performImport(expandedTrip);
        } else {
          performImport(trip);
        }
      } else {
        performImport(trip);
      }
    } catch (err) {
      alert("匯入過程中發生錯誤，請檢查檔案格式。");
    }
  };

  const handleDeleteEntry = (dayId: string, entryId: string) => {
    setTrip(prev => ({
      ...prev,
      days: prev.days.map(day => day.id === dayId ? { ...day, entries: day.entries.filter(e => e.id !== entryId) } : day)
    }));
  };

  const handleEditEntryTrigger = (dayId: string, entry: JournalEntry) => {
    setEditingEntry({ dayId, entry });
  };

  const handleAddEntryToDay = (dayId: string, type: EntryType) => {
    setTargetDayId(dayId);
    setActiveForm(type);
  };

  const handlePrintPDF = () => window.print();

  const handleSaveEntry = (data: Partial<JournalEntry>) => {
    const formType = activeForm || editingEntry?.entry.type;
    if (!formType) return;

    if (editingEntry) {
      setTrip(prev => ({
        ...prev,
        days: prev.days.map(day => day.id === editingEntry.dayId ? {
          ...day,
          entries: day.entries.map(e => e.id === editingEntry.entry.id ? ({ ...e, ...data } as JournalEntry) : e)
        } : day)
      }));
    } else {
      const newEntry: JournalEntry = { id: Date.now().toString(), timestamp: new Date(), type: formType, ...data } as any;
      setTrip(prev => ({
        ...prev,
        days: prev.days.map(day => {
          if (targetDayId ? day.id === targetDayId : day.id === prev.days[0]?.id) {
            const sorted = [...day.entries, newEntry].sort((a, b) => {
              if (a.type === 'itinerary' && b.type === 'itinerary') return (a as ItineraryEntry).time.localeCompare((b as ItineraryEntry).time);
              return 0;
            });
            return { ...day, entries: sorted };
          }
          return day;
        })
      }));
    }
    setActiveForm(null);
    setTargetDayId(null);
    setEditingEntry(null);
  };

  return (
    <div className="min-h-screen pb-32 max-w-md mx-auto bg-[#FAF9F6] relative overflow-x-hidden print:bg-white print:pb-0">
      {/* Dynamic Background Blobs */}
      <div className="fixed top-[10%] -left-10 w-48 h-48 bg-[#E8F1EF] rounded-full blur-[80px] -z-10 opacity-60" />
      <div className="fixed bottom-[20%] -right-10 w-64 h-64 bg-[#FFF5E1] rounded-full blur-[100px] -z-10 opacity-50" />

      <header 
        onClick={() => !isScrolled && setShowTripSettings(true)}
        className={`sticky top-0 z-40 transition-all duration-300 px-6 flex flex-col justify-end cursor-pointer ${isScrolled ? 'h-16 bg-white/80 backdrop-blur-md border-b border-[#EFEFE9]' : 'h-44 bg-transparent'}`}
      >
        <div className={`flex justify-between items-end ${isScrolled ? 'pb-3' : 'pb-6'}`}>
          <div>
            {!isScrolled && (
              <div className="flex items-center gap-1.5 mb-2">
                 <div className="w-5 h-5 rounded-md bg-[#8DA399] flex items-center justify-center text-white rotate-6">
                   <Icon name="trips" size={10} />
                 </div>
                 <span className="text-[9px] font-black uppercase tracking-[0.3em] text-[#8DA399]">Trip Log</span>
              </div>
            )}
            <h1 className={`font-bold text-[#2A2A28] serif leading-tight transition-all duration-300 ${isScrolled ? 'text-lg' : 'text-3xl'}`}>
              {trip.title}
            </h1>
          </div>
          <div className="flex gap-2">
            <button 
              onClick={(e) => { e.stopPropagation(); setShowTripSettings(true); }}
              className={`p-2 bg-white rounded-xl shadow-sm border border-[#EFEFE9] transition-all ${isScrolled ? 'scale-90' : ''}`}
            >
              <Icon name="more" size={16} className="text-[#BABAB5]" />
            </button>
          </div>
        </div>
      </header>

      <main className="px-5 mt-4 relative z-10">
        {activeTab === 'itinerary' && (
          <div className="space-y-4">
            {trip.days.map((day) => (
              <DayCard 
                key={day.id} 
                day={day} 
                onDeleteEntry={handleDeleteEntry} 
                onEditEntry={handleEditEntryTrigger}
                onAddEntryToDay={handleAddEntryToDay}
              />
            ))}
          </div>
        )}

        {activeTab === 'expenses' && (
           <div className="animate-in fade-in slide-in-from-bottom-2 bg-white rounded-[32px] p-6 border border-[#EFEFE9] shadow-sm">
              <div className="flex items-center gap-2 mb-8">
                <div className="w-8 h-8 rounded-xl bg-[#F9EBE7] flex items-center justify-center text-[#A67C74]">
                  <Icon name="expenses" size={16} />
                </div>
                <h2 className="text-lg font-bold serif">支出統計</h2>
              </div>

              {trip.days.map(day => {
                const dayExpenses = day.entries.filter(e => (e.type === 'itinerary' && (e as ItineraryEntry).expenseAmount) || e.type === 'expense');
                if (dayExpenses.length === 0) return null;
                return (
                  <div key={day.id} className="mb-8 last:mb-0">
                    <div className="flex items-center gap-2 mb-3">
                      <span className="text-[9px] font-black text-[#8A8A85] uppercase tracking-widest">DAY {day.dayNumber}</span>
                      <div className="h-[1px] flex-1 bg-[#EFEFE9]" />
                    </div>
                    {dayExpenses.map((e: any) => (
                      <div key={e.id} onClick={() => handleEditEntryTrigger(day.id, e)} className="flex justify-between py-3 border-b border-[#F8F8F5] last:border-0 cursor-pointer">
                        <div className="flex flex-col">
                           <span className="text-sm font-semibold text-[#2A2A28]">{e.type === 'itinerary' ? e.location : e.description}</span>
                           <span className="text-[9px] font-bold text-[#BABAB5] uppercase mt-0.5">{e.type === 'itinerary' ? (e.expenseCategory || '飲食') : e.category}</span>
                        </div>
                        <span className="text-sm font-black tabular-nums self-center">¥{(e.expenseAmount || e.amount).toLocaleString()}</span>
                      </div>
                    ))}
                  </div>
                );
              })}
           </div>
        )}

        {activeTab === 'trips' && (
           <div className="py-24 text-center bg-white/40 border-2 border-dashed border-white rounded-[32px]">
              <div className="w-12 h-12 bg-white rounded-full flex items-center justify-center mx-auto mb-4 shadow-sm">
                <Icon name="trips" size={20} className="text-[#BABAB5]" />
              </div>
              <p className="text-[10px] font-black uppercase tracking-widest text-[#BABAB5]">收藏空間尚未開放</p>
           </div>
        )}
      </main>

      {(activeForm || editingEntry) && (
        <EntryForm 
          type={activeForm || editingEntry!.entry.type} 
          initialData={editingEntry?.entry}
          onClose={() => { setActiveForm(null); setEditingEntry(null); setTargetDayId(null); }} 
          onSave={handleSaveEntry} 
        />
      )}

      {showTripSettings && (
        <TripSettingsForm 
          trip={trip} 
          onClose={() => setShowTripSettings(false)} 
          onSave={handleSaveTripSettings}
          onImport={handleImportData}
          onPrint={handlePrintPDF}
        />
      )}

      <div className="fixed bottom-24 right-6 z-50 print:hidden">
        <button 
          onClick={() => setActiveForm('itinerary')}
          className="w-12 h-12 rounded-2xl bg-[#2A2A28] text-white flex items-center justify-center shadow-lg hover:bg-[#8DA399] transition-all active:scale-90"
        >
          <Icon name="plus" size={20} />
        </button>
      </div>

      <Navigation activeTab={activeTab} onTabChange={setActiveTab} />
    </div>
  );
};

export default App;

import React from 'react';
import { DayTimeline, JournalEntry, ItineraryEntry, ExpenseEntry, EntryType } from '../types';
import EntryItem from './EntryItem';
import Icon from './Icon';
import { COLORS } from '../constants';

interface DayCardProps {
  day: DayTimeline;
  onDeleteEntry: (dayId: string, entryId: string) => void;
  onEditEntry: (dayId: string, entry: JournalEntry) => void;
  onAddEntryToDay: (dayId: string, type: EntryType) => void;
}

const DayCard: React.FC<DayCardProps> = ({ day, onDeleteEntry, onEditEntry, onAddEntryToDay }) => {
  const formattedDate = day.date.toLocaleDateString('zh-TW', {
    month: 'long',
    day: 'numeric',
  });

  const weekday = day.date.toLocaleDateString('zh-TW', { weekday: 'short' });
  const theme = COLORS.palette[(day.dayNumber - 1) % COLORS.palette.length];

  const totalExpense = day.entries.reduce((sum, entry) => {
    if (entry.type === 'itinerary') {
      return sum + ((entry as ItineraryEntry).expenseAmount || 0);
    } else if (entry.type === 'expense') {
      return sum + (entry as ExpenseEntry).amount;
    }
    return sum;
  }, 0);

  return (
    <div className="mb-12 last:mb-0 fade-in-section relative">
      <div className="mb-5 flex items-end gap-3 px-1">
        <div 
          className="relative px-3 py-2 rounded-2xl shadow-sm rotate-[-2deg]"
          style={{ backgroundColor: theme.bg, color: theme.text }}
        >
          {/* 紙膠帶裝飾 */}
          <div className="absolute -top-2 left-1/2 -translate-x-1/2 w-8 h-4 opacity-50 rounded-sm" style={{ backgroundColor: theme.tape }} />
          <div className="flex flex-col items-center">
            <span className="text-[8px] font-black tracking-widest mb-0.5">DAY</span>
            <span className="text-xl font-black leading-none serif">{day.dayNumber}</span>
          </div>
        </div>

        <div className="flex-1 pb-1">
          <div className="flex items-center gap-2 mb-0.5">
             <h2 className="text-lg font-bold serif text-[#2A2A28]">{formattedDate}</h2>
             <span className="text-[10px] font-bold text-[#BABAB5]">{weekday}</span>
          </div>
          <div className="h-[1.5px] w-full bg-gradient-to-r from-[#EFEFE9] to-transparent" />
        </div>

        <button 
          onClick={() => onAddEntryToDay(day.id, 'itinerary')}
          className="w-8 h-8 rounded-xl bg-white border border-[#EFEFE9] text-[#BABAB5] hover:text-[#8DA399] transition-all flex items-center justify-center"
        >
          <Icon name="plus" size={14} />
        </button>
      </div>

      <div className="relative pl-1.5">
        {day.entries.filter(e => e.type === 'itinerary').length > 0 && (
          <div className="absolute left-[10px] top-4 bottom-8 w-[2px] rounded-full bg-[#EFEFE9]" />
        )}

        {day.entries.length === 0 ? (
          <div 
            onClick={() => onAddEntryToDay(day.id, 'itinerary')}
            className="ml-10 py-10 flex flex-col items-center justify-center text-[#BABAB5] border-2 border-dashed border-[#EFEFE9] rounded-[24px] bg-white/20 cursor-pointer"
          >
            <span className="text-[9px] tracking-widest uppercase font-black">點擊記錄回憶</span>
          </div>
        ) : (
          <div className="space-y-3">
            {day.entries.map((entry) => (
              <EntryItem 
                key={entry.id} 
                entry={entry} 
                onDelete={(entryId) => onDeleteEntry(day.id, entryId)}
                onEdit={(entryData) => onEditEntry(day.id, entryData)}
              />
            ))}
          </div>
        )}
      </div>

      {totalExpense > 0 && (
        <div className="mt-4 ml-10 flex items-center">
          <div className="px-3 py-1.5 bg-[#FDFDFB] border border-[#EFEFE9] rounded-xl shadow-sm flex items-center gap-2">
            <span className="text-[8px] font-black uppercase text-[#8DA399]">支出總計</span>
            <span className="text-xs font-bold tabular-nums">¥{totalExpense.toLocaleString()}</span>
          </div>
        </div>
      )}
    </div>
  );
};

