          <div className="relative z-10">
            <div className="flex justify-between items-start mb-2.5">
              <div className="flex items-center gap-1.5">
                <Icon name="clock" size={10} className="text-[#8DA399]" />
                <span className="text-[9px] font-black text-[#8DA399] tracking-widest uppercase">{item.time}</span>
              </div>

