                <div className="text-right">
                  <span className="text-xs font-black tabular-nums text-[#2A2A28]">
                    ¥{item.expenseAmount.toLocaleString()}
                  </span>
                </div>
              ) : null}
            </div>

            <h4 className="text-base font-bold text-[#2A2A28] mb-1 serif leading-tight">{item.location}</h4>
            {item.notes && <p className="text-[11px] text-[#8A8A85] leading-normal font-medium mb-2.5">{item.notes}</p>}

            {item.reflection && (
              <div className="mt-3 p-3 bg-[#FAF9F6] rounded-xl border-l-2 border-[#8DA399]/40 italic">
                <p className="serif text-[#2A2A28] leading-relaxed text-xs opacity-90">
                  「{item.reflection}」
                </p>
              </div>
            )}
          </div>

          <button 
            onClick={handleDelete}
            className="absolute right-3 top-3 opacity-0 group-hover:opacity-100 transition-opacity text-[#BABAB5] hover:text-red-400 p-1"
          >
            <Icon name="plus" size={12} className="rotate-45" />
          </button>
        </div>
      </div>
    );
  }

  if (entry.type === 'expense') {
    const item = entry as ExpenseEntry;
    return (
      <div 
        onClick={handleEdit} 
        className="ml-10 flex justify-between items-center py-3 px-4 border border-[#EFEFE9] rounded-[18px] group bg-white/60 hover:bg-white transition-all shadow-sm"
      >
        <div className="flex items-center gap-3">
