            <span className="text-[8px] text-[#8DA399] font-black uppercase tracking-widest">{item.category}</span>
            <span className="text-xs font-bold text-[#2A2A28] block leading-none">{item.description}</span>
          </div>
        </div>
        <span className="text-xs font-black tabular-nums">¥{item.amount.toLocaleString()}</span>
      </div>
    );
  }

  return null;
};

