interface DayCardProps {
  day: DayTimeline;
  onDeleteEntry: (dayId: string, entryId: string) => void;
  onEditEntry: (dayId: string, entry: JournalEntry) => void;
  onAddEntryToDay: (dayId: string, type: EntryType) => void;
}

const DayCard: React.FC<DayCardProps> = ({ day, onDeleteEntry, onEditEntry, onAddEntryToDay }) => {
  const formattedDate = day.date.toLocaleDateString('zh-TW', {
    month: 'long',
    day: 'numeric',
  });

  const weekday = day.date.toLocaleDateString('zh-TW', { weekday: 'short' });
  const theme = COLORS.palette[(day.dayNumber - 1) % COLORS.palette.length];

  const totalExpense = day.entries.reduce((sum, entry) => {
    if (entry.type === 'itinerary') {
      return sum + ((entry as ItineraryEntry).expenseAmount || 0);
    } else if (entry.type === 'expense') {
      return sum + (entry as ExpenseEntry).amount;
    }
    return sum;
  }, 0);

  return (
    <div className="mb-10 last:mb-0 fade-in-section relative">
      <div className="mb-4 flex items-end gap-2.5 px-0.5">
        <div 
          className="relative px-2.5 py-1.5 rounded-xl shadow-sm rotate-[-2deg]"
          style={{ backgroundColor: theme.bg, color: theme.text }}
        >
          <div className="absolute -top-1.5 left-1/2 -translate-x-1/2 w-7 h-3 opacity-50 rounded-sm" style={{ backgroundColor: theme.tape }} />
          <div className="flex flex-col items-center">
            <span className="text-[7px] font-black tracking-widest mb-0">DAY</span>
            <span className="text-lg font-black leading-none serif">{day.dayNumber}</span>
          </div>
        </div>

        <div className="flex-1 pb-1">
          <div className="flex items-center gap-1.5 mb-0">
             <h2 className="text-base font-bold serif text-[#2A2A28]">{formattedDate}</h2>
             <span className="text-[9px] font-bold text-[#BABAB5]">{weekday}</span>
          </div>
          <div className="h-[1px] w-full bg-gradient-to-r from-[#EFEFE9] to-transparent" />
        </div>

        <button 
          onClick={() => onAddEntryToDay(day.id, 'itinerary')}
          className="w-7 h-7 rounded-lg bg-white border border-[#EFEFE9] text-[#BABAB5] hover:text-[#8DA399] transition-all flex items-center justify-center"
        >
          <Icon name="plus" size={12} />
        </button>
      </div>

      <div className="relative pl-1">
        {day.entries.filter(e => e.type === 'itinerary').length > 0 && (
          <div className="absolute left-[8px] top-3 bottom-6 w-[1.5px] rounded-full bg-[#EFEFE9]" />
        )}

        {day.entries.length === 0 ? (
          <div 
            onClick={() => onAddEntryToDay(day.id, 'itinerary')}
            className="ml-8 py-8 flex flex-col items-center justify-center text-[#BABAB5] border border-dashed border-[#EFEFE9] rounded-[20px] bg-white/20 cursor-pointer"
          >
            <span className="text-[8px] tracking-widest uppercase font-black">點擊記錄回憶</span>
          </div>
        ) : (
          <div className="space-y-2.5">
            {day.entries.map((entry) => (
              <EntryItem 
                key={entry.id} 
                entry={entry} 
                onDelete={(entryId) => onDeleteEntry(day.id, entryId)}
                onEdit={(entryData) => onEditEntry(day.id, entryData)}
              />
            ))}
          </div>
        )}
      </div>

      {totalExpense > 0 && (
        <div className="mt-3 ml-8 flex items-center">
          <div className="px-2.5 py-1 bg-[#FDFDFB] border border-[#EFEFE9] rounded-lg shadow-sm flex items-center gap-1.5">
            <span className="text-[7px] font-black uppercase text-[#8DA399]">總計</span>
            <span className="text-[11px] font-bold tabular-nums">¥{totalExpense.toLocaleString()}</span>
          </div>
        </div>
      )}
    </div>
  );
};

