interface EntryItemProps {
  entry: JournalEntry;
  onDelete?: (id: string) => void;
  onEdit?: (entry: JournalEntry) => void;
}

const EntryItem: React.FC<EntryItemProps> = ({ entry, onDelete, onEdit }) => {
  const handleDelete = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (onDelete && confirm('刪除這則回憶嗎？')) {
      onDelete(entry.id);
    }
  };

  const handleEdit = () => {
    if (onEdit) onEdit(entry);
  };

  if (entry.type === 'itinerary') {
    const item = entry as ItineraryEntry;
    return (
      <div 
        onClick={handleEdit}
        className="relative pl-8 mb-5 group cursor-pointer active:scale-[0.99] transition-all"
      >
        <div className="absolute left-[4px] top-4 w-[8px] h-[8px] rounded-full bg-white border-2 border-[#8DA399] z-10" />

        <div className="bg-white rounded-[20px] p-4 border border-[#EFEFE9] shadow-sm hover:shadow-md transition-all relative overflow-hidden">
          {/* 快速刪除按鈕 - 右上角叉叉 */}
