              <div className="mt-2.5 p-2.5 bg-[#FAF9F6] rounded-lg border-l-2 border-[#8DA399]/30 italic">
                <p className="serif text-[#2A2A28] leading-relaxed text-[11px] opacity-90">
                  「{item.reflection}」
                </p>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }

  if (entry.type === 'expense') {
    const item = entry as ExpenseEntry;
    return (
      <div 
        onClick={handleEdit} 
        className="ml-8 flex justify-between items-center py-2.5 px-3.5 border border-[#EFEFE9] rounded-[16px] group bg-white/60 hover:bg-white transition-all shadow-sm relative"
      >
        <div className="flex items-center gap-2.5">
          <div className="w-5 h-5 rounded-full bg-[#EFEFE9] flex items-center justify-center text-[#8A8A85]">
             <Icon name="expenses" size={10} />
