            <span className="text-[11px] font-bold text-[#2A2A28] block leading-none">{item.description}</span>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <span className="text-[11px] font-black tabular-nums">¥{item.amount.toLocaleString()}</span>
          <button 
            onClick={handleDelete}
            className="w-5 h-5 flex items-center justify-center text-[#BABAB5] hover:text-red-400"
          >
            <Icon name="plus" size={10} className="rotate-45" />
          </button>
        </div>
      </div>
    );
  }

  return null;
};

