    music: Music
  };

  const LucideIcon = icons[name] || Map;
  return <LucideIcon size={size} className={className} onClick={onClick} strokeWidth={1.5} />;
};

export default Icon;

import React, { useState, useEffect } from 'react';
import { EntryType, JournalEntry, ItineraryEntry } from '../types';
import { EXPENSE_CATEGORIES, ITINERARY_ICONS } from '../constants';
import Icon, { IconName } from './Icon';

interface EntryFormProps {
  type: EntryType;
  initialData?: Partial<JournalEntry>;
  onSave: (data: Partial<JournalEntry>) => void;
  onClose: () => void;
}

const EntryForm: React.FC<EntryFormProps> = ({ type, initialData, onSave, onClose }) => {
  const getCurrentTimeRaw = () => {
    const now = new Date();
    return now.toTimeString().slice(0, 5); 
  };

  const [formData, setFormData] = useState<any>({
    time: getCurrentTimeRaw(),
    location: '',
    notes: '',
    expenseAmount: '',
    expenseCategory: '飲食',
    icon: 'mapPin',
    reflection: '',
    amount: '',
    category: '飲食',
    description: ''
  });

  useEffect(() => {
    if (initialData) {
      let time = formData.time;
      if (initialData.type === 'itinerary' && (initialData as any).time) {
        const timeStr = (initialData as any).time;
        if (timeStr.includes('AM') || timeStr.includes('PM')) {
           const [t, modifier] = timeStr.split(' ');
           let [hours, minutes] = t.split(':');
           if (hours === '12') hours = '00';
           if (modifier === 'PM') hours = String(parseInt(hours, 10) + 12).padStart(2, '0');
           time = `${hours}:${minutes}`;
        } else {
           time = timeStr;
        }
      }

      setFormData((prev: any) => ({
        ...prev,
        ...initialData,
        time: time
      }));
    }
  }, [initialData]);

  const isEdit = !!initialData?.id;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const dataToSave = { ...formData };

    if (type === 'itinerary' && dataToSave.time) {
      const [h, m] = dataToSave.time.split(':');
      const hour = parseInt(h, 10);
      const ampm = hour >= 12 ? 'PM' : 'AM';
      const displayHour = hour % 12 || 12;
      dataToSave.time = `${String(displayHour).padStart(2, '0')}:${m} ${ampm}`;
    }

    if (dataToSave.expenseAmount !== '') dataToSave.expenseAmount = parseFloat(dataToSave.expenseAmount);
    if (dataToSave.amount !== '') dataToSave.amount = parseFloat(dataToSave.amount);

    onSave(dataToSave);
  };

  const CategorySelector = ({ value, onChange, label }: { value: string, onChange: (v: string) => void, label: string }) => (
    <div className="space-y-3">
      <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">{label}</label>
      <div className="flex flex-wrap gap-2">
        {EXPENSE_CATEGORIES.map((cat) => (
          <button
            key={cat.id}
            type="button"
            onClick={() => onChange(cat.label)}
            className={`px-4 py-2 rounded-full text-[11px] font-bold tracking-wider transition-all border ${
              value === cat.label 
                ? 'bg-[#8DA399] border-[#8DA399] text-white shadow-md' 
                : 'bg-white border-[#EFEFE9] text-[#8A8A85] hover:border-[#8DA399]'
            }`}
          >
            {cat.label}
          </button>
        ))}
      </div>
    </div>
  );

  return (
    <div className="fixed inset-0 z-[100] bg-[#FDFDFB] animate-in slide-in-from-bottom duration-500 p-8 flex flex-col overflow-y-auto no-scrollbar">
      <div className="flex justify-between items-center mb-8">
        <span className="text-[10px] font-black uppercase tracking-[0.5em] text-[#8DA399]">
          {isEdit ? '編輯行程' : '新增行程'}
        </span>
        <button onClick={onClose} className="p-2 -mr-2 text-[#BABAB5] hover:text-[#2A2A28] transition-colors">
          <Icon name="plus" size={24} className="rotate-45" />
        </button>
      </div>

      <form onSubmit={handleSubmit} className="flex-1 flex flex-col gap-6">
        {type === 'itinerary' ? (
          <>
            <div className="space-y-3">
              <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">選擇標記圖示</label>
              <div className="flex gap-3 overflow-x-auto pb-2 no-scrollbar px-1">
                {ITINERARY_ICONS.map((icon) => (
                  <button
                    key={icon.id}
                    type="button"
                    onClick={() => setFormData({...formData, icon: icon.id})}
                    className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 transition-all ${
                      formData.icon === icon.id 
                        ? 'bg-[#8DA399] text-white shadow-md scale-110' 
                        : 'bg-white border border-[#EFEFE9] text-[#BABAB5] hover:border-[#8DA399]'
                    }`}
                  >
                    <Icon name={icon.id as IconName} size={18} />
                  </button>
                ))}
              </div>
            </div>

            <div className="grid grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">時間</label>
                <input 
                  type="time" 
                  value={formData.time}
                  onChange={(e) => setFormData({...formData, time: e.target.value})}
                  className="w-full text-lg font-medium outline-none bg-transparent border-b border-[#EFEFE9] pb-2 focus:border-[#8DA399] transition-colors"
                />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">支出金額</label>
                <input 
                  type="number" 
                  value={formData.expenseAmount}
                  onChange={(e) => setFormData({...formData, expenseAmount: e.target.value})}
                  className="w-full text-lg font-medium outline-none bg-transparent border-b border-[#EFEFE9] pb-2 focus:border-[#8DA399] transition-colors"
                  placeholder="0"
                />
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">目的地 / 地點</label>
              <input 
                autoFocus
                type="text" 
                value={formData.location}
                onChange={(e) => setFormData({...formData, location: e.target.value})}
                className="w-full text-xl font-bold outline-none bg-transparent border-b border-[#EFEFE9] pb-2 focus:border-[#8DA399] transition-colors"
                placeholder="輸入景點名稱"
              />
            </div>

            <div className="space-y-2">
              <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">備註</label>
              <input 
                type="text"
                value={formData.notes}
                onChange={(e) => setFormData({...formData, notes: e.target.value})}
                className="w-full text-xs font-light outline-none bg-transparent border-b border-[#EFEFE9] pb-2 focus:border-[#8DA399] transition-colors"
                placeholder="記錄一些小細節..."
              />
            </div>

            <div className="space-y-3 pt-4">
              <label className="text-[10px] uppercase tracking-widest text-[#8DA399] font-bold">心靈回憶 (Reflection)</label>
              <textarea 
                value={formData.reflection}
                onChange={(e) => setFormData({...formData, reflection: e.target.value})}
                className="w-full text-base serif italic leading-relaxed outline-none bg-[#FDFDFB] border border-[#EFEFE9] p-4 rounded-2xl min-h-[100px] resize-none focus:border-[#8DA399] transition-all"
                placeholder="此刻的心情是..."
              />
            </div>
          </>
        ) : (
          <div className="space-y-8">
             <div className="space-y-2">
               <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">金額 (JPY)</label>
               <input type="number" value={formData.amount} onChange={(e) => setFormData({...formData, amount: e.target.value})} className="w-full text-4xl font-light outline-none border-b border-[#EFEFE9] pb-2" placeholder="0" />
             </div>

             <CategorySelector 
                label="支出類別" 
                value={formData.category} 
                onChange={(v) => setFormData({...formData, category: v})} 
              />

             <div className="space-y-2">
               <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">項目描述</label>
               <input type="text" value={formData.description} onChange={(e) => setFormData({...formData, description: e.target.value})} className="w-full text-xl font-medium outline-none border-b border-[#EFEFE9] pb-2" placeholder="買了什麼？" />
             </div>
          </div>
        )}

        <div className="mt-auto pb-10">
          <button type="submit" className="w-full py-4 bg-[#2A2A28] text-white rounded-2xl text-[10px] font-black uppercase tracking-[0.4em] hover:bg-[#8DA399] transition-all shadow-lg">
            {isEdit ? '更新紀錄' : '儲存紀錄'}
          </button>
        </div>
      </form>
    </div>
  );
};

