          <Icon name="plus" size={24} className="rotate-45" />
        </button>
      </div>

      <form onSubmit={handleSubmit} className="flex-1 flex flex-col gap-6">
        {type === 'itinerary' ? (
          <>
            <div className="space-y-3">
              <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">選擇標記圖示</label>
              <div className="flex gap-3 overflow-x-auto pb-2 no-scrollbar px-1">
                {ITINERARY_ICONS.map((icon) => (
                  <button
                    key={icon.id}
                    type="button"
                    onClick={() => setFormData({...formData, icon: icon.id})}
                    className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 transition-all ${
                      formData.icon === icon.id 
                        ? 'bg-[#8DA399] text-white shadow-md scale-110' 
                        : 'bg-white border border-[#EFEFE9] text-[#BABAB5] hover:border-[#8DA399]'
                    }`}
                  >
                    <Icon name={icon.id as IconName} size={18} />
                  </button>
                ))}
              </div>
            </div>

            <div className="grid grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">時間 (24h)</label>
                <input 
                  type="time" 
                  value={formData.time}
                  onChange={(e) => setFormData({...formData, time: e.target.value})}
                  className="w-full text-lg font-medium outline-none bg-transparent border-b border-[#EFEFE9] pb-2 focus:border-[#8DA399] transition-colors"
                />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">支出金額</label>
                <input 
