  BookOpen, 
  CreditCard, 
  Compass, 
  Plus, 
  Calendar, 
  Clock, 
  MapPin, 
  Camera,
  ArrowRight,
  MoreHorizontal,
  Download,
  Upload,
  Printer,
  Share2,
  Coffee,
  Utensils,
