// 注意：在實際部署時，需要向 Google Cloud Console 申請 Client ID
// 此處實作邏輯架構，假設 Client ID 已透過環境變數或預設值提供
const CLIENT_ID = (window as any).process?.env?.GOOGLE_CLIENT_ID || 'YOUR_CLIENT_ID_HERE';
const SCOPES = 'https://www.googleapis.com/auth/spreadsheets https://www.googleapis.com/auth/drive.file';

class GoogleSheetsService {
  private accessToken: string | null = null;

  async authenticate(): Promise<string> {
    return new Promise((resolve, reject) => {
      try {
        // 使用 Google Identity Service 進行授權
        const client = (window as any).google?.accounts.oauth2.initTokenClient({
          client_id: CLIENT_ID,
          scope: SCOPES,
          callback: (response: any) => {
            if (response.error) reject(response);
            this.accessToken = response.access_token;
            resolve(response.access_token);
          },
        });
        client.requestAccessToken();
      } catch (err) {
        reject(err);
      }
    });
  }

  // 尋找或建立同步用的試算表
  async getOrCreateSpreadsheet(): Promise<string> {
    if (!this.accessToken) throw new Error('未授權');

    // 1. 搜尋是否有現成的同步檔
    const searchRes = await fetch(
      `https://www.googleapis.com/drive/v3/files?q=name='Komorebi_Travel_Log_Sync'&spaces=drive`,
      { headers: { Authorization: `Bearer ${this.accessToken}` } }
    );
    const searchData = await searchRes.json();

    if (searchData.files && searchData.files.length > 0) {
      return searchData.files[0].id;
    }

    // 2. 建立新檔案
    const createRes = await fetch('https://sheets.googleapis.com/v4/spreadsheets', {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${this.accessToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        properties: { title: 'Komorebi_Travel_Log_Sync' },
      }),
    });
    const createData = await createRes.json();
    return createData.spreadsheetId;
  }

  // 將所有旅程資料同步至雲端
  async uploadData(trips: Trip[]): Promise<void> {
    if (!this.accessToken) await this.authenticate();
    const spreadsheetId = await this.getOrCreateSpreadsheet();

    // 將資料序列化為 JSON 存放在 A1 (簡化版雲端備份)
    // 實際產品開發可拆分到多個工作表，此處採取快速存取策略
    const values = [[JSON.stringify(trips)]];

    await fetch(
      `https://sheets.googleapis.com/v4/spreadsheets/${spreadsheetId}/values/Sheet1!A1?valueInputOption=RAW`,
      {
        method: 'PUT',
        headers: {
          Authorization: `Bearer ${this.accessToken}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ values }),
      }
    );
  }

  // 從雲端抓取資料
  async downloadData(): Promise<Trip[] | null> {
    if (!this.accessToken) await this.authenticate();
    try {
      const spreadsheetId = await this.getOrCreateSpreadsheet();
      const res = await fetch(
        `https://sheets.googleapis.com/v4/spreadsheets/${spreadsheetId}/values/Sheet1!A1`,
        { headers: { Authorization: `Bearer ${this.accessToken}` } }
      );
      const data = await res.json();
      if (data.values && data.values[0] && data.values[0][0]) {
        const parsed = JSON.parse(data.values[0][0]);
        // 轉換 Date 物件
        return parsed.map((t: any) => ({
          ...t,
          startDate: new Date(t.startDate),
          endDate: new Date(t.endDate),
          days: t.days.map((d: any) => ({
            ...d,
            date: new Date(d.date),
            entries: d.entries.map((e: any) => ({
              ...e,
              timestamp: new Date(e.timestamp)
            }))
          }))
        }));
      }
      return null;
    } catch (err) {
      console.error('Download error:', err);
      return null;
    }
  }
}

