          </div>
        </div>

        <button type="button" onClick={onExportImage} className="w-full flex items-center justify-center gap-4 py-6 bg-[#2A2A28] text-white rounded-2xl shadow-sm active:scale-95 transition-all">
          <Icon name="image" size={18} className="text-[#8DA399]" />
          <span className="text-[11px] font-black uppercase tracking-[0.3em]">匯出長圖 (手帳風格)</span>
        </button>

        <div className="mt-auto pb-10">
          <button type="submit" className="w-full py-5 bg-[#2A2A28] text-white rounded-2xl text-[10px] font-black uppercase tracking-[0.4em] shadow-lg">儲存旅程設定</button>
        </div>
      </form>
    </div>
  );
};

export default TripSettingsForm;

import React, { useState, useRef } from 'react';
import { Trip, JournalEntry, ItineraryEntry, ExpenseEntry, SyncState } from '../types';
import Icon from './Icon';

interface TripSettingsFormProps {
  trip: Trip;
  syncState: SyncState;
  onSave: (title: string, start: Date, end: Date) => void;
  onImport: (entries: { date: string, entry: JournalEntry }[]) => void;
  onClose: () => void;
  onExportImage: () => void;
  onCloudSync: (mode: 'upload' | 'download' | 'connect') => void;
}

const TripSettingsForm: React.FC<TripSettingsFormProps> = ({ 
  trip, 
  syncState,
  onSave, 
  onImport, 
  onClose, 
  onExportImage,
  onCloudSync 
}) => {
  const [title, setTitle] = useState(trip.title);
  const [start, setStart] = useState(trip.startDate.toISOString().split('T')[0]);
  const [end, setEnd] = useState(trip.endDate.toISOString().split('T')[0]);
  const [csvUrl, setCsvUrl] = useState('');
  const [isUrlFetching, setIsUrlFetching] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave(title, new Date(start), new Date(end));
  };

  const parseCSVContent = (text: string) => {
    const lines = text.split(/\r?\n/).filter(line => line.trim() !== '');
    if (lines.length < 2) return [];

    const delimiter = lines[0].includes(';') && !lines[0].includes(',') ? ';' : ',';
    const splitCSV = (line: string) => {
      const result = [];
      let current = '';
      let inQuotes = false;
      for (let i = 0; i < line.length; i++) {
        const char = line[i];
        if (char === '"') inQuotes = !inQuotes;
        else if (char === delimiter && !inQuotes) {
          result.push(current.trim());
          current = '';
        } else current += char;
      }
      result.push(current.trim());
      return result;
    };

    const headerRow = splitCSV(lines[0]);
    const getIdx = (keywords: string[]) => headerRow.findIndex(h => keywords.some(k => h.includes(k)));

    const dateIdx = getIdx(['日期', 'Date']);
    const typeIdx = getIdx(['類型', 'Type']);
    const timeIdx = getIdx(['時間', 'Time']);
    const locIdx = getIdx(['地點', '描述', 'Location', 'Description']);
    const amountIdx = getIdx(['金額', 'Amount']);
    const catIdx = getIdx(['分類', '類別', 'Category']);
    const notesIdx = getIdx(['備註', 'Notes', '內容']);
    const reflectionIdx = getIdx(['感觸', '心得', 'Reflection']);

    const entries: { date: string, entry: JournalEntry }[] = [];
    const currentYear = new Date().getFullYear();

    for (let i = 1; i < lines.length; i++) {
      const cells = splitCSV(lines[i]);
      if (cells.length < 3) continue;

      const rawDate = cells[dateIdx === -1 ? 0 : dateIdx];
      const type = cells[typeIdx === -1 ? 1 : typeIdx];
      const rawTime = cells[timeIdx === -1 ? 2 : timeIdx];
      const locOrDesc = cells[locIdx === -1 ? 3 : locIdx];
      const amountStr = cells[amountIdx === -1 ? 4 : amountIdx];
      const categoryStr = catIdx === -1 ? '其他' : (cells[catIdx] || '其他');
      const notesStr = notesIdx === -1 ? '' : (cells[notesIdx] || '');
      const reflectionStr = reflectionIdx === -1 ? '' : (cells[reflectionIdx] || '');

      let finalDateStr = '';
      const dateNums = (rawDate || "").match(/(\d+)/g);
      if (dateNums) {
        let y = currentYear, m = 0, d = 0;
        if (dateNums.length === 2) { m = parseInt(dateNums[0]); d = parseInt(dateNums[1]); }
        else if (dateNums.length >= 3) {
          const v1 = parseInt(dateNums[0]); const v2 = parseInt(dateNums[1]); const v3 = parseInt(dateNums[2]);
          if (v1 > 1000) { y = v1; m = v2; d = v3; }
          else if (v3 > 1000) { y = v3; m = v2; d = v1; }
          else { y = v1 + 2000; m = v2; d = v3; }
        }
        if (m > 0 && m <= 12 && d > 0 && d <= 31) {
          finalDateStr = `${y}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        }
      }

      if (!finalDateStr) continue;

      const id = `remote-${Date.now()}-${i}`;
      const cleanAmount = (val: any) => {
        if (!val) return 0;
        const str = String(val).replace(/[^\d.]/g, '');
        const parsed = parseFloat(str);
        return isNaN(parsed) ? 0 : parsed;
      };

      const typeStr = (type || "").toLowerCase();
      const isExpense = typeStr.includes('支出') || typeStr.includes('expense');

      if (isExpense) {
        entries.push({
          date: finalDateStr,
          entry: { id, timestamp: new Date(), type: 'expense', category: categoryStr, description: locOrDesc || '支出項目', amount: cleanAmount(amountStr), currency: 'TWD' } as ExpenseEntry
        });
      } else {
        let formattedTime = '';
        const tStr = (rawTime || "").toUpperCase();
        const timeMatch = tStr.match(/(\d+):(\d+)/);
        if (timeMatch) {
          let h = parseInt(timeMatch[1], 10);
          const m = timeMatch[2].padStart(2, '0');
          const isPM = tStr.includes('PM');
          const isAM = tStr.includes('AM');
          const finalAMPM = isPM ? 'PM' : (isAM ? 'AM' : (h >= 12 ? 'PM' : 'AM'));
          const displayH = h % 12 || 12;
          formattedTime = `${String(displayH).padStart(2, '0')}:${m} ${finalAMPM}`;
        } else {
          formattedTime = '12:00 PM';
        }

        entries.push({
          date: finalDateStr,
          entry: { id, timestamp: new Date(), type: 'itinerary', time: formattedTime, location: locOrDesc || '地點', notes: notesStr, reflection: reflectionStr, expenseAmount: cleanAmount(amountStr), expenseCategory: categoryStr } as ItineraryEntry
        });
      }
    }
    return entries;
  };

  const handleFetchUrl = async () => {
    if (!csvUrl) return;
    setIsUrlFetching(true);
    try {
      const response = await fetch(csvUrl);
      if (!response.ok) throw new Error('無法抓取資料');
      const text = await response.text();
      const entries = parseCSVContent(text);
      if (entries.length > 0) {
        onImport(entries);
        setCsvUrl('');
      } else {
        alert('CSV 內容為空或格式不符');
      }
    } catch (err) {
      alert('同步失敗。請確保 Google 試算表已「發佈到網路」並選擇「CSV 格式」。');
    } finally {
      setIsUrlFetching(false);
    }
  };

  const exportToCSV = () => {
    const headers = ['日期', '類型', '時間', '地點/描述', '金額(TWD)', '分類', '備註', '感觸'];
    const rows: string[][] = [headers];

    trip.days.forEach(day => {
      const dateStr = day.date.toLocaleDateString('zh-TW');
      day.entries.forEach(entry => {
        let row: string[] = [dateStr];
        if (entry.type === 'itinerary') {
          const e = entry as ItineraryEntry;
          row.push('行程', e.time, e.location, e.expenseAmount?.toString() || '0', e.expenseCategory || '其他', e.notes || '', e.reflection || '');
        } else if (entry.type === 'expense') {
          const e = entry as ExpenseEntry;
          row.push('支出', '', e.description, e.amount.toString(), e.category || '其他', '', '');
        }
        const escapedRow = row.map(cell => `"${(cell || '').toString().replace(/"/g, '""')}"`);
        rows.push(escapedRow);
      });
    });

    const csvContent = "\uFEFF" + rows.map(e => e.join(",")).join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `${trip.title}_旅程紀錄.csv`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="fixed inset-0 z-[110] bg-[#FDFDFB] animate-in slide-in-from-bottom duration-500 p-8 flex flex-col overflow-y-auto no-scrollbar print:hidden">
      <div className="flex justify-between items-center mb-10">
        <span className="text-[10px] font-black uppercase tracking-[0.5em] text-[#8DA399]">旅程設定</span>
        <button onClick={onClose} className="p-2 -mr-2">
          <Icon name="plus" size={24} className="rotate-45 text-[#BABAB5]" />
        </button>
      </div>

      <form onSubmit={handleSubmit} className="flex-1 flex flex-col gap-8">
        <div className="space-y-2">
          <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">旅程標題</label>
          <input 
            autoFocus
            type="text" 
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            className="w-full text-2xl serif outline-none bg-transparent border-b border-[#EFEFE9] pb-4 focus:border-[#8DA399] transition-colors"
          />
        </div>

        <div className="grid grid-cols-2 gap-8">
          <div className="space-y-2">
            <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">開始日期</label>
            <input type="date" value={start} onChange={(e) => setStart(e.target.value)} className="w-full text-base font-light outline-none bg-transparent border-b border-[#EFEFE9] pb-2" />
          </div>
          <div className="space-y-2">
            <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">結束日期</label>
            <input type="date" value={end} onChange={(e) => setEnd(e.target.value)} className="w-full text-base font-light outline-none bg-transparent border-b border-[#EFEFE9] pb-2" />
          </div>
        </div>

        {/* 遠端 CSV 連結同步 */}
        <div className="space-y-4 pt-4 border-t border-[#EFEFE9]">
          <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold block">從 CSV 連結連動 (Google Sheets)</label>
          <div className="flex gap-2">
            <input 
              type="url" 
              value={csvUrl}
              onChange={(e) => setCsvUrl(e.target.value)}
              placeholder="貼上發佈後的 CSV 連結..."
              className="flex-1 text-[11px] font-medium outline-none bg-white border border-[#EFEFE9] px-4 py-3 rounded-xl focus:border-[#8DA399] transition-colors"
            />
            <button 
              type="button"
              onClick={handleFetchUrl}
              disabled={isUrlFetching || !csvUrl}
              className="px-4 py-3 bg-[#2A2A28] text-white rounded-xl text-[10px] font-bold uppercase tracking-widest active:scale-95 disabled:opacity-50 transition-all"
            >
              {isUrlFetching ? '抓取中...' : '同步'}
            </button>
          </div>
          <div className="bg-[#F8F8F5] rounded-xl p-3 border border-[#EFEFE9]">
             <span className="text-[9px] font-black uppercase tracking-widest text-[#8DA399] block mb-1">如何取得連結？</span>
             <p className="text-[8px] text-[#BABAB5] leading-relaxed">
               在 Google 試算表點選：<br/>
               <b>檔案 &gt; 共用 &gt; 發佈到網路 &gt; 選擇「整份文件」與「CSV」格式</b>。<br/>
               複製生成的網址並貼在上方。
             </p>
          </div>
        </div>

        {/* 備份與匯出區塊 */}
        <div className="space-y-4 pt-4 border-t border-[#EFEFE9]">
          <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold block">資料備份與還原</label>
          <div className="grid grid-cols-2 gap-4">
            <button type="button" onClick={exportToCSV} className="flex items-center justify-center gap-3 py-4 border border-[#EFEFE9] rounded-2xl bg-white shadow-sm hover:border-[#8DA399] transition-all">
              <Icon name="download" size={16} className="text-[#BABAB5]" />
              <span className="text-[10px] font-bold text-[#2A2A28]">匯出 CSV</span>
            </button>
            <button type="button" onClick={() => fileInputRef.current?.click()} className="flex items-center justify-center gap-3 py-4 border border-[#EFEFE9] rounded-2xl bg-white shadow-sm hover:border-[#8DA399] transition-all">
              <Icon name="upload" size={16} className="text-[#BABAB5]" />
              <span className="text-[10px] font-bold text-[#2A2A28]">匯入本地</span>
            </button>
            <input type="file" ref={fileInputRef} onChange={(e) => {
              const file = e.target.files?.[0];
              if (file) {
                const reader = new FileReader();
                reader.onload = (re) => {
                  const text = re.target?.result as string;
                  const entries = parseCSVContent(text);
                  if (entries.length > 0) onImport(entries);
                };
                reader.readAsText(file);
              }
            }} accept=".csv" className="hidden" />
          </div>
        </div>

        <button type="button" onClick={onExportImage} className="w-full flex items-center justify-center gap-4 py-6 bg-[#2A2A28] text-white rounded-2xl shadow-sm active:scale-95 transition-all">
          <Icon name="image" size={18} className="text-[#8DA399]" />
          <span className="text-[11px] font-black uppercase tracking-[0.3em]">匯出長圖 (手帳風格)</span>
        </button>

        <div className="mt-auto pb-10">
          <button type="submit" className="w-full py-5 bg-[#2A2A28] text-white rounded-2xl text-[10px] font-black uppercase tracking-[0.4em] shadow-lg">儲存旅程設定</button>
        </div>
      </form>
    </div>
  );
};

export default TripSettingsForm;

export type EntryType = 'itinerary' | 'expense';

export interface BaseEntry {
  id: string;
  timestamp: Date;
  type: EntryType;
}

export interface ItineraryEntry extends BaseEntry {
  type: 'itinerary';
  time: string;
  location: string;
  notes?: string;
  expenseAmount?: number;
  expenseCategory?: string;
  icon?: string;
  reflection?: string;
}

export interface ExpenseEntry extends BaseEntry {
  type: 'expense';
  amount: number;
  category: string;
  currency: string;
  description: string;
}

export type JournalEntry = ItineraryEntry | ExpenseEntry;

export interface DayTimeline {
  id: string;
  date: Date;
  dayNumber: number;
  entries: JournalEntry[];
}

export interface Trip {
  id: string;
  title: string;
  startDate: Date;
  endDate: Date;
  coverImage?: string;
  days: DayTimeline[];
}

export type AppTab = 'itinerary' | 'expenses' | 'trips';

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { AppTab, Trip, JournalEntry, EntryType, DayTimeline, ItineraryEntry, ExpenseEntry } from './types';
import { INITIAL_TRIP, COLORS, EXPENSE_CATEGORIES } from './constants';
import DayCard from './components/DayCard';
import Navigation from './components/Navigation';
import Icon from './components/Icon';
import EntryForm from './components/EntryForm';
import TripSettingsForm from './components/TripSettingsForm';
import * as htmlToImage from 'html-to-image';

const STORAGE_KEY = 'komorebi_trips_v10';

const timeTo24h = (timeStr: string) => {
  if (!timeStr) return "00:00";
  if (!timeStr.includes('AM') && !timeStr.includes('PM')) return timeStr;
  const [t, modifier] = timeStr.split(' ');
  let [hours, minutes] = t.split(':').map(Number);
  if (hours === 12) hours = 0;
  if (modifier === 'PM') hours += 12;
  return `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}`;
};

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<AppTab>('itinerary');

  const [allTrips, setAllTrips] = useState<Trip[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        return parsed.map((t: any) => ({
          ...t,
          startDate: new Date(t.startDate),
          endDate: new Date(t.endDate),
          days: t.days.map((d: any) => ({
            ...d,
            date: new Date(d.date),
            entries: d.entries.map((e: any) => ({
              ...e,
              timestamp: new Date(e.timestamp)
            }))
          }))
        }));
      } catch (e) {
        return [INITIAL_TRIP];
      }
    }
    return [INITIAL_TRIP];
  });

  const [activeTripId, setActiveTripId] = useState<string>(allTrips[0]?.id || INITIAL_TRIP.id);
  const trip = useMemo(() => allTrips.find(t => t.id === activeTripId) || allTrips[0], [allTrips, activeTripId]);

  const [isScrolled, setIsScrolled] = useState(false);
  const [activeForm, setActiveForm] = useState<EntryType | null>(null);
  const [targetDayId, setTargetDayId] = useState<string | null>(null);
  const [editingEntry, setEditingEntry] = useState<{ dayId: string; entry: JournalEntry } | null>(null);
  const [showTripSettings, setShowTripSettings] = useState(false);
  const [isExporting, setIsExporting] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(allTrips));
  }, [allTrips]);

  useEffect(() => {
    const handleScroll = () => setIsScrolled(window.scrollY > 40);
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const expenseAnalysis = useMemo(() => {
    let grandTotal = 0;
    const categoryMap: Record<string, number> = {};
    EXPENSE_CATEGORIES.forEach(cat => categoryMap[cat.label] = 0);

    trip.days.forEach(day => {
      day.entries.forEach(entry => {
        let amount = 0;
        let category = '其他';
        if (entry.type === 'itinerary') {
          const e = entry as ItineraryEntry;
          amount = e.expenseAmount || 0;
          category = e.expenseCategory || '其他';
        } else if (entry.type === 'expense') {
          const e = entry as ExpenseEntry;
          amount = e.amount || 0;
          category = e.category || '其他';
        }
        if (amount > 0) {
          grandTotal += amount;
          categoryMap[category] = (categoryMap[category] || 0) + amount;
        }
      });
    });

    const categories = Object.entries(categoryMap)
      .map(([label, amount]) => ({
        label,
        amount,
        percentage: grandTotal > 0 ? (amount / grandTotal) * 100 : 0
      }))
      .filter(c => c.amount > 0)
      .sort((a, b) => b.amount - a.amount);

    return { grandTotal, categories };
  }, [trip]);

  const generateDaysBetween = (start: Date, end: Date, existingDays: DayTimeline[]): DayTimeline[] => {
    const newDays: DayTimeline[] = [];
    const startDate = new Date(start.getFullYear(), start.getMonth(), start.getDate());
    const endDate = new Date(end.getFullYear(), end.getMonth(), end.getDate());
    const dayMs = 24 * 60 * 60 * 1000;
    const diffTime = endDate.getTime() - startDate.getTime();
    const diffDays = Math.max(1, Math.floor(diffTime / dayMs) + 1);

    for (let i = 0; i < diffDays; i++) {
      const currentDate = new Date(startDate);
      currentDate.setDate(startDate.getDate() + i);
      const dateKey = currentDate.toDateString();
      const existingDay = existingDays.find(d => d.date.toDateString() === dateKey);
      newDays.push({
        id: existingDay?.id || `day-${Date.now()}-${i}`,
        date: currentDate,
        dayNumber: i + 1,
        entries: existingDay?.entries || []
      });
    }
    return newDays;
  };

  const handleSaveTripSettings = (title: string, start: Date, end: Date) => {
    const newDays = generateDaysBetween(start, end, trip.days);
    setAllTrips(prev => prev.map(t => t.id === activeTripId ? { ...t, title, startDate: start, endDate: end, days: newDays } : t));
    setShowTripSettings(false);
  };

  const createNewTrip = () => {
    const newTrip: Trip = {
      ...INITIAL_TRIP,
      id: `trip-${Date.now()}`,
      title: '新旅程',
      startDate: new Date(),
      endDate: new Date(),
      days: [{ id: `day-${Date.now()}`, date: new Date(), dayNumber: 1, entries: [] }]
    };
    setAllTrips(prev => [newTrip, ...prev]);
    setActiveTripId(newTrip.id);
    setActiveTab('itinerary');
    setShowTripSettings(true);
  };

  const deleteTrip = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (allTrips.length <= 1) {
      alert('請至少保留一個旅程。');
      return;
    }
    if (confirm('確定要永久刪除這份典藏旅程嗎？')) {
      const remaining = allTrips.filter(t => t.id !== id);
      setAllTrips(remaining);
      if (activeTripId === id) {
        setActiveTripId(remaining[0].id);
      }
    }
  };

  const handleImportData = (entries: { date: string, entry: JournalEntry }[]) => {
    try {
      if (!entries || entries.length === 0) return;
      const importTimestamps = entries.map(e => {
        const [y, m, d] = e.date.split('-').map(Number);
        return new Date(y, m-1, d).getTime();
      });
      const minT = Math.min(...importTimestamps);
      const maxT = Math.max(...importTimestamps);
      const currentStart = new Date(trip.startDate.getFullYear(), trip.startDate.getMonth(), trip.startDate.getDate()).getTime();
      const currentEnd = new Date(trip.endDate.getFullYear(), trip.endDate.getMonth(), trip.endDate.getDate()).getTime();

      const performImport = (targetTrip: Trip) => {
        let importedCount = 0;
        let duplicateCount = 0;
        const updatedDays = targetTrip.days.map(day => {
          const y = day.date.getFullYear();
          const m = String(day.date.getMonth() + 1).padStart(2, '0');
          const d = String(day.date.getDate()).padStart(2, '0');
          const dayKey = `${y}-${m}-${d}`;

          const newEntriesForDay = entries
            .filter(item => item.date === dayKey)
            .map(item => item.entry)
            .filter(newEntry => {
               const isDuplicate = day.entries.some(existing => {
                 if (existing.type !== newEntry.type) return false;
                 if (existing.type === 'itinerary') {
                   const e1 = existing as ItineraryEntry;
                   const e2 = newEntry as ItineraryEntry;
                   return e1.time === e2.time && e1.location === e2.location;
                 } else {
                   const e1 = existing as ExpenseEntry;
                   const e2 = newEntry as ExpenseEntry;
                   return e1.description === e2.description && e1.amount === e2.amount;
                 }
               });
               if (isDuplicate) {
                 duplicateCount++;
                 return false;
               }
               return true;
            });

          if (newEntriesForDay.length === 0) return day;

          importedCount += newEntriesForDay.length;
          const merged = [...day.entries, ...newEntriesForDay].sort((a, b) => {
            if (a.type === 'itinerary' && b.type === 'itinerary') return timeTo24h((a as ItineraryEntry).time).localeCompare(timeTo24h((b as ItineraryEntry).time));
            return 0;
          });
          return { ...day, entries: merged };
        });

        setAllTrips(prev => prev.map(t => t.id === targetTrip.id ? { ...targetTrip, days: updatedDays } : t));
        setShowTripSettings(false);

        let msg = `✨ 成功匯入 ${importedCount} 筆資料！`;
        if (duplicateCount > 0) msg += `\n(已自動過濾 ${duplicateCount} 筆重複內容)`;
        alert(msg);
      };

      if (minT < currentStart || maxT > currentEnd) {
        if (confirm(`匯入資料包含超出現有行程範圍的日期。\n是否自動擴展旅程天數？`)) {
          const finalStart = new Date(Math.min(currentStart, minT));
          const finalEnd = new Date(Math.max(currentEnd, maxT));
          const expandedDays = generateDaysBetween(finalStart, finalEnd, trip.days);
          const expandedTrip = { ...trip, startDate: finalStart, endDate: finalEnd, days: expandedDays };
          performImport(expandedTrip);
        } else {
          performImport(trip);
        }
      } else {
        performImport(trip);
      }
    } catch (err) {
      alert("匯入過程中發生錯誤，請檢查檔案格式。");
    }
  };

  const handleExportLongImage = async () => {
    if (!containerRef.current) return;
    const originalStyle = containerRef.current.style.overflow;
    setIsExporting(true);
    setShowTripSettings(false);
    await new Promise(resolve => setTimeout(resolve, 800));
    try {
      containerRef.current.style.overflow = 'visible';
      const dataUrl = await htmlToImage.toJpeg(containerRef.current, {
        quality: 0.95,
        cacheBust: true,
        pixelRatio: 2,
        backgroundColor: COLORS.background,
        style: { paddingBottom: '20px', overflow: 'visible' }
      });
      const link = document.createElement('a');
      link.download = `${trip.title}_TravelLog.jpg`;
      link.href = dataUrl;
      link.click();
    } catch (err) {
      alert('圖片匯出失敗');
    } finally {
      if (containerRef.current) containerRef.current.style.overflow = originalStyle;
      setIsExporting(false);
    }
  };

  const handleSaveEntry = (data: Partial<JournalEntry>) => {
    const formType = activeForm || editingEntry?.entry.type;
    if (!formType) return;

    setAllTrips(prev => prev.map(t => {
      if (t.id !== activeTripId) return t;
      return {
        ...t,
        days: t.days.map(day => {
          if (editingEntry) {
            if (day.id !== editingEntry.dayId) return day;
            return {
              ...day,
              entries: day.entries.map(e => e.id === editingEntry.entry.id ? ({ ...e, ...data } as JournalEntry) : e).sort((a, b) => {
                if (a.type === 'itinerary' && b.type === 'itinerary') return timeTo24h((a as ItineraryEntry).time).localeCompare(timeTo24h((b as ItineraryEntry).time));
                return 0;
              })
            };
          } else {
            if (day.id !== targetDayId && !(!targetDayId && day.id === t.days[0].id)) return day;
            const newEntry: JournalEntry = { id: Date.now().toString(), timestamp: new Date(), type: formType, ...data } as any;
            return {
              ...day,
              entries: [...day.entries, newEntry].sort((a, b) => {
                if (a.type === 'itinerary' && b.type === 'itinerary') return timeTo24h((a as ItineraryEntry).time).localeCompare(timeTo24h((b as ItineraryEntry).time));
                return 0;
              })
            };
          }
        })
      };
    }));

    setActiveForm(null);
    setTargetDayId(null);
    setEditingEntry(null);
  };

  const handleDeleteEntry = (dayId: string, entryId: string) => {
    setAllTrips(prev => prev.map(t => t.id === activeTripId ? {
      ...t,
      days: t.days.map(day => day.id === dayId ? { ...day, entries: day.entries.filter(e => entryId !== e.id) } : day)
    } : t));
  };

  const handleAddEntryToDay = (dayId: string, type: EntryType) => {
    setTargetDayId(dayId);
    setActiveForm(type);
  };

  const handleEditEntryTrigger = (dayId: string, entry: JournalEntry) => {
    setEditingEntry({ dayId, entry });
  };

  return (
    <div 
      ref={containerRef}
      className={`min-h-screen pb-28 max-w-md mx-auto bg-[#FAF9F6] relative overflow-x-hidden print:bg-white print:pb-0 ${isExporting ? 'is-exporting' : ''}`}
    >
      <div className="fixed top-[10%] -left-10 w-48 h-48 bg-[#E8F1EF] rounded-full blur-[80px] -z-10 opacity-60" />
      <div className="fixed bottom-[20%] -right-10 w-64 h-64 bg-[#FFF5E1] rounded-full blur-[100px] -z-10 opacity-50" />

      <header 
        onClick={() => !isScrolled && !isExporting && activeTab !== 'trips' && setShowTripSettings(true)}
        className={`sticky top-0 z-40 transition-all duration-300 px-6 flex flex-col justify-end cursor-pointer ${isScrolled ? 'h-14 bg-white/80 backdrop-blur-md border-b border-[#EFEFE9]' : 'h-36 bg-transparent'}`}
      >
        <div className={`flex justify-between items-end ${isScrolled ? 'pb-2' : 'pb-5'}`}>
          <div>
            {!isScrolled && (
              <div className="flex items-center gap-1.5 mb-1.5">
                 <div className="w-4 h-4 rounded bg-[#8DA399] flex items-center justify-center text-white rotate-6">
                   <Icon name="trips" size={10} />
                 </div>
                 <span className="text-[8px] font-black uppercase tracking-[0.2em] text-[#8DA399]">
                   {activeTab === 'trips' ? 'Archives' : 'Travel Record'}
                 </span>
              </div>
            )}
            <h1 className={`font-bold text-[#2A2A28] serif leading-tight transition-all duration-300 ${isScrolled ? 'text-base' : 'text-2xl'}`}>
              {activeTab === 'trips' ? '典藏旅程' : trip.title}
            </h1>
          </div>
          {activeTab !== 'trips' && (
            <button 
              onClick={(e) => { e.stopPropagation(); setShowTripSettings(true); }}
              className={`trip-settings-toggle p-1.5 bg-white rounded-lg shadow-sm border border-[#EFEFE9] transition-all ${isScrolled ? 'scale-90' : ''}`}
            >
              <Icon name="more" size={14} className="text-[#BABAB5]" />
            </button>
          )}
          {activeTab === 'trips' && (
            <button 
              onClick={createNewTrip}
              className={`p-1.5 bg-[#2A2A28] text-white rounded-lg shadow-sm transition-all ${isScrolled ? 'scale-90' : ''}`}
            >
              <Icon name="plus" size={14} />
            </button>
          )}
        </div>
      </header>

      <main className="px-5 mt-4 relative z-10">
        {activeTab === 'itinerary' && (
          <div className="space-y-4">
            {trip.days.map((day) => (
              <DayCard 
                key={day.id} 
                day={day} 
                onDeleteEntry={handleDeleteEntry} 
                onEditEntry={handleEditEntryTrigger}
                onAddEntryToDay={handleAddEntryToDay}
              />
            ))}
          </div>
        )}

        {activeTab === 'expenses' && (
           <div className="space-y-4 animate-in fade-in slide-in-from-bottom-2">
              <div className="bg-white rounded-[28px] p-6 border border-[#EFEFE9] shadow-sm">
                 <div className="mb-6">
                    <span className="text-[10px] font-black uppercase tracking-widest text-[#BABAB5]">旅程總支出</span>
                    <div className="flex items-baseline gap-1 mt-1">
                       <span className="text-3xl font-black text-[#2A2A28] tabular-nums">NT${expenseAnalysis.grandTotal.toLocaleString()}</span>
                    </div>
                 </div>
                 {expenseAnalysis.categories.length > 0 ? (
                    <div className="space-y-4">
                       {expenseAnalysis.categories.map((cat, idx) => {
                          const theme = COLORS.palette[idx % COLORS.palette.length];
                          return (
                             <div key={cat.label} className="space-y-1.5">
                                <div className="flex justify-between items-center text-[10px] font-bold">
                                   <span className="text-[#2A2A28]">{cat.label}</span>
                                   <span className="text-[#BABAB5] tabular-nums">NT${cat.amount.toLocaleString()}</span>
                                </div>
                                <div className="h-2 w-full bg-[#FAF9F6] rounded-full overflow-hidden">
                                   <div className="h-full rounded-full" style={{ width: `${cat.percentage}%`, backgroundColor: theme.tape, opacity: 0.8 }} />
                                </div>
                             </div>
                          );
                       })}
                    </div>
                 ) : (
                    <p className="text-center py-4 text-[10px] text-[#BABAB5] font-bold uppercase">尚無支出數據</p>
                 )}
              </div>

              <div className="bg-white rounded-[28px] p-5 border border-[#EFEFE9] shadow-sm">
                <h2 className="text-sm font-bold serif mb-4">明細清單</h2>
                {trip.days.map(day => {
                   const dayExpenses = day.entries.filter(e => (e.type === 'itinerary' && (e as ItineraryEntry).expenseAmount) || e.type === 'expense');
                   if (dayExpenses.length === 0) return null;
                   return (
                     <div key={day.id} className="mb-4 last:mb-0">
                       <span className="text-[8px] font-black text-[#BABAB5] uppercase mb-2 block tracking-widest">DAY {day.dayNumber}</span>
                       {dayExpenses.map((e: any) => (
                         <div key={e.id} onClick={() => handleEditEntryTrigger(day.id, e)} className="flex justify-between py-2 border-b border-[#F8F8F5] last:border-0 cursor-pointer">
                            <span className="text-xs font-semibold text-[#2A2A28]">{e.type === 'itinerary' ? e.location : e.description}</span>
                            <span className="text-xs font-black">NT${(e.expenseAmount || e.amount).toLocaleString()}</span>
                         </div>
                       ))}
                     </div>
                   );
                })}
              </div>
           </div>
        )}

        {activeTab === 'trips' && (
           <div className="space-y-4 animate-in fade-in slide-in-from-bottom-2">
              {allTrips.map((t) => (
                <div 
                  key={t.id}
                  onClick={() => { setActiveTripId(t.id); setActiveTab('itinerary'); window.scrollTo(0, 0); }}
                  className={`relative p-5 bg-white rounded-[24px] border transition-all cursor-pointer ${activeTripId === t.id ? 'border-[#8DA399] shadow-md ring-1 ring-[#8DA399]/20' : 'border-[#EFEFE9] shadow-sm opacity-80'}`}
                >
                  {activeTripId === t.id && <div className="absolute top-4 right-4 w-1.5 h-1.5 rounded-full bg-[#8DA399]" />}
                  <div className="flex justify-between items-start mb-3">
                    <h3 className="text-lg font-bold serif text-[#2A2A28] pr-10">{t.title}</h3>
                    <button 
                      onClick={(e) => deleteTrip(t.id, e)}
                      className="p-2 -mr-2 text-[#BABAB5] hover:text-red-400 transition-colors"
                    >
                      <Icon name="plus" size={14} className="rotate-45" />
                    </button>
                  </div>
                  <div className="flex items-center gap-4">
                    <div className="flex items-center gap-1.5">
                      <Icon name="calendar" size={10} className="text-[#BABAB5]" />
                      <span className="text-[10px] font-bold text-[#BABAB5]">
                        {t.startDate.toLocaleDateString('zh-TW')} - {t.endDate.toLocaleDateString('zh-TW')}
                      </span>
                    </div>
                    <div className="flex items-center gap-1.5">
                      <Icon name="clock" size={10} className="text-[#BABAB5]" />
                      <span className="text-[10px] font-bold text-[#BABAB5]">{t.days.length} 天行程</span>
                    </div>
                  </div>
                </div>
              ))}
              {allTrips.length === 0 && (
                 <div className="py-20 text-center border-2 border-dashed border-[#EFEFE9] rounded-[28px]">
                   <p className="text-[10px] font-bold text-[#BABAB5] uppercase tracking-widest">點擊上方 + 按鈕建立新旅程</p>
                 </div>
              )}
           </div>
        )}
      </main>

      {(activeForm || editingEntry) && (
        <EntryForm 
          type={activeForm || editingEntry!.entry.type} 
          initialData={editingEntry?.entry}
          onClose={() => { setActiveForm(null); setEditingEntry(null); setTargetDayId(null); }} 
          onSave={handleSaveEntry} 
        />
      )}

      {showTripSettings && (
        <TripSettingsForm 
          trip={trip} 
          onClose={() => setShowTripSettings(false)} 
          onSave={handleSaveTripSettings}
          onImport={handleImportData}
          onExportImage={handleExportLongImage}
        />
      )}

      {activeTab !== 'trips' && (
        <div className="fixed-button fixed bottom-24 right-6 z-50">
          <button 
            onClick={() => setActiveForm('itinerary')}
            className="w-11 h-11 rounded-2xl bg-[#2A2A28] text-white flex items-center justify-center shadow-lg hover:bg-[#8DA399] transition-all active:scale-90"
          >
            <Icon name="plus" size={18} />
          </button>
        </div>
      )}

      <Navigation activeTab={activeTab} onTabChange={setActiveTab} />
    </div>
  );
};

