              <div className="h-[1px] flex-1 bg-dashed border-b border-[#EFEFE9]" />
              {item.expenseAmount && (
                 <span className="text-[9px] font-black tabular-nums text-[#8DA399]">NT${item.expenseAmount.toLocaleString()}</span>
              )}
            </div>

            <div className="flex items-center gap-3">
              <div className="flex flex-col">
                <span className="text-[10px] font-bold text-[#8A8A85] uppercase tracking-tighter leading-none mb-1">From</span>
                <span className="text-xs font-bold text-[#2A2A28] serif">{item.startLocation || '未定'}</span>
              </div>

              <Icon name="arrow" size={12} className="text-[#EFEFE9] mt-3" />

              <div className="flex flex-col">
