  if (entry.type === 'expense') {
    const item = entry as ExpenseEntry;
    return (
      <div 
        onClick={handleEdit} 
        className="ml-8 flex justify-between items-center py-2.5 px-3.5 border border-[#EFEFE9] rounded-[16px] group bg-white/60 hover:bg-white transition-all shadow-sm relative mb-3"
