import React from 'react';
import { JournalEntry, ItineraryEntry, ExpenseEntry } from '../types';
import Icon, { IconName } from './Icon';
import { ITINERARY_ICONS } from '../constants';

interface EntryItemProps {
  entry: JournalEntry;
  onDelete?: (id: string) => void;
  onEdit?: (entry: JournalEntry) => void;
}

const EntryItem: React.FC<EntryItemProps> = ({ entry, onDelete, onEdit }) => {
  const handleDelete = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (onDelete && confirm('刪除這則回憶嗎？')) {
      onDelete(entry.id);
    }
  };

  const handleEdit = () => {
    if (onEdit) onEdit(entry);
  };

  if (entry.type === 'itinerary') {
    const item = entry as ItineraryEntry;
    const transitIcons = ['subway', 'train', 'plane', 'hsr', 'bus'];
    const isTransit = transitIcons.includes(item.icon || '');

    // 獲取該圖示對應的中文標籤
    const iconLabel = ITINERARY_ICONS.find(icon => icon.id === item.icon)?.label || '交通';

    // 交通工具呈現方式：非卡片，而是線條路徑
    if (isTransit && (item.startLocation || item.endLocation)) {
      return (
        <div 
          onClick={handleEdit}
          className="relative pl-8 mb-6 group cursor-pointer active:scale-[0.98] transition-all py-1"
        >
          {/* 左側圖示 */}
          <div className="absolute left-[0px] top-1/2 -translate-y-1/2 w-6 h-6 rounded-full bg-[#FAF9F6] border border-[#EFEFE9] flex items-center justify-center z-10 shadow-sm">
            <Icon name={(item.icon || 'subway') as IconName} size={11} className="text-[#8DA399]" />
          </div>

          <div className="flex flex-col pr-10">
            <div className="flex items-center gap-2 mb-1">
              <span className="text-[8px] font-black text-[#BABAB5] tracking-widest uppercase">{item.time}</span>
              <div className="px-1.5 py-0.5 rounded bg-[#8DA399]/10 border border-[#8DA399]/20">
                <span className="text-[7px] font-black text-[#8DA399] tracking-tighter">{iconLabel}</span>
              </div>
              <div className="h-[1px] flex-1 bg-dashed border-b border-[#EFEFE9]" />
              {item.expenseAmount && (
                 <span className="text-[9px] font-black tabular-nums text-[#8DA399]">NT${item.expenseAmount.toLocaleString()}</span>
              )}
            </div>

            <div className="flex items-center gap-3">
              <div className="flex flex-col">
                <span className="text-[10px] font-bold text-[#8A8A85] uppercase tracking-tighter leading-none mb-1">From</span>
                <span className="text-xs font-bold text-[#2A2A28] serif">{item.startLocation || '起點'}</span>
              </div>

              <Icon name="arrow" size={12} className="text-[#EFEFE9] mt-3" />

              <div className="flex flex-col">
                <span className="text-[10px] font-bold text-[#8A8A85] uppercase tracking-tighter leading-none mb-1">To</span>
                <span className="text-xs font-bold text-[#2A2A28] serif">{item.endLocation || '終點'}</span>
              </div>
            </div>

            {item.notes && <p className="text-[9px] text-[#BABAB5] mt-2 font-medium italic">註: {item.notes}</p>}
          </div>

          <button 
            onClick={handleDelete}
            className="absolute top-1/2 -translate-y-1/2 right-2 w-6 h-6 flex items-center justify-center text-[#BABAB5] opacity-0 group-hover:opacity-100 transition-opacity"
          >
            <Icon name="plus" size={10} className="rotate-45" />
          </button>
        </div>
      );
    }

    // 一般景點呈現方式：卡片式
    return (
      <div 
        onClick={handleEdit}
        className="relative pl-8 mb-5 group cursor-pointer active:scale-[0.99] transition-all"
      >
        <div className="absolute left-[0px] top-3.5 w-6 h-6 rounded-lg bg-white border border-[#EFEFE9] shadow-sm flex items-center justify-center z-10">
          <Icon name={(item.icon || 'mapPin') as IconName} size={11} className="text-[#8DA399]" />
        </div>

        <div className="bg-white rounded-[20px] p-4 border border-[#EFEFE9] shadow-sm hover:shadow-md transition-all relative overflow-hidden">
          <button 
            onClick={handleDelete}
            className="absolute top-2 right-2 w-6 h-6 flex items-center justify-center text-[#BABAB5] hover:text-red-400 bg-[#FDFDFB] rounded-full shadow-sm border border-[#F1F1ED] z-20"
          >
            <Icon name="plus" size={10} className="rotate-45" />
          </button>

          <div className="relative z-10 pr-4">
            <div className="flex justify-between items-start mb-2">
              <div className="flex items-center gap-1">
                <Icon name="clock" size={9} className="text-[#8DA399]" />
                <span className="text-[8px] font-black text-[#8DA399] tracking-widest uppercase">{item.time}</span>
              </div>

              {item.expenseAmount ? (
                <div className="text-right">
                  <span className="text-[11px] font-black tabular-nums text-[#2A2A28]">
                    NT${item.expenseAmount.toLocaleString()}
                  </span>
                </div>
              ) : null}
            </div>

            <h4 className="text-sm font-bold text-[#2A2A28] mb-0.5 serif leading-tight">{item.location}</h4>
            {item.notes && <p className="text-[10px] text-[#8A8A85] leading-normal font-medium mb-2">{item.notes}</p>}

            {item.reflection && (
              <div className="mt-2.5 p-2.5 bg-[#FAF9F6] rounded-lg border-l-2 border-[#8DA399]/30 italic">
                <p className="serif text-[#2A2A28] leading-relaxed text-[11px] opacity-90">
                  「{item.reflection}」
                </p>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }

  if (entry.type === 'expense') {
    const item = entry as ExpenseEntry;
    return (
      <div 
        onClick={handleEdit} 
        className="ml-8 flex justify-between items-center py-2.5 px-3.5 border border-[#EFEFE9] rounded-[16px] group bg-white/60 hover:bg-white transition-all shadow-sm relative mb-3"
      >
        <div className="flex items-center gap-2.5">
          <div className="w-5 h-5 rounded-full bg-[#EFEFE9] flex items-center justify-center text-[#8A8A85]">
             <Icon name="expenses" size={10} />
          </div>
          <div>
            <span className="text-[7px] text-[#8DA399] font-black uppercase tracking-widest">{item.category}</span>
            <span className="text-[11px] font-bold text-[#2A2A28] block leading-none">{item.description}</span>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <span className="text-[11px] font-black tabular-nums">NT${item.amount.toLocaleString()}</span>
          <button 
            onClick={handleDelete}
            className="w-5 h-5 flex items-center justify-center text-[#BABAB5] hover:text-red-400"
          >
            <Icon name="plus" size={10} className="rotate-45" />
          </button>
        </div>
      </div>
    );
  }

  return null;
};

export default EntryItem;

import React, { useState, useEffect } from 'react';
import { EntryType, JournalEntry, ItineraryEntry } from '../types';
import { EXPENSE_CATEGORIES, ITINERARY_ICONS } from '../constants';
import Icon, { IconName } from './Icon';

interface EntryFormProps {
  type: EntryType;
  initialData?: Partial<JournalEntry>;
  onSave: (data: Partial<JournalEntry>) => void;
  onClose: () => void;
}

const EntryForm: React.FC<EntryFormProps> = ({ type, initialData, onSave, onClose }) => {
  const getCurrentTimeRaw = () => {
    const now = new Date();
    return now.toTimeString().slice(0, 5); 
  };

  const [formData, setFormData] = useState<any>({
    time: getCurrentTimeRaw(),
    location: '',
    startLocation: '',
    endLocation: '',
    notes: '',
    expenseAmount: '',
    expenseCategory: '其他',
    icon: 'mapPin',
    reflection: '',
    amount: '',
    category: '其他',
    description: ''
  });

  useEffect(() => {
    if (initialData) {
      let time = formData.time;
      if (initialData.type === 'itinerary' && (initialData as any).time) {
        const timeStr = (initialData as any).time;
        if (timeStr.includes('AM') || timeStr.includes('PM')) {
           const [t, modifier] = timeStr.split(' ');
           let [hoursStr, minutes] = t.split(':');
           let hours = parseInt(hoursStr, 10);

           if (modifier === 'PM' && hours < 12) hours += 12;
           if (modifier === 'AM' && hours === 12) hours = 0;

           time = `${String(hours).padStart(2, '0')}:${minutes}`;
        } else {
           time = timeStr;
        }
      }

      setFormData((prev: any) => ({
        ...prev,
        ...initialData,
        time: time
      }));
    }
  }, [initialData]);

  const isEdit = !!initialData?.id;
  const transitIcons = ['subway', 'train', 'plane', 'hsr', 'bus'];
  const isTransit = transitIcons.includes(formData.icon);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const dataToSave = { ...formData };

    if (type === 'itinerary' && dataToSave.time) {
      const [h, m] = dataToSave.time.split(':');
      const hour = parseInt(h, 10);
      const ampm = hour >= 12 ? 'PM' : 'AM';
      const displayHour = hour % 12 || 12;
      dataToSave.time = `${String(displayHour).padStart(2, '0')}:${m} ${ampm}`;

      // 如果是交通，location 改為起迄點描述，這在搜尋時很有用
      if (isTransit) {
        dataToSave.location = `${dataToSave.startLocation || '起點'} → ${dataToSave.endLocation || '終點'}`;
      }
    }

    if (dataToSave.expenseAmount !== '') dataToSave.expenseAmount = parseFloat(dataToSave.expenseAmount);
    if (dataToSave.amount !== '') dataToSave.amount = parseFloat(dataToSave.amount);

    onSave(dataToSave);
  };

  const CategorySelector = ({ value, onChange, label }: { value: string, onChange: (v: string) => void, label: string }) => (
    <div className="space-y-3">
      <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">{label}</label>
      <div className="grid grid-cols-3 gap-2">
        {EXPENSE_CATEGORIES.map((cat) => (
          <button
            key={cat.id}
            type="button"
            onClick={() => onChange(cat.label)}
            className={`flex flex-col items-center gap-1.5 py-3 rounded-2xl text-[10px] font-bold tracking-wider transition-all border ${
              value === cat.label 
                ? 'bg-[#8DA399] border-[#8DA399] text-white shadow-md' 
                : 'bg-white border-[#EFEFE9] text-[#8A8A85] hover:border-[#8DA399]'
            }`}
          >
            <Icon name={cat.icon as any} size={14} />
            {cat.label}
          </button>
        ))}
      </div>
    </div>
  );

  return (
    <div className="fixed inset-0 z-[100] bg-[#FDFDFB] animate-in slide-in-from-bottom duration-500 p-8 flex flex-col overflow-y-auto no-scrollbar">
      <div className="flex justify-between items-center mb-8">
        <span className="text-[10px] font-black uppercase tracking-[0.5em] text-[#8DA399]">
          {isEdit ? '編輯紀錄' : '新增紀錄'}
        </span>
        <button onClick={onClose} className="p-2 -mr-2 text-[#BABAB5] hover:text-[#2A2A28] transition-colors">
          <Icon name="plus" size={24} className="rotate-45" />
        </button>
      </div>

      <form onSubmit={handleSubmit} className="flex-1 flex flex-col gap-6">
        {type === 'itinerary' ? (
          <>
            <div className="space-y-3">
              <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">選擇標記圖示</label>
              <div className="flex gap-3 overflow-x-auto pb-2 no-scrollbar px-1">
                {ITINERARY_ICONS.map((icon) => (
                  <button
                    key={icon.id}
                    type="button"
                    onClick={() => setFormData({...formData, icon: icon.id})}
                    className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 transition-all ${
                      formData.icon === icon.id 
                        ? 'bg-[#8DA399] text-white shadow-md scale-110' 
                        : 'bg-white border border-[#EFEFE9] text-[#BABAB5] hover:border-[#8DA399]'
                    }`}
                  >
                    <Icon name={icon.id as IconName} size={18} />
                    <span className="sr-only">{icon.label}</span>
                  </button>
                ))}
              </div>
            </div>

            <div className="grid grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">時間 (24h)</label>
                <input 
                  type="time" 
                  value={formData.time}
                  onChange={(e) => setFormData({...formData, time: e.target.value})}
                  className="w-full text-lg font-medium outline-none bg-transparent border-b border-[#EFEFE9] pb-2 focus:border-[#8DA399] transition-colors"
                />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">支出金額</label>
                <input 
                  type="number" 
                  value={formData.expenseAmount}
                  onChange={(e) => setFormData({...formData, expenseAmount: e.target.value})}
                  className="w-full text-lg font-medium outline-none bg-transparent border-b border-[#EFEFE9] pb-2 focus:border-[#8DA399] transition-colors"
                  placeholder="0"
                />
              </div>
            </div>

            {parseFloat(formData.expenseAmount) > 0 && (
               <CategorySelector 
                  label="支出分類" 
                  value={formData.expenseCategory} 
                  onChange={(v) => setFormData({...formData, expenseCategory: v})} 
               />
            )}

            {isTransit ? (
              <div className="grid grid-cols-2 gap-4 animate-in fade-in slide-in-from-top-2">
                <div className="space-y-2">
                  <label className="text-[10px] uppercase tracking-widest text-[#BABAB5] font-bold">起點站</label>
                  <input 
                    type="text" 
                    value={formData.startLocation}
                    onChange={(e) => setFormData({...formData, startLocation: e.target.value})}
