import { GoogleGenAI, Type } from "@google/genai";
import { AIAnalysis, AuthorProfile, Quote } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeQuote = async (content: string, author: string, observationDate: string): Promise<AIAnalysis> => {
  const prompt = `你是一位精通「社會心理學」與「話語分析」的人際關係專家。
  目標：針對紀錄者與 "${author}" 的互動進行「正反辯證」分析。

  互動紀錄：
  - 日期：${observationDate}
  - 參與對象：${author}
  - 內容：${content}

  請返回 JSON 格式進行深度解剖：
  1. resonanceScore: 1-10 的情感撞擊力。
  2. insight: 一段精闢的洞察總結，點出這段互動的核心本質（約 50 字）。
  3. dynamic: 定義這段「權力/情感動態」（例如：隱形的博弈、單向的依賴、互補的默契）。
  4. positiveView: 提供 2 個「正向論點/支持性解讀」。試著挖掘這段話背後的善意、共識或對關係的積極建構。
  5. criticalView: 提供 2 個「反向論點/挑戰性解讀」。試著挑戰表面現象，挖掘隱藏的焦慮、潛在的矛盾或被忽視的心理防衛。
  6. suggestedTags: 3 個精確的關鍵標籤。`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          resonanceScore: { type: Type.NUMBER },
          insight: { type: Type.STRING },
          dynamic: { type: Type.STRING },
          positiveView: { type: Type.ARRAY, items: { type: Type.STRING } },
          criticalView: { type: Type.ARRAY, items: { type: Type.STRING } },
          suggestedTags: { type: Type.ARRAY, items: { type: Type.STRING } }
        },
        required: ["resonanceScore", "insight", "dynamic", "positiveView", "criticalView", "suggestedTags"]
      }
    }
  });

  return JSON.parse(response.text);
};

export const generateAuthorProfile = async (author: string, quotes: Quote[]): Promise<AuthorProfile> => {
  const history = quotes.map(q => `[${q.observationDate}] ${q.content}`).join('\n');

  const prompt = `你是一位精通心理學的人際關係分析大師。
  請根據以下紀錄者與 "${author}" 的多段互動紀錄，為此人建立一份動態「人物誌」。

  互動歷史：
  ${history}

  請以 JSON 格式返回：
  1. characterType: 賦予其一個獨特的人物原型稱號（例如：外冷內熱的守護者）。
  2. traits: 從互動中觀察出的 3-4 個性格特質。
  3. relationshipPhase: 目前關係所處的階段或狀態描述。
  4. interactionGuide: 給予紀錄者的 1 條具體相處或溝通建議。
  5. summary: 對此人的深度性格畫像總結（約 100 字）。`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          characterType: { type: Type.STRING },
          traits: { type: Type.ARRAY, items: { type: Type.STRING } },
          relationshipPhase: { type: Type.STRING },
          interactionGuide: { type: Type.STRING },
          summary: { type: Type.STRING }
        },
        required: ["characterType", "traits", "relationshipPhase", "interactionGuide", "summary"]
      }
    }
  });

  const data = JSON.parse(response.text);
  return {
    ...data,
    lastUpdated: Date.now()
  };
};

import React, { useState } from 'react';
import { Quote } from '../types';
import { analyzeQuote } from '../services/geminiService';

interface QuoteItemProps {
  quote: Quote;
  onUpdate: (updatedQuote: Quote) => void;
  onDelete: (id: string) => void;
}

const QuoteItem: React.FC<QuoteItemProps> = ({ quote, onUpdate, onDelete }) => {
  const [loading, setLoading] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editContent, setEditContent] = useState(quote.content);
  const [editDate, setEditDate] = useState(quote.observationDate);

  const handleAIAnalyze = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setLoading(true);
    try {
      const analysis = await analyzeQuote(quote.content, quote.author, quote.observationDate);
      onUpdate({ ...quote, aiAnalysis: analysis });
    } catch (error) {
      console.error("AI Analysis failed", error);
    } finally {
      setLoading(false);
    }
  };

  const handleSaveEdit = (e: React.MouseEvent) => {
    e.stopPropagation();
    onUpdate({
