/**
 * 系統化整理原始敘述：在最少更動前提下，理順邏輯且不省略任何內容。
 */
export const refineNarrative = async (rawContent: string): Promise<string> => {
  const prompt = `你是一位專業的文字紀錄官。
  使用者提供了一段人際互動的原始敘述。你的任務是：
  1. 在「完全不刪減任何細節」的前提下，優化敘述的邏輯結構。
  2. 讓內容變得清楚明瞭（如：理順因果、修正語病、優化標點）。
  3. 保留原始敘述的情緒、語氣與所有特定的「怪言怪語」。
  4. 整理後的內容應保持原汁原味，但具備系統性的條理。

  原始敘述：
  """
  ${rawContent}
  """

  請直接返回整理後的純文字內容：`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: { temperature: 0.7 }
  });

  return response.text?.trim() || rawContent;
};

/**
 * 雙方立場辯證分析：將我方設為正方，對方設為反方進行論述。
 */
export const analyzeQuote = async (content: string, author: string, observationDate: string): Promise<AIAnalysis> => {
  const prompt = `你是一位精通「溝通心理學」與「關係解構」的分析大師。
  目標：針對紀錄者(我)與 "${author}"(對方) 的互動進行「雙方觀點辯證」。
  請將「我」視為正方，「${author}」視為反方，剖析兩者在此情境下的主觀邏輯衝突。

  互動情境：
  - 時間：${observationDate}
  - 互動者：${author}
  - 內容：${content}

  請返回 JSON 格式：
  1. resonanceScore: 1-10 的心理衝突強度。
  2. insight: 總結這場辯證的核心矛盾（約 50 字）。
  3. dynamic: 定義這場「立場交鋒」的性質。
  4. selfView: 我方觀點 (正方)。提供 2 個論點：我在這段互動中的主觀邏輯、正當性或潛在需求。
  5. otherView: 對方觀點 (反方)。提供 2 個論點：${author} 的行動動態、他的反向邏輯、或他眼中的我。
  6. suggestedTags: 3 個反映雙方立場差異的標籤。`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          resonanceScore: { type: Type.NUMBER },
          insight: { type: Type.STRING },
          dynamic: { type: Type.STRING },
          selfView: { type: Type.ARRAY, items: { type: Type.STRING } },
          otherView: { type: Type.ARRAY, items: { type: Type.STRING } },
          suggestedTags: { type: Type.ARRAY, items: { type: Type.STRING } }
        },
        required: ["resonanceScore", "insight", "dynamic", "selfView", "otherView", "suggestedTags"]
      }
    }
  });

  return JSON.parse(response.text);
};

