                  {quote.aiAnalysis.selfView?.map((p, i) => (
                    <li key={i} className="text-[11px] text-emerald-800/80 leading-relaxed">• {p}</li>
                  ))}
                </ul>
              </div>
              <div className="bg-rose-50/40 rounded-xl p-4 border border-rose-100/60 group-hover/item:bg-rose-50 transition-colors">
                <span className="text-[10px] font-bold text-rose-600 block mb-2 flex items-center gap-1.5 uppercase tracking-wider">
                  <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M6 18L18 6M6 6l12 12" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"/></svg>
                  對方觀點 (反方)
                </span>
                <ul className="space-y-2">
                  {quote.aiAnalysis.otherView?.map((p, i) => (
                    <li key={i} className="text-[11px] text-rose-800/80 leading-relaxed">• {p}</li>
                  ))}
                </ul>
              </div>
            </div>
          </div>
        ) : (
          <button
            type="button"
            onClick={handleAIAnalyze}
            disabled={loading}
            className="mt-3 w-full py-3 bg-white border border-slate-200 text-slate-400 rounded-xl text-[10px] font-bold hover:text-indigo-600 hover:border-indigo-200 hover:bg-indigo-50/30 transition-all flex items-center justify-center gap-2 group/btn"
          >
            {loading ? (
              <div className="flex items-center gap-2">
                <div className="w-3 h-3 border-2 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
                <span>分析雙方腦內立場...</span>
              </div>
            ) : (
              <>
                <span className="group-hover/btn:scale-125 transition-transform">⚖️</span>
                啟動雙方觀點辯證
              </>
            )}
          </button>
        )
      )}
    </div>
  );
};

