 */
export const refineNarrative = async (rawContent: string): Promise<string> => {
  const prompt = `你是一位精通微觀觀察的敘事紀錄官。
  使用者提供了一段關於人際互動的碎片化敘述。請在「完全不刪減任何細節」的前提下，將其整理為一份系統化的觀察日誌。

  要求：
  1. 結構化：理順因果、對話與情境的先後順序。
  2. 保留原味：嚴禁修改說話者的語氣、詞彙或任何細微的語病（那是真實感的來源）。
  3. 最小變動：僅優化標點、分段與語法連結，使邏輯更明瞭。
  4. 字數不減：整理後的內容長度應與原內容相當，不得省略任何瑣碎細節。

  原始敘述：
  """
  ${rawContent}
  """

  請直接返回整理後的結構化文字：`;

  const response = await ai.models.generateContent({
