 */
export const analyzeQuote = async (content: string, author: string, observationDate: string): Promise<AIAnalysis> => {
  const prompt = `你是一位精通「主觀邏輯分析」的關係辯證大師。
  目標：將這場互動解構為一場「心理邏輯的辯論」。

  辯證規則：
  - 正方：紀錄者(我)。剖析我方的「行為預期」與「潛在正當性」。
  - 反方：${author}(對方)。剖析對方的「反向邏輯」或「對該情境的另一套詮釋」。

  互動紀錄：
  - 時間：${observationDate}
  - 互動者：${author}
  - 內容：${content}

  請返回 JSON 格式：
  1. resonanceScore: 1-10 的衝突張力指數。
  2. insight: 洞察總結。指出雙方邏輯在何處產生了致命的位移或資訊差（約 50 字）。
  3. dynamic: 定義這場辯證的核心動態（如：錯位的愛、生存焦慮的對抗、主權的邊界交火）。
  4. selfView: 我方觀點 (正方)。列出 2 點：我在當下所持的道理、期望或受傷的根源。
  5. otherView: 對方觀點 (反方)。列出 2 點：對方之所以那樣反應的自洽邏輯、他對我的行為解讀。
  6. suggestedTags: 3 個精準反映「邏輯對撞點」的標籤。`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          resonanceScore: { type: Type.NUMBER },
          insight: { type: Type.STRING },
          dynamic: { type: Type.STRING },
          selfView: { type: Type.ARRAY, items: { type: Type.STRING } },
          otherView: { type: Type.ARRAY, items: { type: Type.STRING } },
          suggestedTags: { type: Type.ARRAY, items: { type: Type.STRING } }
        },
        required: ["resonanceScore", "insight", "dynamic", "selfView", "otherView", "suggestedTags"]
      }
    }
  });

  return JSON.parse(response.text);
};

