import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Quote, AuthorGroup, AuthorProfile } from './types';
import AuthorCard from './components/AuthorCard';
import AddQuoteModal from './components/AddQuoteModal';

const STORAGE_KEY = 'human-interaction-v2-logs';
const PROFILES_KEY = 'human-interaction-v2-profiles';

const App: React.FC = () => {
  const [quotes, setQuotes] = useState<Quote[]>([]);
  const [profiles, setProfiles] = useState<Record<string, AuthorProfile>>({});
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const savedQuotes = localStorage.getItem(STORAGE_KEY);
    const savedProfiles = localStorage.getItem(PROFILES_KEY);
    if (savedQuotes) {
      try {
        setQuotes(JSON.parse(savedQuotes));
      } catch (e) { console.error("Load quotes failed", e); }
    }
    if (savedProfiles) {
      try {
        setProfiles(JSON.parse(savedProfiles));
      } catch (e) { console.error("Load profiles failed", e); }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(quotes));
  }, [quotes]);

  useEffect(() => {
    localStorage.setItem(PROFILES_KEY, JSON.stringify(profiles));
  }, [profiles]);

  const addQuote = (newQuote: Quote) => {
    setQuotes(prev => [newQuote, ...prev]);
  };

  const updateQuote = (updatedQuote: Quote) => {
    setQuotes(prev => prev.map(q => q.id === updatedQuote.id ? updatedQuote : q));
  };

  const deleteQuote = (id: string) => {
    setQuotes(prev => prev.filter(q => q.id !== id));
  };

  const updateProfile = (author: string, profile: AuthorProfile | null) => {
    setProfiles(prev => {
      const next = { ...prev };
      if (profile === null) {
        delete next[author];
      } else {
        next[author] = profile;
      }
      return next;
    });
  };

  const handleExport = () => {
    const data = {
      quotes,
      profiles,
      exportedAt: new Date().toISOString()
    };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `human-logs-backup-${new Date().toISOString().split('T')[0]}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = JSON.parse(event.target?.result as string);
        if (data.quotes && Array.isArray(data.quotes)) {
          if (window.confirm('匯入將合併現有資料。確定要繼續嗎？')) {
            setQuotes(prev => {
              const existingIds = new Set(prev.map(q => q.id));
              const newQuotes = data.quotes.filter((q: Quote) => !existingIds.has(q.id));
              return [...newQuotes, ...prev].sort((a, b) => b.timestamp - a.timestamp);
            });
            if (data.profiles) {
              setProfiles(prev => ({ ...prev, ...data.profiles }));
            }
            alert('匯入成功！');
          }
        }
      } catch (e) {
        alert('匯入失敗，請檢查檔案格式。');
      }
    };
    reader.readAsText(file);
  };

  const existingAuthors = useMemo(() => {
    const authors = quotes.map(q => q.author);
    return Array.from(new Set(authors)).sort();
  }, [quotes]);

  const authorGroups = useMemo(() => {
    const groups: Record<string, AuthorGroup> = {};
    const filteredQuotes = quotes.filter(q => {
      const sText = searchQuery.toLowerCase();
      return q.content.toLowerCase().includes(sText) || 
             q.author.toLowerCase().includes(sText) || 
             q.tags.some(t => t.toLowerCase().includes(sText));
    });

    filteredQuotes.forEach(quote => {
      if (!groups[quote.author]) {
        groups[quote.author] = { 
          author: quote.author, 
          quotes: [], 
          lastUpdate: 0,
          profile: profiles[quote.author]
        };
      }
      groups[quote.author].quotes.push(quote);
      if (quote.timestamp > groups[quote.author].lastUpdate) {
        groups[quote.author].lastUpdate = quote.timestamp;
      }
    });

    return Object.values(groups).sort((a, b) => b.lastUpdate - a.lastUpdate);
  }, [quotes, searchQuery, profiles]);

  return (
    <div className="min-h-screen pb-24 selection:bg-indigo-100 selection:text-indigo-900">
      <header className="sticky top-0 z-40 transition-all duration-300 glass border-b border-slate-100">
        <div className="max-w-7xl mx-auto px-6 h-20 flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 bg-indigo-600 rounded-2xl flex items-center justify-center text-white shadow-xl shadow-indigo-200 transform hover:rotate-6 transition-transform">
              <svg className="w-7 h-7" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" />
              </svg>
            </div>
            <div className="hidden sm:block">
              <h1 className="text-xl font-black text-slate-800 tracking-tight leading-none">靈魂互動筆記</h1>
              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-[0.2em] mt-1.5">Dialectical Interaction logs</p>
            </div>
          </div>

          <div className="flex-1 max-w-md mx-8 hidden lg:block">
            <div className="relative group">
              <div className="relative flex items-center bg-white/50 border border-slate-200 rounded-2xl px-4 py-2.5 transition-all group-focus-within:bg-white group-focus-within:border-indigo-300">
                <svg className="w-4 h-4 text-slate-400 mr-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                </svg>
                <input
                  type="text"
                  placeholder="搜索內容、人物或心情標籤..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="bg-transparent border-none outline-none text-sm w-full placeholder:text-slate-300 font-medium"
                />
              </div>
            </div>
          </div>

          <div className="flex items-center gap-3">
            <button
              onClick={handleExport}
              title="備份資料"
              className="p-3 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-2xl transition-all"
            >
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1m-4-8l-4-4m0 0L8 8m4-4v12" />
              </svg>
            </button>
            <button
              onClick={() => fileInputRef.current?.click()}
              title="匯入備份"
              className="p-3 text-slate-400 hover:text-emerald-600 hover:bg-emerald-50 rounded-2xl transition-all"
            >
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
              </svg>
              <input type="file" ref={fileInputRef} onChange={handleImport} className="hidden" accept=".json" />
            </button>
            <button
              onClick={() => setIsModalOpen(true)}
              className="flex items-center gap-2.5 px-6 py-3 bg-indigo-600 text-white rounded-2xl font-bold hover:bg-indigo-700 shadow-xl shadow-indigo-100 transition-all transform hover:-translate-y-0.5 active:translate-y-0 active:scale-95"
            >
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4" />
              </svg>
              <span className="hidden sm:inline">紀錄互動</span>
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-6 py-12">
        {quotes.length === 0 && (
          <div className="max-w-2xl mx-auto py-20 text-center animate-float">
            <div className="w-32 h-32 bg-white rounded-[3rem] shadow-2xl flex items-center justify-center mx-auto mb-10 text-indigo-500 border border-indigo-50">
              <svg className="w-16 h-16" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z" />
              </svg>
            </div>
            <h2 className="text-3xl font-black text-slate-800 mb-4 tracking-tight">捕捉雙方邏輯的交會</h2>
            <p className="text-slate-400 text-lg font-medium leading-relaxed mb-12">
              透過紀錄，將隱晦的衝突轉化為明晰的辯證。
            </p>
            <button
              onClick={() => setIsModalOpen(true)}
              className="px-10 py-4 bg-white text-indigo-600 border-2 border-indigo-600 rounded-3xl font-black text-lg hover:bg-indigo-600 hover:text-white transition-all shadow-xl shadow-indigo-50"
            >
              開啟首篇紀錄
            </button>
          </div>
        )}

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {authorGroups.map(group => (
            <AuthorCard
              key={group.author}
              group={group}
              onUpdateQuote={updateQuote}
              onDeleteQuote={deleteQuote}
              onUpdateProfile={updateProfile}
            />
          ))}
        </div>
      </main>

      {isModalOpen && (
        <AddQuoteModal
          onAdd={addQuote}
          onClose={() => setIsModalOpen(false)}
          existingAuthors={existingAuthors}
        />
      )}
    </div>
  );
};

