import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Quote, AuthorGroup, AuthorProfile, AppDataBackup } from './types';
import AuthorCard from './components/AuthorCard';
import AddQuoteModal from './components/AddQuoteModal';

const STORAGE_KEY = 'human-logs-v3-quotes';
const PROFILES_KEY = 'human-logs-v3-profiles';
const APP_VERSION = '3.0.0';

const App: React.FC = () => {
  const [quotes, setQuotes] = useState<Quote[]>([]);
  const [profiles, setProfiles] = useState<Record<string, AuthorProfile>>({});
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [isSyncing, setIsSyncing] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const savedQuotes = localStorage.getItem(STORAGE_KEY);
    const savedProfiles = localStorage.getItem(PROFILES_KEY);
    if (savedQuotes) {
      try {
        const parsed = JSON.parse(savedQuotes);
        setQuotes(Array.isArray(parsed) ? parsed : []);
      } catch (e) { console.error("Restore failed", e); }
    }
    if (savedProfiles) {
      try {
        setProfiles(JSON.parse(savedProfiles));
      } catch (e) { console.error("Restore profiles failed", e); }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(quotes));
  }, [quotes]);

  useEffect(() => {
    localStorage.setItem(PROFILES_KEY, JSON.stringify(profiles));
  }, [profiles]);

  const addQuote = (newQuote: Quote) => {
    setQuotes(prev => [newQuote, ...prev]);
  };

  const updateQuote = (updatedQuote: Quote) => {
    setQuotes(prev => prev.map(q => q.id === updatedQuote.id ? updatedQuote : q));
  };

  const deleteQuote = (id: string) => {
    setQuotes(prev => prev.filter(q => q.id !== id));
  };

  const updateProfile = (author: string, profile: AuthorProfile | null) => {
    setProfiles(prev => {
      const next = { ...prev };
      if (profile === null) delete next[author];
      else next[author] = profile;
      return next;
    });
  };

  const handleExport = () => {
    const data: AppDataBackup = { version: APP_VERSION, quotes, profiles, exportedAt: new Date().toISOString() };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `human-obs-v3-${new Date().toISOString().split('T')[0]}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleCopyBackup = async () => {
    const data: AppDataBackup = { version: APP_VERSION, quotes, profiles, exportedAt: new Date().toISOString() };
    const base64Data = btoa(encodeURIComponent(JSON.stringify(data)));
    await navigator.clipboard.writeText(base64Data);
    alert('備份代碼已複製到剪貼簿！您可以到另一台裝置貼上匯入。');
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data: AppDataBackup = JSON.parse(event.target?.result as string);
        processImportData(data);
      } catch (e) { alert('匯入失敗：檔案格式錯誤。'); }
    };
    reader.readAsText(file);
  };

  const processImportData = (data: AppDataBackup) => {
    if (data.quotes && Array.isArray(data.quotes)) {
      if (window.confirm(`發現 ${data.quotes.length} 條紀錄。確定要合併到現有資料庫嗎？`)) {
        setQuotes(prev => {
          const existingIds = new Set(prev.map(q => q.id));
          const newOnes = data.quotes.filter(q => !existingIds.has(q.id));
          return [...newOnes, ...prev].sort((a, b) => b.timestamp - a.timestamp);
        });
        if (data.profiles) setProfiles(prev => ({ ...prev, ...data.profiles }));
        alert('同步完成！');
      }
    }
  };

  const stats = useMemo(() => ({
    total: quotes.length,
    weirdest: quotes.reduce((max, q) => Math.max(max, q.aiAnalysis?.weirdnessIndex || 0), 0),
    authorsCount: new Set(quotes.map(q => q.author)).size
  }), [quotes]);

  const filteredGroups = useMemo(() => {
    const s = searchQuery.toLowerCase();
    const filtered = quotes.filter(q => 
      q.content.toLowerCase().includes(s) || 
      q.author.toLowerCase().includes(s) || 
      q.tags.some(t => t.toLowerCase().includes(s)) ||
      q.aiAnalysis?.insight.toLowerCase().includes(s) ||
      q.aiAnalysis?.dynamic.toLowerCase().includes(s)
    );

    const groups: Record<string, AuthorGroup> = {};
    filtered.forEach(q => {
      if (!groups[q.author]) groups[q.author] = { author: q.author, quotes: [], lastUpdate: 0, profile: profiles[q.author] };
      groups[q.author].quotes.push(q);
      if (q.timestamp > groups[q.author].lastUpdate) groups[q.author].lastUpdate = q.timestamp;
    });

    return Object.values(groups).sort((a, b) => b.lastUpdate - a.lastUpdate);
  }, [quotes, searchQuery, profiles]);

  const existingAuthors = useMemo(() => Array.from(new Set(quotes.map(q => q.author))).sort(), [quotes]);

  return (
    <div className="min-h-screen bg-[#FDFCFE] selection:bg-purple-100 selection:text-purple-900 pb-20">
      <header className="sticky top-0 z-40 glass border-b border-purple-50 shadow-sm">
        <div className="max-w-7xl mx-auto px-6 h-20 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-gradient-to-br from-purple-500 to-indigo-600 rounded-xl flex items-center justify-center text-white shadow-lg">
              <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 24 24">
                <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm1 15h-2v-2h2v2zm0-4h-2V7h2v6z"/>
              </svg>
            </div>
            <div className="hidden md:block">
              <h1 className="text-lg font-black text-slate-800 tracking-tight">人類觀察日誌</h1>
              <div className="flex gap-4 text-[9px] font-bold text-slate-400 uppercase tracking-widest mt-0.5">
                <span>Total: {stats.total}</span>
                <span className="text-purple-500">Peak Weirdness: {stats.weirdest}</span>
              </div>
            </div>
          </div>

          <div className="flex-1 max-w-md mx-6">
            <div className="relative group">
              <input
                type="text"
                placeholder="探索辯證核心、怪語或對象..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full bg-purple-50/50 border border-transparent focus:bg-white focus:border-purple-200 rounded-2xl px-10 py-2.5 text-sm outline-none transition-all"
              />
              <svg className="absolute left-3 top-3 w-4 h-4 text-purple-300" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
              </svg>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <div className="hidden sm:flex items-center bg-white border border-slate-100 rounded-2xl p-1 gap-1">
              <button onClick={handleExport} className="p-2 text-slate-400 hover:text-purple-600 hover:bg-purple-50 rounded-xl transition-all" title="匯出檔案">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>
              </button>
              <button onClick={handleCopyBackup} className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-xl transition-all" title="複製備份代碼">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 16H6a2 2 0 01-2-2V6a2 2 0 012-2h8a2 2 0 012 2v2m-6 12h8a2 2 0 002-2v-8a2 2 0 00-2-2h-8a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg>
              </button>
              <button onClick={() => fileInputRef.current?.click()} className="p-2 text-slate-400 hover:text-emerald-600 hover:bg-emerald-50 rounded-xl transition-all" title="從檔案匯入">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
              </button>
            </div>
            <input type="file" ref={fileInputRef} onChange={handleImport} className="hidden" accept=".json" />
            <button
              onClick={() => setIsModalOpen(true)}
              className="bg-slate-900 text-white px-5 py-2.5 rounded-2xl font-bold text-sm hover:bg-purple-600 transition-all flex items-center gap-2 shadow-lg shadow-purple-100"
            >
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4" /></svg>
              <span className="hidden lg:inline">新紀錄</span>
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-6 py-10">
        {quotes.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-32 animate-float">
            <div className="w-24 h-24 bg-white rounded-[2.5rem] shadow-2xl flex items-center justify-center text-purple-200 mb-6 border border-purple-50">
              <svg className="w-12 h-12" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg>
            </div>
            <h2 className="text-2xl font-black text-slate-800">開始觀察這個世界</h2>
            <p className="text-slate-400 mt-2">記錄下那些讓你困惑、發笑或深思的怪言怪語。</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {filteredGroups.map(group => (
              <AuthorCard
                key={group.author}
                group={group}
                onUpdateQuote={updateQuote}
                onDeleteQuote={deleteQuote}
                onUpdateProfile={updateProfile}
              />
            ))}
          </div>
        )}
      </main>

      {isModalOpen && (
        <AddQuoteModal onAdd={addQuote} onClose={() => setIsModalOpen(false)} existingAuthors={existingAuthors} />
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Quote } from '../types';
import { analyzeQuote } from '../services/geminiService';

interface QuoteItemProps {
  quote: Quote;
  onUpdate: (updatedQuote: Quote) => void;
  onDelete: (id: string) => void;
}

const QuoteItem: React.FC<QuoteItemProps> = ({ quote, onUpdate, onDelete }) => {
  const [loading, setLoading] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editContent, setEditContent] = useState(quote.content);
  const [editDate, setEditDate] = useState(quote.observationDate);

  const handleAIAnalyze = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setLoading(true);
    try {
      const analysis = await analyzeQuote(quote.content, quote.author, quote.observationDate);
      onUpdate({ ...quote, aiAnalysis: analysis });
    } catch (error) {
      console.error("AI Analysis failed", error);
    } finally {
      setLoading(false);
    }
  };

  const handleSaveEdit = (e: React.MouseEvent) => {
    e.stopPropagation();
    onUpdate({ ...quote, content: editContent, observationDate: editDate });
    setIsEditing(false);
  };

  const handleDeleteClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (window.confirm('確定要永久刪除這段紀錄嗎？')) onDelete(quote.id);
  };

  return (
    <div className="group/item py-6 border-b border-slate-50 last:border-none transition-all relative">
      <div className="flex justify-between items-start gap-4">
        <div className="flex-1">
          {isEditing ? (
            <div className="space-y-3 bg-white p-4 rounded-2xl border border-purple-100 shadow-sm">
              <input 
                type="date" 
                value={editDate}
                onChange={(e) => setEditDate(e.target.value)}
                className="text-[10px] font-bold text-slate-600 bg-slate-50 border-none rounded-lg px-3 py-1.5 outline-none"
              />
              <textarea 
                value={editContent}
                onChange={(e) => setEditContent(e.target.value)}
                className="w-full text-sm font-medium text-slate-800 bg-slate-50 border-none rounded-xl p-3 outline-none focus:ring-2 focus:ring-purple-200 min-h-[100px] resize-none"
              />
              <div className="flex gap-2">
                <button onClick={handleSaveEdit} className="px-4 py-2 bg-slate-900 text-white text-xs font-bold rounded-xl hover:bg-purple-600">保存修改</button>
                <button onClick={() => setIsEditing(false)} className="px-4 py-2 bg-slate-100 text-slate-500 text-xs font-bold rounded-xl hover:bg-slate-200">取消</button>
              </div>
            </div>
          ) : (
            <>
              <div className="flex items-center gap-3 mb-2 text-[10px] font-bold text-slate-400 uppercase tracking-tighter">
                <span className="flex items-center gap-1">
                  <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                  {quote.observationDate}
                </span>
                {quote.aiAnalysis && (
                  <span className="px-2 py-0.5 bg-rose-50 text-rose-500 rounded-md border border-rose-100/50">
                    怪異指數 {quote.aiAnalysis.weirdnessIndex}.0
                  </span>
                )}
              </div>
              <p className="text-base font-semibold text-slate-800 leading-relaxed mb-3 group-hover/item:text-purple-900 transition-colors">
                {quote.content}
              </p>
            </>
          )}
        </div>

        {!isEditing && (
          <div className="flex flex-col gap-1 opacity-0 group-hover/item:opacity-100 transition-all">
            <button onClick={() => setIsEditing(true)} className="p-2 text-slate-300 hover:text-purple-600 hover:bg-purple-50 rounded-lg transition-colors"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" /></svg></button>
            <button onClick={handleDeleteClick} className="p-2 text-slate-300 hover:text-rose-600 hover:bg-rose-50 rounded-lg transition-colors"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg></button>
          </div>
        )}
      </div>

      {!isEditing && (
        quote.aiAnalysis ? (
          <div className="mt-4 space-y-4 animate-in fade-in slide-in-from-top-1 duration-300">
            <div className="bg-slate-900 rounded-2xl p-4 shadow-xl border border-white/10 relative">
              <div className="flex items-center justify-between mb-2">
                <span className="text-[10px] font-black text-purple-400 uppercase tracking-[0.2em]">辯證核心：{quote.aiAnalysis.dynamic}</span>
              </div>
              <p className="text-sm leading-relaxed text-slate-300 font-light mb-2">
                {quote.aiAnalysis.insight}
              </p>
            </div>

            <div className="grid grid-cols-2 gap-2">
              <div className="bg-emerald-50/50 rounded-xl p-3 border border-emerald-100/50">
                <span className="text-[9px] font-bold text-emerald-600 block mb-1 uppercase tracking-wider">我方觀點 (正方)</span>
                <ul className="space-y-1">
                  {quote.aiAnalysis.selfView?.map((p, i) => <li key={i} className="text-[10px] text-emerald-800/70 leading-tight">• {p}</li>)}
                </ul>
              </div>
              <div className="bg-rose-50/50 rounded-xl p-3 border border-rose-100/50">
                <span className="text-[9px] font-bold text-rose-600 block mb-1 uppercase tracking-wider">對方觀點 (反方)</span>
                <ul className="space-y-1">
                  {quote.aiAnalysis.otherView?.map((p, i) => <li key={i} className="text-[10px] text-rose-800/70 leading-tight">• {p}</li>)}
                </ul>
              </div>
            </div>
          </div>
        ) : (
          <button
            onClick={handleAIAnalyze}
            disabled={loading}
            className="mt-3 w-full py-3 bg-white border border-slate-100 text-slate-400 rounded-xl text-[10px] font-bold hover:text-purple-600 hover:border-purple-200 transition-all flex items-center justify-center gap-2 group/btn"
          >
            {loading ? <div className="w-3 h-3 border-2 border-purple-500 border-t-transparent rounded-full animate-spin"></div> : '⚖️ 啟動雙方觀點辯證'}
          </button>
        )
      )}
    </div>
  );
};

