                </span>
                <ul className="space-y-1.5">
                  {quote.aiAnalysis.selfView?.map((p, i) => <li key={i} className="text-[11px] text-emerald-800/70 leading-tight">• {p}</li>)}
                </ul>
              </div>
              <div className="bg-rose-50/50 rounded-2xl p-4 border border-rose-100/50">
                <span className="text-[10px] font-bold text-rose-600 block mb-2 uppercase tracking-wider flex items-center gap-1.5">
                  <div className="w-1.5 h-1.5 rounded-full bg-rose-400"></div>
                  對方觀點 (反方)
                </span>
                <ul className="space-y-1.5">
                  {quote.aiAnalysis.otherView?.map((p, i) => <li key={i} className="text-[11px] text-rose-800/70 leading-tight">• {p}</li>)}
                </ul>
              </div>
            </div>
          </div>
        ) : (
