            onClick={handleAIAnalyze}
            disabled={loading}
            className="mt-3 w-full py-3 bg-white border border-purple-50 text-slate-400 rounded-full text-[10px] font-bold hover:text-indigo-600 hover:border-indigo-100 transition-all flex items-center justify-center gap-2 group/btn"
          >
            {loading ? <div className="w-3 h-3 border-2 border-indigo-500 border-t-transparent rounded-full animate-spin"></div> : '⚖️ 啟動立場辯證分析'}
          </button>
