import { GoogleGenAI, Type } from "@google/genai";
import { AIAnalysis, AuthorProfile, Quote } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * 系統化整理：不再生成報告，而是基於原文進行「文字增益」與「流暢度潤飾」。
 */
export const refineNarrative = async (rawContent: string): Promise<string> => {
  const prompt = `你是一位擅長捕捉人類細微情緒的「文字精煉師」。

  任務：將以下這段粗糙的「人類觀察紀錄」進行潤飾。

  要求：
  1. **絕對不要** 寫成報告、分析或總結格式。不要出現「背景、結果、觀察」等標題。
  2. **保留靈魂**：嚴格保留原文中所有古怪、有趣、或令人困惑的「怪言怪語」原始詞彙。
  3. **優化流暢度**：僅修正語序、補足省略的脈絡，讓這段紀錄讀起來更有畫面感與敘事張力。
  4. **字數適中**：長度應與原文相仿，僅做質感的提升。

  原始紀錄內容：
  """
  ${rawContent}
  """`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: { 
