import React, { useState } from 'react';
import { AuthorGroup, Quote, AuthorProfile } from '../types';
import QuoteItem from './QuoteItem';
import ProfileModal from './ProfileModal';
import { generateAuthorProfile } from '../services/geminiService';

interface AuthorCardProps {
  group: AuthorGroup;
  onUpdateQuote: (updatedQuote: Quote) => void;
  onDeleteQuote: (id: string) => void;
  onUpdateProfile: (author: string, profile: AuthorProfile | null) => void;
}

const AuthorCard: React.FC<AuthorCardProps> = ({ group, onUpdateQuote, onDeleteQuote, onUpdateProfile }) => {
  const [isGeneratingProfile, setIsGeneratingProfile] = useState(false);
  const [showProfile, setShowProfile] = useState(false);

  const authorInitial = group.author.charAt(0).toUpperCase();
  const avatarColors = [
    'from-indigo-100 to-indigo-200 text-indigo-600 shadow-indigo-100/50',
    'from-emerald-100 to-emerald-200 text-emerald-600 shadow-emerald-100/50',
    'from-rose-100 to-rose-200 text-rose-600 shadow-rose-100/50',
    'from-amber-100 to-amber-200 text-amber-600 shadow-amber-100/50',
    'from-purple-100 to-purple-200 text-purple-600 shadow-purple-100/50'
  ];
  const colorIndex = group.author.length % avatarColors.length;

  const handleGenerateProfile = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setIsGeneratingProfile(true);
    try {
      const profile = await generateAuthorProfile(group.author, group.quotes);
      onUpdateProfile(group.author, profile);
      setShowProfile(true);
    } catch (error) {
      console.error("Failed", error);
    } finally {
      setIsGeneratingProfile(false);
    }
  };

  const handleResetProfile = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (window.confirm(`重置 ${group.author} 的人物誌？`)) onUpdateProfile(group.author, null);
  };

  const sortedQuotes = [...group.quotes].sort((a, b) => b.timestamp - a.timestamp);

  return (
    <div className="bg-white rounded-[2.5rem] shadow-sm border border-purple-50 overflow-hidden flex flex-col h-full hover:shadow-xl hover:shadow-purple-100/20 transition-all duration-500">
      <div className="p-8 pb-4">
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center gap-4">
            <div className={`w-14 h-14 rounded-2xl flex items-center justify-center font-black text-xl bg-gradient-to-br shadow-lg ${avatarColors[colorIndex]}`}>
              {authorInitial}
            </div>
            <div>
              <h3 className="text-xl font-black text-slate-800 tracking-tight">{group.author}</h3>
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-0.5">觀察樣本 #{group.quotes.length}</p>
            </div>
          </div>

          <div className="flex flex-col gap-1 items-end relative z-10">
            <button 
              onClick={group.profile ? (e) => { e.stopPropagation(); setShowProfile(true); } : handleGenerateProfile}
              disabled={isGeneratingProfile}
              className={`px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-widest transition-all shadow-md ${
                group.profile 
                ? 'bg-slate-900 text-white hover:bg-slate-800' 
                : 'bg-indigo-50 text-indigo-500 hover:bg-indigo-100'
              }`}
            >
              {isGeneratingProfile ? '分析中...' : group.profile ? '人物誌' : '分析特質'}
            </button>
            {group.profile && (
              <button onClick={handleResetProfile} className="text-[8px] font-bold text-slate-300 hover:text-rose-400 uppercase tracking-widest px-2">重置資料</button>
            )}
          </div>
        </div>

        {group.profile && (
          <div className="bg-indigo-50/50 rounded-[1.5rem] p-4 border border-indigo-100/30 mb-4">
            <span className="text-[9px] font-black text-indigo-400 uppercase tracking-[0.2em] block mb-1">人物原型</span>
            <p className="text-xs font-bold text-slate-700 italic leading-relaxed">
              「{group.profile.characterType}」
            </p>
          </div>
        )}
      </div>

      <div className="flex-1 overflow-y-auto max-h-[500px] px-8 pb-8 space-y-3 custom-scrollbar">
        {sortedQuotes.map(quote => (
          <QuoteItem key={quote.id} quote={quote} onUpdate={onUpdateQuote} onDelete={onDeleteQuote} />
        ))}
      </div>

      <div className="px-8 py-5 bg-slate-50 border-t border-purple-50/50 flex justify-between items-center">
        <div className="flex items-center gap-1.5">
          <div className="w-1.5 h-1.5 rounded-full bg-emerald-400"></div>
          <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">資料已加密儲存</span>
        </div>
        <p className="text-[10px] font-mono text-slate-400">
          SEQ_{group.quotes.length.toString().padStart(3, '0')}
        </p>
      </div>

      {showProfile && group.profile && (
        <ProfileModal author={group.author} profile={group.profile} onClose={() => setShowProfile(false)} />
      )}
    </div>
  );
};

