export const refineNarrative = async (rawContent: string): Promise<string> => {
  try {
    const ai = getAIInstance();
    const prompt = `你是一位專業的「文字整理員」。

    任務：將以下這段斷斷續續、較為口語的人類觀察紀錄整理成一段順暢、邏輯清晰的文字。

    要求：
    1. **保持平實**：不要添加任何文學修飾、形容詞或感性的張力。
    2. **邏輯理順**：修正斷斷續續的語序，補足語法上的缺失，讓紀錄讀起來通順且有條理。
