import React, { useState } from 'react';
import { Quote } from '../types';
import { refineNarrative } from '../services/geminiService';

interface AddQuoteModalProps {
  onAdd: (quote: Quote) => void;
  onClose: () => void;
  existingAuthors: string[];
}

const AddQuoteModal: React.FC<AddQuoteModalProps> = ({ onAdd, onClose, existingAuthors }) => {
  const [content, setContent] = useState('');
  const [author, setAuthor] = useState('');
  const [observationDate, setObservationDate] = useState(new Date().toISOString().split('T')[0]);
  const [tags, setTags] = useState('');
  const [isRefining, setIsRefining] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!content || !author) return;

    const newQuote: Quote = {
      id: Date.now().toString(),
      content,
      author: author.trim(),
      observationDate,
      timestamp: Date.now(),
      tags: tags.split(',').map(t => t.trim()).filter(t => t !== ''),
    };

    onAdd(newQuote);
    onClose();
  };

  const handleRefine = async () => {
    if (!content.trim() || isRefining) return;
    setIsRefining(true);
    try {
      const refined = await refineNarrative(content);
      if (refined === content) {
        alert('AI 認為目前語句已足夠通順，無需調整。');
      }
      setContent(refined);
    } catch (error) {
      console.error("AI 順稿失敗詳細資訊:", error);
      alert('AI 順稿失敗。請檢查 API Key 是否正確設定，並查看控制台 (F12) 報錯訊息。');
    } finally {
      setIsRefining(false);
    }
  };

  const selectExistingAuthor = (name: string) => {
    setAuthor(name);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
      <div className="bg-white rounded-[2rem] w-full max-w-lg shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-200">
        <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-indigo-50/30">
          <div>
            <h2 className="text-2xl font-bold text-slate-800">紀錄這段互動</h2>
            <p className="text-xs text-slate-400 mt-1 uppercase tracking-widest font-bold">Log Interaction Event</p>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-white rounded-full transition-colors text-slate-400">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-5">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">發生日期</label>
              <input
                type="date"
                required
                value={observationDate}
                onChange={(e) => setObservationDate(e.target.value)}
                className="w-full px-4 py-3 rounded-2xl border border-slate-100 bg-slate-50 focus:bg-white focus:ring-2 focus:ring-indigo-500 outline-none transition-all text-sm"
              />
            </div>
            <div className="relative">
              <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">對象名稱</label>
              <input
                type="text"
                required
                list="existing-authors"
                value={author}
                onChange={(e) => setAuthor(e.target.value)}
                autoComplete="off"
                className="w-full px-4 py-3 rounded-2xl border border-slate-100 bg-slate-50 focus:bg-white focus:ring-2 focus:ring-indigo-500 outline-none transition-all text-sm"
                placeholder="例如：母親、老闆..."
              />
              <datalist id="existing-authors">
                {existingAuthors.map(name => (
                  <option key={name} value={name} />
                ))}
              </datalist>

              {existingAuthors.length > 0 && (
                <div className="mt-2 flex flex-wrap gap-1.5 max-h-16 overflow-y-auto custom-scrollbar">
                  {existingAuthors.slice(0, 5).map(name => (
                    <button
                      key={name}
                      type="button"
                      onClick={() => selectExistingAuthor(name)}
                      className={`text-[9px] font-bold px-2 py-1 rounded-lg border transition-all ${
                        author === name 
                        ? 'bg-indigo-600 border-indigo-600 text-white' 
                        : 'bg-indigo-50 border-indigo-100 text-indigo-500 hover:border-indigo-300'
                      }`}
                    >
                      {name}
                    </button>
                  ))}
                </div>
              )}
            </div>
          </div>

          <div>
            <div className="flex justify-between items-center mb-2">
              <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider">發生了什麼事？</label>
              <button
                type="button"
                onClick={handleRefine}
                disabled={isRefining || !content.trim()}
                className={`text-[10px] font-bold flex items-center gap-1.5 px-3 py-1 rounded-full transition-all ${
                  isRefining 
                  ? 'bg-indigo-100 text-indigo-400' 
                  : 'bg-indigo-50 text-indigo-600 hover:bg-indigo-600 hover:text-white border border-indigo-100'
                } disabled:opacity-40 disabled:cursor-not-allowed`}
              >
                {isRefining ? (
                  <>
                    <div className="w-2 h-2 border-2 border-indigo-400 border-t-transparent rounded-full animate-spin"></div>
                    正在理順語句...
                  </>
                ) : (
                  <>
                    <span>✨</span> AI 語句順稿
                  </>
                )}
              </button>
            </div>
            <textarea
              required
              value={content}
              onChange={(e) => setContent(e.target.value)}
              className="w-full px-4 py-3 rounded-2xl border border-slate-100 bg-slate-50 focus:bg-white focus:ring-2 focus:ring-indigo-500 outline-none transition-all h-32 resize-none text-sm leading-relaxed"
              placeholder="例如：他今天突然誇獎了我的工作成果，但我感覺到他眼神有一絲疲憊。"
            />
          </div>

          <div>
            <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">心情標籤 (逗號隔開)</label>
            <input
              type="text"
              value={tags}
              onChange={(e) => setTags(e.target.value)}
              className="w-full px-4 py-3 rounded-2xl border border-slate-100 bg-slate-50 focus:bg-white focus:ring-2 focus:ring-indigo-500 outline-none transition-all text-sm"
              placeholder="例如：意外, 暖心, 複雜"
            />
          </div>

          <button
            type="submit"
            className="w-full py-4 bg-slate-900 text-white rounded-2xl font-bold text-lg hover:bg-indigo-600 shadow-xl shadow-slate-200 transition-all transform active:scale-[0.98] mt-4"
          >
            保存這段記憶
          </button>
        </form>
      </div>
    </div>
  );
};

