import React, { useState } from 'react';
import { Quote } from '../types';
import { analyzeQuote } from '../services/geminiService';

interface QuoteItemProps {
  quote: Quote;
  onUpdate: (updatedQuote: Quote) => void;
  onDelete: (id: string) => void;
}

const QuoteItem: React.FC<QuoteItemProps> = ({ quote, onUpdate, onDelete }) => {
  const [loading, setLoading] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editContent, setEditContent] = useState(quote.content);
  const [editDate, setEditDate] = useState(quote.observationDate);

  const handleAIAnalyze = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setLoading(true);
    try {
      const analysis = await analyzeQuote(quote.content, quote.author, quote.observationDate);
      onUpdate({ ...quote, aiAnalysis: analysis });
    } catch (error) {
      console.error("AI Analysis 失敗:", error);
      alert('AI 分析失敗，請檢查網路連線或稍後再試。');
    } finally {
      setLoading(false);
    }
  };

  const handleSaveEdit = (e: React.MouseEvent) => {
    e.stopPropagation();
    onUpdate({ ...quote, content: editContent, observationDate: editDate });
    setIsEditing(false);
  };

  const handleDeleteClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (window.confirm('確定要永久刪除這段紀錄嗎？')) onDelete(quote.id);
  };

  const getWeirdnessLabel = (score: number) => {
    if (score <= 2) return { label: '平淡無奇', color: 'bg-emerald-100 text-emerald-600', bar: 'bg-emerald-400' };
    if (score <= 4) return { label: '微微出戲', color: 'bg-blue-100 text-blue-600', bar: 'bg-blue-400' };
    if (score <= 6) return { label: '奇思妙想', color: 'bg-amber-100 text-amber-600', bar: 'bg-amber-400' };
    if (score <= 8) return { label: '人類奇行', color: 'bg-orange-100 text-orange-600', bar: 'bg-orange-400' };
    return { label: '邏輯崩壞', color: 'bg-rose-100 text-rose-600', bar: 'bg-rose-400' };
  };

  const weirdness = quote.aiAnalysis ? getWeirdnessLabel(quote.aiAnalysis.weirdnessIndex) : null;

  return (
    <div className="group/item py-6 border-b border-purple-50/50 last:border-none relative">
      <div className="flex justify-between items-start gap-4">
        <div className="flex-1">
          {isEditing ? (
            <div className="space-y-3 bg-white p-4 rounded-3xl border border-purple-100 shadow-sm">
              <input 
                type="date" 
                value={editDate}
                onChange={(e) => setEditDate(e.target.value)}
                className="text-xs font-bold text-slate-500 bg-purple-50/50 border-none rounded-full px-4 py-2 outline-none w-auto"
              />
              <textarea 
                value={editContent}
                onChange={(e) => setEditContent(e.target.value)}
                className="w-full text-sm font-medium text-slate-800 bg-purple-50/50 border-none rounded-2xl p-4 outline-none focus:ring-2 focus:ring-purple-200 min-h-[100px] resize-none"
              />
              <div className="flex gap-2">
                <button onClick={handleSaveEdit} className="px-5 py-2 bg-slate-900 text-white text-xs font-bold rounded-full hover:bg-slate-800">保存</button>
                <button onClick={() => setIsEditing(false)} className="px-5 py-2 bg-slate-100 text-slate-500 text-xs font-bold rounded-full hover:bg-slate-200">取消</button>
              </div>
            </div>
          ) : (
            <>
              <div className="flex items-center gap-3 mb-2">
                <span className="px-3 py-1 bg-purple-50 text-purple-400 text-[10px] font-bold rounded-full border border-purple-100/50">
                  {quote.observationDate}
                </span>
                {weirdness && (
                  <div className="flex items-center gap-2">
                    <span className={`px-3 py-1 ${weirdness.color} text-[10px] font-black rounded-full border border-current/10 uppercase tracking-widest`}>
                      {weirdness.label}
                    </span>
                    <div className="w-16 h-1.5 bg-slate-100 rounded-full overflow-hidden">
                      <div 
                        className={`h-full ${weirdness.bar} transition-all duration-1000`} 
                        style={{ width: `${(quote.aiAnalysis?.weirdnessIndex || 0) * 10}%` }}
                      ></div>
                    </div>
                  </div>
                )}
              </div>
              <p className="text-base font-bold text-slate-800 leading-relaxed mb-3">
                {quote.content}
              </p>
            </>
          )}
        </div>

        {!isEditing && (
          <div className="flex flex-col gap-1 opacity-0 group-hover/item:opacity-100 transition-all">
            <button onClick={() => setIsEditing(true)} className="p-2 text-slate-300 hover:text-slate-600 hover:bg-purple-50 rounded-full transition-colors"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" /></svg></button>
            <button onClick={handleDeleteClick} className="p-2 text-slate-300 hover:text-rose-600 hover:bg-rose-50 rounded-full transition-colors"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg></button>
          </div>
        )}
      </div>

      {!isEditing && (
        quote.aiAnalysis ? (
          <div className="mt-4 space-y-3">
            <div className="bg-slate-900 rounded-[1.5rem] p-4 shadow-lg border border-white/5">
              <span className="text-[9px] font-black text-indigo-400 uppercase tracking-widest block mb-1">💡 辯證洞察：{quote.aiAnalysis.dynamic}</span>
              <p className="text-sm leading-relaxed text-slate-200 font-light">
                {quote.aiAnalysis.insight}
              </p>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
              <div className="bg-emerald-50/50 rounded-2xl p-4 border border-emerald-100/50">
                <span className="text-[10px] font-bold text-emerald-600 block mb-2 uppercase tracking-wider flex items-center gap-1.5">
                  <div className="w-1.5 h-1.5 rounded-full bg-emerald-400"></div>
                  我方邏輯
                </span>
