import { GoogleGenAI, Type } from "@google/genai";
import { AIAnalysis, AuthorProfile, Quote } from "../types";

/**
 * 語句順稿 - 使用 Flash 模型處理簡單文字任務
 */
export const refineNarrative = async (rawContent: string): Promise<string> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `請將這段零碎的口語觀察紀錄整理成通順且平實的繁體中文文字：\n\n"""\n${rawContent}\n"""`,
      config: { 
        temperature: 0.2,
      }
    });
    return response.text?.trim() || rawContent;
  } catch (error) {
    console.error("Gemini refineNarrative 失敗:", error);
    throw error;
  }
};

/**
 * 雙方立場辯證分析 - 使用 Pro 模型處理複雜推理任務
 */
export const analyzeQuote = async (content: string, author: string, observationDate: string): Promise<AIAnalysis> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `你是一個冷靜的人類行為觀察學家。
請分析這段對話/互動。對象: ${author}，發生於: ${observationDate}。
內容: 「${content}」

請分析雙方（我方與${author}）潛在的邏輯立場，判斷這段文字背後的情感傾向（正面、負面、或中性），並給出一個精闢的觀察。
請用繁體中文回答。`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        thinkingConfig: { thinkingBudget: 4000 },
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            resonanceScore: { type: Type.NUMBER, description: "衝突張力指數 (1-10)" },
            weirdnessIndex: { type: Type.NUMBER, description: "怪異驚訝指數 (1-10)" },
            sentiment: { 
              type: Type.STRING, 
              enum: ['positive', 'negative', 'neutral'],
              description: "情感傾向" 
            },
            sentimentLabel: { 
              type: Type.STRING, 
              description: "簡短的情感形容詞 (例如：溫馨、尷尬、諷刺、挑釁)" 
            },
            insight: { type: Type.STRING, description: "一句話的犀利洞察" },
            dynamic: { type: Type.STRING, description: "互動關係的分類標籤" },
            selfView: { type: Type.ARRAY, items: { type: Type.STRING }, description: "我方當時可能的內心邏輯" },
            otherView: { type: Type.ARRAY, items: { type: Type.STRING }, description: "對方當時可能的內心邏輯" },
            suggestedTags: { type: Type.ARRAY, items: { type: Type.STRING }, description: "建議的 3 個標籤" }
          },
          required: ["resonanceScore", "weirdnessIndex", "sentiment", "sentimentLabel", "insight", "dynamic", "selfView", "otherView", "suggestedTags"]
        }
      }
    });

    const data = JSON.parse(response.text?.trim() || "{}");
    return { ...data, analyzedAt: Date.now() };
  } catch (error) {
    console.error("Gemini analyzeQuote 失敗:", error);
    throw error;
  }
};

/**
 * 歸納行為模式 - 使用 Pro 模型生成深度人物誌
 */
export const generateAuthorProfile = async (author: string, quotes: Quote[]): Promise<AuthorProfile> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const history = quotes.map(q => `[${q.observationDate}] ${q.content}`).join('\n');
    const prompt = `根據以下關於 "${author}" 的多筆觀察紀錄，分析其人格特質、行為模式與建議的相處之道。
請用繁體中文回答。

紀錄列表：
${history}`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        thinkingConfig: { thinkingBudget: 8000 },
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            characterType: { type: Type.STRING, description: "人物原型名稱 (例如: 隱性控制者)" },
            traits: { type: Type.ARRAY, items: { type: Type.STRING }, description: "三個核心特徵" },
            relationshipPhase: { type: Type.STRING, description: "目前關係的階段描述" },
            interactionGuide: { type: Type.STRING, description: "建議的互動指南" },
            summary: { type: Type.STRING, description: "完整的人格特質總結" }
          },
          required: ["characterType", "traits", "relationshipPhase", "interactionGuide", "summary"]
        }
      }
    });

    return { ...JSON.parse(response.text?.trim() || "{}"), lastUpdated: Date.now() };
  } catch (error) {
    console.error("Gemini generateAuthorProfile 失敗:", error);
    throw error;
  }
};

