import React, { useState } from 'react';
import { Quote, AIAnalysis } from '../types';
import { analyzeQuote } from '../services/geminiService';

interface QuoteItemProps {
  quote: Quote;
  onUpdate: (updatedQuote: Quote) => void;
  onDelete: (id: string) => void;
}

const QuoteItem: React.FC<QuoteItemProps> = ({ quote, onUpdate, onDelete }) => {
  const [loading, setLoading] = useState(false);
  const [isExpanded, setIsExpanded] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editContent, setEditContent] = useState(quote.content);
  const [editDate, setEditDate] = useState(quote.observationDate);

  const handleAIAnalyze = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setLoading(true);
    try {
      const analysis = await analyzeQuote(quote.content, quote.author, quote.observationDate);
      onUpdate({ ...quote, aiAnalysis: analysis });
      setIsExpanded(true); // 分析後自動展開
    } catch (error) {
      console.error("AI Analysis 失敗:", error);
      alert('AI 分析失敗，請檢查網路連線或稍後再試。');
    } finally {
      setLoading(false);
    }
  };

  const handleSaveEdit = (e: React.MouseEvent) => {
    e.stopPropagation();
    onUpdate({ ...quote, content: editContent, observationDate: editDate });
    setIsEditing(false);
  };

  const handleDeleteClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (window.confirm('確定要永久刪除這段紀錄嗎？')) onDelete(quote.id);
  };

  const getWeirdnessLabel = (score: number) => {
    if (score <= 2) return { label: '平淡', color: 'bg-emerald-100 text-emerald-600' };
    if (score <= 5) return { label: '微怪', color: 'bg-blue-100 text-blue-600' };
    if (score <= 8) return { label: '奇行', color: 'bg-orange-100 text-orange-600' };
    return { label: '崩壞', color: 'bg-rose-100 text-rose-600' };
  };

  const getSentimentStyles = (sentiment: AIAnalysis['sentiment']) => {
    switch (sentiment) {
      case 'positive': return { color: 'text-emerald-500', icon: '😊' };
      case 'negative': return { color: 'text-rose-500', icon: '😫' };
      case 'neutral': default: return { color: 'text-slate-400', icon: '😐' };
    }
  };

  const weirdness = quote.aiAnalysis ? getWeirdnessLabel(quote.aiAnalysis.weirdnessIndex) : null;
  const sentiment = quote.aiAnalysis ? getSentimentStyles(quote.aiAnalysis.sentiment) : null;

  // 截取內容作為標題
  const displayTitle = quote.content.length > 25 ? quote.content.substring(0, 25) + '...' : quote.content;

  return (
    <div className={`group/item border border-purple-100/50 rounded-2xl transition-all duration-300 mb-3 overflow-hidden ${isExpanded ? 'bg-white shadow-lg ring-1 ring-purple-100' : 'bg-purple-50/30 hover:bg-white hover:shadow-sm'}`}>
      {/* 條目頭部 - 永遠顯示 */}
      <div 
        onClick={() => !isEditing && setIsExpanded(!isExpanded)}
        className="px-5 py-4 flex items-center justify-between cursor-pointer gap-4"
      >
        <div className="flex items-center gap-3 flex-1 min-w-0">
          <span className="shrink-0 text-[10px] font-mono font-bold text-slate-400 bg-white px-2 py-0.5 rounded border border-slate-100">
            {quote.observationDate.split('-').slice(1).join('/')}
          </span>

          <h4 className={`text-sm font-bold truncate transition-colors ${isExpanded ? 'text-indigo-600' : 'text-slate-700'}`}>
            {isExpanded ? '詳細觀察紀錄' : displayTitle}
          </h4>

          {!isExpanded && (
            <div className="flex items-center gap-1.5 shrink-0">
              {sentiment && <span className="text-xs" title={quote.aiAnalysis?.sentimentLabel}>{sentiment.icon}</span>}
              {weirdness && (
                <span className={`text-[9px] font-black px-1.5 py-0.5 rounded-md ${weirdness.color} uppercase`}>
                  {weirdness.label}
                </span>
              )}
            </div>
          )}
        </div>

        <div className="flex items-center gap-3 shrink-0">
          {!isExpanded && !quote.aiAnalysis && (
            <button 
              onClick={handleAIAnalyze}
              className="text-[10px] font-bold text-indigo-500 hover:text-indigo-700 transition-colors"
            >
              {loading ? '...' : 'AI分析'}
            </button>
          )}
          <svg 
            className={`w-4 h-4 text-slate-300 transition-transform duration-300 ${isExpanded ? 'rotate-180 text-indigo-400' : ''}`} 
            fill="none" 
            stroke="currentColor" 
            viewBox="0 0 24 24"
          >
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" />
          </svg>
        </div>
      </div>

      {/* 展開詳情區域 */}
      {isExpanded && (
        <div className="px-5 pb-6 animate-in slide-in-from-top-2 duration-300">
          <div className="pt-2 border-t border-purple-50">
            {isEditing ? (
              <div className="space-y-4 py-4">
                <div className="grid grid-cols-2 gap-3">
                   <div>
                    <label className="block text-[10px] font-black text-slate-400 uppercase mb-1">日期</label>
                    <input 
                      type="date" 
                      value={editDate}
                      onChange={(e) => setEditDate(e.target.value)}
                      className="w-full text-xs font-bold text-slate-600 bg-slate-50 border border-slate-100 rounded-xl px-3 py-2 outline-none focus:ring-2 focus:ring-indigo-100"
                    />
                  </div>
                </div>
                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase mb-1">紀錄內容</label>
                  <textarea 
                    value={editContent}
                    onChange={(e) => setEditContent(e.target.value)}
                    className="w-full text-sm font-medium text-slate-800 bg-slate-50 border border-slate-100 rounded-xl p-4 outline-none focus:ring-2 focus:ring-indigo-100 min-h-[120px] resize-none"
                  />
                </div>
                <div className="flex gap-2 justify-end">
                  <button onClick={handleSaveEdit} className="px-5 py-2 bg-slate-900 text-white text-xs font-bold rounded-full hover:bg-indigo-600 transition-all">保存更改</button>
                  <button onClick={() => setIsEditing(false)} className="px-5 py-2 bg-slate-100 text-slate-500 text-xs font-bold rounded-full hover:bg-slate-200">取消</button>
                </div>
              </div>
            ) : (
              <div className="py-4">
                <div className="bg-slate-50 rounded-2xl p-4 mb-6 relative">
                  <div className="absolute -top-3 left-4 px-2 bg-white text-[9px] font-black text-slate-400 border border-slate-100 rounded uppercase">事件內容</div>
                  <p className="text-base text-slate-800 font-medium leading-relaxed italic">
                    「{quote.content}」
                  </p>
                </div>

                {quote.aiAnalysis ? (
                  <div className="space-y-4">
                    {/* AI Insight Header */}
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-2">
                        <span className={`px-2 py-0.5 rounded text-[10px] font-black border ${sentiment?.color} bg-white`}>
                          {sentiment?.icon} {quote.aiAnalysis.sentimentLabel}
                        </span>
                        <span className="text-[10px] font-black text-indigo-400 uppercase tracking-widest">
                          {quote.aiAnalysis.dynamic}
                        </span>
                      </div>
                      <div className="flex items-center gap-1.5">
                        <span className="text-[10px] font-bold text-slate-400">怪異指數</span>
                        <span className="text-xs font-black text-rose-500">{quote.aiAnalysis.weirdnessIndex}/10</span>
                      </div>
                    </div>

                    {/* AI Logic Box */}
                    <div className="bg-slate-900 rounded-2xl p-5 shadow-inner">
                      <p className="text-sm leading-relaxed text-indigo-100 font-light mb-4">
                        <span className="text-indigo-400 font-black mr-2">洞察：</span>
                        {quote.aiAnalysis.insight}
                      </p>

                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                        <div className="bg-white/5 rounded-xl p-3 border border-white/10">
                          <span className="text-[9px] font-bold text-emerald-400 block mb-2 uppercase tracking-tighter">● 我方邏輯</span>
                          <ul className="space-y-1">
                            {quote.aiAnalysis.selfView?.map((p, i) => <li key={i} className="text-[10px] text-slate-300 leading-tight">• {p}</li>)}
                          </ul>
                        </div>
                        <div className="bg-white/5 rounded-xl p-3 border border-white/10">
                          <span className="text-[9px] font-bold text-rose-400 block mb-2 uppercase tracking-tighter">● 對方邏輯</span>
                          <ul className="space-y-1">
                            {quote.aiAnalysis.otherView?.map((p, i) => <li key={i} className="text-[10px] text-slate-300 leading-tight">• {p}</li>)}
                          </ul>
                        </div>
                      </div>
                    </div>
                  </div>
                ) : (
                  <button
                    onClick={handleAIAnalyze}
                    disabled={loading}
                    className="w-full py-4 bg-indigo-50 border border-indigo-100 text-indigo-500 rounded-2xl text-xs font-bold hover:bg-indigo-600 hover:text-white transition-all flex items-center justify-center gap-2 group"
                  >
                    {loading ? (
                      <div className="w-4 h-4 border-2 border-current border-t-transparent rounded-full animate-spin"></div>
                    ) : (
                      <>
                        <span className="text-base group-hover:scale-110 transition-transform">⚖️</span> 
                        啟動 AI 立場辯證分析
                      </>
                    )}
                  </button>
                )}

                {/* 操作按鈕組 */}
                <div className="mt-6 pt-4 border-t border-slate-100 flex justify-end gap-3">
                  <button 
                    onClick={(e) => { e.stopPropagation(); setIsEditing(true); }}
                    className="flex items-center gap-1.5 px-3 py-1.5 text-[10px] font-bold text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-all"
                  >
                    <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" /></svg>
                    編輯紀錄
                  </button>
                  <button 
                    onClick={handleDeleteClick}
                    className="flex items-center gap-1.5 px-3 py-1.5 text-[10px] font-bold text-slate-400 hover:text-rose-600 hover:bg-rose-50 rounded-lg transition-all"
                  >
                    <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                    刪除
                  </button>
                </div>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

