    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `你是一個冷靜的人類行為觀察學家。
請分析這段對話。對象: ${author}，日期: ${observationDate}。
內容: 「${content}」

請分析雙方立場，並特別針對「時間點」給出語境分析（例如該日期是週幾、是否接近月底、深夜還是清晨的語境影響）。
請用繁體中文回答。`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        thinkingConfig: { thinkingBudget: 2000 },
        maxOutputTokens: 2000, 
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            resonanceScore: { type: Type.NUMBER },
            weirdnessIndex: { type: Type.NUMBER },
            sentiment: { type: Type.STRING, enum: ['positive', 'negative', 'neutral'] },
            sentimentLabel: { type: Type.STRING },
            insight: { type: Type.STRING },
            dynamic: { type: Type.STRING },
            selfView: { type: Type.ARRAY, items: { type: Type.STRING } },
            otherView: { type: Type.ARRAY, items: { type: Type.STRING } },
            suggestedTags: { type: Type.ARRAY, items: { type: Type.STRING } },
            temporalContext: { type: Type.STRING, description: "時間語境分析，如：週一早晨的職涯焦慮" },
            behaviorCycle: { type: Type.STRING, description: "行為週期性描述" }
          },
          required: ["resonanceScore", "weirdnessIndex", "sentiment", "sentimentLabel", "insight", "dynamic", "selfView", "otherView", "suggestedTags", "temporalContext", "behaviorCycle"]
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("無回傳內容");
    return { ...JSON.parse(text.trim()), analyzedAt: Date.now() };
  } catch (error) {
    console.error("Gemini analyzeQuote 失敗:", error);
    throw error;
  }
};

export const generateAuthorProfile = async (author: string, quotes: Quote[]): Promise<AuthorProfile> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const history = quotes.map(q => `[${q.observationDate}] ${q.content}`).join('\n');
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `根據以下關於 "${author}" 的歷史觀察，分析其特質與「行為規律時間」：\n\n${history}`,
      config: {
        thinkingConfig: { thinkingBudget: 2000 },
        maxOutputTokens: 2000,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            characterType: { type: Type.STRING },
            traits: { type: Type.ARRAY, items: { type: Type.STRING } },
            relationshipPhase: { type: Type.STRING },
            interactionGuide: { type: Type.STRING },
            summary: { type: Type.STRING },
            activeTimePattern: { type: Type.STRING, description: "最容易發作/出現怪言怪語的時段規律" }
          },
          required: ["characterType", "traits", "relationshipPhase", "interactionGuide", "summary", "activeTimePattern"]
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("無回傳內容");
    return { ...JSON.parse(text.trim()), lastUpdated: Date.now() };
  } catch (error) {
    console.error("Gemini generateAuthorProfile 失敗:", error);
    throw error;
  }
};

import React, { useState } from 'react';
import { Quote, AIAnalysis } from '../types';
import { analyzeQuote } from '../services/geminiService';

interface QuoteItemProps {
  quote: Quote;
  prevQuoteDate?: string; // 用於計算時間差
  onUpdate: (updatedQuote: Quote) => void;
  onDelete: (id: string) => void;
}

const QuoteItem: React.FC<QuoteItemProps> = ({ quote, prevQuoteDate, onUpdate, onDelete }) => {
  const [loading, setLoading] = useState(false);
  const [isExpanded, setIsExpanded] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editContent, setEditContent] = useState(quote.content);
  const [editDate, setEditDate] = useState(quote.observationDate);

  const handleAIAnalyze = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setLoading(true);
    try {
      const analysis = await analyzeQuote(quote.content, quote.author, quote.observationDate);
      onUpdate({ ...quote, aiAnalysis: analysis });
      setIsExpanded(true);
    } catch (error) {
      console.error("AI Analysis 失敗:", error);
      alert('AI 分析失敗');
    } finally {
      setLoading(false);
    }
  };

  const getDayDiff = () => {
    if (!prevQuoteDate) return null;
    const current = new Date(quote.observationDate).getTime();
    const prev = new Date(prevQuoteDate).getTime();
    const diff = Math.floor(Math.abs(current - prev) / (1000 * 60 * 60 * 24));
    return diff;
  };

  const getSentimentStyles = (sentiment: AIAnalysis['sentiment']) => {
    switch (sentiment) {
      case 'positive': return { color: 'text-emerald-500', icon: '😊' };
      case 'negative': return { color: 'text-rose-500', icon: '😫' };
      default: return { color: 'text-slate-400', icon: '😐' };
    }
  };

  const dayDiff = getDayDiff();
  const sentiment = quote.aiAnalysis ? getSentimentStyles(quote.aiAnalysis.sentiment) : null;
  const displayTitle = quote.content.length > 20 ? quote.content.substring(0, 20) + '...' : quote.content;

  return (
    <div className={`group/item border border-purple-100/50 rounded-2xl transition-all duration-300 mb-3 overflow-hidden ${isExpanded ? 'bg-white shadow-lg ring-1 ring-purple-100' : 'bg-purple-50/30 hover:bg-white'}`}>
      {/* 摺疊標頭 */}
      <div 
        onClick={() => !isEditing && setIsExpanded(!isExpanded)}
        className="px-5 py-4 flex items-center justify-between cursor-pointer gap-4"
      >
        <div className="flex items-center gap-3 flex-1 min-w-0">
          <div className="flex flex-col items-center shrink-0">
            <span className="text-[10px] font-mono font-bold text-slate-400">
              {quote.observationDate.split('-').slice(1).join('/')}
            </span>
            {dayDiff !== null && !isExpanded && (
              <span className="text-[8px] text-indigo-300 font-bold">+{dayDiff}d</span>
            )}
          </div>

          <div className="flex-1 truncate">
            <h4 className={`text-sm font-bold truncate ${isExpanded ? 'text-indigo-600' : 'text-slate-700'}`}>
              {quote.aiAnalysis?.temporalContext || displayTitle}
            </h4>
            {!isExpanded && quote.aiAnalysis && (
              <p className="text-[9px] text-slate-400 truncate italic">{displayTitle}</p>
            )}
          </div>

          {!isExpanded && quote.aiAnalysis && (
            <div className="flex items-center gap-1.5 shrink-0">
              <span className="text-xs">{sentiment?.icon}</span>
              <span className="text-[9px] font-black text-rose-400 border border-rose-100 px-1 rounded">
                W:{quote.aiAnalysis.weirdnessIndex}
              </span>
            </div>
          )}
        </div>

        <div className="flex items-center gap-3 shrink-0">
          <svg className={`w-4 h-4 text-slate-300 transition-transform ${isExpanded ? 'rotate-180 text-indigo-400' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg>
        </div>
      </div>

      {/* 詳情內容 */}
      {isExpanded && (
        <div className="px-5 pb-6 animate-in slide-in-from-top-1">
          <div className="pt-2 border-t border-purple-50">
            {isEditing ? (
              <div className="space-y-4 py-4">
                <textarea 
                  value={editContent}
                  onChange={(e) => setEditContent(e.target.value)}
                  className="w-full text-sm bg-slate-50 border border-slate-100 rounded-xl p-4 min-h-[100px]"
                />
                <div className="flex gap-2 justify-end">
                  <button onClick={(e) => { e.stopPropagation(); onUpdate({...quote, content: editContent}); setIsEditing(false); }} className="px-4 py-1.5 bg-slate-900 text-white text-xs rounded-full">保存</button>
                  <button onClick={() => setIsEditing(false)} className="px-4 py-1.5 bg-slate-100 text-slate-400 text-xs rounded-full">取消</button>
                </div>
              </div>
            ) : (
              <div className="py-4 space-y-4">
                <div className="bg-slate-50 rounded-2xl p-4 relative">
                  <p className="text-base text-slate-800 font-medium italic leading-relaxed">「{quote.content}」</p>
                </div>

                {quote.aiAnalysis ? (
                  <div className="space-y-4">
                    <div className="flex items-center justify-between text-[10px] font-bold">
                      <div className="flex gap-2">
                        <span className="text-indigo-500 bg-indigo-50 px-2 py-0.5 rounded uppercase">脈絡：{quote.aiAnalysis.temporalContext}</span>
                        <span className="text-amber-500 bg-amber-50 px-2 py-0.5 rounded uppercase">節奏：{quote.aiAnalysis.behaviorCycle}</span>
                      </div>
                    </div>

                    <div className="bg-slate-900 rounded-2xl p-5 shadow-inner">
                      <p className="text-sm text-indigo-100 font-light mb-4">
                        <span className="text-indigo-400 font-black mr-2">行為洞察：</span>{quote.aiAnalysis.insight}
                      </p>
                      <div className="grid grid-cols-2 gap-3">
                        <div className="bg-white/5 rounded-xl p-3 border border-white/10">
                          <span className="text-[9px] font-bold text-emerald-400 block mb-1 uppercase">我方邏輯</span>
                          {quote.aiAnalysis.selfView.map((v, i) => <p key={i} className="text-[10px] text-slate-300 leading-tight">• {v}</p>)}
                        </div>
                        <div className="bg-white/5 rounded-xl p-3 border border-white/10">
                          <span className="text-[9px] font-bold text-rose-400 block mb-1 uppercase">對方邏輯</span>
                          {quote.aiAnalysis.otherView.map((v, i) => <p key={i} className="text-[10px] text-slate-300 leading-tight">• {v}</p>)}
                        </div>
                      </div>
                    </div>
                  </div>
                ) : (
                  <button onClick={handleAIAnalyze} disabled={loading} className="w-full py-3 bg-indigo-50 text-indigo-500 rounded-xl text-xs font-bold hover:bg-indigo-600 hover:text-white transition-all">
                    {loading ? '分析中...' : '🧬 啟動時間脈絡辯證'}
                  </button>
                )}

                <div className="flex justify-end gap-3 mt-4">
                  <button onClick={(e) => { e.stopPropagation(); setIsEditing(true); }} className="text-[10px] text-slate-400 hover:text-indigo-600">編輯</button>
                  <button onClick={(e) => { e.stopPropagation(); if(confirm('刪除？')) onDelete(quote.id); }} className="text-[10px] text-slate-400 hover:text-rose-600">刪除</button>
                </div>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default QuoteItem;

import React, { useState } from 'react';
import { AuthorGroup, Quote, AuthorProfile } from '../types';
import QuoteItem from './QuoteItem';
import ProfileModal from './ProfileModal';
import { generateAuthorProfile } from '../services/geminiService';

interface AuthorCardProps {
  group: AuthorGroup;
  onUpdateQuote: (updatedQuote: Quote) => void;
  onDeleteQuote: (id: string) => void;
  onUpdateProfile: (author: string, profile: AuthorProfile | null) => void;
}

const AuthorCard: React.FC<AuthorCardProps> = ({ group, onUpdateQuote, onDeleteQuote, onUpdateProfile }) => {
  const [isGeneratingProfile, setIsGeneratingProfile] = useState(false);
  const [showProfile, setShowProfile] = useState(false);

  const handleGenerateProfile = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setIsGeneratingProfile(true);
    try {
      const profile = await generateAuthorProfile(group.author, group.quotes);
      onUpdateProfile(group.author, profile);
      setShowProfile(true);
    } catch (error) {
      console.error("Failed", error);
    } finally {
      setIsGeneratingProfile(false);
    }
  };

  const sortedQuotes = [...group.quotes].sort((a, b) => b.timestamp - a.timestamp);

  return (
    <div className="bg-white rounded-[2.5rem] shadow-sm border border-purple-50 overflow-hidden flex flex-col h-full hover:shadow-xl transition-all duration-500">
      <div className="p-8 pb-4">
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center gap-4">
            <div className={`w-14 h-14 rounded-2xl flex items-center justify-center font-black text-xl bg-gradient-to-br from-indigo-100 to-indigo-200 text-indigo-600 shadow-lg`}>
              {group.author.charAt(0).toUpperCase()}
            </div>
            <div>
              <h3 className="text-xl font-black text-slate-800 tracking-tight">{group.author}</h3>
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-0.5">觀察樣本 #{group.quotes.length}</p>
            </div>
          </div>

          <button 
            onClick={group.profile ? () => setShowProfile(true) : handleGenerateProfile}
            disabled={isGeneratingProfile}
            className="px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-widest transition-all shadow-md bg-indigo-50 text-indigo-500 hover:bg-indigo-600 hover:text-white"
          >
            {isGeneratingProfile ? '分析中...' : group.profile ? '人物誌' : '行為規律分析'}
          </button>
        </div>

        {group.profile && (
          <div className="bg-indigo-50/50 rounded-[1.5rem] p-4 border border-indigo-100/30 mb-4">
            <div className="flex justify-between items-center mb-1">
              <span className="text-[9px] font-black text-indigo-400 uppercase tracking-widest">發作規律</span>
              <span className="text-[8px] bg-white px-1.5 py-0.5 rounded text-indigo-300 border border-indigo-50">{group.profile.activeTimePattern}</span>
            </div>
            <p className="text-xs font-bold text-slate-700 italic">「{group.profile.characterType}」</p>
          </div>
        )}
      </div>

      <div className="flex-1 overflow-y-auto max-h-[500px] px-8 pb-8 space-y-3 custom-scrollbar">
        {sortedQuotes.map((quote, index) => (
          <QuoteItem 
            key={quote.id} 
            quote={quote} 
            prevQuoteDate={sortedQuotes[index + 1]?.observationDate}
            onUpdate={onUpdateQuote} 
            onDelete={onDeleteQuote} 
          />
        ))}
      </div>

      {showProfile && group.profile && (
        <ProfileModal author={group.author} profile={group.profile} onClose={() => setShowProfile(false)} />
      )}
    </div>
  );
};

export default AuthorCard;

import { GoogleGenAI, Type } from "@google/genai";
