export const refineNarrative = async (rawContent: string): Promise<string> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `請將這段零碎的口語觀察紀錄整理成通順且平實的繁體中文文字，保留口語的精髓但去除贅字：\n\n"""\n${rawContent}\n"""`,
      config: { temperature: 0.2 }
    });
    return response.text?.trim() || rawContent;
  } catch (error) {
    console.error("Gemini refineNarrative 失敗:", error);
    throw error;
  }
};

export const analyzeQuote = async (content: string, author: string, observationDate: string): Promise<AIAnalysis> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    // 分析時將日期作為語境參考，但不讓它主導整個分析
    const prompt = `你是一個冷靜的人類行為觀察學家。
請分析這段互動。對象: ${author}，發生日期: ${observationDate}。
內容: 「${content}」

分析要求：
1. 辯證分析雙方（我方與${author}）潛在的內心邏輯立場。
2. 根據日期推論可能的「時間脈絡」（例如：週一早晨的焦慮、接近週末的放鬆、月底的壓力等）。
3. 評價這段言行的「怪異指數」。
請用繁體中文回答。`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        thinkingConfig: { thinkingBudget: 2000 },
        maxOutputTokens: 2000, 
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            resonanceScore: { type: Type.NUMBER },
            weirdnessIndex: { type: Type.NUMBER },
            sentiment: { type: Type.STRING, enum: ['positive', 'negative', 'neutral'] },
            sentimentLabel: { type: Type.STRING },
            insight: { type: Type.STRING },
            dynamic: { type: Type.STRING },
            selfView: { type: Type.ARRAY, items: { type: Type.STRING }, description: "我方的潛在動機或邏輯" },
            otherView: { type: Type.ARRAY, items: { type: Type.STRING }, description: "對方的潛在動機或邏輯" },
            suggestedTags: { type: Type.ARRAY, items: { type: Type.STRING } },
            temporalContext: { type: Type.STRING, description: "時間語境摘要，例如：週二午後的防禦心態" },
            behaviorCycle: { type: Type.STRING, description: "行為週期性的小發現" }
          },
          required: ["resonanceScore", "weirdnessIndex", "sentiment", "sentimentLabel", "insight", "dynamic", "selfView", "otherView", "suggestedTags", "temporalContext", "behaviorCycle"]
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("無回傳內容");
    return { ...JSON.parse(text.trim()), analyzedAt: Date.now() };
  } catch (error) {
    console.error("Gemini analyzeQuote 失敗:", error);
    throw error;
  }
