        className="px-5 py-4 flex items-center justify-between cursor-pointer gap-4"
      >
        <div className="flex items-center gap-3 flex-1 min-w-0">
          <span className="shrink-0 text-[10px] font-mono font-bold text-slate-400 bg-white/80 px-2 py-0.5 rounded border border-slate-100">
            {formattedDate}
          </span>
          <h4 className={`text-sm font-bold truncate transition-colors ${isExpanded ? 'text-indigo-600' : 'text-slate-700'}`}>
            {isExpanded ? '詳細觀察記錄' : title}
          </h4>
          {!isExpanded && quote.aiAnalysis && (
            <div className="flex items-center gap-1.5 shrink-0">
              <span className="text-xs">{getSentimentIcon(quote.aiAnalysis.sentiment)}</span>
              <span className="text-[9px] font-black px-1.5 py-0.5 rounded bg-rose-50 text-rose-400 border border-rose-100">
                W:{quote.aiAnalysis.weirdnessIndex}
              </span>
            </div>
          )}
        </div>

        <div className="flex items-center gap-3 shrink-0">
          {!isExpanded && !quote.aiAnalysis && (
            <button 
              onClick={handleAIAnalyze}
              className="text-[10px] font-bold text-indigo-500 hover:text-indigo-700"
            >
              {loading ? '...' : '分析'}
            </button>
          )}
          <svg className={`w-4 h-4 text-slate-300 transition-transform duration-300 ${isExpanded ? 'rotate-180 text-indigo-500' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg>
        </div>
      </div>

      {/* 展開詳情 */}
      {isExpanded && (
        <div className="px-5 pb-6 animate-in slide-in-from-top-2 duration-300">
          <div className="pt-2 border-t border-purple-50">
            <div className="bg-slate-50 rounded-2xl p-4 mb-4 relative">
              <div className="absolute -top-3 left-4 px-2 bg-white text-[9px] font-black text-slate-300 border border-slate-100 rounded uppercase">事件原文</div>
              <p className="text-base text-slate-800 font-medium italic leading-relaxed">「{quote.content}」</p>
            </div>

            {quote.aiAnalysis ? (
              <div className="space-y-4">
                <div className="bg-slate-900 rounded-2xl p-5 shadow-inner">
                  <div className="flex items-center justify-between mb-4">
                    <span className="text-[10px] font-black text-indigo-400 uppercase tracking-widest">🧬 行為辯證邏輯</span>
                    <span className="text-[10px] text-white/40 font-mono">{quote.aiAnalysis.dynamic}</span>
                  </div>

                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 mb-4">
                    <div className="bg-white/5 rounded-xl p-3 border border-white/10">
                      <span className="text-[9px] font-bold text-emerald-400 block mb-1 uppercase">我方潛在動機</span>
                      {quote.aiAnalysis.selfView.map((v, i) => <p key={i} className="text-[10px] text-slate-300 leading-tight">• {v}</p>)}
                    </div>
                    <div className="bg-white/5 rounded-xl p-3 border border-white/10">
                      <span className="text-[9px] font-bold text-rose-400 block mb-1 uppercase">對方潛在動機</span>
