                    </div>
                  </div>
                  <p className="text-[11px] text-indigo-100 font-light italic leading-relaxed">
                    <span className="text-indigo-400 font-bold mr-1">洞察：</span>{quote.aiAnalysis.insight}
                  </p>
                </div>

                <div className="flex flex-wrap gap-1.5">
                  {quote.tags.map(tag => (
                    <span key={tag} className="text-[9px] font-bold px-2 py-0.5 bg-indigo-50 text-indigo-500 rounded-md">#{tag}</span>
                  ))}
