import { GoogleGenAI, Type } from "@google/genai";
import { AIAnalysis, AuthorProfile, Quote } from "../types";

export const refineNarrative = async (rawContent: string): Promise<string> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `請將以下原始觀察紀錄修飾成流暢且富有觀察美感的繁體中文。內容如下：\n\n${rawContent}`,
      config: { 
        systemInstruction: "你是一個專業的文字修飾助手。你的唯一任務是順稿。請直接回傳修飾後的純文字。嚴禁包含任何引言、結語、點評、分析或多版本選項。保留原始意涵，去除冗贅，使其更易閱讀。",
        temperature: 0.1 
      }
    });
    return response.text?.trim() || rawContent;
  } catch (error) {
    console.error("Gemini refineNarrative 失敗:", error);
    throw error;
  }
};

export const analyzeQuote = async (content: string, author: string, observationDate: string): Promise<AIAnalysis> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `你是一個冷峻且洞察力極強的人類行為觀察學家。請針對這段對象為「${author}」的互動進行「深度邏輯與心理辯證」。

內容：「${content}」

分析指南（拒絕輕描淡寫，追求深刻見解）：
1. 【核心洞察】：用一句話精確刺破這場互動的荒謬本質。
2. 【當下立場】：我方在當下的心理預設是什麼？對方又是基於何種慣性或邏輯在回應？
3. 【情緒潛流】：這段話背後隱藏了什麼樣的情緒策略（如：被動攻擊、尋求補償、權力壓制或防禦機制）？
4. 【關係漣漪】：這場看似微小的互動，反映了你們關係中長期存在的什麼問題？未來可能引發什麼樣的連鎖反應？

請以繁體中文回傳 JSON。`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            resonanceScore: { type: Type.NUMBER },
            weirdnessIndex: { type: Type.NUMBER },
            sentiment: { type: Type.STRING, enum: ['positive', 'negative', 'neutral'] },
            sentimentLabel: { type: Type.STRING },
            insight: { type: Type.STRING, description: "對這場邏輯錯位的深刻總結" },
            dynamic: { type: Type.STRING, description: "立場碰撞的類型" },
            selfView: { type: Type.ARRAY, items: { type: Type.STRING }, description: "我方的心理預設與期待" },
            otherView: { type: Type.ARRAY, items: { type: Type.STRING }, description: "對方的反應邏輯與立場" },
            subtext: { type: Type.STRING, description: "文字背後隱藏的情緒潛流與動機" },
            relationshipRipple: { type: Type.STRING, description: "此次互動對關係長遠的影響與漣漪" },
            suggestedTags: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ["resonanceScore", "weirdnessIndex", "sentiment", "sentimentLabel", "insight", "dynamic", "selfView", "otherView", "subtext", "relationshipRipple", "suggestedTags"]
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("無內容");
    return { ...JSON.parse(text.trim()), analyzedAt: Date.now() };
  } catch (error) {
    console.error("Gemini analyzeQuote 失敗:", error);
    throw error;
  }
};

export const generateAuthorProfile = async (author: string, quotes: Quote[]): Promise<AuthorProfile> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const history = [...quotes]
      .sort((a, b) => new Date(a.observationDate).getTime() - new Date(b.observationDate).getTime())
      .map(q => `[${q.observationDate}] ${q.content}`)
      .join('\n');

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: `分析 "${author}" 與觀察者之間的關係演進趨勢。
${history}

任務：
1. 歸納此人的核心行為標籤。
2. 根據時間序產出 5-7 個關係質量數據點 (0-100分)。`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            characterType: { type: Type.STRING },
            traits: { type: Type.ARRAY, items: { type: Type.STRING } },
            relationshipPhase: { type: Type.STRING },
            interactionGuide: { type: Type.STRING },
            summary: { type: Type.STRING },
            stabilityScore: { type: Type.NUMBER },
            relationshipTrend: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  date: { type: Type.STRING },
                  score: { type: Type.NUMBER },
                  label: { type: Type.STRING }
                },
                required: ["date", "score", "label"]
              }
            }
          },
          required: ["characterType", "traits", "relationshipPhase", "interactionGuide", "summary", "stabilityScore", "relationshipTrend"]
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("無內容");
    return { ...JSON.parse(text.trim()), lastUpdated: Date.now() };
  } catch (error) {
    console.error("Gemini generateAuthorProfile 失敗:", error);
    throw error;
  }
};

