import React, { useState } from 'react';
import { AuthorGroup, Quote, AuthorProfile } from '../types';
import QuoteItem from './QuoteItem';
import ProfileModal from './ProfileModal';
import { generateAuthorProfile } from '../services/geminiService';

interface AuthorCardProps {
  group: AuthorGroup;
  onUpdateQuote: (updatedQuote: Quote) => void;
  onDeleteQuote: (id: string) => void;
  onUpdateProfile: (author: string, profile: AuthorProfile | null) => void;
}

const AuthorCard: React.FC<AuthorCardProps> = ({ group, onUpdateQuote, onDeleteQuote, onUpdateProfile }) => {
  const [isGeneratingProfile, setIsGeneratingProfile] = useState(false);
  const [showProfile, setShowProfile] = useState(false);

  const handleGenerateProfile = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setIsGeneratingProfile(true);
    try {
      const profile = await generateAuthorProfile(group.author, group.quotes);
      onUpdateProfile(group.author, profile);
      // 如果原本沒顯示人物誌，生成後自動顯示
      if (!group.profile) setShowProfile(true);
    } catch (error) {
      console.error("Failed", error);
    } finally {
      setIsGeneratingProfile(false);
    }
  };

  const sortedQuotes = [...group.quotes].sort((a, b) => b.timestamp - a.timestamp);

  return (
    <div className="bg-white rounded-[2.5rem] shadow-sm border border-purple-50 overflow-hidden flex flex-col h-full hover:shadow-xl transition-all duration-500">
      <div className="p-8 pb-4">
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center gap-4">
            <div className={`w-14 h-14 rounded-2xl flex items-center justify-center font-black text-xl bg-gradient-to-br from-indigo-100 to-indigo-200 text-indigo-600 shadow-lg`}>
              {group.author.charAt(0).toUpperCase()}
            </div>
            <div>
              <h3 className="text-xl font-black text-slate-800 tracking-tight">{group.author}</h3>
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-0.5">觀察樣本 #{group.quotes.length}</p>
            </div>
          </div>

          <div className="flex items-center gap-1.5">
            {group.profile && (
              <button 
                onClick={handleGenerateProfile}
                disabled={isGeneratingProfile}
                className="p-2.5 rounded-full bg-slate-50 text-slate-400 hover:bg-indigo-50 hover:text-indigo-500 transition-all border border-slate-100"
                title="重新整理人物誌"
              >
                <svg className={`w-4 h-4 ${isGeneratingProfile ? 'animate-spin' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
                </svg>
              </button>
            )}
            <button 
              onClick={group.profile ? () => setShowProfile(true) : handleGenerateProfile}
              disabled={isGeneratingProfile}
              className="px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-widest transition-all shadow-md bg-indigo-50 text-indigo-500 hover:bg-indigo-600 hover:text-white"
            >
              {isGeneratingProfile && !group.profile ? '分析中...' : group.profile ? '查看人物誌' : '行為規律分析'}
            </button>
          </div>
        </div>

        {group.profile && (
          <div className="bg-indigo-50/50 rounded-[1.5rem] p-4 border border-indigo-100/30 mb-4">
            <div className="flex justify-between items-center mb-1">
              <span className="text-[9px] font-black text-indigo-400 uppercase tracking-widest">發作規律</span>
              <span className="text-[8px] bg-white px-1.5 py-0.5 rounded text-indigo-300 border border-indigo-50">{group.profile.activeTimePattern}</span>
            </div>
            <p className="text-xs font-bold text-slate-700 italic">「{group.profile.characterType}」</p>
          </div>
        )}
      </div>

      <div className="flex-1 overflow-y-auto max-h-[500px] px-8 pb-8 space-y-3 custom-scrollbar">
        {sortedQuotes.map((quote, index) => (
          <QuoteItem 
            key={quote.id} 
            quote={quote} 
            onUpdate={onUpdateQuote} 
            onDelete={onDeleteQuote} 
          />
        ))}
      </div>

      {showProfile && group.profile && (
        <ProfileModal author={group.author} profile={group.profile} onClose={() => setShowProfile(false)} />
      )}
    </div>
  );
};

export default AuthorCard;

import { GoogleGenAI, Type } from "@google/genai";
import { AIAnalysis, AuthorProfile, Quote } from "../types";

export const refineNarrative = async (rawContent: string): Promise<string> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `請將以下原始觀察紀錄修飾成流暢且富有觀察美感的繁體中文。內容如下：\n\n${rawContent}`,
      config: { 
        systemInstruction: "你是一個專業的文字修飾助手。你的唯一任務是順稿。請直接回傳修飾後的純文字。嚴禁包含任何引言、結語、點評、分析或多版本選項。保留原始意涵，去除冗贅，使其更易閱讀。",
        temperature: 0.1 
      }
    });
    return response.text?.trim() || rawContent;
  } catch (error) {
    console.error("Gemini refineNarrative 失敗:", error);
    throw error;
  }
};

export const analyzeQuote = async (content: string, author: string, observationDate: string): Promise<AIAnalysis> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `你是一個極致理性的「人際關係軍師」，專門為「我方（觀察者）」剖析與「對方（${author}）」之間的對峙與衝突。

內容描述了你們的一次互動：「${content}」

分析指令（嚴禁普世大局觀，必須限縮在「兩人間的對抗」）：
1. 【衝突本質】：用一句話直接點出你（我方）與 ${author} 在這一刻最核心的「心理碰撞點」是什麼。
2. 【我方期待 vs 對方邏輯】：我方當時想要達成什麼心理目標？而 ${author} 是用了什麼樣的邏輯或行為防禦來抵銷我方的意圖？
3. 【權力與情緒潛流】：分析這場對話中，誰在試圖掌控局面？背後隱藏了什麼樣的被動攻擊、試探或情緒勒索？
4. 【關係磨損/演變】：這次碰撞如何具體地改變了你對 ${author} 的認知邊界？這對你們二人未來的互動有什麼具體的風險提醒？

請以繁體中文回傳 JSON。`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            resonanceScore: { type: Type.NUMBER, description: "雙方張力指數 1-10" },
            weirdnessIndex: { type: Type.NUMBER },
            sentiment: { type: Type.STRING, enum: ['positive', 'negative', 'neutral'] },
            sentimentLabel: { type: Type.STRING, description: "這場衝突的情緒底色" },
            insight: { type: Type.STRING, description: "對這場二人衝突的尖銳總結" },
            dynamic: { type: Type.STRING, description: "衝突類型，例如：期待落空、認知對抗、權力爭奪" },
            selfView: { type: Type.ARRAY, items: { type: Type.STRING }, description: "我方的真實動機與心理期待" },
            otherView: { type: Type.ARRAY, items: { type: Type.STRING }, description: "對方的對抗邏輯與防衛機制" },
            subtext: { type: Type.STRING, description: "隱藏在對話下的權力博弈或情緒潛流" },
            relationshipRipple: { type: Type.STRING, description: "此事件對你們兩人後續互動的具體影響" },
            suggestedTags: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ["resonanceScore", "weirdnessIndex", "sentiment", "sentimentLabel", "insight", "dynamic", "selfView", "otherView", "subtext", "relationshipRipple", "suggestedTags"]
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("無內容");
    return { ...JSON.parse(text.trim()), analyzedAt: Date.now() };
  } catch (error) {
    console.error("Gemini analyzeQuote 失敗:", error);
    throw error;
  }
};

export const generateAuthorProfile = async (author: string, quotes: Quote[]): Promise<AuthorProfile> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const history = [...quotes]
      .sort((a, b) => new Date(a.observationDate).getTime() - new Date(b.observationDate).getTime())
      .map(q => `[${q.observationDate}] ${q.content}`)
      .join('\n');

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: `你正在為觀察者建立與 "${author}" 的關係深度檔案。
透過以下歷史互動，分析這兩人間的關係慣性。
${history}

任務：
1. 歸納此人在面對觀察者時最常使用的「行為對抗模式」。
2. 預測這段關係的長期演進方向。`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            characterType: { type: Type.STRING, description: "對我方而言，他是什麼樣的對抗角色" },
            traits: { type: Type.ARRAY, items: { type: Type.STRING } },
            relationshipPhase: { type: Type.STRING },
            interactionGuide: { type: Type.STRING, description: "我方未來的應對策略" },
            summary: { type: Type.STRING, description: "這兩人的長期對抗總結" },
            stabilityScore: { type: Type.NUMBER },
            relationshipTrend: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  date: { type: Type.STRING },
                  score: { type: Type.NUMBER },
                  label: { type: Type.STRING }
                },
                required: ["date", "score", "label"]
              }
            }
          },
          required: ["characterType", "traits", "relationshipPhase", "interactionGuide", "summary", "stabilityScore", "relationshipTrend"]
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("無內容");
    return { ...JSON.parse(text.trim()), lastUpdated: Date.now() };
  } catch (error) {
    console.error("Gemini generateAuthorProfile 失敗:", error);
    throw error;
  }
};

import React, { useState } from 'react';
import { Quote, AIAnalysis } from '../types';
import { analyzeQuote } from '../services/geminiService';

interface QuoteItemProps {
  quote: Quote;
  onUpdate: (updatedQuote: Quote) => void;
  onDelete: (id: string) => void;
}

const QuoteItem: React.FC<QuoteItemProps> = ({ quote, onUpdate, onDelete }) => {
  const [loading, setLoading] = useState(false);
  const [isExpanded, setIsExpanded] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editedContent, setEditedContent] = useState(quote.content);

  const handleAIAnalyze = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setLoading(true);
    try {
      // 使用當前編輯中的內容進行分析（若編輯中則用編輯內容，否則用原始內容）
      const contentToAnalyze = isEditing ? editedContent : quote.content;
      const analysis = await analyzeQuote(contentToAnalyze, quote.author, quote.observationDate);

      // 如果是在編輯狀態下分析，分析完自動儲存內容並關閉編輯狀態
      onUpdate({ ...quote, content: contentToAnalyze, aiAnalysis: analysis });
      setIsEditing(false);
      setIsExpanded(true);
    } catch (error) {
      console.error("AI Analysis failed", error);
    } finally {
      setLoading(false);
    }
  };

  const handleSaveEdit = (e: React.MouseEvent) => {
    e.stopPropagation();
    onUpdate({ ...quote, content: editedContent });
    setIsEditing(false);
  };

  const formattedDate = new Date(quote.observationDate).toLocaleDateString('zh-TW', {
    month: 'short',
    day: 'numeric'
  });

  const title = quote.content.length > 22 ? quote.content.substring(0, 22) + '...' : quote.content;

  const getSentimentIcon = (sentiment: AIAnalysis['sentiment']) => {
    switch (sentiment) {
      case 'positive': return '😊';
      case 'negative': return '😫';
      default: return '😐';
    }
  };

  return (
    <div className={`group/item border border-purple-100/50 rounded-2xl transition-all duration-300 mb-3 overflow-hidden ${isExpanded ? 'bg-white shadow-lg ring-1 ring-purple-100' : 'bg-purple-50/40 hover:bg-white hover:shadow-sm'}`}>
      {/* 摺疊頭部 */}
      <div 
        onClick={() => setIsExpanded(!isExpanded)}
        className="px-5 py-4 flex items-center justify-between cursor-pointer gap-4"
      >
        <div className="flex items-center gap-3 flex-1 min-w-0">
          <span className="shrink-0 text-[10px] font-mono font-bold text-slate-400 bg-white/80 px-2 py-0.5 rounded border border-slate-100">
            {formattedDate}
          </span>
          <h4 className={`text-sm font-bold truncate transition-colors ${isExpanded ? 'text-indigo-600' : 'text-slate-700'}`}>
            {isExpanded ? '二人關係對抗剖析' : title}
          </h4>
          {!isExpanded && quote.aiAnalysis && (
            <div className="flex items-center gap-1.5 shrink-0">
              <span className="text-xs">{getSentimentIcon(quote.aiAnalysis.sentiment)}</span>
              <span className="text-[9px] font-black px-1.5 py-0.5 rounded bg-rose-50 text-rose-400 border border-rose-100">
                TENSION:{quote.aiAnalysis.resonanceScore}
              </span>
            </div>
          )}
        </div>

        <div className="flex items-center gap-3 shrink-0">
          <svg className={`w-4 h-4 text-slate-300 transition-transform duration-300 ${isExpanded ? 'rotate-180 text-indigo-500' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg>
        </div>
      </div>

      {/* 展開詳情 */}
      {isExpanded && (
        <div className="px-5 pb-6 animate-in slide-in-from-top-2 duration-300">
          <div className="pt-2 border-t border-purple-50">
            {/* 原文編輯區 */}
            <div className="bg-slate-50 rounded-2xl p-5 mb-6 relative border border-slate-100/50">
              <div className="flex justify-between items-center absolute -top-3 left-4 right-4">
                <div className="px-2 bg-white text-[9px] font-black text-slate-300 border border-slate-100 rounded uppercase tracking-tighter">當下事件紀錄</div>
                <button 
                  onClick={(e) => { e.stopPropagation(); setIsEditing(!isEditing); }}
                  className="px-2 bg-white text-[9px] font-black text-indigo-400 border border-indigo-100 rounded uppercase hover:bg-indigo-50 transition-colors"
                >
                  {isEditing ? '取消' : '修正內容'}
                </button>
              </div>

              {isEditing ? (
                <div className="mt-2 space-y-3">
                  <textarea 
                    value={editedContent}
                    onChange={(e) => setEditedContent(e.target.value)}
                    className="w-full bg-white border border-indigo-100 rounded-xl p-3 text-sm focus:ring-2 focus:ring-indigo-200 outline-none min-h-[100px] resize-none"
                    placeholder="修正對話細節..."
                  />
                  <div className="flex gap-2">
                    <button 
                      onClick={handleSaveEdit}
                      className="px-4 py-1.5 bg-indigo-600 text-white text-[10px] font-bold rounded-lg shadow-sm hover:bg-indigo-700 transition-all"
                    >
                      僅儲存內容
                    </button>
                    <button 
                      onClick={handleAIAnalyze}
                      disabled={loading}
                      className="px-4 py-1.5 bg-slate-900 text-white text-[10px] font-bold rounded-lg shadow-sm hover:bg-indigo-600 transition-all flex items-center gap-2"
                    >
                      {loading ? '分析中...' : '儲存並重新剖析'}
                    </button>
                  </div>
                </div>
              ) : (
                <p className="text-base text-slate-800 font-medium italic leading-relaxed">「{quote.content}」</p>
              )}
            </div>

            {quote.aiAnalysis ? (
              <div className="space-y-6">
                {/* 1. 二人立場辯證看板 */}
