  observationDate: string; // 發生日期
  timestamp: number;
  tags: string[];
  aiAnalysis?: AIAnalysis;
}

export interface AIAnalysis {
  resonanceScore: number; // 衝突/共鳴張力
  weirdnessIndex: number; // 怪異指數 (1-10)
  sentiment: 'positive' | 'negative' | 'neutral'; // 情感傾向
  sentimentLabel: string; // 情感標籤
  insight: string; // 核心洞察
  dynamic: string; // 互動動態標籤
  selfView: string[]; // 我方當下立場
  otherView: string[]; // 對方當下立場
  subtext: string; // 情緒潛流與隱藏動機
  relationshipRipple: string; // 此次互動對關係的潛在長遠影響
  analyzedAt: number;
  suggestedTags: string[];
}

export interface TrendPoint {
  date: string;
  score: number; // 關係正向/張力分值
  label: string;
}

export interface AuthorProfile {
  characterType: string;
  traits: string[];
  relationshipPhase: string;
  interactionGuide: string;
  summary: string;
  lastUpdated: number;
  activeTimePattern?: string;
  relationshipTrend: TrendPoint[];
