import React, { useState, useEffect } from 'react';
import { Quote, AIAnalysis } from '../types';
import { analyzeQuote } from '../services/geminiService';

interface QuoteItemProps {
  quote: Quote;
  allQuotes: Quote[]; // 新增：傳入所有紀錄以進行關聯分析
  onUpdate: (updatedQuote: Quote) => void;
  onDelete: (id: string) => void;
}

const QuoteItem: React.FC<QuoteItemProps> = ({ quote, allQuotes, onUpdate, onDelete }) => {
  const [loading, setLoading] = useState(false);
  const [isExpanded, setIsExpanded] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editedContent, setEditedContent] = useState(quote.content);
  const [loadingText, setLoadingText] = useState('啟動深度分析');

  useEffect(() => {
    if (loading) {
      const texts = ['正在剖析對抗邏輯', '正在追蹤情緒潛流', '正在解構博弈本質', '正在生成互動報告'];
      let i = 0;
      const timer = setInterval(() => {
        setLoadingText(texts[i % texts.length] + '...');
        i++;
      }, 1000);
      return () => clearInterval(timer);
    } else {
      setLoadingText('重新剖析二人衝突動態');
    }
  }, [loading]);

  const handleAIAnalyze = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setLoading(true);
    try {
      const contentToAnalyze = isEditing ? editedContent : quote.content;
      const analysis = await analyzeQuote(contentToAnalyze, quote.author, quote.observationDate);

      onUpdate({ ...quote, content: contentToAnalyze, aiAnalysis: analysis });
      setIsEditing(false);
      setIsExpanded(true);
    } catch (error) {
      console.error("AI Analysis failed", error);
      alert("AI 分析失敗，請稍後再試。");
    } finally {
      setLoading(false);
    }
  };

  const handleSaveEdit = (e: React.MouseEvent) => {
    e.stopPropagation();
    onUpdate({ ...quote, content: editedContent });
    setIsEditing(false);
  };

  const scrollToQuote = (id: string) => {
    const element = document.getElementById(`quote-${id}`);
    if (element) {
      element.scrollIntoView({ behavior: 'smooth', block: 'center' });
      // 增加一個短暫的高亮效果
      element.classList.add('ring-4', 'ring-indigo-400', 'ring-opacity-50');
      setTimeout(() => {
        element.classList.remove('ring-4', 'ring-indigo-400', 'ring-opacity-50');
      }, 2000);
    }
  };

  const formattedDate = new Date(quote.observationDate).toLocaleDateString('zh-TW', {
    month: 'short',
    day: 'numeric'
  });

  const displayTitle = quote.aiAnalysis?.insight 
    ? quote.aiAnalysis.insight 
    : (quote.content.length > 30 ? quote.content.substring(0, 30) + '...' : quote.content);

  const getSentimentIcon = (sentiment: AIAnalysis['sentiment']) => {
    switch (sentiment) {
      case 'positive': return '😊';
      case 'negative': return '😫';
      default: return '😐';
    }
  };

  // 關聯紀錄篩選邏輯
  const relatedQuotes = quote.aiAnalysis ? allQuotes.filter(q => 
    q.id !== quote.id && 
    (q.aiAnalysis?.suggestedTags.some(tag => quote.aiAnalysis?.suggestedTags.includes(tag)) || 
     q.tags.some(tag => quote.aiAnalysis?.suggestedTags.includes(tag)))
  ).slice(0, 3) : [];

  return (
    <div 
      id={`quote-${quote.id}`}
      className={`group/item border border-purple-100/50 rounded-2xl transition-all duration-300 mb-3 overflow-hidden ${isExpanded ? 'bg-white shadow-lg ring-1 ring-purple-100' : 'bg-purple-50/40 hover:bg-white hover:shadow-sm'}`}
    >
      {/* 摺疊頭部 */}
      <div 
        onClick={() => setIsExpanded(!isExpanded)}
        className="px-5 py-4 flex items-center justify-between cursor-pointer gap-4"
      >
        <div className="flex items-center gap-3 flex-1 min-w-0">
          <span className="shrink-0 text-[10px] font-mono font-bold text-slate-400 bg-white/80 px-2 py-0.5 rounded border border-slate-100">
            {formattedDate}
          </span>
          <h4 className={`text-sm font-bold truncate transition-colors flex-1 ${isExpanded ? 'text-indigo-600' : 'text-slate-700'}`}>
            {displayTitle}
          </h4>
          {!isExpanded && quote.aiAnalysis && (
            <div className="flex items-center gap-1.5 shrink-0 ml-2">
              <span className="text-[10px] font-black px-1.5 py-0.5 rounded bg-rose-50 text-rose-400 border border-rose-100">
                T:{quote.aiAnalysis.resonanceScore}
              </span>
              <span className="text-sm opacity-80">{getSentimentIcon(quote.aiAnalysis.sentiment)}</span>
            </div>
          )}
        </div>

        <div className="flex items-center gap-3 shrink-0">
          <svg className={`w-4 h-4 text-slate-300 transition-transform duration-300 ${isExpanded ? 'rotate-180 text-indigo-500' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg>
        </div>
      </div>

      {/* 展開詳情 */}
      {isExpanded && (
        <div className="px-5 pb-6 animate-in slide-in-from-top-2 duration-300">
          <div className="pt-2 border-t border-purple-50">
            {/* 原文編輯區 */}
            <div className="bg-slate-50 rounded-2xl p-5 mb-6 relative border border-slate-100/50">
              <div className="flex justify-between items-center absolute -top-3 left-4 right-4">
