import React, { useState } from 'react';
import { AuthorGroup, Quote, AuthorProfile } from '../types';
import QuoteItem from './QuoteItem';
import ProfileModal from './ProfileModal';
import { generateAuthorProfile } from '../services/geminiService';

interface AuthorCardProps {
  group: AuthorGroup;
  allQuotes: Quote[]; // 新增：接收全局所有紀錄
  onUpdateQuote: (updatedQuote: Quote) => void;
  onDeleteQuote: (id: string) => void;
  onUpdateProfile: (author: string, profile: AuthorProfile | null) => void;
}

const AuthorCard: React.FC<AuthorCardProps> = ({ group, allQuotes, onUpdateQuote, onDeleteQuote, onUpdateProfile }) => {
  const [isGeneratingProfile, setIsGeneratingProfile] = useState(false);
  const [showProfile, setShowProfile] = useState(false);

  const handleGenerateProfile = async (e?: React.MouseEvent) => {
    e?.stopPropagation();
    setIsGeneratingProfile(true);
    try {
      const profile = await generateAuthorProfile(group.author, group.quotes);
      onUpdateProfile(group.author, profile);
      // 如果原本沒顯示人物誌，生成後自動顯示
      if (!group.profile) setShowProfile(true);
    } catch (error) {
      console.error("Profile generation failed", error);
      alert("分析失敗，請檢查 API 金鑰或網路狀態。");
    } finally {
      setIsGeneratingProfile(false);
    }
  };

  const sortedQuotes = [...group.quotes].sort((a, b) => b.timestamp - a.timestamp);

  return (
    <div className="bg-white rounded-[2.5rem] shadow-sm border border-purple-50 overflow-hidden flex flex-col h-full hover:shadow-xl transition-all duration-500">
      <div className="p-8 pb-4">
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center gap-4">
            <div className={`w-14 h-14 rounded-2xl flex items-center justify-center font-black text-xl bg-gradient-to-br from-indigo-100 to-indigo-200 text-indigo-600 shadow-lg`}>
              {group.author.charAt(0).toUpperCase()}
            </div>
            <div>
              <h3 className="text-xl font-black text-slate-800 tracking-tight">{group.author}</h3>
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-0.5">觀察樣本 #{group.quotes.length}</p>
            </div>
          </div>

          <div className="flex items-center gap-1.5">
            {group.profile && (
              <button 
                onClick={handleGenerateProfile}
                disabled={isGeneratingProfile}
                className="p-2.5 rounded-full bg-slate-50 text-slate-400 hover:bg-indigo-50 hover:text-indigo-500 transition-all border border-slate-100 disabled:opacity-50"
                title="重新整理人物誌"
              >
                <svg className={`w-4 h-4 ${isGeneratingProfile ? 'animate-spin' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
                </svg>
              </button>
            )}
            <button 
              onClick={group.profile ? () => setShowProfile(true) : (e) => handleGenerateProfile(e)}
              disabled={isGeneratingProfile}
              className="px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-widest transition-all shadow-md bg-indigo-50 text-indigo-500 hover:bg-indigo-600 hover:text-white disabled:opacity-50"
            >
              {isGeneratingProfile && !group.profile ? '深度剖析中...' : group.profile ? '查看人物誌' : '啟動行為分析'}
            </button>
          </div>
        </div>

        {group.profile && (
          <div className="bg-indigo-50/50 rounded-[1.5rem] p-4 border border-indigo-100/30 mb-4">
            <div className="flex justify-between items-center mb-1">
              <span className="text-[9px] font-black text-indigo-400 uppercase tracking-widest">發作規律</span>
              <span className="text-[8px] bg-white px-1.5 py-0.5 rounded text-indigo-300 border border-indigo-50">{group.profile.activeTimePattern}</span>
            </div>
            <p className="text-xs font-bold text-slate-700 italic">「{group.profile.characterType}」</p>
          </div>
        )}
      </div>

      <div className="flex-1 overflow-y-auto max-h-[500px] px-8 pb-8 space-y-3 custom-scrollbar">
        {sortedQuotes.map((quote, index) => (
          <QuoteItem 
            key={quote.id} 
            quote={quote} 
            allQuotes={allQuotes}
            onUpdate={onUpdateQuote} 
            onDelete={onDeleteQuote} 
          />
        ))}
      </div>

      {showProfile && group.profile && (
        <ProfileModal 
          author={group.author} 
          profile={group.profile} 
          onClose={() => setShowProfile(false)} 
          onRefresh={handleGenerateProfile}
          isRefreshing={isGeneratingProfile}
        />
      )}
    </div>
  );
};

export default AuthorCard;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Quote, AuthorGroup, AuthorProfile, AppDataBackup, MyProfile } from './types';
import AuthorCard from './components/AuthorCard';
import AddQuoteModal from './components/AddQuoteModal';
import MyProfileModal from './components/MyProfileModal';
import { generateMyProfile } from './services/geminiService';

const STORAGE_KEY = 'human-logs-v3-quotes';
const PROFILES_KEY = 'human-logs-v3-profiles';
const MY_PROFILE_KEY = 'human-logs-v3-myprofile';
const APP_VERSION = '3.3.0';

const App: React.FC = () => {
  const [quotes, setQuotes] = useState<Quote[]>([]);
  const [profiles, setProfiles] = useState<Record<string, AuthorProfile>>({});
  const [myProfile, setMyProfile] = useState<MyProfile | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMyProfileModalOpen, setIsMyProfileModalOpen] = useState(false);
  const [isGeneratingMyProfile, setIsGeneratingMyProfile] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [showSyncMenu, setShowSyncMenu] = useState(false);
  const [selectedAuthor, setSelectedAuthor] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const savedQuotes = localStorage.getItem(STORAGE_KEY);
    const savedProfiles = localStorage.getItem(PROFILES_KEY);
    const savedMyProfile = localStorage.getItem(MY_PROFILE_KEY);
    if (savedQuotes) {
      try {
        const parsed = JSON.parse(savedQuotes);
        setQuotes(Array.isArray(parsed) ? parsed : []);
      } catch (e) { console.error("Restore failed", e); }
    }
    if (savedProfiles) {
      try {
        setProfiles(JSON.parse(savedProfiles));
      } catch (e) { console.error("Restore profiles failed", e); }
    }
    if (savedMyProfile) {
      try {
        setMyProfile(JSON.parse(savedMyProfile));
      } catch (e) { console.error("Restore my profile failed", e); }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(quotes));
  }, [quotes]);

  useEffect(() => {
    localStorage.setItem(PROFILES_KEY, JSON.stringify(profiles));
  }, [profiles]);

  useEffect(() => {
    if (myProfile) localStorage.setItem(MY_PROFILE_KEY, JSON.stringify(myProfile));
  }, [myProfile]);

  const addQuote = (newQuote: Quote) => setQuotes(prev => [newQuote, ...prev]);
  const updateQuote = (updatedQuote: Quote) => setQuotes(prev => prev.map(q => q.id === updatedQuote.id ? updatedQuote : q));
  const deleteQuote = (id: string) => setQuotes(prev => prev.filter(q => q.id !== id));

  const updateProfile = (author: string, profile: AuthorProfile | null) => {
    setProfiles(prev => {
      const next = { ...prev };
      if (profile === null) delete next[author];
      else next[author] = profile;
      return next;
    });
  };

  const handleGenerateMyProfile = async () => {
    if (quotes.filter(q => q.aiAnalysis).length === 0) {
      alert("請先對至少一則記錄進行「關係衝突剖析」，AI 才能建立您的畫像。");
      return;
    }

    setIsGeneratingMyProfile(true);
    try {
      const profile = await generateMyProfile(quotes);
      setMyProfile(profile);
      // 生成完畢後，如果是第一次則打開，如果已經打開則更新數據
      setIsMyProfileModalOpen(true);
    } catch (e) {
      console.error(e);
      alert("生成自畫像失敗。");
    } finally {
      setIsGeneratingMyProfile(false);
    }
  };

  const handleExport = () => {
    const data: AppDataBackup = { version: APP_VERSION, quotes, profiles, myProfile: myProfile || undefined, exportedAt: new Date().toISOString() };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `human-obs-${new Date().toISOString().split('T')[0]}.json`;
    a.click();
    URL.revokeObjectURL(url);
    setShowSyncMenu(false);
  };

  const handleCopyBackup = async () => {
    const data: AppDataBackup = { version: APP_VERSION, quotes, profiles, exportedAt: new Date().toISOString() };
    const base64Data = btoa(encodeURIComponent(JSON.stringify(data)));
    await navigator.clipboard.writeText(base64Data);
    alert('同步代碼已複製！');
    setShowSyncMenu(false);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data: AppDataBackup = JSON.parse(event.target?.result as string);
        if (data.quotes) {
          setQuotes(prev => {
            const existingIds = new Set(prev.map(q => q.id));
            const newOnes = data.quotes.filter(q => !existingIds.has(q.id));
            return [...newOnes, ...prev].sort((a, b) => b.timestamp - a.timestamp);
          });
          if (data.profiles) setProfiles(prev => ({ ...prev, ...data.profiles }));
          if (data.myProfile) setMyProfile(data.myProfile);
          alert('匯入成功！');
        }
      } catch (e) { alert('匯入格式錯誤'); }
      setShowSyncMenu(false);
    };
    reader.readAsText(file);
  };

  const allGroups = useMemo(() => {
    const groups: Record<string, AuthorGroup> = {};
    quotes.forEach(q => {
      if (!groups[q.author]) groups[q.author] = { author: q.author, quotes: [], lastUpdate: 0, profile: profiles[q.author] };
      groups[q.author].quotes.push(q);
      if (q.timestamp > groups[q.author].lastUpdate) groups[q.author].lastUpdate = q.timestamp;
    });
    return Object.values(groups).sort((a, b) => b.lastUpdate - a.lastUpdate);
  }, [quotes, profiles]);

  const filteredGroups = useMemo(() => {
    const s = searchQuery.toLowerCase();
    if (!s) return allGroups;
    return allGroups.filter(g => 
      g.author.toLowerCase().includes(s) || 
      g.quotes.some(q => q.content.toLowerCase().includes(s) || q.tags.some(t => t.toLowerCase().includes(s)))
    );
  }, [allGroups, searchQuery]);

  const existingAuthors = useMemo(() => Array.from(new Set(quotes.map(q => q.author))).sort(), [quotes]);

  const avatarColors = [
    'from-indigo-100 to-indigo-200 text-indigo-600',
    'from-emerald-100 to-emerald-200 text-emerald-600',
    'from-rose-100 to-rose-200 text-rose-600',
    'from-amber-100 to-amber-200 text-amber-600',
