              const colorIdx = group.author.length % avatarColors.length;
              return (
                <button
                  key={group.author}
                  onClick={() => setSelectedAuthor(group.author)}
                  className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-purple-50 hover:shadow-xl hover:shadow-purple-100/50 hover:-translate-y-1 transition-all flex flex-col items-center text-center group"
                >
                  <div className={`w-20 h-20 rounded-3xl flex items-center justify-center font-black text-2xl bg-gradient-to-br shadow-md mb-4 ${avatarColors[colorIdx]}`}>
                    {group.author.charAt(0).toUpperCase()}
                  </div>
                  <h3 className="text-sm font-black text-slate-800 tracking-tight">{group.author}</h3>
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">
                    {group.quotes.length} 則紀錄
                  </p>
                  {group.profile && (
                    <span className="mt-3 px-2 py-1 bg-indigo-50 text-indigo-500 text-[8px] font-black rounded-lg border border-indigo-100 uppercase line-clamp-1">
                      {group.profile.characterType}
                    </span>
                  )}
                </button>
              );
            })}
          </div>
        )}
      </main>

      <button
        onClick={() => setIsModalOpen(true)}
        className="sm:hidden fixed bottom-8 right-8 w-16 h-16 bg-slate-900 text-white rounded-full flex items-center justify-center shadow-2xl shadow-indigo-200 z-40 active:scale-90 transition-transform"
        aria-label="新增紀錄"
      >
        <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4" /></svg>
      </button>

      {isModalOpen && (
        <AddQuoteModal onAdd={addQuote} onClose={() => setIsModalOpen(false)} existingAuthors={existingAuthors} />
      )}

      {isMyProfileModalOpen && myProfile && (
        <MyProfileModal 
          profile={myProfile} 
          onClose={() => setIsMyProfileModalOpen(false)} 
          onRefresh={handleGenerateMyProfile}
          isRefreshing={isGeneratingMyProfile}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Quote, AuthorGroup, AuthorProfile, AppDataBackup, MyProfile } from './types';
import AuthorCard from './components/AuthorCard';
import AddQuoteModal from './components/AddQuoteModal';
import MyProfileModal from './components/MyProfileModal';
import { generateMyProfile } from './services/geminiService';

const STORAGE_KEY = 'human-logs-v3-quotes';
const PROFILES_KEY = 'human-logs-v3-profiles';
const MY_PROFILE_KEY = 'human-logs-v3-myprofile';
const APP_VERSION = '3.3.0';

type SortType = 'lastUpdate' | 'frequency';

const App: React.FC = () => {
  const [quotes, setQuotes] = useState<Quote[]>([]);
  const [profiles, setProfiles] = useState<Record<string, AuthorProfile>>({});
  const [myProfile, setMyProfile] = useState<MyProfile | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMyProfileModalOpen, setIsMyProfileModalOpen] = useState(false);
  const [isGeneratingMyProfile, setIsGeneratingMyProfile] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [sortBy, setSortBy] = useState<SortType>('lastUpdate');
  const [showSyncMenu, setShowSyncMenu] = useState(false);
  const [selectedAuthor, setSelectedAuthor] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const savedQuotes = localStorage.getItem(STORAGE_KEY);
    const savedProfiles = localStorage.getItem(PROFILES_KEY);
    const savedMyProfile = localStorage.getItem(MY_PROFILE_KEY);
    if (savedQuotes) {
      try {
        const parsed = JSON.parse(savedQuotes);
        setQuotes(Array.isArray(parsed) ? parsed : []);
      } catch (e) { console.error("Restore failed", e); }
    }
    if (savedProfiles) {
      try {
        setProfiles(JSON.parse(savedProfiles));
      } catch (e) { console.error("Restore profiles failed", e); }
    }
    if (savedMyProfile) {
      try {
        setMyProfile(JSON.parse(savedMyProfile));
      } catch (e) { console.error("Restore my profile failed", e); }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(quotes));
  }, [quotes]);

  useEffect(() => {
    localStorage.setItem(PROFILES_KEY, JSON.stringify(profiles));
  }, [profiles]);

  useEffect(() => {
    if (myProfile) localStorage.setItem(MY_PROFILE_KEY, JSON.stringify(myProfile));
  }, [myProfile]);

  const addQuote = (newQuote: Quote) => setQuotes(prev => [newQuote, ...prev]);
  const updateQuote = (updatedQuote: Quote) => setQuotes(prev => prev.map(q => q.id === updatedQuote.id ? updatedQuote : q));
  const deleteQuote = (id: string) => setQuotes(prev => prev.filter(q => q.id !== id));

  const updateProfile = (author: string, profile: AuthorProfile | null) => {
    setProfiles(prev => {
      const next = { ...prev };
      if (profile === null) delete next[author];
      else next[author] = profile;
      return next;
    });
  };

  const handleGenerateMyProfile = async () => {
    if (quotes.filter(q => q.aiAnalysis).length === 0) {
      alert("請先對至少一則記錄進行「關係衝突剖析」，AI 才能建立您的畫像。");
      return;
    }

    setIsGeneratingMyProfile(true);
    try {
      const profile = await generateMyProfile(quotes);
      setMyProfile(profile);
      setIsMyProfileModalOpen(true);
    } catch (e) {
      console.error(e);
      alert("生成自畫像失敗。");
    } finally {
      setIsGeneratingMyProfile(false);
    }
  };

  const handleExport = () => {
    const data: AppDataBackup = { version: APP_VERSION, quotes, profiles, myProfile: myProfile || undefined, exportedAt: new Date().toISOString() };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `human-obs-${new Date().toISOString().split('T')[0]}.json`;
    a.click();
    URL.revokeObjectURL(url);
    setShowSyncMenu(false);
  };

  const handleCopyBackup = async () => {
    const data: AppDataBackup = { version: APP_VERSION, quotes, profiles, exportedAt: new Date().toISOString() };
    const base64Data = btoa(encodeURIComponent(JSON.stringify(data)));
    await navigator.clipboard.writeText(base64Data);
    alert('同步代碼已複製！');
    setShowSyncMenu(false);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data: AppDataBackup = JSON.parse(event.target?.result as string);
        if (data.quotes) {
          setQuotes(prev => {
            const existingIds = new Set(prev.map(q => q.id));
            const newOnes = data.quotes.filter(q => !existingIds.has(q.id));
            return [...newOnes, ...prev].sort((a, b) => b.timestamp - a.timestamp);
          });
          if (data.profiles) setProfiles(prev => ({ ...prev, ...data.profiles }));
          if (data.myProfile) setMyProfile(data.myProfile);
          alert('匯入成功！');
        }
      } catch (e) { alert('匯入格式錯誤'); }
      setShowSyncMenu(false);
    };
    reader.readAsText(file);
  };

  const allGroups = useMemo(() => {
    const groups: Record<string, AuthorGroup> = {};
    quotes.forEach(q => {
      if (!groups[q.author]) {
        groups[q.author] = { author: q.author, quotes: [], lastUpdate: 0, profile: profiles[q.author] };
      }
      groups[q.author].quotes.push(q);
      if (q.timestamp > groups[q.author].lastUpdate) groups[q.author].lastUpdate = q.timestamp;
    });

    const result = Object.values(groups);

    // 執行排序
    if (sortBy === 'lastUpdate') {
      return result.sort((a, b) => b.lastUpdate - a.lastUpdate);
    } else {
      return result.sort((a, b) => {
        const freqDiff = b.quotes.length - a.quotes.length;
        return freqDiff !== 0 ? freqDiff : b.lastUpdate - a.lastUpdate;
      });
    }
  }, [quotes, profiles, sortBy]);

  const filteredGroups = useMemo(() => {
    const s = searchQuery.trim().toLowerCase();
    if (!s) return allGroups;

    // 精準搜尋邏輯
    const isAuthorSearch = s.startsWith('author:');
    const isContentSearch = s.startsWith('content:');
    const term = isAuthorSearch ? s.replace('author:', '') : (isContentSearch ? s.replace('content:', '') : s);

    return allGroups.filter(g => {
      const matchAuthor = g.author.toLowerCase().includes(term);
      const matchContent = g.quotes.some(q => 
        q.content.toLowerCase().includes(term) || 
        q.tags.some(t => t.toLowerCase().includes(term)) ||
        q.aiAnalysis?.insight.toLowerCase().includes(term)
      );

      if (isAuthorSearch) return matchAuthor;
      if (isContentSearch) return matchContent;
      return matchAuthor || matchContent;
    });
  }, [allGroups, searchQuery]);

  const existingAuthors = useMemo(() => Array.from(new Set(quotes.map(q => q.author))).sort(), [quotes]);

  const avatarColors = [
    'from-indigo-100 to-indigo-200 text-indigo-600',
    'from-emerald-100 to-emerald-200 text-emerald-600',
    'from-rose-100 to-rose-200 text-rose-600',
    'from-amber-100 to-amber-200 text-amber-600',
    'from-purple-100 to-purple-200 text-purple-600'
  ];

  return (
