              <input
                type="text"
                placeholder="搜尋內容... (可用 author: 或 content:)"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full bg-purple-50/50 border border-transparent focus:border-purple-200 focus:bg-white rounded-full px-10 py-2.5 text-sm transition-all outline-none"
              />
              <svg className="absolute left-3.5 top-3 w-4 h-4 text-purple-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
              {searchQuery && (
                <button onClick={() => setSearchQuery('')} className="absolute right-3.5 top-3 text-purple-300 hover:text-purple-500">
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
              )}
            </div>

            {/* 排序切換器 */}
            <div className="hidden md:flex bg-purple-50 rounded-full p-1 border border-purple-100">
              <button 
                onClick={() => setSortBy('lastUpdate')}
                className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-[10px] font-black uppercase tracking-wider transition-all ${sortBy === 'lastUpdate' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
              >
                <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                時間
              </button>
              <button 
                onClick={() => setSortBy('frequency')}
                className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-[10px] font-black uppercase tracking-wider transition-all ${sortBy === 'frequency' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
              >
                <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" /></svg>
                頻率
              </button>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <button 
              onClick={myProfile ? () => setIsMyProfileModalOpen(true) : handleGenerateMyProfile}
              disabled={isGeneratingMyProfile}
              className={`flex items-center gap-2 px-5 py-2.5 rounded-full font-black text-[11px] uppercase tracking-[0.2em] transition-all shadow-lg ${
                isGeneratingMyProfile 
                ? 'bg-slate-100 text-slate-400 cursor-not-allowed' 
                : myProfile 
                  ? 'bg-gradient-to-r from-indigo-600 to-purple-600 text-white hover:scale-105 active:scale-95 shadow-indigo-100' 
                  : 'bg-white text-indigo-600 border border-indigo-200 hover:bg-indigo-50'
              }`}
            >
              {isGeneratingMyProfile ? (
                <div className="w-3 h-3 border-2 border-indigo-400 border-t-transparent rounded-full animate-spin"></div>
              ) : '👁️'}
              <span className="hidden sm:inline">{isGeneratingMyProfile ? '剖析中' : myProfile ? '自畫像' : '啟動鏡像'}</span>
            </button>

            <div className="relative">
              <button 
                onClick={() => setShowSyncMenu(!showSyncMenu)}
                className={`p-3 rounded-full transition-all ${showSyncMenu ? 'bg-indigo-600 text-white' : 'bg-indigo-50 text-indigo-500 hover:bg-indigo-100'}`}
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" /></svg>
              </button>

              {showSyncMenu && (
                <div className="absolute right-0 mt-3 w-48 bg-white rounded-3xl shadow-2xl border border-purple-50 p-2 animate-in fade-in zoom-in duration-200">
                  <button onClick={handleExport} className="w-full text-left px-4 py-3 hover:bg-purple-50 rounded-2xl text-xs font-bold text-slate-600 flex items-center gap-3">📤 匯出檔案</button>
                  <button onClick={handleCopyBackup} className="w-full text-left px-4 py-3 hover:bg-purple-50 rounded-2xl text-xs font-bold text-slate-600 flex items-center gap-3">📋 複製同步碼</button>
                  <button onClick={() => fileInputRef.current?.click()} className="w-full text-left px-4 py-3 hover:bg-purple-50 rounded-2xl text-xs font-bold text-slate-600 flex items-center gap-3 border-t border-purple-50 mt-1 pt-2">📥 從檔案匯入</button>
                  <input type="file" ref={fileInputRef} onChange={handleImport} className="hidden" accept=".json" />
                </div>
              )}
            </div>

            <button
              onClick={() => setIsModalOpen(true)}
              className="hidden sm:flex items-center gap-2 px-6 py-2.5 bg-slate-900 text-white rounded-full font-bold text-sm hover:bg-indigo-600 transition-all shadow-xl shadow-slate-200"
            >
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4" /></svg>
              新紀錄
            </button>
          </div>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 py-8">
        {quotes.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-32 animate-float">
            <div className="w-24 h-24 bg-white rounded-[2.5rem] shadow-xl flex items-center justify-center text-purple-200 mb-6 border border-purple-50">
              <span className="text-4xl">🧬</span>
            </div>
            <h2 className="text-2xl font-black text-slate-800">開始人類觀察</h2>
            <p className="text-slate-400 mt-2 text-center max-w-xs">點擊下方的按鈕，記錄下身邊那些「充滿性格」的對話吧！</p>
          </div>
        ) : selectedAuthor ? (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
            <button 
              onClick={() => setSelectedAuthor(null)}
              className="mb-8 flex items-center gap-2 text-slate-400 hover:text-indigo-600 transition-colors font-bold text-sm uppercase tracking-widest"
            >
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M15 19l-7-7 7-7" /></svg>
              返回名單
            </button>
            <div className="max-w-2xl mx-auto">
              {allGroups.filter(g => g.author === selectedAuthor).map(group => (
                <AuthorCard
                  key={group.author}
                  group={group}
                  allQuotes={quotes}
                  onUpdateQuote={updateQuote}
                  onDeleteQuote={deleteQuote}
                  onUpdateProfile={updateProfile}
                />
              ))}
            </div>
          </div>
        ) : filteredGroups.length === 0 ? (
          <div className="text-center py-32">
            <div className="text-4xl mb-4">🔍</div>
            <h3 className="text-xl font-bold text-slate-400">找不到符合條件的對象或內容</h3>
            <p className="text-slate-300 text-sm mt-2">嘗試更換關鍵字或清除篩選條件</p>
          </div>
        ) : (
          <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-6 animate-in fade-in duration-500">
            {filteredGroups.map(group => {
              const colorIdx = group.author.length % avatarColors.length;
              const lastDate = new Date(group.lastUpdate).toLocaleDateString('zh-TW', { month: 'short', day: 'numeric' });

              return (
                <button
                  key={group.author}
                  onClick={() => setSelectedAuthor(group.author)}
                  className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-purple-50 hover:shadow-xl hover:shadow-purple-100/50 hover:-translate-y-1 transition-all flex flex-col items-center text-center group relative overflow-hidden"
                >
                  <div className={`w-20 h-20 rounded-3xl flex items-center justify-center font-black text-2xl bg-gradient-to-br shadow-md mb-4 ${avatarColors[colorIdx]}`}>
                    {group.author.charAt(0).toUpperCase()}
                  </div>
                  <h3 className="text-sm font-black text-slate-800 tracking-tight">{group.author}</h3>

                  {/* 動態資訊顯示 */}
                  <div className="mt-2 flex flex-col gap-1">
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                      {sortBy === 'frequency' ? `總紀錄 ${group.quotes.length} 則` : `更新於 ${lastDate}`}
                    </p>
                    {sortBy === 'frequency' && (
                      <p className="text-[9px] text-indigo-300 font-mono italic">{lastDate}</p>
                    )}
                    {sortBy === 'lastUpdate' && (
                      <p className="text-[9px] text-indigo-300 font-mono italic">{group.quotes.length} 則</p>
                    )}
                  </div>

                  {group.profile && (
                    <span className="mt-3 px-2 py-1 bg-indigo-50 text-indigo-500 text-[8px] font-black rounded-lg border border-indigo-100 uppercase line-clamp-1 w-full">
                      {group.profile.characterType}
                    </span>
                  )}
                </button>
              );
            })}
          </div>
        )}
      </main>

      <button
        onClick={() => setIsModalOpen(true)}
        className="sm:hidden fixed bottom-8 right-8 w-16 h-16 bg-slate-900 text-white rounded-full flex items-center justify-center shadow-2xl shadow-indigo-200 z-40 active:scale-90 transition-transform"
      >
        <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4" /></svg>
      </button>

      {isModalOpen && (
        <AddQuoteModal onAdd={addQuote} onClose={() => setIsModalOpen(false)} existingAuthors={existingAuthors} />
      )}

      {isMyProfileModalOpen && myProfile && (
        <MyProfileModal 
          profile={myProfile} 
          onClose={() => setIsMyProfileModalOpen(false)} 
          onRefresh={handleGenerateMyProfile}
          isRefreshing={isGeneratingMyProfile}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Quote, AuthorGroup, AuthorProfile, AppDataBackup, MyProfile } from './types';
import AuthorCard from './components/AuthorCard';
import AddQuoteModal from './components/AddQuoteModal';
import MyProfileModal from './components/MyProfileModal';
import { generateMyProfile } from './services/geminiService';

const STORAGE_KEY = 'human-logs-v3-quotes';
const PROFILES_KEY = 'human-logs-v3-profiles';
const MY_PROFILE_KEY = 'human-logs-v3-myprofile';
const APP_VERSION = '3.3.0';

type SortType = 'lastUpdate' | 'frequency';

const App: React.FC = () => {
  const [quotes, setQuotes] = useState<Quote[]>([]);
  const [profiles, setProfiles] = useState<Record<string, AuthorProfile>>({});
  const [myProfile, setMyProfile] = useState<MyProfile | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMyProfileModalOpen, setIsMyProfileModalOpen] = useState(false);
  const [isGeneratingMyProfile, setIsGeneratingMyProfile] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [sortBy, setSortBy] = useState<SortType>('lastUpdate');
  const [showSyncMenu, setShowSyncMenu] = useState(false);
  const [selectedAuthor, setSelectedAuthor] = useState<string | null>(null);
  const [feedbackMessage, setFeedbackMessage] = useState<string | null>(null);
  const [isShaking, setIsShaking] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const savedQuotes = localStorage.getItem(STORAGE_KEY);
    const savedProfiles = localStorage.getItem(PROFILES_KEY);
    const savedMyProfile = localStorage.getItem(MY_PROFILE_KEY);
    if (savedQuotes) {
      try {
        const parsed = JSON.parse(savedQuotes);
        setQuotes(Array.isArray(parsed) ? parsed : []);
      } catch (e) { console.error("Restore failed", e); }
    }
    if (savedProfiles) {
      try {
        setProfiles(JSON.parse(savedProfiles));
      } catch (e) { console.error("Restore profiles failed", e); }
    }
    if (savedMyProfile) {
      try {
        setMyProfile(JSON.parse(savedMyProfile));
      } catch (e) { console.error("Restore my profile failed", e); }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(quotes));
  }, [quotes]);

  useEffect(() => {
    localStorage.setItem(PROFILES_KEY, JSON.stringify(profiles));
  }, [profiles]);

  useEffect(() => {
    if (myProfile) localStorage.setItem(MY_PROFILE_KEY, JSON.stringify(myProfile));
  }, [myProfile]);

  const addQuote = (newQuote: Quote) => setQuotes(prev => [newQuote, ...prev]);
  const updateQuote = (updatedQuote: Quote) => setQuotes(prev => prev.map(q => q.id === updatedQuote.id ? updatedQuote : q));
  const deleteQuote = (id: string) => setQuotes(prev => prev.filter(q => q.id !== id));

  const updateProfile = (author: string, profile: AuthorProfile | null) => {
    setProfiles(prev => {
      const next = { ...prev };
      if (profile === null) delete next[author];
      else next[author] = profile;
      return next;
    });
  };

  const triggerFeedback = (msg: string) => {
    setFeedbackMessage(msg);
    setIsShaking(true);
    setTimeout(() => {
      setIsShaking(false);
    }, 500);
    setTimeout(() => {
      setFeedbackMessage(null);
    }, 4000);
  };

  const handleGenerateMyProfile = async () => {
    const analyzedCount = quotes.filter(q => q.aiAnalysis).length;

    if (analyzedCount === 0) {
      triggerFeedback("數據不足：請先對至少一則紀錄進行「深度分析」以開啟鏡像協定。");
      return;
    }

    if (analyzedCount < 3 && !myProfile) {
      // 雖然可以生成，但提醒數據越多越準
      console.log("提示：數據較少，畫像可能不夠精確。");
    }

    setIsGeneratingMyProfile(true);
    try {
      const profile = await generateMyProfile(quotes);
      setMyProfile(profile);
      setIsMyProfileModalOpen(true);
    } catch (e) {
      console.error(e);
      triggerFeedback("鏡像校準失敗：請檢查網路連線或 AI 金鑰狀態。");
    } finally {
      setIsGeneratingMyProfile(false);
    }
  };

  const handleExport = () => {
    const data: AppDataBackup = { version: APP_VERSION, quotes, profiles, myProfile: myProfile || undefined, exportedAt: new Date().toISOString() };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `human-obs-${new Date().toISOString().split('T')[0]}.json`;
    a.click();
    URL.revokeObjectURL(url);
    setShowSyncMenu(false);
  };

  const handleCopyBackup = async () => {
    const data: AppDataBackup = { version: APP_VERSION, quotes, profiles, exportedAt: new Date().toISOString() };
    const base64Data = btoa(encodeURIComponent(JSON.stringify(data)));
    await navigator.clipboard.writeText(base64Data);
    alert('同步代碼已複製！');
    setShowSyncMenu(false);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data: AppDataBackup = JSON.parse(event.target?.result as string);
        if (data.quotes) {
          setQuotes(prev => {
            const existingIds = new Set(prev.map(q => q.id));
            const newOnes = data.quotes.filter(q => !existingIds.has(q.id));
            return [...newOnes, ...prev].sort((a, b) => b.timestamp - a.timestamp);
          });
          if (data.profiles) setProfiles(prev => ({ ...prev, ...data.profiles }));
          if (data.myProfile) setMyProfile(data.myProfile);
          alert('匯入成功！');
        }
      } catch (e) { alert('匯入格式錯誤'); }
      setShowSyncMenu(false);
    };
    reader.readAsText(file);
  };

  const allGroups = useMemo(() => {
    const groups: Record<string, AuthorGroup> = {};
    quotes.forEach(q => {
      if (!groups[q.author]) {
        groups[q.author] = { author: q.author, quotes: [], lastUpdate: 0, profile: profiles[q.author] };
      }
      groups[q.author].quotes.push(q);
      if (q.timestamp > groups[q.author].lastUpdate) groups[q.author].lastUpdate = q.timestamp;
    });

    const result = Object.values(groups);

    // 執行排序
    if (sortBy === 'lastUpdate') {
      return result.sort((a, b) => b.lastUpdate - a.lastUpdate);
    } else {
      return result.sort((a, b) => {
        const freqDiff = b.quotes.length - a.quotes.length;
        return freqDiff !== 0 ? freqDiff : b.lastUpdate - a.lastUpdate;
      });
    }
  }, [quotes, profiles, sortBy]);

  const filteredGroups = useMemo(() => {
    const s = searchQuery.trim().toLowerCase();
    if (!s) return allGroups;

    // 精準搜尋邏輯
    const isAuthorSearch = s.startsWith('author:');
    const isContentSearch = s.startsWith('content:');
    const term = isAuthorSearch ? s.replace('author:', '') : (isContentSearch ? s.replace('content:', '') : s);

    return allGroups.filter(g => {
      const matchAuthor = g.author.toLowerCase().includes(term);
      const matchContent = g.quotes.some(q => 
        q.content.toLowerCase().includes(term) || 
        q.tags.some(t => t.toLowerCase().includes(term)) ||
        q.aiAnalysis?.insight.toLowerCase().includes(term)
      );

      if (isAuthorSearch) return matchAuthor;
      if (isContentSearch) return matchContent;
      return matchAuthor || matchContent;
    });
  }, [allGroups, searchQuery]);

  const existingAuthors = useMemo(() => Array.from(new Set(quotes.map(q => q.author))).sort(), [quotes]);

  const avatarColors = [
    'from-indigo-100 to-indigo-200 text-indigo-600',
    'from-emerald-100 to-emerald-200 text-emerald-600',
    'from-rose-100 to-rose-200 text-rose-600',
    'from-amber-100 to-amber-200 text-amber-600',
    'from-purple-100 to-purple-200 text-purple-600'
  ];

  return (
    <div className="min-h-screen bg-[#F8F7FF] pb-32">
      <nav className="sticky top-0 z-50 bg-white/70 backdrop-blur-xl border-b border-purple-100/50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 h-20 flex items-center justify-between gap-4">
          <div className="flex items-center gap-2 shrink-0 cursor-pointer" onClick={() => setSelectedAuthor(null)}>
            <div className="w-10 h-10 bg-indigo-500 rounded-2xl flex items-center justify-center text-white shadow-lg shadow-indigo-100 rotate-3 transition-transform hover:rotate-0">
              <span className="text-xl">🖋️</span>
            </div>
            <h1 className="hidden sm:block text-lg font-black text-slate-800 tracking-tight">觀察日誌</h1>
          </div>

          {/* 搜尋區優化 */}
          <div className="flex-1 max-w-xl flex items-center gap-3">
            <div className="flex-1 relative group">
              <input
                type="text"
                placeholder="搜尋內容... (可用 author: 或 content:)"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full bg-purple-50/50 border border-transparent focus:border-purple-200 focus:bg-white rounded-full px-10 py-2.5 text-sm transition-all outline-none"
              />
              <svg className="absolute left-3.5 top-3 w-4 h-4 text-purple-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
              {searchQuery && (
                <button onClick={() => setSearchQuery('')} className="absolute right-3.5 top-3 text-purple-300 hover:text-purple-500">
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
              )}
            </div>

            {/* 排序切換器 */}
            <div className="hidden md:flex bg-purple-50 rounded-full p-1 border border-purple-100">
              <button 
                onClick={() => setSortBy('lastUpdate')}
                className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-[10px] font-black uppercase tracking-wider transition-all ${sortBy === 'lastUpdate' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
              >
                <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                時間
              </button>
              <button 
                onClick={() => setSortBy('frequency')}
                className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-[10px] font-black uppercase tracking-wider transition-all ${sortBy === 'frequency' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
              >
                <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" /></svg>
                頻率
              </button>
            </div>
          </div>

          <div className="flex items-center gap-2 relative">
            {/* 提示訊息 */}
            {feedbackMessage && (
              <div className="absolute top-full mt-3 right-0 w-64 bg-slate-900 text-white p-3 rounded-2xl shadow-2xl text-[11px] font-bold z-[100] animate-in fade-in slide-in-from-top-2 duration-300 border border-white/10">
                <div className="flex items-start gap-2">
                  <span className="text-amber-400 text-sm">⚠️</span>
                  <p className="leading-relaxed">{feedbackMessage}</p>
                </div>
                <div className="absolute -top-1.5 right-6 w-3 h-3 bg-slate-900 rotate-45 border-l border-t border-white/10"></div>
              </div>
            )}

            <button 
              onClick={myProfile ? () => setIsMyProfileModalOpen(true) : handleGenerateMyProfile}
              disabled={isGeneratingMyProfile}
              className={`flex items-center gap-2 px-5 py-2.5 rounded-full font-black text-[11px] uppercase tracking-[0.2em] transition-all shadow-lg ${
                isShaking ? 'animate-[shake_0.5s_ease-in-out]' : ''
              } ${
                isGeneratingMyProfile 
                ? 'bg-slate-100 text-slate-400 cursor-not-allowed' 
                : myProfile 
                  ? 'bg-gradient-to-r from-indigo-600 to-purple-600 text-white hover:scale-105 active:scale-95 shadow-indigo-100' 
                  : 'bg-white text-indigo-600 border border-indigo-200 hover:bg-indigo-50'
              }`}
            >
              {isGeneratingMyProfile ? (
                <div className="w-3 h-3 border-2 border-indigo-400 border-t-transparent rounded-full animate-spin"></div>
              ) : '👁️'}
              <span className="hidden sm:inline">{isGeneratingMyProfile ? '剖析中' : myProfile ? '自畫像' : '啟動鏡像'}</span>
            </button>

            <div className="relative">
              <button 
                onClick={() => setShowSyncMenu(!showSyncMenu)}
                className={`p-3 rounded-full transition-all ${showSyncMenu ? 'bg-indigo-600 text-white' : 'bg-indigo-50 text-indigo-500 hover:bg-indigo-100'}`}
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" /></svg>
              </button>

              {showSyncMenu && (
                <div className="absolute right-0 mt-3 w-48 bg-white rounded-3xl shadow-2xl border border-purple-50 p-2 animate-in fade-in zoom-in duration-200">
                  <button onClick={handleExport} className="w-full text-left px-4 py-3 hover:bg-purple-50 rounded-2xl text-xs font-bold text-slate-600 flex items-center gap-3">📤 匯出檔案</button>
                  <button onClick={handleCopyBackup} className="w-full text-left px-4 py-3 hover:bg-purple-50 rounded-2xl text-xs font-bold text-slate-600 flex items-center gap-3">📋 複製同步碼</button>
                  <button onClick={() => fileInputRef.current?.click()} className="w-full text-left px-4 py-3 hover:bg-purple-50 rounded-2xl text-xs font-bold text-slate-600 flex items-center gap-3 border-t border-purple-50 mt-1 pt-2">📥 從檔案匯入</button>
                  <input type="file" ref={fileInputRef} onChange={handleImport} className="hidden" accept=".json" />
                </div>
              )}
            </div>

            <button
              onClick={() => setIsModalOpen(true)}
              className="hidden sm:flex items-center gap-2 px-6 py-2.5 bg-slate-900 text-white rounded-full font-bold text-sm hover:bg-indigo-600 transition-all shadow-xl shadow-slate-200"
            >
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4" /></svg>
              新紀錄
            </button>
          </div>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 py-8">
        {quotes.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-32 animate-float">
            <div className="w-24 h-24 bg-white rounded-[2.5rem] shadow-xl flex items-center justify-center text-purple-200 mb-6 border border-purple-50">
              <span className="text-4xl">🧬</span>
            </div>
            <h2 className="text-2xl font-black text-slate-800">開始人類觀察</h2>
            <p className="text-slate-400 mt-2 text-center max-w-xs">點擊下方的按鈕，記錄下身邊那些「充滿性格」的對話吧！</p>
          </div>
        ) : selectedAuthor ? (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
            <button 
              onClick={() => setSelectedAuthor(null)}
              className="mb-8 flex items-center gap-2 text-slate-400 hover:text-indigo-600 transition-colors font-bold text-sm uppercase tracking-widest"
            >
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M15 19l-7-7 7-7" /></svg>
              返回名單
            </button>
            <div className="max-w-2xl mx-auto">
              {allGroups.filter(g => g.author === selectedAuthor).map(group => (
                <AuthorCard
                  key={group.author}
                  group={group}
                  allQuotes={quotes}
                  onUpdateQuote={updateQuote}
                  onDeleteQuote={deleteQuote}
                  onUpdateProfile={updateProfile}
                />
              ))}
            </div>
          </div>
        ) : filteredGroups.length === 0 ? (
          <div className="text-center py-32">
            <div className="text-4xl mb-4">🔍</div>
            <h3 className="text-xl font-bold text-slate-400">找不到符合條件的對象或內容</h3>
            <p className="text-slate-300 text-sm mt-2">嘗試更換關鍵字或清除篩選條件</p>
          </div>
        ) : (
          <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-6 animate-in fade-in duration-500">
            {filteredGroups.map(group => {
              const colorIdx = group.author.length % avatarColors.length;
              const lastDate = new Date(group.lastUpdate).toLocaleDateString('zh-TW', { month: 'short', day: 'numeric' });

              return (
                <button
                  key={group.author}
                  onClick={() => setSelectedAuthor(group.author)}
                  className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-purple-50 hover:shadow-xl hover:shadow-purple-100/50 hover:-translate-y-1 transition-all flex flex-col items-center text-center group relative overflow-hidden"
                >
                  <div className={`w-20 h-20 rounded-3xl flex items-center justify-center font-black text-2xl bg-gradient-to-br shadow-md mb-4 ${avatarColors[colorIdx]}`}>
                    {group.author.charAt(0).toUpperCase()}
                  </div>
                  <h3 className="text-sm font-black text-slate-800 tracking-tight">{group.author}</h3>

                  {/* 動態資訊顯示 */}
                  <div className="mt-2 flex flex-col gap-1">
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                      {sortBy === 'frequency' ? `總紀錄 ${group.quotes.length} 則` : `更新於 ${lastDate}`}
                    </p>
                    {sortBy === 'frequency' && (
                      <p className="text-[9px] text-indigo-300 font-mono italic">{lastDate}</p>
                    )}
                    {sortBy === 'lastUpdate' && (
                      <p className="text-[9px] text-indigo-300 font-mono italic">{group.quotes.length} 則</p>
                    )}
                  </div>

                  {group.profile && (
                    <span className="mt-3 px-2 py-1 bg-indigo-50 text-indigo-500 text-[8px] font-black rounded-lg border border-indigo-100 uppercase line-clamp-1 w-full">
                      {group.profile.characterType}
                    </span>
                  )}
                </button>
              );
            })}
          </div>
        )}
      </main>

      <button
        onClick={() => setIsModalOpen(true)}
        className="sm:hidden fixed bottom-8 right-8 w-16 h-16 bg-slate-900 text-white rounded-full flex items-center justify-center shadow-2xl shadow-indigo-200 z-40 active:scale-90 transition-transform"
      >
        <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4" /></svg>
      </button>

      {isModalOpen && (
        <AddQuoteModal onAdd={addQuote} onClose={() => setIsModalOpen(false)} existingAuthors={existingAuthors} />
      )}

      {isMyProfileModalOpen && myProfile && (
        <MyProfileModal 
          profile={myProfile} 
          onClose={() => setIsMyProfileModalOpen(false)} 
          onRefresh={handleGenerateMyProfile}
          isRefreshing={isGeneratingMyProfile}
        />
      )}

      <style>{`
        @keyframes shake {
          0%, 100% { transform: translateX(0); }
          25% { transform: translateX(-5px); }
          75% { transform: translateX(5px); }
        }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Quote, AuthorGroup, AuthorProfile, AppDataBackup, MyProfile } from './types';
import AuthorCard from './components/AuthorCard';
import AddQuoteModal from './components/AddQuoteModal';
import MyProfileModal from './components/MyProfileModal';
import { generateMyProfile } from './services/geminiService';

const STORAGE_KEY = 'human-logs-v3-quotes';
const PROFILES_KEY = 'human-logs-v3-profiles';
const MY_PROFILE_KEY = 'human-logs-v3-myprofile';
const APP_VERSION = '3.3.0';

type SortType = 'lastUpdate' | 'frequency';

const App: React.FC = () => {
  const [quotes, setQuotes] = useState<Quote[]>([]);
  const [profiles, setProfiles] = useState<Record<string, AuthorProfile>>({});
  const [myProfile, setMyProfile] = useState<MyProfile | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMyProfileModalOpen, setIsMyProfileModalOpen] = useState(false);
  const [isGeneratingMyProfile, setIsGeneratingMyProfile] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [sortBy, setSortBy] = useState<SortType>('lastUpdate');
  const [showSyncMenu, setShowSyncMenu] = useState(false);
  const [selectedAuthor, setSelectedAuthor] = useState<string | null>(null);
  const [feedbackMessage, setFeedbackMessage] = useState<string | null>(null);
  const [isShaking, setIsShaking] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const savedQuotes = localStorage.getItem(STORAGE_KEY);
    const savedProfiles = localStorage.getItem(PROFILES_KEY);
    const savedMyProfile = localStorage.getItem(MY_PROFILE_KEY);
    if (savedQuotes) {
      try {
        const parsed = JSON.parse(savedQuotes);
        setQuotes(Array.isArray(parsed) ? parsed : []);
      } catch (e) { console.error("Restore failed", e); }
    }
    if (savedProfiles) {
      try {
        setProfiles(JSON.parse(savedProfiles));
      } catch (e) { console.error("Restore profiles failed", e); }
    }
    if (savedMyProfile) {
      try {
        setMyProfile(JSON.parse(savedMyProfile));
      } catch (e) { console.error("Restore my profile failed", e); }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(quotes));
  }, [quotes]);

  useEffect(() => {
    localStorage.setItem(PROFILES_KEY, JSON.stringify(profiles));
  }, [profiles]);

  useEffect(() => {
    if (myProfile) localStorage.setItem(MY_PROFILE_KEY, JSON.stringify(myProfile));
  }, [myProfile]);

  const addQuote = (newQuote: Quote) => setQuotes(prev => [newQuote, ...prev]);
  const updateQuote = (updatedQuote: Quote) => setQuotes(prev => prev.map(q => q.id === updatedQuote.id ? updatedQuote : q));
  const deleteQuote = (id: string) => setQuotes(prev => prev.filter(q => q.id !== id));

  const updateProfile = (author: string, profile: AuthorProfile | null) => {
    setProfiles(prev => {
      const next = { ...prev };
      if (profile === null) delete next[author];
      else next[author] = profile;
      return next;
    });
  };

  const triggerFeedback = (msg: string) => {
    setFeedbackMessage(msg);
    setIsShaking(true);
    setTimeout(() => setIsShaking(false), 500);
    // 增加自動消失時間
    setTimeout(() => setFeedbackMessage(null), 5000);
  };

  const handleGenerateMyProfile = async () => {
    if (isGeneratingMyProfile) return;

    // 1. 基礎驗證：是否有任何紀錄
    if (quotes.length === 0) {
      triggerFeedback("鏡像失敗：目前沒有任何觀察紀錄，請先新增對話紀錄。");
      return;
    }

    // 2. 深度驗證：是否有已分析的資料
    const analyzedQuotes = quotes.filter(q => q.aiAnalysis);
    if (analyzedQuotes.length === 0) {
      triggerFeedback("深度不足：請先在紀錄中點擊「啟動深度分析」，讓 AI 掌握您的衝突邏輯。");
      return;
    }

    setIsGeneratingMyProfile(true);
    setFeedbackMessage(null);

    try {
      // 3. Pro 模型金鑰驗證 (依據規範)
      if (typeof window.aistudio !== 'undefined') {
        const hasKey = await window.aistudio.hasSelectedApiKey();
        if (!hasKey) {
          triggerFeedback("權限要求：Pro 模型需要選擇付費專案的 API Key。");
          await window.aistudio.openSelectKey();
          // 依照規範，開啟視窗後直接嘗試繼續
        }
      }

      const profile = await generateMyProfile(quotes);
      setMyProfile(profile);
      setIsMyProfileModalOpen(true);
    } catch (e: any) {
      console.error(e);
      const errorMsg = e.message || "";

      if (errorMsg.includes("Requested entity was not found")) {
        triggerFeedback("模型存取失敗：請重新選擇正確的 API Key。");
        if (typeof window.aistudio !== 'undefined') {
          await window.aistudio.openSelectKey();
        }
      } else {
        triggerFeedback("鏡像校準中斷：可能是網路不穩或 AI 處理超時，請稍後重試。");
      }
    } finally {
      setIsGeneratingMyProfile(false);
    }
  };

  const handleExport = () => {
    const data: AppDataBackup = { version: APP_VERSION, quotes, profiles, myProfile: myProfile || undefined, exportedAt: new Date().toISOString() };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `human-obs-${new Date().toISOString().split('T')[0]}.json`;
    a.click();
    URL.revokeObjectURL(url);
    setShowSyncMenu(false);
  };

  const handleCopyBackup = async () => {
    const data: AppDataBackup = { version: APP_VERSION, quotes, profiles, exportedAt: new Date().toISOString() };
    const base64Data = btoa(encodeURIComponent(JSON.stringify(data)));
    await navigator.clipboard.writeText(base64Data);
    alert('同步代碼已複製！');
    setShowSyncMenu(false);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data: AppDataBackup = JSON.parse(event.target?.result as string);
        if (data.quotes) {
          setQuotes(prev => {
            const existingIds = new Set(prev.map(q => q.id));
            const newOnes = data.quotes.filter(q => !existingIds.has(q.id));
            return [...newOnes, ...prev].sort((a, b) => b.timestamp - a.timestamp);
          });
          if (data.profiles) setProfiles(prev => ({ ...prev, ...data.profiles }));
          if (data.myProfile) setMyProfile(data.myProfile);
          alert('匯入成功！');
        }
      } catch (e) { alert('匯入格式錯誤'); }
      setShowSyncMenu(false);
    };
    reader.readAsText(file);
  };

  const allGroups = useMemo(() => {
    const groups: Record<string, AuthorGroup> = {};
    quotes.forEach(q => {
      if (!groups[q.author]) {
        groups[q.author] = { author: q.author, quotes: [], lastUpdate: 0, profile: profiles[q.author] };
      }
      groups[q.author].quotes.push(q);
      if (q.timestamp > groups[q.author].lastUpdate) groups[q.author].lastUpdate = q.timestamp;
    });

    const result = Object.values(groups);
    if (sortBy === 'lastUpdate') {
      return result.sort((a, b) => b.lastUpdate - a.lastUpdate);
    } else {
      return result.sort((a, b) => {
        const freqDiff = b.quotes.length - a.quotes.length;
        return freqDiff !== 0 ? freqDiff : b.lastUpdate - a.lastUpdate;
      });
    }
  }, [quotes, profiles, sortBy]);

  const filteredGroups = useMemo(() => {
    const s = searchQuery.trim().toLowerCase();
    if (!s) return allGroups;
    const isAuthorSearch = s.startsWith('author:');
    const isContentSearch = s.startsWith('content:');
    const term = isAuthorSearch ? s.replace('author:', '') : (isContentSearch ? s.replace('content:', '') : s);

    return allGroups.filter(g => {
      const matchAuthor = g.author.toLowerCase().includes(term);
      const matchContent = g.quotes.some(q => 
        q.content.toLowerCase().includes(term) || 
        q.tags.some(t => t.toLowerCase().includes(term)) ||
        q.aiAnalysis?.insight.toLowerCase().includes(term)
      );
      if (isAuthorSearch) return matchAuthor;
      if (isContentSearch) return matchContent;
      return matchAuthor || matchContent;
    });
  }, [allGroups, searchQuery]);

  const existingAuthors = useMemo(() => Array.from(new Set(quotes.map(q => q.author))).sort(), [quotes]);

  const avatarColors = [
    'from-indigo-100 to-indigo-200 text-indigo-600',
    'from-emerald-100 to-emerald-200 text-emerald-600',
    'from-rose-100 to-rose-200 text-rose-600',
    'from-amber-100 to-amber-200 text-amber-600',
    'from-purple-100 to-purple-200 text-purple-600'
  ];

  return (
    <div className="min-h-screen bg-[#F8F7FF] pb-32">
      <nav className="sticky top-0 z-50 bg-white/70 backdrop-blur-xl border-b border-purple-100/50">
        {/* 生成進度條 */}
        {isGeneratingMyProfile && (
          <div className="absolute bottom-0 left-0 h-0.5 bg-indigo-500 animate-[progress_3s_infinite] w-full origin-left"></div>
        )}

        <div className="max-w-7xl mx-auto px-4 sm:px-6 h-20 flex items-center justify-between gap-4">
          <div className="flex items-center gap-2 shrink-0 cursor-pointer" onClick={() => setSelectedAuthor(null)}>
            <div className="w-10 h-10 bg-indigo-500 rounded-2xl flex items-center justify-center text-white shadow-lg shadow-indigo-100 rotate-3 transition-transform hover:rotate-0">
              <span className="text-xl">🖋️</span>
            </div>
            <h1 className="hidden sm:block text-lg font-black text-slate-800 tracking-tight">觀察日誌</h1>
          </div>

          <div className="flex-1 max-w-xl flex items-center gap-3">
            <div className="flex-1 relative group">
              <input
                type="text"
                placeholder="搜尋內容... (可用 author: 或 content:)"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full bg-purple-50/50 border border-transparent focus:border-purple-200 focus:bg-white rounded-full px-10 py-2.5 text-sm transition-all outline-none"
              />
              <svg className="absolute left-3.5 top-3 w-4 h-4 text-purple-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
              {searchQuery && (
                <button onClick={() => setSearchQuery('')} className="absolute right-3.5 top-3 text-purple-300 hover:text-purple-500">
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
              )}
            </div>

            <div className="hidden md:flex bg-purple-50 rounded-full p-1 border border-purple-100">
              <button onClick={() => setSortBy('lastUpdate')} className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-[10px] font-black uppercase tracking-wider transition-all ${sortBy === 'lastUpdate' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>時間</button>
              <button onClick={() => setSortBy('frequency')} className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-[10px] font-black uppercase tracking-wider transition-all ${sortBy === 'frequency' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>頻率</button>
            </div>
          </div>

          <div className="flex items-center gap-2 relative">
            {feedbackMessage && (
              <div className="absolute top-full mt-3 right-0 w-72 bg-slate-900 text-white p-4 rounded-2xl shadow-2xl text-[11px] font-bold z-[100] animate-in fade-in slide-in-from-top-2 duration-300 border border-white/10">
                <div className="flex items-start gap-3">
                  <span className="text-amber-400 text-sm">⚠️</span>
                  <div className="flex-1">
                    <p className="leading-relaxed mb-2">{feedbackMessage}</p>
                    <div className="h-1 w-full bg-white/10 rounded-full overflow-hidden">
                       <div className="h-full bg-amber-400 animate-[timer_5s_linear_forwards]"></div>
                    </div>
                  </div>
                </div>
                <div className="absolute -top-1.5 right-6 w-3 h-3 bg-slate-900 rotate-45 border-l border-t border-white/10"></div>
              </div>
            )}

            <button 
              onClick={myProfile ? () => setIsMyProfileModalOpen(true) : handleGenerateMyProfile}
              disabled={isGeneratingMyProfile}
              className={`flex items-center gap-2 px-5 py-2.5 rounded-full font-black text-[11px] uppercase tracking-[0.2em] transition-all shadow-lg ${
                isShaking ? 'animate-[shake_0.5s_ease-in-out]' : ''
              } ${
                isGeneratingMyProfile 
                ? 'bg-indigo-50 text-indigo-400 cursor-wait' 
                : myProfile 
                  ? 'bg-gradient-to-r from-indigo-600 to-purple-600 text-white hover:scale-105 active:scale-95 shadow-indigo-100' 
                  : 'bg-white text-indigo-600 border border-indigo-200 hover:bg-indigo-50'
              }`}
            >
              {isGeneratingMyProfile ? (
                <div className="w-3 h-3 border-2 border-indigo-400 border-t-transparent rounded-full animate-spin"></div>
              ) : '👁️'}
              <span className="hidden sm:inline">{isGeneratingMyProfile ? '剖析鏡像中' : myProfile ? '查看自畫像' : '啟動鏡像'}</span>
            </button>

            <div className="relative">
              <button onClick={() => setShowSyncMenu(!showSyncMenu)} className={`p-3 rounded-full transition-all ${showSyncMenu ? 'bg-indigo-600 text-white' : 'bg-indigo-50 text-indigo-500 hover:bg-indigo-100'}`}>
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" /></svg>
              </button>
              {showSyncMenu && (
                <div className="absolute right-0 mt-3 w-48 bg-white rounded-3xl shadow-2xl border border-purple-50 p-2 animate-in fade-in zoom-in duration-200">
                  <button onClick={handleExport} className="w-full text-left px-4 py-3 hover:bg-purple-50 rounded-2xl text-xs font-bold text-slate-600 flex items-center gap-3">📤 匯出檔案</button>
                  <button onClick={handleCopyBackup} className="w-full text-left px-4 py-3 hover:bg-purple-50 rounded-2xl text-xs font-bold text-slate-600 flex items-center gap-3">📋 複製同步碼</button>
                  <button onClick={() => fileInputRef.current?.click()} className="w-full text-left px-4 py-3 hover:bg-purple-50 rounded-2xl text-xs font-bold text-slate-600 flex items-center gap-3 border-t border-purple-50 mt-1 pt-2">📥 從檔案匯入</button>
                  <input type="file" ref={fileInputRef} onChange={handleImport} className="hidden" accept=".json" />
                </div>
              )}
            </div>

            <button onClick={() => setIsModalOpen(true)} className="hidden sm:flex items-center gap-2 px-6 py-2.5 bg-slate-900 text-white rounded-full font-bold text-sm hover:bg-indigo-600 transition-all shadow-xl shadow-slate-200">
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4" /></svg>
              新紀錄
            </button>
          </div>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 py-8">
        {quotes.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-32 animate-float">
            <div className="w-24 h-24 bg-white rounded-[2.5rem] shadow-xl flex items-center justify-center text-purple-200 mb-6 border border-purple-50">
              <span className="text-4xl">🧬</span>
            </div>
            <h2 className="text-2xl font-black text-slate-800">開始人類觀察</h2>
            <p className="text-slate-400 mt-2 text-center max-w-xs">點擊下方的按鈕，記錄下身邊那些「充滿性格」的對話吧！</p>
          </div>
        ) : selectedAuthor ? (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
            <button onClick={() => setSelectedAuthor(null)} className="mb-8 flex items-center gap-2 text-slate-400 hover:text-indigo-600 transition-colors font-bold text-sm uppercase tracking-widest">
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M15 19l-7-7 7-7" /></svg>
              返回名單
            </button>
            <div className="max-w-2xl mx-auto">
              {allGroups.filter(g => g.author === selectedAuthor).map(group => (
                <AuthorCard key={group.author} group={group} allQuotes={quotes} onUpdateQuote={updateQuote} onDeleteQuote={deleteQuote} onUpdateProfile={updateProfile} />
              ))}
            </div>
          </div>
        ) : filteredGroups.length === 0 ? (
          <div className="text-center py-32">
            <div className="text-4xl mb-4">🔍</div>
            <h3 className="text-xl font-bold text-slate-400">找不到符合條件的對象或內容</h3>
          </div>
        ) : (
          <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-6 animate-in fade-in duration-500">
            {filteredGroups.map(group => {
              const colorIdx = group.author.length % avatarColors.length;
              const lastDate = new Date(group.lastUpdate).toLocaleDateString('zh-TW', { month: 'short', day: 'numeric' });
              return (
                <button key={group.author} onClick={() => setSelectedAuthor(group.author)} className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-purple-50 hover:shadow-xl hover:shadow-purple-100/50 hover:-translate-y-1 transition-all flex flex-col items-center text-center group relative overflow-hidden">
                  <div className={`w-20 h-20 rounded-3xl flex items-center justify-center font-black text-2xl bg-gradient-to-br shadow-md mb-4 ${avatarColors[colorIdx]}`}>{group.author.charAt(0).toUpperCase()}</div>
                  <h3 className="text-sm font-black text-slate-800 tracking-tight">{group.author}</h3>
                  <div className="mt-2 flex flex-col gap-1">
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{sortBy === 'frequency' ? `總紀錄 ${group.quotes.length} 則` : `更新於 ${lastDate}`}</p>
                  </div>
                  {group.profile && <span className="mt-3 px-2 py-1 bg-indigo-50 text-indigo-500 text-[8px] font-black rounded-lg border border-indigo-100 uppercase line-clamp-1 w-full">{group.profile.characterType}</span>}
                </button>
              );
            })}
          </div>
        )}
      </main>

      {isModalOpen && <AddQuoteModal onAdd={addQuote} onClose={() => setIsModalOpen(false)} existingAuthors={existingAuthors} />}
      {isMyProfileModalOpen && myProfile && <MyProfileModal profile={myProfile} onClose={() => setIsMyProfileModalOpen(false)} onRefresh={handleGenerateMyProfile} isRefreshing={isGeneratingMyProfile} />}

      <style>{`
        @keyframes shake {
          0%, 100% { transform: translateX(0); }
          25% { transform: translateX(-5px); }
          75% { transform: translateX(5px); }
        }
        @keyframes timer {
          from { width: 100%; }
          to { width: 0%; }
        }
        @keyframes progress {
          0% { transform: scaleX(0); }
          50% { transform: scaleX(0.7); }
          100% { transform: scaleX(1); }
        }
      `}</style>
    </div>
  );
};

