export const generateMyProfile = async (quotes: Quote[]): Promise<MyProfile> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const analyzedQuotes = quotes.filter(q => q.aiAnalysis);
    if (analyzedQuotes.length === 0) throw new Error("需要至少一則已分析的紀錄來建立自畫像。");

    const dataSnapshot = analyzedQuotes.map(q => ({
      context: q.content,
      myExpectation: q.aiAnalysis!.selfView,
      conflictType: q.aiAnalysis!.dynamic,
      subtext: q.aiAnalysis!.subtext
    }));

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: `分析樣本數據：\n${JSON.stringify(dataSnapshot, null, 2)}\n\n請以繁體中文回傳觀察者的衝突人格自畫像 JSON。`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            conflictArchetype: { type: Type.STRING },
            coreTraits: { type: Type.ARRAY, items: { type: Type.STRING } },
            emotionalTriggers: { type: Type.ARRAY, items: { type: Type.STRING } },
            defenseMechanisms: { type: Type.ARRAY, items: { type: Type.STRING } },
            growthInsight: { type: Type.STRING },
            summary: { type: Type.STRING }
          },
          required: ["conflictArchetype", "coreTraits", "emotionalTriggers", "defenseMechanisms", "growthInsight", "summary"]
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("無內容");
    return { ...JSON.parse(text.trim()), lastUpdated: Date.now() };
  } catch (error) {
    console.error("Gemini generateMyProfile 失敗:", error);
    throw error;
  }
};

import React, { useState, useEffect } from 'react';
import { Quote, AIAnalysis } from '../types';
import { analyzeQuote } from '../services/geminiService';

interface QuoteItemProps {
  quote: Quote;
  allQuotes: Quote[];
  onUpdate: (updatedQuote: Quote) => void;
  onDelete: (id: string) => void;
}

const QuoteItem: React.FC<QuoteItemProps> = ({ quote, allQuotes, onUpdate, onDelete }) => {
  const [loading, setLoading] = useState(false);
  const [isExpanded, setIsExpanded] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editedContent, setEditedContent] = useState(quote.content);
  const [loadingText, setLoadingText] = useState('啟動深度分析');

  useEffect(() => {
    if (loading) {
      const texts = ['正在剖析對抗邏輯', '正在追蹤情緒潛流', '正在解構博弈本質', '正在生成互動報告'];
      let i = 0;
      const timer = setInterval(() => {
        setLoadingText(texts[i % texts.length] + '...');
        i++;
      }, 1000);
      return () => clearInterval(timer);
    } else {
      setLoadingText('重新剖析二人衝突動態');
    }
  }, [loading]);

  const handleAIAnalyze = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setLoading(true);
    try {
      const contentToAnalyze = isEditing ? editedContent : quote.content;
      const analysis = await analyzeQuote(contentToAnalyze, quote.author, quote.observationDate);
      onUpdate({ ...quote, content: contentToAnalyze, aiAnalysis: analysis });
      setIsEditing(false);
      setIsExpanded(true);
    } catch (error) {
      console.error("AI Analysis failed", error);
      alert("AI 分析失敗，請稍後再試。");
    } finally {
      setLoading(false);
    }
  };

  const handleSaveEdit = (e: React.MouseEvent) => {
    e.stopPropagation();
    onUpdate({ ...quote, content: editedContent });
    setIsEditing(false);
  };

  const scrollToQuote = (id: string) => {
    const element = document.getElementById(`quote-${id}`);
    if (element) {
      element.scrollIntoView({ behavior: 'smooth', block: 'center' });
      element.classList.add('ring-4', 'ring-indigo-400', 'ring-opacity-50');
      setTimeout(() => {
        element.classList.remove('ring-4', 'ring-indigo-400', 'ring-opacity-50');
      }, 2000);
    }
  };

  const formattedDate = new Date(quote.observationDate).toLocaleDateString('zh-TW', {
    month: 'short',
    day: 'numeric'
  });

  const getTensionStyle = (score: number) => {
    if (score >= 8) return 'bg-rose-500 text-white border-rose-600 shadow-[0_0_8px_rgba(244,63,94,0.3)]';
    if (score >= 5) return 'bg-amber-100 text-amber-700 border-amber-200';
    return 'bg-emerald-50 text-emerald-600 border-emerald-100';
  };

  const getSentimentIcon = (sentiment: AIAnalysis['sentiment']) => {
    switch (sentiment) {
      case 'positive': return '😊';
      case 'negative': return '😫';
      default: return '😐';
    }
  };

  const relatedQuotes = quote.aiAnalysis ? allQuotes.filter(q => 
    q.id !== quote.id && 
    (q.aiAnalysis?.suggestedTags.some(tag => quote.aiAnalysis?.suggestedTags.includes(tag)) || 
     q.tags.some(tag => quote.aiAnalysis?.suggestedTags.includes(tag)))
  ).slice(0, 3) : [];

  return (
    <div 
      id={`quote-${quote.id}`}
      className={`group/item border transition-all duration-300 mb-3 overflow-hidden rounded-3xl ${isExpanded ? 'bg-white shadow-xl ring-1 ring-purple-100 border-purple-100' : 'bg-white/50 border-slate-100 hover:bg-white hover:shadow-md'}`}
    >
      {/* 折疊頭部佈局 */}
      <div 
        onClick={() => setIsExpanded(!isExpanded)}
        className="px-6 py-5 flex items-start gap-5 cursor-pointer"
      >
        {/* 左側：日期 */}
        <div className="flex flex-col items-center shrink-0 w-12 pt-1">
          <span className="text-[10px] font-black text-slate-300 uppercase tracking-tighter leading-none mb-1">{new Date(quote.observationDate).getFullYear()}</span>
          <span className="text-sm font-black text-slate-500">{formattedDate}</span>
        </div>

        {/* 中間：內文與洞察預覽 */}
        <div className="flex-1 min-w-0 flex flex-col gap-1.5">
          <div className="flex items-center gap-2 mb-0.5">
            {quote.aiAnalysis && (
              <span className={`text-[9px] font-black px-1.5 py-0.5 rounded-md border uppercase tracking-wider shrink-0 ${getTensionStyle(quote.aiAnalysis.resonanceScore)}`}>
                衝突強度 {quote.aiAnalysis.resonanceScore}/10
              </span>
            )}
            <div className="flex gap-1 overflow-hidden">
              {quote.tags.slice(0, 2).map(tag => (
                <span key={tag} className="text-[9px] text-slate-400 font-bold bg-slate-50 px-1.5 rounded border border-slate-100/50 whitespace-nowrap">#{tag}</span>
              ))}
            </div>
          </div>

          <p className={`text-sm leading-relaxed transition-all ${isExpanded ? 'text-slate-800 font-medium' : 'text-slate-600 line-clamp-1'}`}>
            {quote.content}
          </p>

          {!isExpanded && quote.aiAnalysis && (
            <p className="text-[11px] text-indigo-500/70 font-bold italic line-clamp-1 mt-0.5">
              💡 {quote.aiAnalysis.insight}
            </p>
          )}
        </div>

        {/* 右側：狀態圖示 */}
        <div className="flex items-center gap-3 shrink-0 pt-1">
          {quote.aiAnalysis && <span className="text-base grayscale-[0.5] group-hover/item:grayscale-0 transition-all">{getSentimentIcon(quote.aiAnalysis.sentiment)}</span>}
          <svg className={`w-4 h-4 text-slate-300 transition-transform duration-300 ${isExpanded ? 'rotate-180 text-indigo-500' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg>
        </div>
      </div>

      {/* 展開詳情 */}
      {isExpanded && (
        <div className="px-6 pb-8 animate-in slide-in-from-top-2 duration-300">
          <div className="pt-4 border-t border-purple-50">
            {/* 原文編輯區 */}
            <div className="bg-slate-50 rounded-3xl p-6 mb-8 relative border border-slate-100/50">
              <div className="flex justify-between items-center absolute -top-3 left-6 right-6">
                <div className="px-2 bg-white text-[9px] font-black text-slate-300 border border-slate-100 rounded-md uppercase tracking-tighter">當下事件紀錄</div>
                <button 
                  onClick={(e) => { e.stopPropagation(); setIsEditing(!isEditing); }}
                  className="px-2 bg-white text-[9px] font-black text-indigo-400 border border-indigo-100 rounded-md uppercase hover:bg-indigo-50 transition-colors"
                >
                  {isEditing ? '取消' : '修正內容'}
                </button>
              </div>

              {isEditing ? (
                <div className="mt-2 space-y-3">
                  <textarea 
                    value={editedContent}
                    onChange={(e) => setEditedContent(e.target.value)}
                    className="w-full bg-white border border-indigo-100 rounded-2xl p-4 text-sm focus:ring-2 focus:ring-indigo-200 outline-none min-h-[120px] resize-none leading-relaxed"
                  />
                  <div className="flex gap-2">
                    <button onClick={handleSaveEdit} className="px-5 py-2 bg-indigo-600 text-white text-[10px] font-black rounded-xl shadow-sm hover:bg-indigo-700 transition-all">僅儲存內容</button>
                    <button onClick={handleAIAnalyze} disabled={loading} className="px-5 py-2 bg-slate-900 text-white text-[10px] font-black rounded-xl shadow-sm hover:bg-indigo-600 transition-all flex items-center gap-2">
                      {loading && <div className="w-3 h-3 border-2 border-current border-t-transparent rounded-full animate-spin"></div>}
                      {loading ? loadingText : '儲存並重新剖析'}
                    </button>
                  </div>
                </div>
              ) : (
                <p className="text-lg text-slate-800 font-medium italic leading-relaxed tracking-tight">「{quote.content}」</p>
              )}
            </div>

            {quote.aiAnalysis ? (
              <div className="space-y-8">
                {/* 立場辯證 */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-5 relative">
                  <div className="hidden md:block absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 z-10">
                    <div className="w-10 h-10 bg-white border border-slate-100 rounded-full flex items-center justify-center text-[10px] font-black text-slate-300 shadow-md">VS</div>
                  </div>
                  <div className="bg-indigo-50/50 rounded-3xl p-5 border border-indigo-100/50">
                    <span className="text-[9px] font-black text-indigo-600 block mb-3 uppercase tracking-widest">我方的心理期待 / 動機</span>
                    {quote.aiAnalysis.selfView.map((v, i) => (
                      <p key={i} className="text-xs text-indigo-900 leading-snug mb-2 font-medium flex gap-2">
