                  <div className="flex items-center gap-3 mb-6">
                    <span className="px-3 py-1 bg-indigo-500 text-white text-[9px] font-black rounded-full uppercase tracking-[0.2em]">二人對峙關係剖析</span>
                    <div className="h-px flex-1 bg-white/10"></div>
                  </div>

                  <div className="space-y-6 relative z-10">
                    <div>
                      <h5 className="text-indigo-400 text-[10px] font-black uppercase tracking-widest mb-2 flex items-center gap-2">
                         <span className="w-1.5 h-1.5 rounded-full bg-indigo-500 animate-pulse"></span> 衝突本質拆解
                      </h5>
                      <p className="text-lg text-indigo-50 font-black leading-tight italic border-b border-indigo-500/20 pb-3">「{quote.aiAnalysis.insight}」</p>
