export const generateAuthorProfile = async (author: string, quotes: Quote[]): Promise<AuthorProfile> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const history = [...quotes]
      .sort((a, b) => new Date(a.observationDate).getTime() - new Date(b.observationDate).getTime())
      .map(q => `[${q.observationDate}] ${q.content}`)
      .join('\n');

    // 切換至 gemini-3-flash-preview 以增加調用穩定性
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `你正在為觀察者建立與 "${author}" 的關係深度檔案。
透過以下歷史互動，分析這兩人間的關係慣性。
${history}

任務：
1. 歸納此人在面對觀察者時最常使用的「行為對抗模式」。
2. 評估兩人間的互動穩定度。`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            characterType: { type: Type.STRING, description: "對我方而言，他是什麼樣的對抗角色" },
            traits: { type: Type.ARRAY, items: { type: Type.STRING } },
            relationshipPhase: { type: Type.STRING },
            interactionGuide: { type: Type.STRING, description: "我方未來的應對策略" },
