            stabilityScore: { type: Type.NUMBER, description: "關係穩定度 1-100" },
            relationshipTrend: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  date: { type: Type.STRING },
                  score: { type: Type.NUMBER },
                  label: { type: Type.STRING }
                },
                required: ["date", "score", "label"]
