                {/* 關聯紀錄 */}
                {relatedQuotes.length > 0 && (
                  <div className="mt-6 pt-6 border-t border-purple-50">
                    <h5 className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                      <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M13.828 10.172a4 4 0 00-5.656 0l-4 4a4 4 0 105.656 5.656l1.102-1.101m-.758-4.899a4 4 0 005.656 0l4-4a4 4 0 00-5.656-5.656l-1.1 1.1" /></svg>
                      關聯相似事件
                    </h5>
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                      {relatedQuotes.map(rq => (
                        <div key={rq.id} onClick={() => scrollToQuote(rq.id)} className="p-4 bg-white border border-purple-50 rounded-2xl hover:border-indigo-300 hover:shadow-lg transition-all cursor-pointer group/rel">
                          <div className="flex justify-between items-start mb-2">
                            <span className="text-[8px] font-black text-slate-400 bg-slate-50 px-1.5 py-0.5 rounded border border-slate-100">{rq.author} • {new Date(rq.observationDate).toLocaleDateString()}</span>
                            <span className="text-[8px] font-bold text-indigo-400">強度 {rq.aiAnalysis?.resonanceScore}</span>
                          </div>
                          <p className="text-[11px] text-slate-600 line-clamp-2 italic group-hover/rel:text-indigo-600 transition-colors">「{rq.aiAnalysis?.shortTitle || rq.aiAnalysis?.insight || rq.content}」</p>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            ) : (
              <button onClick={handleAIAnalyze} disabled={loading} className="w-full py-6 bg-indigo-50 text-indigo-500 border border-indigo-100 rounded-3xl text-[12px] font-black hover:bg-indigo-600 hover:text-white transition-all flex items-center justify-center gap-3">
                {loading ? <div className="w-4 h-4 border-2 border-current border-t-transparent rounded-full animate-spin"></div> : <span className="text-xl">🧬</span>}
                {loading ? loadingText : '啟動深度關係衝突剖析'}
              </button>
            )}

            <div className="flex justify-between items-center mt-8 pt-5 border-t border-slate-100">
               <span className="text-[9px] text-slate-300 font-mono italic uppercase tracking-widest">Conflict Engine V6.1.2</span>
              <button onClick={() => onDelete(quote.id)} className="text-[10px] font-bold text-slate-400 hover:text-rose-500 transition-colors uppercase tracking-widest">移除紀錄</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

