import { GoogleGenAI, Type } from "@google/genai";
import { AIAnalysis, AuthorProfile, Quote, MyProfile } from "../types";

export const refineNarrative = async (rawContent: string): Promise<string> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `請將以下原始觀察紀錄修飾成流暢且富有觀察美感的繁體中文。內容如下：\n\n${rawContent}`,
      config: { 
        systemInstruction: "你是一個專業的文字修飾助手。你的唯一任務是順稿。請直接回傳修飾後的純文字。嚴禁包含任何引言、結語、點評、分析 or 多版本選項。保留原始意涵，去除冗贅，使其更易閱讀。",
        temperature: 0.1 
      }
    });
    return response.text?.trim() || rawContent;
  } catch (error) {
    console.error("Gemini refineNarrative 失敗:", error);
    throw error;
  }
};

export const analyzeQuote = async (content: string, author: string, observationDate: string): Promise<AIAnalysis> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `你是一個極致理性的「人際關係軍師」，專門為「我方（觀察者）」剖析與「對方（${author}）」之間的對峙與衝突。

內容描述了你們的一次互動：「${content}」

分析指令：
1. 【衝突標題】：請為這次互動起一個 5-10 字的精煉標題，直接反映碰撞的核心（例如：洗碗權力的邊界爭奪）。
2. 【衝突強度】：評估雙方立場的分歧程度。1分代表極度和諧/順從，10分代表極度對抗/決裂。
3. 【衝突本質】：用一句話直接點出你（我方）與 ${author} 在這一刻最核心的「心理碰撞點」。
4. 【我方期待 vs 對方邏輯】：我方當時想要達成什麼心理目標？而 ${author} 是用了什麼樣的邏輯或行為防禦來抵銷我方的意圖？
5. 【權力與情緒潛流】：分析這場對話中，誰在試圖掌控局面？背後隱藏了什麼樣的被動攻擊、試探或情緒勒索？
6. 【關係磨損/演變】：這次碰撞如何具體地改變了你對 ${author} 的認知邊界？

請以繁體中文回傳 JSON。`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            shortTitle: { type: Type.STRING, description: "5-10 字的互動核心標題" },
            resonanceScore: { type: Type.NUMBER, description: "衝突強度指數 1-10" },
            weirdnessIndex: { type: Type.NUMBER },
            sentiment: { type: Type.STRING, enum: ['positive', 'negative', 'neutral'] },
            sentimentLabel: { type: Type.STRING, description: "這場衝突的情緒底色" },
