    console.error("Gemini generateAuthorProfile 失敗:", error);
    throw error;
  }
};

export const generateMyProfile = async (quotes: Quote[]): Promise<MyProfile> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const analyzedQuotes = quotes.filter(q => q.aiAnalysis);

    const dataSnapshot = analyzedQuotes.map(q => ({
      context: q.content,
      myExpectation: q.aiAnalysis!.selfView,
      conflictType: q.aiAnalysis!.dynamic,
      subtext: q.aiAnalysis!.subtext,
      sentiment: q.aiAnalysis!.sentiment,
      insight: q.aiAnalysis!.insight
    }));

    const prompt = `你是一個深度心理剖析師。請根據觀察者與他人的對峙樣本，還原其深層人格代碼。
數據樣本：\n${JSON.stringify(dataSnapshot, null, 2)}

任務要求：
1. 【價值觀/三觀分析】：從衝突點反推我方在乎的是什麼？對於「金錢、權力、關係、自我、正義」等事物的核心觀點是什麼。
2. 【成長建議】：不僅要給啟示，還要詳細說明「為什麼這是我方的弱點」以及「具體如何優化」的執行步驟。

請回傳 JSON：`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            conflictArchetype: { type: Type.STRING },
            thinkingTendency: { type: Type.STRING },
            responsePattern: { type: Type.STRING },
            emotionalFlow: { type: Type.STRING },
            conflictRoot: { type: Type.STRING },
            defenseProtocol: { type: Type.STRING },
            worldview: { type: Type.ARRAY, items: { type: Type.STRING }, description: "分析我方對特定事物的價值觀觀點" },
            detailedGrowth: { type: Type.STRING, description: "深度成長建議與具體優化步驟" },
            growthInsight: { type: Type.STRING, description: "一句精煉的啟示" },
            summary: { type: Type.STRING }
          },
          required: ["conflictArchetype", "thinkingTendency", "responsePattern", "emotionalFlow", "conflictRoot", "defenseProtocol", "worldview", "detailedGrowth", "growthInsight", "summary"]
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("無內容");
    return { ...JSON.parse(text.trim()), lastUpdated: Date.now() };
  } catch (error) {
    console.error("Gemini generateMyProfile 失敗:", error);
    throw error;
  }
};

