  }, [profiles]);

  useEffect(() => {
    if (myProfile) localStorage.setItem(MY_PROFILE_KEY, JSON.stringify(myProfile));
  }, [myProfile]);

  const addQuote = (newQuote: Quote) => setQuotes(prev => [newQuote, ...prev]);
  const updateQuote = (updatedQuote: Quote) => setQuotes(prev => prev.map(q => q.id === updatedQuote.id ? updatedQuote : q));
  const deleteQuote = (id: string) => setQuotes(prev => prev.filter(q => q.id !== id));

  const updateProfile = (author: string, profile: AuthorProfile | null) => {
    setProfiles(prev => {
      const next = { ...prev };
      if (profile === null) delete next[author];
      else next[author] = profile;
      return next;
    });
  };

  const triggerFeedback = (msg: string) => {
    setFeedbackMessage(msg);
    setIsShaking(true);
    setTimeout(() => setIsShaking(false), 500);
    setTimeout(() => setFeedbackMessage(null), 5000);
  };

  const handleGenerateMyProfile = async () => {
    if (isGeneratingMyProfile) return;
    if (quotes.length === 0) {
      triggerFeedback("數據量不足：目前沒有任何觀察紀錄。");
      return;
    }
    const analyzedQuotes = quotes.filter(q => q.aiAnalysis);
    if (analyzedQuotes.length === 0) {
      triggerFeedback("深度不足：請先在個別紀錄中啟動 AI 深度分析。");
      return;
    }

    setIsGeneratingMyProfile(true);
    try {
      if (typeof window.aistudio !== 'undefined') {
        const hasKey = await window.aistudio.hasSelectedApiKey();
        if (!hasKey) await window.aistudio.openSelectKey();
      }
      const profile = await generateMyProfile(quotes);
      setMyProfile(profile);
      setIsMyProfileModalOpen(true);
    } catch (e: any) {
      triggerFeedback("同步失敗：校準中斷，請重試。");
    } finally {
      setIsGeneratingMyProfile(false);
    }
  };

  const handleExport = () => {
    const data: AppDataBackup = { version: APP_VERSION, quotes, profiles, myProfile: myProfile || undefined, exportedAt: new Date().toISOString() };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `human-case-files-${new Date().toISOString().split('T')[0]}.json`;
    a.click();
    URL.revokeObjectURL(url);
    setShowSyncMenu(false);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data: AppDataBackup = JSON.parse(event.target?.result as string);
        if (data.quotes) {
          setQuotes(prev => {
            const existingIds = new Set(prev.map(q => q.id));
            const newOnes = data.quotes.filter(q => !existingIds.has(q.id));
            return [...newOnes, ...prev].sort((a, b) => b.timestamp - a.timestamp);
          });
          if (data.profiles) setProfiles(prev => ({ ...prev, ...data.profiles }));
          if (data.myProfile) setMyProfile(data.myProfile);
        }
      } catch (e) { alert('匯入格式錯誤'); }
      setShowSyncMenu(false);
    };
    reader.readAsText(file);
  };

  const allGroups = useMemo(() => {
    const groups: Record<string, AuthorGroup> = {};
    quotes.forEach(q => {
      if (!groups[q.author]) {
        groups[q.author] = { author: q.author, quotes: [], lastUpdate: 0, profile: profiles[q.author] };
      }
      groups[q.author].quotes.push(q);
      if (q.timestamp > groups[q.author].lastUpdate) groups[q.author].lastUpdate = q.timestamp;
    });

    const result = Object.values(groups);
    return sortBy === 'lastUpdate' 
      ? result.sort((a, b) => b.lastUpdate - a.lastUpdate)
      : result.sort((a, b) => (b.quotes.length - a.quotes.length) || (b.lastUpdate - a.lastUpdate));
  }, [quotes, profiles, sortBy]);

  const filteredGroups = useMemo(() => {
    const s = searchQuery.trim().toLowerCase();
    if (!s) return allGroups;
    return allGroups.filter(g => 
      g.author.toLowerCase().includes(s) || 
      g.quotes.some(q => q.content.toLowerCase().includes(s))
    );
  }, [allGroups, searchQuery]);

  const avatarColors = [
    'border-slate-400 bg-slate-100 text-slate-700',
    'border-amber-600 bg-amber-50 text-amber-800',
    'border-blue-600 bg-blue-50 text-blue-800',
    'border-stone-600 bg-stone-100 text-stone-800'
  ];

  return (
    <div className="min-h-screen pb-32">
      <nav className="sticky top-0 z-50 bg-[#ede4d5]/80 backdrop-blur-md border-b border-stone-300">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 h-20 flex items-center justify-between gap-4">
          <div className="flex items-center gap-3 shrink-0 cursor-pointer" onClick={() => setSelectedAuthor(null)}>
            <div className="w-10 h-10 bg-stone-800 rounded-lg flex items-center justify-center text-[#f1e7d0] shadow-md">
              <span className="text-xl font-black">C</span>
            </div>
            <h1 className="hidden sm:block text-xl font-black text-stone-900 tracking-tighter">HUMAN_CASE_FILES</h1>
          </div>

          <div className="flex-1 max-w-xl flex items-center gap-3">
            <div className="flex-1 relative">
              <input
                type="text"
                placeholder="搜尋證據標籤..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full bg-white/50 border border-stone-300 rounded-lg px-10 py-2.5 text-sm transition-all outline-none focus:ring-1 focus:ring-stone-400"
              />
              <svg className="absolute left-3.5 top-3 w-4 h-4 text-stone-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
            </div>
          </div>

          <div className="flex items-center gap-3">
            <button 
              onClick={myProfile ? () => setIsMyProfileModalOpen(true) : handleGenerateMyProfile}
              className={`px-5 py-2.5 rounded-lg font-black text-[11px] uppercase tracking-widest border transition-all ${
                myProfile ? 'bg-stone-900 text-white border-stone-900' : 'bg-white text-stone-800 border-stone-300'
              }`}
            >
              {isGeneratingMyProfile ? '剖析中...' : '靈魂自畫像'}
            </button>

            <button onClick={() => setShowSyncMenu(!showSyncMenu)} className="p-2.5 bg-white border border-stone-300 rounded-lg text-stone-600">
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" /></svg>
            </button>
            {showSyncMenu && (
              <div className="absolute right-0 top-full mt-2 w-48 bg-white rounded-lg shadow-xl border border-stone-200 p-1 z-50">
                <button onClick={handleExport} className="w-full text-left px-4 py-3 hover:bg-stone-50 rounded text-xs font-bold text-stone-600">📤 匯出卷宗</button>
                <button onClick={() => fileInputRef.current?.click()} className="w-full text-left px-4 py-3 hover:bg-stone-50 rounded text-xs font-bold text-stone-600">📥 匯入卷宗</button>
                <input type="file" ref={fileInputRef} onChange={handleImport} className="hidden" accept=".json" />
              </div>
            )}

            <button onClick={() => setIsModalOpen(true)} className="px-6 py-2.5 bg-stone-900 text-white rounded-lg font-bold text-sm shadow-lg">
              紀錄新證據
            </button>
          </div>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 py-10">
        {selectedAuthor ? (
          <div>
            <button onClick={() => setSelectedAuthor(null)} className="mb-6 flex items-center gap-2 text-stone-500 font-bold text-xs uppercase tracking-widest">
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M15 19l-7-7 7-7" /></svg>
              返回卷宗列表
            </button>
            <div className="max-w-3xl mx-auto">
              {allGroups.filter(g => g.author === selectedAuthor).map(group => (
                <AuthorCard key={group.author} group={group} allQuotes={quotes} onUpdateQuote={updateQuote} onDeleteQuote={deleteQuote} onUpdateProfile={updateProfile} />
              ))}
            </div>
          </div>
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredGroups.map(group => {
              const colorIdx = group.author.length % avatarColors.length;
              return (
                <button 
                  key={group.author} 
                  onClick={() => setSelectedAuthor(group.author)}
                  className="case-folder p-8 rounded-lg text-left transition-transform hover:-translate-y-1 hover:rotate-1"
                >
                  <div className="flex justify-between items-start mb-6">
                    <div className={`w-14 h-14 border-2 rounded-lg flex items-center justify-center font-black text-xl ${avatarColors[colorIdx]}`}>
                      {group.author.charAt(0)}
                    </div>
                    <div className="stamp">Evidence Sample</div>
                  </div>
                  <h3 className="text-xl font-black text-stone-900 mb-2">{group.author}</h3>
                  <p className="text-[10px] font-bold text-stone-500 uppercase tracking-widest">存檔數量: {group.quotes.length} | 狀態: 已採樣</p>
                  {group.profile && (
                    <div className="mt-4 pt-4 border-t border-stone-200">
                      <span className="text-[11px] font-handwriting text-blue-700 text-lg">"{group.profile.characterType}"</span>
                    </div>
                  )}
                </button>
              );
            })}
          </div>
        )}
      </main>

      {isModalOpen && <AddQuoteModal onAdd={addQuote} onClose={() => setIsModalOpen(false)} existingAuthors={Array.from(new Set(quotes.map(q => q.author)))} />}
      {isMyProfileModalOpen && myProfile && <MyProfileModal profile={myProfile} onClose={() => setIsMyProfileModalOpen(false)} onRefresh={handleGenerateMyProfile} isRefreshing={isGeneratingMyProfile} />}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { AuthorGroup, Quote, AuthorProfile } from '../types';
import QuoteItem from './QuoteItem';
import ProfileModal from './ProfileModal';
import { generateAuthorProfile } from '../services/geminiService';

interface AuthorCardProps {
  group: AuthorGroup;
  allQuotes: Quote[];
  onUpdateQuote: (updatedQuote: Quote) => void;
  onDeleteQuote: (id: string) => void;
  onUpdateProfile: (author: string, profile: AuthorProfile | null) => void;
}

const AuthorCard: React.FC<AuthorCardProps> = ({ group, allQuotes, onUpdateQuote, onDeleteQuote, onUpdateProfile }) => {
  const [isGeneratingProfile, setIsGeneratingProfile] = useState(false);
  const [showProfile, setShowProfile] = useState(false);

  const handleGenerateProfile = async (e?: React.MouseEvent) => {
    e?.stopPropagation();
    if (isGeneratingProfile) return;
    setIsGeneratingProfile(true);
    try {
      if (typeof window.aistudio !== 'undefined') {
        const hasKey = await window.aistudio.hasSelectedApiKey();
        if (!hasKey) await window.aistudio.openSelectKey();
      }
      const profile = await generateAuthorProfile(group.author, group.quotes);
      onUpdateProfile(group.author, profile);
      if (!group.profile) setShowProfile(true);
    } catch (error: any) {
      alert("剖析失敗，請檢查連線。");
    } finally {
      setIsGeneratingProfile(false);
    }
  };

  return (
    <div className="case-folder rounded-lg p-10 flex flex-col gap-8 min-h-[600px]">
      <div className="flex flex-col sm:flex-row justify-between items-start gap-6 border-b-2 border-stone-300 pb-8">
        <div className="flex gap-6">
          <div className="w-20 h-20 bg-stone-100 border-2 border-stone-400 rounded-lg flex items-center justify-center text-4xl font-black text-stone-800">
            {group.author.charAt(0)}
          </div>
          <div>
            <h3 className="text-3xl font-black text-stone-900 tracking-tighter">SUBJECT: {group.author}</h3>
            <p className="text-xs font-bold text-stone-500 uppercase tracking-widest mt-2">Observation Samples: #{group.quotes.length}</p>
            {group.profile && (
              <div className="mt-3 flex items-center gap-2">
                <span className="stamp">Profiled</span>
                <span className="text-blue-700 font-handwriting text-xl">"{group.profile.characterType}"</span>
              </div>
            )}
          </div>
        </div>

        <div className="flex gap-3">
          <button 
            onClick={group.profile ? () => setShowProfile(true) : () => handleGenerateProfile()}
            className="px-6 py-2.5 bg-stone-900 text-white rounded-lg text-[11px] font-black uppercase tracking-widest"
          >
            {isGeneratingProfile ? '校準中...' : group.profile ? '查看人物誌分析' : '啟動深度取證'}
          </button>
        </div>
      </div>

      <div className="flex-1 space-y-4">
        <h4 className="text-[10px] font-black text-stone-400 uppercase tracking-widest mb-4">Evidence History (Sorted by Date)</h4>
        {[...group.quotes].sort((a, b) => b.timestamp - a.timestamp).map(quote => (
          <QuoteItem 
            key={quote.id} 
            quote={quote} 
            allQuotes={allQuotes}
            onUpdate={onUpdateQuote} 
            onDelete={onDeleteQuote} 
          />
        ))}
      </div>

      {showProfile && group.profile && (
        <ProfileModal 
          author={group.author} 
          profile={group.profile} 
          onClose={() => setShowProfile(false)} 
          onRefresh={handleGenerateProfile}
          isRefreshing={isGeneratingProfile}
        />
      )}
    </div>
  );
};

export default AuthorCard;

import React, { useState, useEffect } from 'react';
import { Quote, AIAnalysis } from '../types';
import { analyzeQuote } from '../services/geminiService';

interface QuoteItemProps {
  quote: Quote;
  allQuotes: Quote[];
  onUpdate: (updatedQuote: Quote) => void;
  onDelete: (id: string) => void;
}

const QuoteItem: React.FC<QuoteItemProps> = ({ quote, allQuotes, onUpdate, onDelete }) => {
  const [loading, setLoading] = useState(false);
  const [isExpanded, setIsExpanded] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editedContent, setEditedContent] = useState(quote.content);

  const handleAIAnalyze = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setLoading(true);
    try {
      const contentToAnalyze = isEditing ? editedContent : quote.content;
      const analysis = await analyzeQuote(contentToAnalyze, quote.author, quote.observationDate);
      onUpdate({ ...quote, content: contentToAnalyze, aiAnalysis: analysis });
      setIsEditing(false);
      setIsExpanded(true);
    } catch (error) {
      alert("分析失敗。");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div 
      className={`border-b border-stone-200 transition-all ${isExpanded ? 'bg-white/50 -mx-2 px-2 py-4' : 'hover:bg-white/30 py-3'}`}
    >
      <div 
        onClick={() => setIsExpanded(!isExpanded)}
        className="flex items-start gap-4 cursor-pointer"
      >
        <div className="shrink-0 w-16 text-center">
          <span className="block text-[10px] font-black text-stone-400 uppercase leading-none mb-1">{new Date(quote.observationDate).getFullYear()}</span>
          <span className="block text-sm font-black text-stone-800">{new Date(quote.observationDate).toLocaleDateString('zh-TW', { month: 'short', day: 'numeric' })}</span>
        </div>

        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 mb-1">
            {quote.aiAnalysis && (
              <span className="text-[9px] font-black px-1.5 py-0.5 border border-stone-800 uppercase tracking-tighter">
                TENSION: {quote.aiAnalysis.resonanceScore}
              </span>
            )}
            <div className="flex gap-1">
              {quote.tags.slice(0, 2).map(tag => (
                <span key={tag} className="text-[9px] text-stone-500 font-bold font-mono">#{tag}</span>
              ))}
            </div>
          </div>
          <p className={`text-sm leading-relaxed ${isExpanded ? 'font-bold' : 'truncate text-stone-700'}`}>
            {quote.aiAnalysis?.shortTitle || quote.content}
          </p>
        </div>

        <div className="shrink-0 pt-1">
          <svg className={`w-4 h-4 text-stone-400 transition-transform ${isExpanded ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg>
        </div>
      </div>

      {isExpanded && (
        <div className="mt-6 animate-in slide-in-from-top-1 duration-200">
          <div className="bg-white p-6 rounded-lg border border-stone-200 shadow-inner mb-6 relative">
            <div className="absolute -top-3 left-4 px-2 bg-[#f9f5ed] text-[9px] font-black text-stone-400 uppercase border border-stone-200">Raw Transcript</div>
            <p className="text-lg font-handwriting text-stone-800 leading-tight">"{quote.content}"</p>
          </div>

          {quote.aiAnalysis ? (
            <div className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="bg-stone-50 p-4 border border-stone-200 rounded">
                  <span className="text-[9px] font-black text-stone-400 block mb-2 uppercase">Self Projection</span>
                  {quote.aiAnalysis.selfView.map((v, i) => <p key={i} className="text-xs text-stone-700 mb-1">• {v}</p>)}
                </div>
                <div className="bg-stone-50 p-4 border border-stone-200 rounded">
                  <span className="text-[9px] font-black text-stone-400 block mb-2 uppercase">Subject Logic</span>
                  {quote.aiAnalysis.otherView.map((v, i) => <p key={i} className="text-xs text-stone-700 mb-1">• {v}</p>)}
                </div>
              </div>

              <div className="bg-stone-800 text-white p-6 rounded-lg">
                <h5 className="text-[9px] font-black text-stone-400 uppercase tracking-widest mb-3">Core Pattern Analysis</h5>
                <p className="text-base font-black italic mb-4">"{quote.aiAnalysis.insight}"</p>
                <p className="text-xs text-stone-300 leading-relaxed opacity-80">{quote.aiAnalysis.subtext}</p>
              </div>
            </div>
          ) : (
            <button onClick={handleAIAnalyze} disabled={loading} className="w-full py-4 border-2 border-dashed border-stone-300 rounded-lg text-[11px] font-black uppercase text-stone-400 hover:border-stone-800 hover:text-stone-800 transition-all">
              {loading ? '分析數據中...' : '啟動 AI 模式提取'}
            </button>
          )}

          <div className="mt-6 flex justify-end">
            <button onClick={() => onDelete(quote.id)} className="text-[9px] font-black text-stone-300 hover:text-red-700 uppercase">移除證據</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default QuoteItem;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Quote, AuthorGroup, AuthorProfile, AppDataBackup, MyProfile } from './types';
import AuthorCard from './components/AuthorCard';
import AddQuoteModal from './components/AddQuoteModal';
import MyProfileModal from './components/MyProfileModal';
import { generateMyProfile } from './services/geminiService';

const STORAGE_KEY = 'human-logs-v3-quotes';
const PROFILES_KEY = 'human-logs-v3-profiles';
const MY_PROFILE_KEY = 'human-logs-v3-myprofile';
const APP_VERSION = '4.0.0';

type SortType = 'lastUpdate' | 'frequency';

const App: React.FC = () => {
  const [quotes, setQuotes] = useState<Quote[]>([]);
  const [profiles, setProfiles] = useState<Record<string, AuthorProfile>>({});
  const [myProfile, setMyProfile] = useState<MyProfile | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMyProfileModalOpen, setIsMyProfileModalOpen] = useState(false);
  const [isGeneratingMyProfile, setIsGeneratingMyProfile] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [sortBy, setSortBy] = useState<SortType>('lastUpdate');
  const [showSyncMenu, setShowSyncMenu] = useState(false);
  const [selectedAuthor, setSelectedAuthor] = useState<string | null>(null);
  const [feedbackMessage, setFeedbackMessage] = useState<string | null>(null);
  const [isShaking, setIsShaking] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const savedQuotes = localStorage.getItem(STORAGE_KEY);
    const savedProfiles = localStorage.getItem(PROFILES_KEY);
    const savedMyProfile = localStorage.getItem(MY_PROFILE_KEY);
    if (savedQuotes) {
      try {
        const parsed = JSON.parse(savedQuotes);
        setQuotes(Array.isArray(parsed) ? parsed : []);
      } catch (e) { console.error("Restore failed", e); }
    }
    if (savedProfiles) {
      try {
        setProfiles(JSON.parse(savedProfiles));
      } catch (e) { console.error("Restore profiles failed", e); }
    }
    if (savedMyProfile) {
      try {
        setMyProfile(JSON.parse(savedMyProfile));
      } catch (e) { console.error("Restore my profile failed", e); }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(quotes));
  }, [quotes]);

  useEffect(() => {
    localStorage.setItem(PROFILES_KEY, JSON.stringify(profiles));
  }, [profiles]);

  useEffect(() => {
    if (myProfile) localStorage.setItem(MY_PROFILE_KEY, JSON.stringify(myProfile));
  }, [myProfile]);

  const addQuote = (newQuote: Quote) => setQuotes(prev => [newQuote, ...prev]);
  const updateQuote = (updatedQuote: Quote) => setQuotes(prev => prev.map(q => q.id === updatedQuote.id ? updatedQuote : q));
  const deleteQuote = (id: string) => setQuotes(prev => prev.filter(q => q.id !== id));

  const updateProfile = (author: string, profile: AuthorProfile | null) => {
    setProfiles(prev => {
      const next = { ...prev };
      if (profile === null) delete next[author];
      else next[author] = profile;
      return next;
    });
  };

  const triggerFeedback = (msg: string) => {
    setFeedbackMessage(msg);
    setIsShaking(true);
    setTimeout(() => setIsShaking(false), 500);
    setTimeout(() => setFeedbackMessage(null), 5000);
  };

  const handleGenerateMyProfile = async () => {
    if (isGeneratingMyProfile) return;
    if (quotes.length === 0) {
      triggerFeedback("數據量不足：目前沒有任何觀察紀錄。");
      return;
    }
    const analyzedQuotes = quotes.filter(q => q.aiAnalysis);
    if (analyzedQuotes.length === 0) {
      triggerFeedback("深度不足：請先在個別紀錄中啟動 AI 深度分析。");
      return;
    }

    setIsGeneratingMyProfile(true);
    try {
      if (typeof window.aistudio !== 'undefined') {
        const hasKey = await window.aistudio.hasSelectedApiKey();
        if (!hasKey) await window.aistudio.openSelectKey();
      }
      const profile = await generateMyProfile(quotes);
      setMyProfile(profile);
      setIsMyProfileModalOpen(true);
    } catch (e: any) {
      triggerFeedback("同步失敗：校準中斷，請重試。");
    } finally {
      setIsGeneratingMyProfile(false);
    }
  };

  const handleExport = () => {
    const data: AppDataBackup = { version: APP_VERSION, quotes, profiles, myProfile: myProfile || undefined, exportedAt: new Date().toISOString() };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `human-case-files-${new Date().toISOString().split('T')[0]}.json`;
    a.click();
    URL.revokeObjectURL(url);
    setShowSyncMenu(false);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data: AppDataBackup = JSON.parse(event.target?.result as string);
        if (data.quotes) {
          setQuotes(prev => {
            const existingIds = new Set(prev.map(q => q.id));
            const newOnes = data.quotes.filter(q => !existingIds.has(q.id));
            return [...newOnes, ...prev].sort((a, b) => b.timestamp - a.timestamp);
          });
          if (data.profiles) setProfiles(prev => ({ ...prev, ...data.profiles }));
          if (data.myProfile) setMyProfile(data.myProfile);
        }
      } catch (e) { alert('匯入格式錯誤'); }
      setShowSyncMenu(false);
    };
    reader.readAsText(file);
  };

  const allGroups = useMemo(() => {
    const groups: Record<string, AuthorGroup> = {};
    quotes.forEach(q => {
      if (!groups[q.author]) {
        groups[q.author] = { author: q.author, quotes: [], lastUpdate: 0, profile: profiles[q.author] };
      }
      groups[q.author].quotes.push(q);
      if (q.timestamp > groups[q.author].lastUpdate) groups[q.author].lastUpdate = q.timestamp;
    });

    const result = Object.values(groups);
    return sortBy === 'lastUpdate' 
      ? result.sort((a, b) => b.lastUpdate - a.lastUpdate)
      : result.sort((a, b) => (b.quotes.length - a.quotes.length) || (b.lastUpdate - a.lastUpdate));
  }, [quotes, profiles, sortBy]);

  const filteredGroups = useMemo(() => {
    const s = searchQuery.trim().toLowerCase();
    if (!s) return allGroups;
    return allGroups.filter(g => 
      g.author.toLowerCase().includes(s) || 
      g.quotes.some(q => q.content.toLowerCase().includes(s))
    );
  }, [allGroups, searchQuery]);

  const avatarColors = [
    'border-slate-400 bg-slate-100 text-slate-700',
    'border-amber-600 bg-amber-50 text-amber-800',
    'border-blue-600 bg-blue-50 text-blue-800',
    'border-stone-600 bg-stone-100 text-stone-800'
  ];

  return (
    <div className="min-h-screen pb-20 sm:pb-32">
      <nav className="sticky top-0 z-50 bg-[#ede4d5]/90 backdrop-blur-md border-b border-stone-300">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 h-16 sm:h-20 flex items-center justify-between gap-3">
          <div className="flex items-center gap-2 sm:gap-3 shrink-0 cursor-pointer" onClick={() => setSelectedAuthor(null)}>
            <div className="w-8 h-8 sm:w-10 sm:h-10 bg-stone-800 rounded-lg flex items-center justify-center text-[#f1e7d0] shadow-md">
              <span className="text-lg sm:text-xl font-black">C</span>
            </div>
            <h1 className="hidden md:block text-xl font-black text-stone-900 tracking-tighter uppercase">CASE_FILES</h1>
          </div>

          <div className="flex-1 max-w-sm sm:max-w-xl flex items-center">
            <div className="w-full relative">
              <input
                type="text"
                placeholder="搜尋證據..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full bg-white/50 border border-stone-300 rounded-lg pl-9 pr-4 py-2 text-xs sm:text-sm outline-none focus:ring-1 focus:ring-stone-400"
              />
              <svg className="absolute left-3 top-2.5 w-4 h-4 text-stone-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
            </div>
          </div>

          <div className="flex items-center gap-2 shrink-0">
            <button 
              onClick={myProfile ? () => setIsMyProfileModalOpen(true) : handleGenerateMyProfile}
              title="校準自畫像"
              className={`p-2.5 sm:px-4 sm:py-2 rounded-lg font-black text-[10px] sm:text-[11px] uppercase tracking-widest border transition-all ${
                myProfile ? 'bg-stone-900 text-white border-stone-900' : 'bg-white text-stone-800 border-stone-300'
              }`}
            >
              <span className="hidden sm:inline">{isGeneratingMyProfile ? '剖析中...' : '靈魂自畫像'}</span>
              <span className="sm:hidden text-base">👁️</span>
            </button>

            <button onClick={() => setShowSyncMenu(!showSyncMenu)} className="p-2.5 bg-white border border-stone-300 rounded-lg text-stone-600">
              <svg className="w-4 h-4 sm:w-5 sm:h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" /></svg>
            </button>

            <button onClick={() => setIsModalOpen(true)} className="p-2.5 sm:px-5 sm:py-2 bg-stone-900 text-white rounded-lg font-bold text-xs sm:text-sm shadow-md flex items-center gap-2">
              <span className="text-base sm:text-lg">+</span>
              <span className="hidden sm:inline">紀錄證據</span>
            </button>
          </div>
        </div>
        {showSyncMenu && (
          <div className="absolute right-4 top-18 w-40 bg-white rounded-lg shadow-xl border border-stone-200 p-1 z-50">
            <button onClick={handleExport} className="w-full text-left px-4 py-3 hover:bg-stone-50 rounded text-[10px] font-bold text-stone-600 uppercase">📤 匯出卷宗</button>
            <button onClick={() => fileInputRef.current?.click()} className="w-full text-left px-4 py-3 hover:bg-stone-50 rounded text-[10px] font-bold text-stone-600 uppercase">📥 匯入卷宗</button>
            <input type="file" ref={fileInputRef} onChange={handleImport} className="hidden" accept=".json" />
          </div>
        )}
      </nav>

      {feedbackMessage && (
        <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[100] px-4 py-2 bg-rose-600 text-white text-[10px] font-black uppercase tracking-widest rounded-full shadow-lg animate-bounce">
          {feedbackMessage}
        </div>
      )}

      <main className="max-w-7xl mx-auto px-4 sm:px-6 py-6 sm:py-10">
        {selectedAuthor ? (
          <div>
            <button onClick={() => setSelectedAuthor(null)} className="mb-6 flex items-center gap-2 text-stone-500 font-bold text-[10px] uppercase tracking-widest">
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M15 19l-7-7 7-7" /></svg>
              返回卷宗列表
            </button>
            <div className="max-w-3xl mx-auto">
              {allGroups.filter(g => g.author === selectedAuthor).map(group => (
                <AuthorCard key={group.author} group={group} allQuotes={quotes} onUpdateQuote={updateQuote} onDeleteQuote={deleteQuote} onUpdateProfile={updateProfile} />
              ))}
            </div>
          </div>
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4 sm:gap-6">
            {filteredGroups.map(group => {
              const colorIdx = group.author.length % avatarColors.length;
              return (
                <button 
                  key={group.author} 
                  onClick={() => setSelectedAuthor(group.author)}
                  className="case-folder p-6 sm:p-8 rounded-lg text-left transition-transform hover:-translate-y-1 active:scale-[0.98]"
                >
                  <div className="flex justify-between items-start mb-4 sm:mb-6">
                    <div className={`w-12 h-12 sm:w-14 sm:h-14 border-2 rounded-lg flex items-center justify-center font-black text-xl ${avatarColors[colorIdx]}`}>
                      {group.author.charAt(0)}
                    </div>
                    <div className="stamp scale-90 sm:scale-100">Sample_{group.quotes.length}</div>
                  </div>
                  <h3 className="text-lg sm:text-xl font-black text-stone-900 mb-1">{group.author}</h3>
                  <p className="text-[9px] font-bold text-stone-500 uppercase tracking-widest">證據樣本已存檔</p>
                  {group.profile && (
