import React, { useState } from 'react';
import { Quote } from '../types';
import { refineNarrative } from '../services/geminiService';

interface AddQuoteModalProps {
  onAdd: (quote: Quote) => void;
  onClose: () => void;
  existingAuthors: string[];
}

const AddQuoteModal: React.FC<AddQuoteModalProps> = ({ onAdd, onClose, existingAuthors }) => {
  const [content, setContent] = useState('');
  const [author, setAuthor] = useState('');
  const [observationDate, setObservationDate] = useState(new Date().toISOString().split('T')[0]);
  const [tags, setTags] = useState('');
  const [isRefining, setIsRefining] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!content || !author) return;

    const newQuote: Quote = {
      id: Date.now().toString(),
      content,
      author: author.trim(),
      observationDate,
      timestamp: Date.now(),
      tags: tags.split(',').map(t => t.trim()).filter(t => t !== ''),
    };

    onAdd(newQuote);
    onClose();
  };

  const handleRefine = async () => {
    if (!content.trim() || isRefining) return;
    setIsRefining(true);
    try {
      const refined = await refineNarrative(content);
      setContent(refined);
    } catch (error) {
      console.error("AI 順稿失敗:", error);
    } finally {
      setIsRefining(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm overflow-y-auto">
      <div className="case-folder rounded-lg w-full max-w-lg shadow-2xl my-auto animate-in fade-in zoom-in duration-200 overflow-hidden">
        <div className="p-6 sm:p-8 border-b-2 border-stone-300 flex justify-between items-center bg-stone-100/50">
          <div>
            <h2 className="text-xl sm:text-2xl font-black text-stone-800 tracking-tighter">NEW_EVIDENCE_LOG</h2>
            <p className="text-[10px] text-stone-400 mt-1 uppercase tracking-widest font-black">證據取證採樣中</p>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-stone-200 rounded-full transition-colors text-stone-400">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-6 sm:p-8 space-y-6">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
            <div>
              <label className="block text-[10px] font-black text-stone-500 uppercase tracking-widest mb-2">事件日期</label>
              <input
                type="date"
                required
                value={observationDate}
                onChange={(e) => setObservationDate(e.target.value)}
                className="w-full px-4 py-3 bg-white/50 border border-stone-300 rounded focus:ring-1 focus:ring-stone-800 outline-none transition-all text-sm font-mono"
              />
            </div>
            <div>
              <label className="block text-[10px] font-black text-stone-500 uppercase tracking-widest mb-2">對象 Subject</label>
              <input
                type="text"
                required
                list="existing-authors"
                value={author}
                onChange={(e) => setAuthor(e.target.value)}
                autoComplete="off"
                className="w-full px-4 py-3 bg-white/50 border border-stone-300 rounded focus:ring-1 focus:ring-stone-800 outline-none transition-all text-sm font-mono"
                placeholder="輸入觀察對象..."
              />
              <datalist id="existing-authors">
                {existingAuthors.map(name => <option key={name} value={name} />)}
              </datalist>
            </div>
          </div>

          <div>
            <div className="flex justify-between items-center mb-2">
              <label className="block text-[10px] font-black text-stone-500 uppercase tracking-widest">證據內容 Transcript</label>
              <button
                type="button"
                onClick={handleRefine}
                disabled={isRefining || !content.trim()}
                className="text-[9px] font-black flex items-center gap-1.5 px-3 py-1 bg-stone-100 border border-stone-300 rounded-full hover:bg-stone-200 transition-all disabled:opacity-50"
              >
                {isRefining ? '美化中...' : '✨ 語句美化'}
              </button>
            </div>
            <textarea
              required
              value={content}
              onChange={(e) => setContent(e.target.value)}
              className="w-full px-5 py-4 bg-white/80 border-2 border-dashed border-stone-300 rounded-lg focus:border-stone-800 outline-none transition-all h-36 resize-none text-base font-handwriting leading-tight text-stone-800"
              placeholder="記錄最真實的觀察內容..."
            />
          </div>

          <div>
            <label className="block text-[10px] font-black text-stone-500 uppercase tracking-widest mb-2">心情標記 Tags (逗號隔開)</label>
            <input
              type="text"
              value={tags}
              onChange={(e) => setTags(e.target.value)}
              className="w-full px-4 py-3 bg-white/50 border border-stone-300 rounded focus:ring-1 focus:ring-stone-800 outline-none transition-all text-xs font-mono"
              placeholder="例如：驚訝, 幽默, 令人費解"
            />
          </div>

          <div className="pt-2">
            <button
              type="submit"
              className="w-full py-4 bg-stone-900 text-[#f1e7d0] rounded-lg font-black text-base uppercase tracking-widest hover:bg-black transition-all shadow-xl active:scale-[0.98]"
            >
              確認存檔並封印
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

