import React, { useState } from 'react';
import { Quote } from '../types';
import { refineNarrative } from '../services/geminiService';

interface AddQuoteModalProps {
  onAdd: (quote: Quote) => void;
  onClose: () => void;
  existingAuthors: string[];
}

const AddQuoteModal: React.FC<AddQuoteModalProps> = ({ onAdd, onClose, existingAuthors }) => {
  const [content, setContent] = useState('');
  const [author, setAuthor] = useState('');
  const [observationDate, setObservationDate] = useState(new Date().toISOString().split('T')[0]);
  const [tags, setTags] = useState('');
  const [isRefining, setIsRefining] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!content || !author) return;

    const newQuote: Quote = {
      id: Date.now().toString(),
      content,
      author: author.trim(),
      observationDate,
      timestamp: Date.now(),
      tags: tags.split(',').map(t => t.trim()).filter(t => t !== ''),
    };

    onAdd(newQuote);
    onClose();
  };

  const handleRefine = async () => {
    if (!content.trim() || isRefining) return;
    setIsRefining(true);
    try {
      const refined = await refineNarrative(content);
      setContent(refined);
    } catch (error) {
      console.error("AI 順稿失敗:", error);
    } finally {
      setIsRefining(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-2 sm:p-4 bg-slate-900/60 backdrop-blur-sm overflow-y-auto">
      <div className="case-folder rounded-lg w-full max-w-lg shadow-2xl my-auto animate-in fade-in zoom-in duration-200 overflow-hidden">
        <div className="p-5 sm:p-8 border-b-2 border-stone-300 flex justify-between items-center bg-[#ede4d5]">
          <div>
            <h2 className="text-xl sm:text-2xl font-black text-stone-800 tracking-tighter">NEW_EVIDENCE_LOG</h2>
            <p className="text-[8px] sm:text-[10px] text-stone-500 mt-0.5 uppercase tracking-widest font-black">證據取證採樣中 Archive_001</p>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-stone-300/50 rounded-full transition-colors text-stone-400">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-5 sm:p-8 space-y-5 sm:space-y-6 bg-[#f9f5ed]">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 sm:gap-6">
            <div>
              <label className="block text-[9px] font-black text-stone-500 uppercase tracking-widest mb-1.5">事件日期 Date</label>
              <input
                type="date"
                required
                value={observationDate}
                onChange={(e) => setObservationDate(e.target.value)}
                className="w-full px-4 py-2.5 bg-white border border-stone-300 rounded focus:ring-1 focus:ring-stone-800 outline-none transition-all text-sm font-mono"
              />
            </div>
            <div>
              <label className="block text-[9px] font-black text-stone-500 uppercase tracking-widest mb-1.5">對象 Subject</label>
              <input
                type="text"
                required
                list="existing-authors"
                value={author}
                onChange={(e) => setAuthor(e.target.value)}
                autoComplete="off"
                className="w-full px-4 py-2.5 bg-white border border-stone-300 rounded focus:ring-1 focus:ring-stone-800 outline-none transition-all text-sm font-mono"
                placeholder="ID 或代號..."
              />
              <datalist id="existing-authors">
                {existingAuthors.map(name => <option key={name} value={name} />)}
              </datalist>
            </div>
          </div>

          <div>
            <div className="flex justify-between items-center mb-1.5">
              <label className="block text-[9px] font-black text-stone-500 uppercase tracking-widest">證據 Transcript</label>
              <button
                type="button"
                onClick={handleRefine}
                disabled={isRefining || !content.trim()}
                className="text-[8px] font-black flex items-center gap-1.5 px-2.5 py-1 bg-stone-100 border border-stone-300 rounded hover:bg-stone-200 transition-all disabled:opacity-50"
              >
                {isRefining ? '整理中...' : '✨ 文本潤飾'}
              </button>
            </div>
            <textarea
              required
              value={content}
              onChange={(e) => setContent(e.target.value)}
              className="w-full px-4 py-3 bg-white border-2 border-dashed border-stone-300 rounded-lg focus:border-stone-800 outline-none transition-all h-32 sm:h-36 resize-none text-[15px] sm:text-base font-handwriting leading-snug text-stone-800"
              placeholder="記錄在此觀察到的對話或行為碎片..."
            />
          </div>

          <div>
            <label className="block text-[9px] font-black text-stone-500 uppercase tracking-widest mb-1.5">分類標記 Tags</label>
            <input
              type="text"
              value={tags}
              onChange={(e) => setTags(e.target.value)}
              className="w-full px-4 py-2.5 bg-white border border-stone-300 rounded focus:ring-1 focus:ring-stone-800 outline-none transition-all text-xs font-mono"
              placeholder="逗號隔開：驚訝, 幽默, 令人費解..."
            />
          </div>

          <div className="pt-2">
            <button
              type="submit"
              className="w-full py-3.5 sm:py-4 bg-stone-900 text-[#f1e7d0] rounded-lg font-black text-sm sm:text-base uppercase tracking-[0.2em] hover:bg-black transition-all shadow-lg active:scale-[0.98]"
            >
              提交檔案並封存
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

