          <div className="w-16 h-16 sm:w-20 sm:h-20 bg-stone-100 border-2 border-stone-400 rounded-lg flex items-center justify-center text-3xl sm:text-4xl font-black text-stone-800 shrink-0 shadow-sm">
            {group.author.charAt(0)}
          </div>
          <div className="flex-1 min-w-0">
