            <p className="text-[10px] font-bold text-stone-500 uppercase tracking-widest mt-1">
              Samples: #{group.quotes.length}
            </p>
            {group.profile && (
              <div className="mt-2 flex flex-wrap items-center gap-x-3 gap-y-1">
                <span className="text-blue-700 font-handwriting text-lg sm:text-xl italic">
                  "{group.profile.characterType}"
                </span>
                {/* 改為絕對定位或更輕量的小標籤，避免擠壓空間 */}
