5. 【自我保護與防衛策略】：壓力下的自動反應（理性化、抽離、冷處理？）
6. 【世界觀與價值觀（三觀）】：反推我最在乎的價值底線（例如：公平、效率、誠實、權力平衡等）。
7. 【詳細成長建議】：說明為什麼這是我方的弱點，並提供 3 個具體的優化練習。
8. 【總結】：人格素描。`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            conflictArchetype: { type: Type.STRING },
            thinkingTendency: { type: Type.STRING },
            responsePattern: { type: Type.STRING },
            emotionalFlow: { type: Type.STRING },
            conflictRoot: { type: Type.STRING },
            defenseProtocol: { type: Type.STRING },
            worldview: { type: Type.ARRAY, items: { type: Type.STRING }, description: "具體分析我對價值觀的 3-5 個核心觀點" },
            detailedGrowth: { type: Type.STRING, description: "深層弱點分析與具體的優化步驟說明" },
            growthInsight: { type: Type.STRING },
            summary: { type: Type.STRING }
          },
          required: ["conflictArchetype", "thinkingTendency", "responsePattern", "emotionalFlow", "conflictRoot", "defenseProtocol", "worldview", "detailedGrowth", "growthInsight", "summary"]
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("無內容");
    return { ...JSON.parse(text.trim()), lastUpdated: Date.now() };
  } catch (error) {
    console.error("Gemini generateMyProfile 失敗:", error);
    throw error;
  }
};

