          required: ["shortTitle", "resonanceScore", "weirdnessIndex", "sentiment", "sentimentLabel", "insight", "dynamic", "selfView", "otherView", "subtext", "relationshipRipple", "suggestedTags"]
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("無內容");
    return { ...JSON.parse(text.trim()), analyzedAt: Date.now() };
  } catch (error) {
    console.error("Gemini analyzeQuote 失敗:", error);
    throw error;
  }
};

