import React, { useState } from 'react';
import { Quote } from '../types';
import { analyzeQuote, refineNarrative } from '../services/geminiService';

interface QuoteItemProps {
  quote: Quote;
  allQuotes: Quote[];
  onUpdate: (updatedQuote: Quote) => void;
  onDelete: (id: string) => void;
}

const QuoteItem: React.FC<QuoteItemProps> = ({ quote, allQuotes, onUpdate, onDelete }) => {
  const [loading, setLoading] = useState(false);
  const [isExpanded, setIsExpanded] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editedContent, setEditedContent] = useState(quote.content);
  const [isRefining, setIsRefining] = useState(false);

  const handleAIAnalyze = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setLoading(true);
    try {
      // 若在編輯中儲存並分析，若不在編輯中直接分析
      const finalContent = isEditing ? editedContent : quote.content;
      const analysis = await analyzeQuote(finalContent, quote.author, quote.observationDate);
      onUpdate({ ...quote, content: finalContent, aiAnalysis: analysis });
      setIsEditing(false);
      setIsExpanded(true);
    } catch (error) {
      alert("分析失敗，請檢查 API Key 或網路狀態。");
    } finally {
      setLoading(false);
    }
  };

  const handleRefine = async () => {
    if (isRefining) return;
    setIsRefining(true);
    try {
      const refined = await refineNarrative(editedContent);
      setEditedContent(refined);
    } catch (error) {
      alert("潤飾失敗。");
    } finally {
      setIsRefining(false);
    }
  };

  const handleSaveEdit = (e: React.MouseEvent) => {
    e.stopPropagation();
    onUpdate({ ...quote, content: editedContent });
    setIsEditing(false);
  };

  return (
    <div className={`border-b border-stone-200 transition-all ${isExpanded ? 'bg-white/60 -mx-2 px-2 py-5 rounded-lg shadow-sm' : 'hover:bg-white/30 py-4'}`}>
      <div 
        onClick={() => setIsExpanded(!isExpanded)}
        className="flex items-start gap-3 cursor-pointer group"
      >
        <div className="shrink-0 w-14 text-center pt-1">
          <span className="block text-[8px] font-black text-stone-400 uppercase leading-none mb-1 opacity-60">
            {new Date(quote.observationDate).getFullYear()}
          </span>
          <span className="block text-xs font-black text-stone-800 tracking-tighter">
            {new Date(quote.observationDate).toLocaleDateString('zh-TW', { month: '2-digit', day: '2-digit' })}
          </span>
        </div>

        <div className="flex-1 min-w-0">
          <div className="flex flex-wrap items-center gap-x-2 gap-y-1 mb-1.5">
            {quote.aiAnalysis && (
              <span className="text-[8px] font-black px-1.5 py-0.5 border border-stone-800 uppercase tracking-tighter bg-white shadow-sm shrink-0">
                TENSION: {quote.aiAnalysis.resonanceScore}
              </span>
            )}
            <div className="flex flex-wrap gap-1">
              {quote.tags.slice(0, 3).map(tag => (
                <span key={tag} className="text-[8px] text-stone-400 font-bold font-mono">#{tag}</span>
              ))}
            </div>
          </div>
          <p className={`text-sm sm:text-base leading-snug ${isExpanded ? 'font-black text-stone-900' : 'truncate text-stone-600'}`}>
            {quote.aiAnalysis?.shortTitle || quote.content}
          </p>
        </div>

        <div className="shrink-0 pt-1.5 px-1">
          <svg className={`w-4 h-4 text-stone-300 transition-transform duration-300 ${isExpanded ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" />
          </svg>
        </div>
      </div>

      {isExpanded && (
        <div className="mt-6 animate-in slide-in-from-top-2 duration-300">
          {/* Raw Transcript Block with Edit functionality */}
          <div className="bg-white p-5 rounded-lg border border-stone-200 shadow-inner mb-6 relative group/edit">
            <div className="absolute -top-3 left-4 px-2 bg-[#f9f5ed] text-[8px] font-black text-stone-400 uppercase border border-stone-200">Raw Transcript</div>

            {!isEditing && (
              <button 
                onClick={(e) => { e.stopPropagation(); setIsEditing(true); setEditedContent(quote.content); }}
                className="absolute top-2 right-2 p-1.5 text-stone-300 hover:text-stone-800 transition-colors bg-white rounded-full border border-stone-100 shadow-sm"
                title="編輯紀錄"
              >
                <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" />
                </svg>
              </button>
            )}

            {isEditing ? (
              <div className="space-y-3">
                <textarea
                  value={editedContent}
                  onChange={(e) => setEditedContent(e.target.value)}
                  className="w-full bg-stone-50 border-2 border-dashed border-stone-200 rounded p-3 text-sm font-handwriting leading-tight outline-none focus:border-stone-400 min-h-[120px] transition-all"
                  placeholder="修正當時的對話細節..."
                  autoFocus
                />
                <div className="flex justify-between items-center">
                  <button
                    onClick={handleRefine}
                    disabled={isRefining}
                    className="text-[10px] font-black uppercase tracking-widest px-3 py-1.5 bg-stone-100 text-stone-600 hover:bg-stone-200 rounded border border-stone-200 flex items-center gap-1.5 disabled:opacity-50"
                  >
                    {isRefining ? '順稿中...' : '✨ AI 潤飾(白話)'}
                  </button>
                  <div className="flex gap-2">
                    <button 
                      onClick={(e) => { e.stopPropagation(); setIsEditing(false); }}
                      className="text-[10px] font-black uppercase tracking-widest px-3 py-1.5 text-stone-400 hover:text-stone-600"
                    >
                      取消
                    </button>
                    <button 
                      onClick={handleSaveEdit}
                      className="text-[10px] font-black uppercase tracking-widest px-4 py-1.5 bg-stone-800 text-white rounded shadow-sm hover:bg-black"
                    >
                      儲存變更
                    </button>
                  </div>
                </div>
              </div>
            ) : (
              <p className="text-lg sm:text-xl font-handwriting text-stone-800 leading-tight">
                "{quote.content}"
              </p>
            )}
          </div>

          {quote.aiAnalysis ? (
            <div className="space-y-6">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="bg-stone-50/80 p-4 border border-stone-200 rounded-lg">
                  <span className="text-[9px] font-black text-stone-400 block mb-2 uppercase tracking-widest border-b border-stone-200 pb-1">Observation_Self</span>
                  {quote.aiAnalysis.selfView.map((v, i) => <p key={i} className="text-xs text-stone-600 py-1 flex gap-2"><span className="text-stone-300">▹</span>{v}</p>)}
                </div>
                <div className="bg-stone-50/80 p-4 border border-stone-200 rounded-lg">
                  <span className="text-[9px] font-black text-stone-400 block mb-2 uppercase tracking-widest border-b border-stone-200 pb-1">Observation_Subject</span>
                  {quote.aiAnalysis.otherView.map((v, i) => <p key={i} className="text-xs text-stone-600 py-1 flex gap-2"><span className="text-stone-300">▹</span>{v}</p>)}
                </div>
              </div>

              <div className="bg-stone-900 text-[#f1e7d0] p-6 rounded-xl shadow-xl relative overflow-hidden">
                <h5 className="text-[9px] font-black text-stone-500 uppercase tracking-[0.3em] mb-4">Core Analysis Log</h5>
                <p className="text-lg font-black italic mb-4 leading-tight">"{quote.aiAnalysis.insight}"</p>
                <div className="h-px bg-stone-700 w-full mb-4 opacity-50"></div>
                <p className="text-sm text-stone-300 leading-relaxed font-light mb-6">
                  {quote.aiAnalysis.subtext}
                </p>

                <button 
                  onClick={handleAIAnalyze} 
                  disabled={loading}
                  className="w-full sm:w-auto px-4 py-2 border border-stone-700 rounded-lg text-[9px] font-black uppercase tracking-widest hover:bg-stone-800 transition-all flex items-center justify-center gap-2 disabled:opacity-50"
                >
                  <svg className={`w-3 h-3 ${loading ? 'animate-spin' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
                  </svg>
                  {loading ? '更新數據中...' : '重新剖析事件'}
                </button>
              </div>
            </div>
          ) : (
            <button 
              onClick={handleAIAnalyze} 
              disabled={loading} 
              className="group w-full py-8 border-2 border-dashed border-stone-300 rounded-xl text-[11px] font-black uppercase text-stone-400 hover:border-stone-800 hover:text-stone-800 transition-all flex flex-col items-center justify-center gap-2"
            >
              <span className="text-2xl mb-1">{loading ? '⌛' : '🧬'}</span>
              {loading ? '正在分析博弈動態...' : '啟動 AI 智慧觀察'}
            </button>
          )}

          <div className="mt-8 flex justify-between items-center px-1">
             <span className="text-[8px] font-mono text-stone-400 uppercase tracking-widest">Entry_ID: {quote.id.slice(-6)}</span>
            <button 
              onClick={(e) => { e.stopPropagation(); onDelete(quote.id); }} 
              className="text-[9px] font-black text-stone-300 hover:text-rose-700 uppercase tracking-widest flex items-center gap-1 transition-colors"
            >
              <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
              移除證據
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

