import React, { useState } from 'react';
import { Quote } from '../types';
import { refineNarrative } from '../services/geminiService';

interface AddQuoteModalProps {
  onAdd: (quote: Quote) => void;
  onClose: () => void;
  existingAuthors: string[];
}

const AddQuoteModal: React.FC<AddQuoteModalProps> = ({ onAdd, onClose, existingAuthors }) => {
  const [content, setContent] = useState('');
  const [author, setAuthor] = useState('');
  const [observationDate, setObservationDate] = useState(new Date().toISOString().split('T')[0]);
  const [tags, setTags] = useState('');
  const [isRefining, setIsRefining] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!content || !author) return;

    const newQuote: Quote = {
      id: Date.now().toString(),
      content,
      author: author.trim(),
      observationDate,
      timestamp: Date.now(),
      tags: tags.split(',').map(t => t.trim()).filter(t => t !== ''),
    };

    onAdd(newQuote);
    onClose();
  };

  const handleRefine = async () => {
    if (!content.trim() || isRefining) return;
    setIsRefining(true);
    try {
      // 確保已選取 API Key
      if (typeof window.aistudio !== 'undefined') {
        const hasKey = await window.aistudio.hasSelectedApiKey();
        if (!hasKey) {
          await window.aistudio.openSelectKey();
          // 指令要求 proceed immediately, 但我們會嘗試捕捉可能的第一次失敗
        }
      }

      const refined = await refineNarrative(content);
      setContent(refined);
    } catch (error: any) {
      console.error("AI 順稿失敗:", error);
      if (error.message?.includes("Requested entity was not found") || error.message?.includes("API_KEY_MISSING")) {
        alert("找不到有效的 API Key，請重新選取付費專案的金鑰。");
        if (typeof window.aistudio !== 'undefined') await window.aistudio.openSelectKey();
      } else {
        alert("潤飾失敗，請檢查網路連線或稍後再試。");
      }
    } finally {
      setIsRefining(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-2 sm:p-4 bg-slate-900/60 backdrop-blur-sm overflow-y-auto">
      <div className="case-folder rounded-lg w-full max-w-lg shadow-2xl my-auto animate-in fade-in zoom-in duration-200 overflow-hidden">
        <div className="p-5 sm:p-8 border-b-2 border-stone-300 flex justify-between items-center bg-[#ede4d5]">
          <div>
            <h2 className="text-xl sm:text-2xl font-black text-stone-800 tracking-tighter">NEW_EVIDENCE</h2>
            <p className="text-[8px] sm:text-[10px] text-stone-500 mt-0.5 uppercase tracking-widest font-black">Archive_Log_001</p>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-stone-300/50 rounded-full transition-colors text-stone-400">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

