interface ProfileModalProps {
  author: string;
  profile: AuthorProfile;
  onClose: () => void;
  onRefresh?: () => Promise<void>;
  isRefreshing?: boolean;
}

const ProfileModal: React.FC<ProfileModalProps> = ({ author, profile, onClose, onRefresh, isRefreshing = false }) => {
  const [loadingText, setLoadingText] = useState('正在校準神經網絡...');

  useEffect(() => {
    if (isRefreshing) {
      const texts = ['分析行為慣性...', '追蹤情緒觸發...', '模擬關係演進...', '生成對抗策略...'];
      let i = 0;
      const timer = setInterval(() => {
        setLoadingText(texts[i % texts.length]);
        i++;
      }, 1500);
      return () => clearInterval(timer);
    }
  }, [isRefreshing]);

  const RelationshipChart = () => {
    const hasTrend = profile.relationshipTrend && profile.relationshipTrend.length > 0;

    return (
      <div className="mt-4 bg-stone-100/50 p-4 sm:p-6 rounded-2xl border border-stone-300 shadow-inner">
        <h3 className="text-[9px] sm:text-[10px] font-black text-stone-500 uppercase tracking-widest mb-6 sm:mb-8 flex justify-between items-center">
