        {hasTrend ? (
          <div className="h-40 sm:h-48 flex items-end gap-1.5 sm:gap-3 px-1 pb-6 relative border-b border-stone-300">
            {/* 背景網格參考線 */}
            <div className="absolute inset-0 flex flex-col justify-between pointer-events-none pb-6">
              <div className="border-t border-stone-200 w-full h-0 relative">
                <span className="absolute -left-1 -top-2 text-[7px] text-stone-300 font-mono">100</span>
              </div>
              <div className="border-t border-stone-200 border-dashed w-full h-0 relative">
                <span className="absolute -left-1 -top-2 text-[7px] text-stone-300 font-mono">50</span>
              </div>
