                const score = typeof point.score === 'number' ? point.score : 0;
                const displayHeight = Math.max((score / 100) * 100, 5); // 至少 5% 高度可見

                return (
                  <div key={i} className="flex-1 min-w-[30px] max-w-[60px] flex flex-col items-center group relative z-10 h-full justify-end">
