                    <div className="absolute -top-6 left-1/2 -translate-x-1/2 opacity-0 group-hover:opacity-100 transition-all bg-stone-900 text-white text-[9px] px-2 py-0.5 rounded shadow-xl z-20 whitespace-nowrap pointer-events-none">
                      {point.label}: {score}
                    </div>

                    {/* 長條圖本體 */}
                    <div 
                      className={`w-full transition-all duration-700 ease-out rounded-t-sm relative cursor-pointer shadow-sm group-hover:shadow-md group-hover:brightness-110 ${score > 60 ? 'bg-stone-800' : 'bg-stone-400'}`}
                      style={{ height: `${displayHeight}%` }}
                    >
                      {/* 高光裝飾線 */}
                      <div className="absolute inset-y-0 left-0 w-[1px] bg-white/20"></div>
                    </div>

                    {/* 日期標籤 */}
                    <div className="absolute -bottom-6 left-1/2 -translate-x-1/2 text-[7px] sm:text-[8px] text-stone-500 font-mono whitespace-nowrap rotate-45 sm:rotate-0 origin-left">
