      </div>
    );
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-2 sm:p-4 bg-slate-900/60 backdrop-blur-sm overflow-y-auto">
      <div className="case-folder rounded-lg w-full max-w-2xl shadow-2xl relative my-auto animate-in fade-in zoom-in duration-300 overflow-hidden">
