            </div>
          </div>
        </div>

        <div className="p-6 sm:p-10 space-y-8 sm:space-y-10 max-h-[60vh] overflow-y-auto custom-scrollbar bg-[#f9f5ed]">
          <RelationshipChart />

          <section>
            <h3 className="text-[9px] sm:text-[10px] font-black text-stone-400 uppercase tracking-[0.2em] mb-3">調查家深度總結 Report Summary</h3>
            <p className="text-stone-700 leading-relaxed text-sm sm:text-base font-medium">{profile.summary}</p>
          </section>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 sm:gap-8">
            <section>
              <h3 className="text-[9px] sm:text-[10px] font-black text-stone-400 uppercase tracking-[0.2em] mb-3">顯著行為特質 Traits</h3>
              <div className="flex flex-wrap gap-2">
                {profile.traits.map((trait, i) => (
                  <span key={i} className="px-2.5 py-1 bg-white border border-stone-300 text-stone-700 rounded text-[10px] font-bold shadow-sm uppercase">{trait}</span>
                ))}
