import { GoogleGenAI, Type } from "@google/genai";
import { AIAnalysis, AuthorProfile, Quote, MyProfile } from "../types";

const getAIClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API_KEY_MISSING");
  }
  return new GoogleGenAI({ apiKey });
};

export const refineNarrative = async (rawContent: string): Promise<string> => {
  try {
    const ai = getAIClient();
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `請將以下原始觀察紀錄整理成通順、有條理且「自然平易」的繁體中文白話文。紀錄內容：\n\n${rawContent}`,
      config: { 
        systemInstruction: "你是一個幽默、毒舌但觀察入微的文字編輯。你的任務是將亂七八糟的口語紀錄整理成好讀、順暢的「白話敘述」。\n\n核心原則：\n1. 絕對禁止使用文言文（如：其、之、曰、於）。\n2. 禁止使用生硬的公文辭彙（如：該員、係屬、大放厥詞）。\n3. 保留原始對話的生命力與幽默笑點，讓它讀起來像是一個有趣的觀察日記。\n4. 直接回傳整理後的白話內容，不要有任何開場白或結語。",
        temperature: 0.5
      }
    });
    return response.text?.trim() || rawContent;
  } catch (error: any) {
    console.error("Gemini refineNarrative 失敗:", error);
    if (error.message === "API_KEY_MISSING") throw new Error("請先選取有效的 API Key");
    throw error;
  }
};

export const analyzeQuote = async (content: string, author: string, observationDate: string): Promise<AIAnalysis> => {
  try {
    const ai = getAIClient();
    const prompt = `你是一個極致理性的「人際關係軍師」，專門為「我方（觀察者）」剖析與「對方（${author}）」之間的對峙與衝突。

內容描述了你們的一次互動：「${content}」

分析指令：
