  }, [isRefreshing]);

  const RelationshipChart = () => {
    const hasTrend = profile.relationshipTrend && profile.relationshipTrend.length > 0;

    return (
      <div className="mt-4 bg-stone-100/50 p-4 sm:p-6 rounded-2xl border border-stone-300 shadow-inner">
