export default ProfileModal;

import React, { useState } from 'react';
import { AuthorGroup, Quote, AuthorProfile } from '../types';
import QuoteItem from './QuoteItem';
import ProfileModal from './ProfileModal';
import { generateAuthorProfile } from '../services/geminiService';

interface AuthorCardProps {
  group: AuthorGroup;
  allQuotes: Quote[];
  onUpdateQuote: (updatedQuote: Quote) => void;
  onDeleteQuote: (id: string) => void;
  onUpdateProfile: (author: string, profile: AuthorProfile | null) => void;
}

const AuthorCard: React.FC<AuthorCardProps> = ({ group, allQuotes, onUpdateQuote, onDeleteQuote, onUpdateProfile }) => {
  const [isGeneratingProfile, setIsGeneratingProfile] = useState(false);
  const [showProfile, setShowProfile] = useState(false);

  const handleGenerateProfile = async (e?: React.MouseEvent) => {
    e?.stopPropagation();
    if (isGeneratingProfile) return;

    // 檢查是否有足夠的 AI 分析紀錄
    const analyzedQuotes = group.quotes.filter(q => q.aiAnalysis);
    if (analyzedQuotes.length === 0) {
      alert("缺乏深度樣本：請先在右側事件列表中點擊「啟動 AI 智慧觀察」分析幾則紀錄。");
      return;
    }

    setIsGeneratingProfile(true);
    try {
      if (typeof window.aistudio !== 'undefined') {
        const hasKey = await window.aistudio.hasSelectedApiKey();
        if (!hasKey) await window.aistudio.openSelectKey();
      }

      const profile = await generateAuthorProfile(group.author, group.quotes);
      onUpdateProfile(group.author, profile);
      if (!group.profile) setShowProfile(true);
    } catch (error: any) {
      console.error("Profile generation error:", error);
      if (error.message?.includes("API_KEY_MISSING") || error.message?.includes("entity was not found")) {
        alert("剖析失敗：API Key 無效或尚未設定付費專案。");
        if (typeof window.aistudio !== 'undefined') await window.aistudio.openSelectKey();
      } else {
        alert("剖析連線失敗：請檢查網路或稍後再試。");
      }
    } finally {
      setIsGeneratingProfile(false);
    }
  };

  return (
    <div className="case-folder rounded-lg p-5 sm:p-10 flex flex-col gap-6 sm:gap-8 min-h-[500px] sm:min-h-[600px]">
      {/* Card Header */}
      <div className="flex flex-col gap-5 border-b-2 border-stone-300 pb-6 sm:pb-8 relative">
        <div className="flex items-start gap-4 sm:gap-6 relative">
          <div className="w-16 h-16 sm:w-20 sm:h-20 bg-stone-100 border-2 border-stone-400 rounded-lg flex items-center justify-center text-3xl sm:text-4xl font-black text-stone-800 shrink-0 shadow-sm z-10">
            {group.author.charAt(0)}
          </div>
          <div className="flex-1 min-w-0 pr-8">
            <h3 className="text-xl sm:text-3xl font-black text-stone-900 tracking-tighter truncate uppercase leading-tight">
              SUBJECT: {group.author}
            </h3>
            <p className="text-[10px] font-bold text-stone-500 uppercase tracking-widest mt-1">
              Samples: #{group.quotes.length} ({group.quotes.filter(q => q.aiAnalysis).length} analyzed)
            </p>
            {group.profile && (
              <div className="mt-2">
                <span className="text-blue-700 font-handwriting text-lg sm:text-2xl italic leading-none">
                  "{group.profile.characterType}"
                </span>
              </div>
            )}
          </div>
          {/* 印章絕對定位 */}
          {group.profile && (
            <div className="absolute top-0 right-0 stamp scale-75 sm:scale-90 opacity-40 pointer-events-none translate-x-1 -translate-y-1 select-none">
              Profiled
            </div>
          )}
        </div>

        <div className="flex flex-wrap gap-2">
          {group.profile ? (
            <>
              <button 
                onClick={() => setShowProfile(true)}
                className="flex-1 sm:flex-none px-5 py-2.5 bg-stone-900 text-[#f1e7d0] rounded-lg text-[10px] font-black uppercase tracking-widest hover:bg-black transition-all shadow-md active:scale-95"
              >
                查看分析報告
              </button>
              <button 
                onClick={handleGenerateProfile}
                disabled={isGeneratingProfile}
                className="flex-1 sm:flex-none px-4 py-2.5 bg-white border border-stone-300 text-stone-600 rounded-lg text-[10px] font-black uppercase tracking-widest hover:bg-stone-50 transition-all flex items-center justify-center gap-2 disabled:opacity-50"
              >
                <svg className={`w-3.5 h-3.5 ${isGeneratingProfile ? 'animate-spin' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
                </svg>
                {isGeneratingProfile ? '校準數據中...' : '重新生成跨時段剖析'}
              </button>
            </>
          ) : (
            <button 
              onClick={() => handleGenerateProfile()}
              disabled={isGeneratingProfile}
              className="w-full px-6 py-3.5 bg-stone-900 text-[#f1e7d0] rounded-lg text-xs font-black uppercase tracking-[0.2em] hover:bg-black transition-all shadow-lg flex items-center justify-center gap-3"
            >
              {isGeneratingProfile ? '正在解構博弈軌跡...' : '啟動跨時段深度分析 (Evolution Scan)'}
            </button>
          )}
        </div>
      </div>

      {/* Evidence List */}
      <div className="flex-1 space-y-4">
        <h4 className="text-[10px] font-black text-stone-400 uppercase tracking-widest mb-1 px-1 flex justify-between items-center">
          <span>Evidence History</span>
          <span className="text-[7px] opacity-60">OLD ➔ NEW</span>
        </h4>
        <div className="space-y-1">
          {[...group.quotes].sort((a, b) => {
            const dateCompare = a.observationDate.localeCompare(b.observationDate);
            if (dateCompare !== 0) return dateCompare;
            return a.timestamp - b.timestamp;
          }).map(quote => (
            <QuoteItem 
              key={quote.id} 
              quote={quote} 
              allQuotes={allQuotes}
              onUpdate={onUpdateQuote} 
              onDelete={onDeleteQuote} 
            />
          ))}
        </div>
      </div>

      {showProfile && group.profile && (
        <ProfileModal 
          author={group.author} 
          profile={group.profile} 
          onClose={() => setShowProfile(false)} 
          onRefresh={handleGenerateProfile}
          isRefreshing={isGeneratingProfile}
        />
      )}
    </div>
  );
};

export default AuthorCard;

