            ))}
          </div>
        )}
      </main>

      {isModalOpen && <AddQuoteModal onAdd={addQuote} onClose={() => setIsModalOpen(false)} existingAuthors={Array.from(new Set(quotes.map(q => q.author)))} />}
      {isMyProfileModalOpen && myProfile && <MyProfileModal profile={myProfile} onClose={() => setIsMyProfileModalOpen(false)} onRefresh={handleGenerateMyProfile} isRefreshing={isGeneratingMyProfile} />}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { AuthorGroup, Quote, AuthorProfile } from '../types';
import QuoteItem from './QuoteItem';
import ProfileModal from './ProfileModal';
import { generateAuthorProfile } from '../services/geminiService';

interface AuthorCardProps {
  group: AuthorGroup;
  allQuotes: Quote[];
  onUpdateQuote: (updatedQuote: Quote) => void;
  onDeleteQuote: (id: string) => void;
  onUpdateProfile: (author: string, profile: AuthorProfile | null) => void;
}

const AuthorCard: React.FC<AuthorCardProps> = ({ group, allQuotes, onUpdateQuote, onDeleteQuote, onUpdateProfile }) => {
  const [isGeneratingProfile, setIsGeneratingProfile] = useState(false);
  const [showProfile, setShowProfile] = useState(false);

  const handleGenerateProfile = async (e?: React.MouseEvent) => {
    e?.stopPropagation();
    if (isGeneratingProfile) return;

    // 檢查是否有足夠的 AI 分析紀錄
    const analyzedQuotes = group.quotes.filter(q => q.aiAnalysis);
    if (analyzedQuotes.length === 0) {
      alert("缺乏深度樣本：請先在右側事件列表中點擊「啟動 AI 智慧觀察」分析幾則紀錄。");
      return;
    }

    setIsGeneratingProfile(true);
    try {
      if (typeof window.aistudio !== 'undefined') {
        const hasKey = await window.aistudio.hasSelectedApiKey();
        if (!hasKey) await window.aistudio.openSelectKey();
      }

      const profile = await generateAuthorProfile(group.author, group.quotes);
      onUpdateProfile(group.author, profile);
      if (!group.profile) setShowProfile(true);
    } catch (error: any) {
      console.error("Profile generation error:", error);
      const errorMsg = error.message || "";
      if (errorMsg.includes("429") || errorMsg.includes("quota")) {
        alert("API 額度已耗盡：Gemini 免費層級限制每日請求次數。請稍後再試，或更換 API Key。");
      } else if (errorMsg.includes("API_KEY_MISSING") || errorMsg.includes("entity was not found")) {
        alert("剖析失敗：API Key 無效或尚未設定付費專案。");
        if (typeof window.aistudio !== 'undefined') await window.aistudio.openSelectKey();
      } else {
        alert("剖析連線失敗：請檢查網路或稍後再試。");
      }
    } finally {
      setIsGeneratingProfile(false);
    }
  };

  return (
    <div className="case-folder rounded-lg p-5 sm:p-10 flex flex-col gap-6 sm:gap-8 min-h-[500px] sm:min-h-[600px]">
      {/* Card Header */}
      <div className="flex flex-col gap-5 border-b-2 border-stone-300 pb-6 sm:pb-8 relative">
        <div className="flex items-start gap-4 sm:gap-6 relative">
          <div className="w-16 h-16 sm:w-20 sm:h-20 bg-stone-100 border-2 border-stone-400 rounded-lg flex items-center justify-center text-3xl sm:text-4xl font-black text-stone-800 shrink-0 shadow-sm z-10">
            {group.author.charAt(0)}
          </div>
          <div className="flex-1 min-w-0 pr-8">
            <h3 className="text-xl sm:text-3xl font-black text-stone-900 tracking-tighter truncate uppercase leading-tight">
              SUBJECT: {group.author}
            </h3>
            <p className="text-[10px] font-bold text-stone-500 uppercase tracking-widest mt-1">
              Samples: #{group.quotes.length} ({group.quotes.filter(q => q.aiAnalysis).length} analyzed)
            </p>
            {group.profile && (
              <div className="mt-2">
                <span className="text-blue-700 font-handwriting text-lg sm:text-2xl italic leading-none">
                  "{group.profile.characterType}"
                </span>
              </div>
            )}
          </div>
          {/* 印章絕對定位 */}
          {group.profile && (
            <div className="absolute top-0 right-0 stamp scale-75 sm:scale-90 opacity-40 pointer-events-none translate-x-1 -translate-y-1 select-none">
              Profiled
            </div>
          )}
        </div>

        <div className="flex flex-wrap gap-2">
          {group.profile ? (
            <>
              <button 
                onClick={() => setShowProfile(true)}
                className="flex-1 sm:flex-none px-5 py-2.5 bg-stone-900 text-[#f1e7d0] rounded-lg text-[10px] font-black uppercase tracking-widest hover:bg-black transition-all shadow-md active:scale-95"
              >
                查看分析報告
              </button>
              <button 
                onClick={handleGenerateProfile}
                disabled={isGeneratingProfile}
                className="flex-1 sm:flex-none px-4 py-2.5 bg-white border border-stone-300 text-stone-600 rounded-lg text-[10px] font-black uppercase tracking-widest hover:bg-stone-50 transition-all flex items-center justify-center gap-2 disabled:opacity-50"
              >
                <svg className={`w-3.5 h-3.5 ${isGeneratingProfile ? 'animate-spin' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
                </svg>
                {isGeneratingProfile ? '校準數據中...' : '重新生成跨時段剖析'}
              </button>
            </>
          ) : (
            <button 
              onClick={() => handleGenerateProfile()}
              disabled={isGeneratingProfile}
              className="w-full px-6 py-3.5 bg-stone-900 text-[#f1e7d0] rounded-lg text-xs font-black uppercase tracking-[0.2em] hover:bg-black transition-all shadow-lg flex items-center justify-center gap-3"
            >
              {isGeneratingProfile ? '正在解構博弈軌跡...' : '啟動跨時段深度分析 (Evolution Scan)'}
            </button>
          )}
        </div>
      </div>

      {/* Evidence List */}
      <div className="flex-1 space-y-4">
        <h4 className="text-[10px] font-black text-stone-400 uppercase tracking-widest mb-1 px-1 flex justify-between items-center">
          <span>Evidence History</span>
          <span className="text-[7px] opacity-60">OLD ➔ NEW</span>
        </h4>
        <div className="space-y-1">
          {[...group.quotes].sort((a, b) => {
            const dateCompare = a.observationDate.localeCompare(b.observationDate);
            if (dateCompare !== 0) return dateCompare;
            return a.timestamp - b.timestamp;
          }).map(quote => (
            <QuoteItem 
              key={quote.id} 
              quote={quote} 
              allQuotes={allQuotes}
              onUpdate={onUpdateQuote} 
              onDelete={onDeleteQuote} 
            />
          ))}
        </div>
      </div>

      {showProfile && group.profile && (
        <ProfileModal 
          author={group.author} 
          profile={group.profile} 
          onClose={() => setShowProfile(false)} 
          onRefresh={handleGenerateProfile}
          isRefreshing={isGeneratingProfile}
        />
      )}
    </div>
  );
};

export default AuthorCard;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Quote, AuthorGroup, AuthorProfile, AppDataBackup, MyProfile } from './types';
import AuthorCard from './components/AuthorCard';
import AddQuoteModal from './components/AddQuoteModal';
import MyProfileModal from './components/MyProfileModal';
import { generateMyProfile } from './services/geminiService';

const STORAGE_KEY = 'human-logs-v3-quotes';
const PROFILES_KEY = 'human-logs-v3-profiles';
const MY_PROFILE_KEY = 'human-logs-v3-myprofile';
const APP_VERSION = '4.0.0';

type SortType = 'lastUpdate' | 'frequency';

const App: React.FC = () => {
  const [quotes, setQuotes] = useState<Quote[]>([]);
  const [profiles, setProfiles] = useState<Record<string, AuthorProfile>>({});
  const [myProfile, setMyProfile] = useState<MyProfile | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMyProfileModalOpen, setIsMyProfileModalOpen] = useState(false);
  const [isGeneratingMyProfile, setIsGeneratingMyProfile] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [sortBy, setSortBy] = useState<SortType>('lastUpdate');
  const [showSyncMenu, setShowSyncMenu] = useState(false);
  const [selectedAuthor, setSelectedAuthor] = useState<string | null>(null);
  const [feedbackMessage, setFeedbackMessage] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Load data from localStorage on mount
  useEffect(() => {
    const savedQuotes = localStorage.getItem(STORAGE_KEY);
    const savedProfiles = localStorage.getItem(PROFILES_KEY);
    const savedMyProfile = localStorage.getItem(MY_PROFILE_KEY);
    if (savedQuotes) {
      try {
        const parsed = JSON.parse(savedQuotes);
        setQuotes(Array.isArray(parsed) ? parsed : []);
      } catch (e) { console.error("Restore failed", e); }
    }
    if (savedProfiles) {
      try {
        setProfiles(JSON.parse(savedProfiles));
      } catch (e) { console.error("Restore profiles failed", e); }
    }
    if (savedMyProfile) {
      try {
        setMyProfile(JSON.parse(savedMyProfile));
      } catch (e) { console.error("Restore my profile failed", e); }
    }
  }, []);

  // Sync data to localStorage
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(quotes));
  }, [quotes]);

  useEffect(() => {
    localStorage.setItem(PROFILES_KEY, JSON.stringify(profiles));
  }, [profiles]);

  useEffect(() => {
    if (myProfile) localStorage.setItem(MY_PROFILE_KEY, JSON.stringify(myProfile));
  }, [myProfile]);

  const addQuote = (newQuote: Quote) => setQuotes(prev => [newQuote, ...prev]);
  const updateQuote = (updatedQuote: Quote) => setQuotes(prev => prev.map(q => q.id === updatedQuote.id ? updatedQuote : q));
  const deleteQuote = (id: string) => setQuotes(prev => prev.filter(q => q.id !== id));

  const updateProfile = (author: string, profile: AuthorProfile | null) => {
    setProfiles(prev => {
      const next = { ...prev };
      if (profile === null) delete next[author];
      else next[author] = profile;
      return next;
    });
  };

  const triggerFeedback = (msg: string) => {
    setFeedbackMessage(msg);
    setTimeout(() => setFeedbackMessage(null), 4000);
  };

  // Generate the global user profile (Self Insight)
  const handleGenerateMyProfile = async () => {
    if (isGeneratingMyProfile) return;

    const analyzedQuotes = quotes.filter(q => q.aiAnalysis);
    if (analyzedQuotes.length === 0) {
      triggerFeedback("深度不足：請先在個別紀錄中啟動 AI 深度分析。");
      return;
    }

    setIsGeneratingMyProfile(true);
    try {
      if (typeof window.aistudio !== 'undefined') {
        const hasKey = await window.aistudio.hasSelectedApiKey();
        if (!hasKey) await window.aistudio.openSelectKey();
      }

      const profile = await generateMyProfile(quotes);
      setMyProfile(profile);
      setIsMyProfileModalOpen(true);
      triggerFeedback("靈魂畫像校準完成");
    } catch (e: any) {
      console.error("My profile generation error:", e);
      const errorMsg = e.message || e.toString() || "";
      if (errorMsg.includes("429") || errorMsg.includes("quota") || errorMsg.includes("RESOURCE_EXHAUSTED")) {
        alert("⚠️ Gemini API 額度已耗盡\n\n目前的請求頻率或每日配額已達上限。請：\n1. 稍等一兩分鐘後再次點擊刷新。\n2. 若仍不行，請隔日再試。\n3. 或更換一個 API Key。\n\n(免費版 API 每分鐘/每日請求次數有限)");
      } else if (errorMsg.includes("API_KEY_MISSING") || errorMsg.includes("Requested entity was not found")) {
        triggerFeedback("API Key 錯誤：請重新選取付費專案金鑰。");
        if (typeof window.aistudio !== 'undefined') await window.aistudio.openSelectKey();
      } else {
        triggerFeedback("連線超時：請檢查網路或稍後再試。");
      }
    } finally {
      setIsGeneratingMyProfile(false);
    }
  };

  const handleExport = () => {
    const data: AppDataBackup = { version: APP_VERSION, quotes, profiles, myProfile: myProfile || undefined, exportedAt: new Date().toISOString() };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `case-files-${new Date().toISOString().split('T')[0]}.json`;
    a.click();
    URL.revokeObjectURL(url);
    setShowSyncMenu(false);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data: AppDataBackup = JSON.parse(event.target?.result as string);
        if (data.quotes) {
          setQuotes(data.quotes);
          if (data.profiles) setProfiles(data.profiles);
          if (data.myProfile) setMyProfile(data.myProfile);
          triggerFeedback("匯入成功");
        }
      } catch (e) { alert('匯入格式錯誤'); }
      setShowSyncMenu(false);
    };
    reader.readAsText(file);
  };

  const allGroups = useMemo(() => {
    const groups: Record<string, AuthorGroup> = {};
    quotes.forEach(q => {
      if (!groups[q.author]) {
        groups[q.author] = { author: q.author, quotes: [], lastUpdate: 0, profile: profiles[q.author] };
      }
      groups[q.author].quotes.push(q);
      const obsTime = new Date(q.observationDate).getTime();
      if (obsTime > groups[q.author].lastUpdate) groups[q.author].lastUpdate = obsTime;
    });
    return Object.values(groups).sort((a, b) => b.lastUpdate - a.lastUpdate);
  }, [quotes, profiles]);

  const filteredGroups = useMemo(() => {
    const s = searchQuery.trim().toLowerCase();
    if (!s) return allGroups;
    return allGroups.filter(g => 
      g.author.toLowerCase().includes(s) || 
      g.quotes.some(q => q.content.toLowerCase().includes(s))
    );
  }, [allGroups, searchQuery]);

  return (
    <div className="min-h-screen pb-20 sm:pb-32">
      <nav className="sticky top-0 z-50 bg-[#ede4d5]/95 backdrop-blur-md border-b border-stone-300">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 h-16 sm:h-20 flex items-center justify-between gap-2 sm:gap-4">
          <div className="flex items-center gap-2 sm:gap-3 shrink-0 cursor-pointer" onClick={() => setSelectedAuthor(null)}>
            <div className="w-8 h-8 sm:w-10 sm:h-10 bg-stone-800 rounded flex items-center justify-center text-[#f1e7d0] shadow-md">
              <span className="text-lg sm:text-xl font-black">C</span>
            </div>
            <h1 className="hidden md:block text-xl font-black text-stone-900 tracking-tighter uppercase">CASE_FILES</h1>
          </div>

          <div className="flex-1 max-w-sm relative">
            <input
              type="text"
              placeholder="搜尋證據..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full bg-white/50 border border-stone-300 rounded-lg pl-9 pr-4 py-2 text-xs sm:text-sm outline-none focus:ring-1 focus:ring-stone-400"
            />
            <svg className="absolute left-3 top-2.5 w-4 h-4 text-stone-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
            </svg>
          </div>

          <div className="flex items-center gap-2">
            <button 
              onClick={() => setShowSyncMenu(!showSyncMenu)}
              className="p-2 hover:bg-stone-200 rounded-full transition-colors relative"
            >
              <svg className="w-5 h-5 text-stone-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1m-4-8l-4-4m0 0L8 8m4-4v12" />
              </svg>
              {showSyncMenu && (
                <div className="absolute right-0 mt-2 w-48 bg-white border border-stone-200 rounded-lg shadow-xl py-2 z-50">
                  <button onClick={handleExport} className="w-full px-4 py-2 text-left text-sm hover:bg-stone-50 flex items-center gap-2">
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1M8 8l4 4m0 0l4-4m-4 4V4" /></svg>
                    導出備份
                  </button>
                  <button onClick={() => fileInputRef.current?.click()} className="w-full px-4 py-2 text-left text-sm hover:bg-stone-50 flex items-center gap-2">
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1M12 12h.01M16 8l-4 4-4-4" /></svg>
                    匯入備份
                  </button>
                </div>
              )}
            </button>
            <input type="file" ref={fileInputRef} onChange={handleImport} className="hidden" accept=".json" />
          </div>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 py-8">
        {feedbackMessage && (
          <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[60] animate-in fade-in slide-in-from-top-4">
            <div className="bg-stone-800 text-[#f1e7d0] px-6 py-3 rounded-full shadow-2xl text-xs font-black uppercase tracking-widest border border-stone-600">
              {feedbackMessage}
            </div>
          </div>
        )}

        {selectedAuthor ? (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
            {filteredGroups.filter(g => g.author === selectedAuthor).map(group => (
              <AuthorCard 
                key={group.author} 
                group={group} 
                allQuotes={quotes}
                onUpdateQuote={updateQuote} 
                onDeleteQuote={deleteQuote} 
                onUpdateProfile={updateProfile}
              />
            ))}
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredGroups.map(group => (
              <div 
                key={group.author} 
                onClick={() => setSelectedAuthor(group.author)}
                className="case-folder p-6 cursor-pointer hover:shadow-xl transition-all group relative overflow-hidden h-64 flex flex-col justify-between"
              >
                <div className="flex items-start gap-4">
                  <div className="w-12 h-12 bg-stone-100 border border-stone-300 rounded flex items-center justify-center text-xl font-black text-stone-800">
                    {group.author.charAt(0)}
                  </div>
                  <div className="flex-1 min-w-0">
                    <h3 className="text-lg font-black text-stone-900 truncate uppercase">SUBJECT: {group.author}</h3>
                    <p className="text-[10px] text-stone-500 font-bold uppercase tracking-widest">Samples: {group.quotes.length}</p>
                  </div>
                </div>
                {group.profile && (
                   <p className="text-blue-700 font-handwriting italic text-lg truncate mt-2">"{group.profile.characterType}"</p>
                )}
                <div className="mt-auto pt-4 border-t border-stone-200 flex justify-between items-center text-[10px] text-stone-400 font-mono">
                  <span>Last Update: {new Date(group.lastUpdate).toLocaleDateString()}</span>
                  <span className="group-hover:text-stone-800 transition-colors">Open File ➔</span>
                </div>
              </div>
            ))}

            {filteredGroups.length === 0 && (
              <div className="col-span-full py-20 text-center">
                <p className="text-stone-400 font-black uppercase tracking-[0.3em] text-xs">No Case Files Found</p>
              </div>
            )}
          </div>
        )}
      </main>

      {/* Floating Action Buttons */}
      <div className="fixed bottom-6 right-6 flex flex-col gap-4 z-40">
        <button 
          onClick={handleGenerateMyProfile}
          disabled={isGeneratingMyProfile}
          className="w-14 h-14 bg-white border-2 border-stone-800 rounded-full flex items-center justify-center shadow-xl hover:bg-stone-50 transition-all group relative"
          title="我的觀察視角"
        >
          {isGeneratingMyProfile ? (
            <div className="w-6 h-6 border-2 border-stone-800 border-t-transparent rounded-full animate-spin"></div>
          ) : (
             <span className="text-2xl group-hover:scale-110 transition-transform">👁️</span>
          )}
          <span className="absolute right-full mr-4 top-1/2 -translate-y-1/2 px-3 py-1 bg-stone-800 text-white text-[10px] font-black uppercase tracking-widest rounded whitespace-nowrap opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none">
            我的觀察視角
          </span>
        </button>

        <button 
          onClick={() => setIsModalOpen(true)}
          className="w-14 h-14 bg-stone-900 text-[#f1e7d0] rounded-full flex items-center justify-center shadow-xl hover:scale-105 transition-all group relative"
          title="新增證據"
        >
          <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4" /></svg>
          <span className="absolute right-full mr-4 top-1/2 -translate-y-1/2 px-3 py-1 bg-stone-800 text-white text-[10px] font-black uppercase tracking-widest rounded whitespace-nowrap opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none">
            記錄新發現
          </span>
        </button>
      </div>

      {isModalOpen && (
        <AddQuoteModal 
          onAdd={addQuote} 
          onClose={() => setIsModalOpen(false)} 
          existingAuthors={allGroups.map(g => g.author)}
        />
      )}

      {isMyProfileModalOpen && myProfile && (
        <MyProfileModal 
          profile={myProfile} 
          onClose={() => setIsMyProfileModalOpen(false)} 
          onRefresh={handleGenerateMyProfile}
          isRefreshing={isGeneratingMyProfile}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Quote, AuthorGroup, AuthorProfile, AppDataBackup, MyProfile } from './types';
import AuthorCard from './components/AuthorCard';
import AddQuoteModal from './components/AddQuoteModal';
import MyProfileModal from './components/MyProfileModal';
import { generateMyProfile } from './services/geminiService';

const STORAGE_KEY = 'human-logs-v3-quotes';
const PROFILES_KEY = 'human-logs-v3-profiles';
const MY_PROFILE_KEY = 'human-logs-v3-myprofile';
const APP_VERSION = '4.0.0';

type SortType = 'lastUpdate' | 'frequency';

const App: React.FC = () => {
  const [quotes, setQuotes] = useState<Quote[]>([]);
  const [profiles, setProfiles] = useState<Record<string, AuthorProfile>>({});
  const [myProfile, setMyProfile] = useState<MyProfile | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMyProfileModalOpen, setIsMyProfileModalOpen] = useState(false);
  const [isGeneratingMyProfile, setIsGeneratingMyProfile] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [sortBy, setSortBy] = useState<SortType>('lastUpdate');
  const [showSyncMenu, setShowSyncMenu] = useState(false);
  const [selectedAuthor, setSelectedAuthor] = useState<string | null>(null);
  const [feedbackMessage, setFeedbackMessage] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Load data from localStorage on mount
  useEffect(() => {
    const savedQuotes = localStorage.getItem(STORAGE_KEY);
    const savedProfiles = localStorage.getItem(PROFILES_KEY);
    const savedMyProfile = localStorage.getItem(MY_PROFILE_KEY);
    if (savedQuotes) {
      try {
        const parsed = JSON.parse(savedQuotes);
        setQuotes(Array.isArray(parsed) ? parsed : []);
      } catch (e) { console.error("Restore failed", e); }
    }
    if (savedProfiles) {
      try {
        setProfiles(JSON.parse(savedProfiles));
      } catch (e) { console.error("Restore profiles failed", e); }
    }
    if (savedMyProfile) {
      try {
        setMyProfile(JSON.parse(savedMyProfile));
      } catch (e) { console.error("Restore my profile failed", e); }
    }
  }, []);

  // Sync data to localStorage
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(quotes));
  }, [quotes]);

  useEffect(() => {
    localStorage.setItem(PROFILES_KEY, JSON.stringify(profiles));
  }, [profiles]);

  useEffect(() => {
    if (myProfile) localStorage.setItem(MY_PROFILE_KEY, JSON.stringify(myProfile));
  }, [myProfile]);

  const addQuote = (newQuote: Quote) => setQuotes(prev => [newQuote, ...prev]);
  const updateQuote = (updatedQuote: Quote) => setQuotes(prev => prev.map(q => q.id === updatedQuote.id ? updatedQuote : q));
  const deleteQuote = (id: string) => setQuotes(prev => prev.filter(q => q.id !== id));

  const updateProfile = (author: string, profile: AuthorProfile | null) => {
    setProfiles(prev => {
      const next = { ...prev };
      if (profile === null) delete next[author];
      else next[author] = profile;
      return next;
    });
  };

  const triggerFeedback = (msg: string) => {
    setFeedbackMessage(msg);
    setTimeout(() => setFeedbackMessage(null), 4000);
  };

  // Generate the global user profile (Self Insight)
  const handleGenerateMyProfile = async () => {
    if (isGeneratingMyProfile) return;

    const analyzedQuotes = quotes.filter(q => q.aiAnalysis);
    if (analyzedQuotes.length === 0) {
      triggerFeedback("樣本不足：請先分析幾則紀錄。");
      return;
    }

    setIsGeneratingMyProfile(true);
    try {
      if (typeof window.aistudio !== 'undefined') {
        const hasKey = await window.aistudio.hasSelectedApiKey();
        if (!hasKey) await window.aistudio.openSelectKey();
      }

      const profile = await generateMyProfile(quotes);
      setMyProfile(profile);
      setIsMyProfileModalOpen(true);
      triggerFeedback("靈魂畫像校準完成");
    } catch (e: any) {
      console.error("My profile generation error:", e);
      const errorMsg = e.message || e.toString() || "";
      if (errorMsg.includes("429") || errorMsg.includes("quota") || errorMsg.includes("RESOURCE_EXHAUSTED")) {
        alert("⚠️ API 額度已耗盡\n\nGemini 免費版 API 每分鐘與每日請求次數有限。\n請稍等 30 秒後再試，或更換 API Key。");
      } else if (errorMsg.includes("API_KEY_MISSING") || errorMsg.includes("Requested entity was not found")) {
        triggerFeedback("API Key 錯誤：請重新選取金鑰。");
        if (typeof window.aistudio !== 'undefined') await window.aistudio.openSelectKey();
      } else {
        triggerFeedback("分析失敗，請檢查網路狀態。");
      }
    } finally {
      setIsGeneratingMyProfile(false);
    }
  };

  const handleExport = () => {
    const data: AppDataBackup = { version: APP_VERSION, quotes, profiles, myProfile: myProfile || undefined, exportedAt: new Date().toISOString() };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `case-files-${new Date().toISOString().split('T')[0]}.json`;
    a.click();
    URL.revokeObjectURL(url);
    setShowSyncMenu(false);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data: AppDataBackup = JSON.parse(event.target?.result as string);
        if (data.quotes) {
          setQuotes(data.quotes);
          if (data.profiles) setProfiles(data.profiles);
          if (data.myProfile) setMyProfile(data.myProfile);
          triggerFeedback("匯入成功");
        }
      } catch (e) { alert('匯入格式錯誤'); }
      setShowSyncMenu(false);
    };
    reader.readAsText(file);
  };

  const allGroups = useMemo(() => {
    const groups: Record<string, AuthorGroup> = {};
    quotes.forEach(q => {
      if (!groups[q.author]) {
        groups[q.author] = { author: q.author, quotes: [], lastUpdate: 0, profile: profiles[q.author] };
      }
      groups[q.author].quotes.push(q);
      const obsTime = new Date(q.observationDate).getTime();
      if (obsTime > groups[q.author].lastUpdate) groups[q.author].lastUpdate = obsTime;
    });
    return Object.values(groups).sort((a, b) => b.lastUpdate - a.lastUpdate);
  }, [quotes, profiles]);

  const filteredGroups = useMemo(() => {
    const s = searchQuery.trim().toLowerCase();
    if (!s) return allGroups;
    return allGroups.filter(g => 
      g.author.toLowerCase().includes(s) || 
      g.quotes.some(q => q.content.toLowerCase().includes(s))
    );
  }, [allGroups, searchQuery]);

  return (
    <div className="min-h-screen pb-20 sm:pb-32">
      <nav className="sticky top-0 z-50 bg-[#ede4d5]/95 backdrop-blur-md border-b border-stone-300">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 h-16 sm:h-20 flex items-center justify-between gap-2 sm:gap-4">
          <div className="flex items-center gap-2 sm:gap-3 shrink-0 cursor-pointer" onClick={() => setSelectedAuthor(null)}>
            <div className="w-8 h-8 sm:w-10 sm:h-10 bg-stone-800 rounded flex items-center justify-center text-[#f1e7d0] shadow-md">
              <span className="text-lg sm:text-xl font-black">C</span>
            </div>
            <h1 className="hidden md:block text-xl font-black text-stone-900 tracking-tighter uppercase">CASE_FILES</h1>
          </div>

          <div className="flex-1 max-w-sm relative">
            <input
              type="text"
              placeholder="搜尋證據..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full bg-white/50 border border-stone-300 rounded-lg pl-9 pr-4 py-2 text-xs sm:text-sm outline-none focus:ring-1 focus:ring-stone-400"
            />
            <svg className="absolute left-3 top-2.5 w-4 h-4 text-stone-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
            </svg>
          </div>

          <div className="flex items-center gap-2">
            <button 
              onClick={() => setShowSyncMenu(!showSyncMenu)}
              className="p-2 hover:bg-stone-200 rounded-full transition-colors relative"
            >
              <svg className="w-5 h-5 text-stone-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1m-4-8l-4-4m0 0L8 8m4-4v12" />
              </svg>
              {showSyncMenu && (
                <div className="absolute right-0 mt-2 w-48 bg-white border border-stone-200 rounded-lg shadow-xl py-2 z-50">
                  <button onClick={handleExport} className="w-full px-4 py-2 text-left text-sm hover:bg-stone-50 flex items-center gap-2">
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1M8 8l4 4m0 0l4-4m-4 4V4" /></svg>
                    導出備份
                  </button>
                  <button onClick={() => fileInputRef.current?.click()} className="w-full px-4 py-2 text-left text-sm hover:bg-stone-50 flex items-center gap-2">
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1M12 12h.01M16 8l-4 4-4-4" /></svg>
                    匯入備份
                  </button>
                </div>
              )}
            </button>
            <input type="file" ref={fileInputRef} onChange={handleImport} className="hidden" accept=".json" />
          </div>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 py-8">
        {feedbackMessage && (
          <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[60] animate-in fade-in slide-in-from-top-4">
            <div className="bg-stone-800 text-[#f1e7d0] px-6 py-3 rounded-full shadow-2xl text-xs font-black uppercase tracking-widest border border-stone-600">
              {feedbackMessage}
            </div>
          </div>
        )}

        {selectedAuthor ? (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
            {filteredGroups.filter(g => g.author === selectedAuthor).map(group => (
              <AuthorCard 
                key={group.author} 
                group={group} 
                allQuotes={quotes}
                onUpdateQuote={updateQuote} 
                onDeleteQuote={deleteQuote} 
                onUpdateProfile={updateProfile}
              />
            ))}
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredGroups.map(group => (
              <div 
                key={group.author} 
                onClick={() => setSelectedAuthor(group.author)}
                className="case-folder p-6 cursor-pointer hover:shadow-xl transition-all group relative overflow-hidden h-64 flex flex-col justify-between"
              >
                <div className="flex items-start gap-4">
                  <div className="w-12 h-12 bg-stone-100 border border-stone-300 rounded flex items-center justify-center text-xl font-black text-stone-800">
                    {group.author.charAt(0)}
                  </div>
                  <div className="flex-1 min-w-0">
                    <h3 className="text-lg font-black text-stone-900 truncate uppercase">SUBJECT: {group.author}</h3>
                    <p className="text-[10px] text-stone-500 font-bold uppercase tracking-widest">Samples: {group.quotes.length}</p>
                  </div>
                </div>
                {group.profile && (
                   <p className="text-blue-700 font-handwriting italic text-lg truncate mt-2">"{group.profile.characterType}"</p>
                )}
                <div className="mt-auto pt-4 border-t border-stone-200 flex justify-between items-center text-[10px] text-stone-400 font-mono">
                  <span>Last Update: {new Date(group.lastUpdate).toLocaleDateString()}</span>
                  <span className="group-hover:text-stone-800 transition-colors">Open File ➔</span>
                </div>
              </div>
            ))}

            {filteredGroups.length === 0 && (
              <div className="col-span-full py-20 text-center">
                <p className="text-stone-400 font-black uppercase tracking-[0.3em] text-xs">No Case Files Found</p>
              </div>
            )}
          </div>
        )}
      </main>

      {/* Floating Action Buttons */}
      <div className="fixed bottom-6 right-6 flex flex-col gap-4 z-40">
        <button 
          onClick={() => myProfile ? setIsMyProfileModalOpen(true) : handleGenerateMyProfile()}
          disabled={isGeneratingMyProfile}
          className={`w-14 h-14 rounded-full flex items-center justify-center shadow-xl hover:scale-105 transition-all group relative border-2 ${
            myProfile ? 'bg-stone-900 text-white border-stone-900' : 'bg-white text-stone-800 border-stone-800'
          }`}
          title="我的觀察視角"
        >
          {isGeneratingMyProfile ? (
            <div className="w-6 h-6 border-2 border-current border-t-transparent rounded-full animate-spin"></div>
          ) : (
             <span className="text-2xl group-hover:rotate-12 transition-transform">👁️</span>
          )}
          <span className="absolute right-full mr-4 top-1/2 -translate-y-1/2 px-3 py-1 bg-stone-800 text-white text-[10px] font-black uppercase tracking-widest rounded whitespace-nowrap opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none">
            {myProfile ? '查看我的視角' : '啟動自我剖析'}
          </span>
        </button>

        <button 
          onClick={() => setIsModalOpen(true)}
          className="w-14 h-14 bg-stone-900 text-[#f1e7d0] rounded-full flex items-center justify-center shadow-xl hover:scale-105 transition-all group relative"
          title="新增證據"
        >
          <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4" /></svg>
          <span className="absolute right-full mr-4 top-1/2 -translate-y-1/2 px-3 py-1 bg-stone-800 text-white text-[10px] font-black uppercase tracking-widest rounded whitespace-nowrap opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none">
            記錄新發現
          </span>
        </button>
      </div>

      {isModalOpen && (
        <AddQuoteModal 
          onAdd={addQuote} 
          onClose={() => setIsModalOpen(false)} 
          existingAuthors={allGroups.map(g => g.author)}
        />
      )}

      {isMyProfileModalOpen && myProfile && (
        <MyProfileModal 
          profile={myProfile} 
          onClose={() => setIsMyProfileModalOpen(false)} 
          onRefresh={handleGenerateMyProfile}
          isRefreshing={isGeneratingMyProfile}
        />
      )}
    </div>
  );
};

export default App;
